window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_004"]={"n":"陈维崧","dyn":"清","poems":[{"t":"惆怅词","f":"七言绝句","c":["三鼓出门乌夜飞，五更还家星宿希。","水晶楼角几时暖？","独坐待君归不归？"]},{"t":"将归留别练塘诸子","f":"五言律诗","c":["游子衣边雪，慈亲地下心。","都将苴杖泪，并作苦寒吟。","此意复谁识，当歌难自禁。","劳君霜夜弹，莫打失巢禽。"]},{"t":"贺新郎 七夕感怀再用前韵","f":"古风","c":["鹊又填桥矣。","满长安、千门砧杵，四围云水。","长记常年茅屋下，佳节团圞能几。","有和病、云鬟挥涕。","纵病倘然人尚在，也未应、我泪多如此。","弹不尽，半襟雨。","如今剩有孱躯耳。","便思量、故乡瓜果，也成千里。","谁借针楼丝一缕，穿我啼红珠子。","奈又说、春蚕竟死。","嘱付月钩休潋滟，幸怜人、正坐罗窗里。","风乍吼，粉云起。"]},{"t":"八归 二月十一夜风月甚佳，过水水绘园听诸郎弦管，灯下因遣家信，凄然不成一字，赋此以寄闺人","f":"古风","c":["弹得弦清，飘来笛脆，曲室诸郎歌管。","他乡风月佳无比，只是中年以后，心情顿懒。","遥忆故园妆阁上，镇玉臂、云鬟凄断。","伤心处、何事尊前，听一声河满。","却是绛河欲没，珠绳乍转，画角谯楼哀怨。","旧事如尘，新愁似梦，可惜一场分散。","奈天涯滋味，瞒不过、南归鱼雁。","吮霜毫、才提还倦。","莫虑春寒，罗襟红泪暖。"]},{"t":"沁园春 三月三日尉氏道中作","f":"古风","c":["登尉缭台，上三垂岗，伤如之何。","忆谈兵说剑，才情磊落，投秦去魏，意气嵯峨。","我到中原，重寻旧迹，牧笛吹风起夜波。","谁相问，纵残碑尚在，一半销磨。","短衣此日经过，叹禊日难逢晋永和。","正水边柳眼，斜窥芳岸，风前燕尾，乱剪晴莎。","异国韶光，中年意味，写上乌丝感慨多。","休凭吊，喜湔裙挑菜，士女娑拖。"]},{"t":"洞仙歌 乞巧同蘧庵先生赋","f":"古风","c":["碧云耿耿，见银河低泻。","人在针楼曝衣罢。","告天孙、臣本屠钓江东，疏拙甚，愿以蛛丝巧借。","天孙含笑答，见事卿迟，大抵聪明让聋哑。","试看古今来，刘项孙曹，都留做、残编閒话。","只赐汝狂騃倍常年，好烂醉高歌，花天月夜。"]},{"t":"贺新郎 五人之墓再用前韵","f":"古风","c":["古碣穿云罅。","记当年、黄门诏狱，群贤就鲊。","激起金阊十万户，白棓霜戈激射。","风雨骤、冷光高下。","慷慨吴儿偏嗜义，便提烹、谈笑何曾怕。","抉吾目，胥门挂。","铜仙有泪如铅泻。","怅千秋、唐陵汉隧，荒寒难画。","此处丰碑长屹立，苔绣坟前羊马。","敢轻易、霆轰电打。","多少道傍卿与相，对屠沽、不愧谁人者。","野香发，暗狼藉。"]},{"t":"踏莎行 冬夜不寐","f":"古风","c":["旧恨如丝，新寒似水。","两般都著人心里。","五更刁斗汴梁城，一天风雪成皋垒。","古寺钟生，邻墙月死。","枕头欹遍如何是。","半生孤愤酒难浇，挑灯且读韩非子。"]},{"t":"贺新郎 冬夜不寐写怀用稼轩同父倡和韵","f":"古风","c":["已矣何须说。","笑乐安、彦升儿子，寒天衣葛。","百结千丝穿已破，磨尽炎风腊雪。","看种种、是余之发。","半世琵琶知者少，枉教人、斜抱胸前月。","羞再挟，王门瑟。","黄皮裤褶军装别。","出萧关、边笳夜起，黄云四合。","直向李陵台畔望，多少如霜战骨。","陇头水、助人愁绝。","此意尽豪那易遂，学龙吟、屈煞床头铁。","风正吼，烛花裂。"]},{"t":"江南春 本意和倪云林原韵","f":"古风","c":["风光三月连樱笋。","美人踌躇白日静。","小屏空翠飐东风，不见其馀见衫影。","无端料峭春闺冷。","忽忆青骢别乡井。","长将妾泪黦红巾。","愿作征夫车畔尘。","人归迟，春去急。","雨丝满院流光湿。","锦书道远嗟奚及。","坐守吴山一春碧。","何日功成还马邑。","双倚枇杷花树立。","夕阳飞絮化为萍。","揽之不得徒营营。"]},{"t":"夏初临 本意","f":"古风","c":["中酒心情，拆棉时节，瞢腾刚送春归。","一亩池塘，绿阴浓触帘衣。","柳花搅乱晴晖。","更画梁、玉剪交飞。","贩茶船重，挑笋人忙，山市成围。","蓦然却想，三十年前，铜驼恨积，金谷人稀。","划残竹粉，旧愁写向阑西。","惆怅移时。","镇无聊、搯损蔷薇。","许谁知。","细柳新蒲，都付鹃啼。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其三","f":"古风","c":["何人又唱安公子，汉苑烟浓。","魏寝霜封，犵岭蛮乡一万重。","雪消巴蜀添春水，谁驾艨艟。","陡起鱼龙，此夜横江有阿童。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其一","f":"古风","c":["今年明月无情甚，偏向江东。","只照军容，不放银花万树红。","凤城飞下征南骑，一片刀弓。","铁甲呼风，愁杀思乡沈侍中。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其五","f":"古风","c":["杜陵诸弟飘零甚，几阵离鸿。","捩影长空，燕市梁园类转蓬。","后湖一雁尤酸楚，竟逐晨风。","一去无踪，雨打夭桃坠冷红。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其四","f":"古风","c":["早年丧乱曾尝过，复壁为佣。","城旦为舂，儿女宵啼贼火红。","回头三十年前事，笺恳天公。","衰鬓如蓬，莫遣咸阳又举烽。"]},{"t":"贺新郎 用辛稼轩陈同甫倡和原韵送王正子之襄阳明春归广陵并嘱示何生龙若","f":"古风","c":["立马和君说。","到襄阳、为余先问，隆中诸葛。","往日英雄潮打尽，怪煞怒涛崩雪。","今古恨、总多于发。","再问大堤诸女伴，白铜鞮、可有閒风月。","谁弹向，楚天瑟。","才逢燕市还分别。","怅生平、无多知己，几番离合。","此去武昌鱼不少，莫惜颜筋柳骨。","要频看、郑虔三绝。","一幅新词《凄凉犯》，嘱来春、并示何生铁。","霜夜吼，剑花裂。"]},{"t":"贺新郎 甲辰广陵中秋小饮孙豹人溉堂归歌示阮亭","f":"古风","c":["把酒狂歌起。","正天上、琉璃万顷，月华如水。","下有长江流不尽，多少残山剩垒。","谁说道、英雄竟死。","一听秦筝人已醉，恨月明、恰照吾衰矣。","城头点，打不止。","当年此夜吴趋里。","有无数、红牙金缕，明眸皓齿。","笑作镇西鸲鹆舞，眼底何知程李。","讵今日、一寒至此。","明月无情蝉鬓去，且五湖、归伴鱼竿耳。","知我者，阮亭子。"]},{"t":"齐天乐 辽后妆楼","f":"古风","c":["洗妆楼下伤情路，西风又吹人到。","一绺山鬟，半梳苔发，想像新兴闹扫。","塔铃声悄。","说不尽当年，月明花晓。","人在天边，轴帘遥闪茜钗小。","如今顿成往事，回心深院里，也长秋草。","上苑云房，官家水殿，惯是萧娘易老。","红颜懊恼。","与建业萧家，一般残照。","惹甚閒愁，且归斟翠醥。"]},{"t":"好事近 同友人过野寺","f":"古风","c":["春水碧于天，还与晴山赊翠。","历历几家烟店，缀山边水次。","莺声唤我过溪桥，扑帽暖香坠。","风弄杏花低处，露前村小寺。"]},{"t":"沁园春 赠别芝麓先生即用其题乌丝词韵三首 其二","f":"古风","c":["虽则毋归，对酒当歌，终难激扬。","似孔家文举，幼原了了，卫家叔宝，晚更茫茫。","五剧金鞭，六街宝马，谁数吾家老子昂。","公真误，叹臣今已老，发短心长。","御沟偶过毬场。","笑涂辙都为若辈妨。","更内家髻样，巧如马坠，小侯舞势，快作鸾翔。","酒则数行，食而三叹，断尽西风烈士肠。","登城望，有千群筚篥，万点牛羊。"]},{"t":"望江南 岁暮杂忆十首 其三","f":"古风","c":["江南忆，少小住长洲。","夜火千家红杏幕，春衫十里绿杨楼。","头白想重游。"]},{"t":"望江南 岁暮杂忆十首 其四","f":"古风","c":["江南忆，白下最堪怜。","东冶璧人新诀绝，南朝玉树旧因缘。","秋雨蒋山前。"]},{"t":"望江南 岁暮杂忆十首 其九","f":"古风","c":["江南忆，罨画最风流。","白屋山腰烟内市，红阑水面雨中楼。","楼上漾帘钩。"]},{"t":"望江南 岁暮杂忆十首 其五","f":"古风","c":["江南忆，懊恼是西湖。","秋月春花钱又赵，青山绿水越连吴。","往事只模糊。"]},{"t":"菩萨蛮 江行二首 其二","f":"古风","c":["江流只向台城打，阅江楼上人非也。","对此正茫茫，烟波空断肠。","布帆摇铁鹿，碾破长江绿。","回首望台城，依稀横吹声。"]},{"t":"水龙吟 江行望秣陵作","f":"古风","c":["轻舟夜剪秋江，西风鳞甲生江面。","瓦官阁下，方山亭外，惊涛雪片。","一带蒋州，千寻铁锁，等閒烧断。","只波间皓月，流光欲下，旧曾照，金陵县。","何处回帆挝鼓，更玉笛、数声哀怨。","回思旧事，永嘉南渡，流人何限。","如此江山，几人怜惜，斜阳断岸。","正江南烟水，濛濛飞尽，楚天新雁。"]},{"t":"满江红 江村夏咏十首 其二","f":"古风","c":["野水濛濛，掩映处、烟扉三两。","羡门外、黄云䆉稏，麦场如掌。","叱叱村头驱犊返，瀰瀰江口叉鱼往。","喜田园、四月不曾闲，人劳攘。","嫩晴后，桑阴敞。","老屋下，田歌漾。","更芋区新灌，鹅群初放。","婆饼焦啼秧马活，社公雨过缫车响。","笑吴侬、原住五湖边，曾呼长。"]},{"t":"渡江云 江南忆同云臣和蘧庵先生韵","f":"古风","c":["江豚翻碧浪，凭高极望，折戟半沈沙。","鸡笼山下路，记得凤城，数十万人家。","貂禅掩映，钟山翠、叠鼓鸣笳。","更参差、青溪红板，从古说繁华。","堪嗟。","齐台梁苑，残月微风，剩颓墙败瓦。","祇苍凉、半林枫槲，四壁龙蛇。","几番夜向寒潮泊，空城下、浪打蒹葭。","青衫湿，隔船同诉天涯。"]},{"t":"南乡子 江南杂咏六首 其五","f":"古风","c":["万艘千船。","今年米价减常年。","乍可宣房填蚁穴。","愁绝。","不愿官家言改折。"]},{"t":"南乡子 江南杂咏六首 其四","f":"古风","c":["鸡狗骚然。","朝惊北陌暮南阡。","印响西风猩作记。","如鬼。","老券排家验钤尾。"]},{"t":"南乡子 江南杂咏六首 其三","f":"古风","c":["户派门摊。","官催后保督前团。","毁屋得缗上州府。","归去。","独宿牛车滴秋雨。"]},{"t":"贺新郎 纤夫词","f":"古风","c":["战舰排江口。","正天边、真王拜印，蛟螭蟠钮。","徵发棹船郎十万，列郡风驰雨骤。","叹闾左、骚然鸡狗。","里正前团催后保，尽累累、锁繫空仓后。","捽头去，敢摇手。","稻花恰称霜天秀。","有丁男、临岐诀绝，草间病妇。","此去三江牵百丈，雪浪排樯夜吼。","背耐得、土牛鞭否。","好倚后园枫树下，向丛祠、亟倩巫浇酒。","神祐我，归田亩。"]},{"t":"蝶恋花 纪艳十首 其七","f":"古风","c":["拂晓相逢花弄口。","如此天寒，何事清晨走。","小院绿熊铺褥厚，玉梅花下交三九。","招入绣屏闲写久。","斜送横波，郎莫衣单否。","袖里任郎沾宝兽，雕龙手压描鸾手。"]},{"t":"满江红 自封邱北岸渡河至汴梁","f":"古风","c":["漭漭河声，捩柁处、怒涛千尺。","绝壁下、鱼龙悲啸，水波欲立。","一派灰飞官渡火，五更霜洒中原血。","问成皋、京索事如何。","都陈迹。","虫牢外，风萧瑟。","廪延畔，沙堆积。","试中流骋望，百忧横集。","混混且拚流日夜，芒芒不辨天南北。","但望中、似见有人烟，陈桥驿。"]},{"t":"尉迟杯 许月度新自金陵归以青溪集示我感赋","f":"古风","c":["青溪路。","记旧日、年少嬉游处。","覆舟山畔人家，麾扇渡头士女。","水花风片，有十万、珠帘夹烟浦。","泊画船、柳下楼前，衣香暗落如雨。","闻说近日台城，剩黄蝶濛濛，和梦飞舞。","绿水青山浑似画，只添了、几行秋戍。","三更后、盈盈皓月，见无数、精灵含泪语。","想胭脂、井底娇魂，至今怕说擒虎。"]},{"t":"西江月 过冯唐故里","f":"古风","c":["酒罢燕歌竟歇，途穷赵瑟难求。","滹沱水抱太行流，行过鄗南关口。","匹马霜天古迹，三河玉勒长楸。","翩翩过客半鸣驺，笑尔冯公白首。"]},{"t":"洞仙歌 过汜水县虎牢关作","f":"古风","c":["积铁苍然，关势临崖偻。","崭绝东京好门户。","挽藤萝月黑，谁恐行人，落叶捲，声似牢中哮虎。","无情惟洛水，日夜东流，不为愁人带愁去。","寂寞北邙山，苦对西风，排一派、唐陵汉墓。","任吊古伤今已无人，只霜打棠梨，暗啼红雨。"]},{"t":"满庭芳 过虎牢","f":"古风","c":["汜水东来，荥阳西去，伤心斜日哀湍。","横鞭顾盼，又过虎牢关。","叹息提兵血战，西风响、一片刀环。","英雄泪，乱山枫叶，不待晓霜丹。","追攀。","当日事，炎精末造，遗恨灵桓。","又许昌迁驾，不肯回銮。","今古兴亡转换，谁相问、剩水残山。","凭高望，汉陵魏殿，一样土花斑。"]},{"t":"满江红 何明瑞先生筵上作","f":"古风","c":["阳羡书生，记年少、剧于健马。","公一顾、风鬃雾鬣，尽居其下。","两院黄骢佳子弟，三条红烛乔声价。","恰思量、已是廿年前，凄凉话。","铁笛叫，南徐夜。","玉山倒，西窗下。","且摴蒱六博，弹筝行炙。","被酒我思张子布，临江不见甘兴霸。","只春潮、溅雪白人头，堪悲咤。"]},{"t":"贺新郎 作家书竟题范龙仙书斋壁上芦雁图","f":"古风","c":["漏悄裁书罢。","绕廊行、偶然瞥见，壁间小画。","一派芦花江岸上，白雁濛濛欲下。","有飞且、鸣而悲者。","万里重关归梦杳，拍寒汀、絮尽伤心话。","挨不了，凄凉夜。","城头戍鼓刚三打。","正四壁、人声都静，月华如泻。","再向丹青移烛认，水墨阴阴入化。","恍嘹呖、枕棱窗罅。","曾在孤舟逢此景，便画图、相对心犹怕。","君莫向，高斋挂。"]},{"t":"满江红 怀阮亭叠前韵","f":"古风","c":["隋帝宫门，杨柳岸、春浓花涨。","曾密报、杜家书记，平安无恙。","相赏每多松石意，此情原在钱刀上。","记红桥、风月六年游，皆君饷。","瓜果宴，离旌漾。","禅智寺，骊歌唱。","任吴霜鬓里，渐为君酿。","漫说休文围带减，吾年四十还须杖。","夜阑时、梦汝帽檐斜，论诗状。"]},{"t":"满江红 怅怅词五首 其二","f":"古风","c":["日夕此间，以眼泪、洗胭脂面。","谁复惜、松螺脚短，不堪君荐。","几帙骂人鹦鹉著，半床诅世芙蓉撰。","笑嵚崎、侠骨缚青衫，奚其便。","曷不向，青河战。","曷不向，青楼宴。","问何为潦倒、青藜笔砚。","老大怕逢裘马辈，颠狂合入烟花院。","誓从今、傅粉上须眉，簪歌钏。"]},{"t":"浣溪沙 投金濑怀古","f":"七言古诗","c":["格格沙禽拍野塘，离离苦竹上空墙。","投金濑在漾斜阳。","击絮□才怜伍员，浣纱溪又产夷光。","英雄生死繫红妆。"]},{"t":"师师令 汴京访李师师故巷","f":"古风","c":["宣和天子，爱微行坊市。","有人潜隐小屏红，低唱道、香橙纤指。","夜半无人莺语脆，正绿窗风细。","如今往事消沈矣，怅暮云千里。","含情试问旧倡楼，奈门巷、条条相似。","头白居人随意指，道斜阳边是。"]},{"t":"满江红 汴京怀古十首 其三","f":"古风","c":["汜水敖仓，是楚汉、提戈边界。","想昔日、名姬骏马，英雄梗概。","荥泽波痕寒叠雪，成皋山色愁凝黛。","叹从来、竖子易成名，今安在。","俎上肉，何无赖。","鸿门斗，真难耐。","算野花断镞，几更年代。","秦鹿讵为刘季死，楚猴甘受周苛卖。","笑纷纷、青史论都讹，因成败。"]},{"t":"满江红 汴京怀古十首 其一","f":"古风","c":["坏堞崩沙，人说道、古夷门也。","我到日、一番凭吊，泪同铅泻。","流水空祠牛弄笛，斜阳废馆风吹瓦。","买道旁、浊酒酹先生，班荆话。","摄衣坐，神閒暇。","北向刭，魂悲咤。","行年七十矣，翁何求者。","四十斤椎真可用，三千食客都堪骂。","使非公、万骑压邯郸，城几下。"]},{"t":"满江红 汴京怀古十首 其二","f":"古风","c":["铅筑无成，不信道、英雄竟死。","犹有客、弃家破产，东求力士。","太息已看秦帝矣，悲歌只念韩亡耳。","道旁观、谁道祖龙耶，妄男子。","狙击处，悲风起。","大索罢，浮云逝。","叹事虽不就，波腾海沸。","嬴政关河空宿草，刘郎宫寝成荒垒。","只千年、还响子房椎，奸雄悸。"]},{"t":"木兰花慢 汴梁城内有李师师巷经过感赋","f":"古风","c":["是东京旧迹，愁漠漠、雨丝丝。","怅赵宋繁华，樊楼笑语，总被风吹。","凄其。","剩勾栏在，照绿窗、曾挂月如规。","今日颓垣废井，当年舞榭歌基。","师师。","雪貌玉为肌。","玩月赏花时。","惹君王夜幸，香橙暗擘，腻笋潜携。","谁知。","小屏风后，有周郎、低唱断肠词。","一代春娇寂寞，半城夜火参差。"]},{"t":"点绛唇 阻风江口","f":"古风","c":["浊浪堆空，暨阳城下风涛怒。","冰车铁柱，隐隐轰吴楚。","独眺君山，且共春申语。","愁如许，一杯酹汝，同看蛟龙舞。"]},{"t":"满江红 陈郎以扇索书为赋一阕","f":"古风","c":["铁笛钿筝，还记得、白头陈九。","曾消受、妓堂丝管，毬场花酒。","籍福无双丞相客，善才第一琵琶手。","叹今朝、寒食草青青，人何有。","弱息在，佳儿又。","玉山皎，琼枝秀。","喜门风不坠，家声依旧。","生子何须李亚子，少年当学王昙首。","对君家、两世湿青衫，吾衰丑。"]},{"t":"画堂春 春景和少游原韵","f":"古风","c":["今年愁似柳条长，春宵梦断昭阳。","杏花著雨隔篱香，瘦不成妆。","十载流连蜂蝶，半生沦落湖湘。","残红几斛扑衣裳，和泪同量。"]},{"t":"望海潮 题马贵阳画册","f":"古风","c":["极北龙归，江东马渡，君臣建业偏安。","天上无愁，宫中有庆，声声玉树金莲。","点缀太平年。","更尚书艳曲，丞相蛮笺。","月夕花朝，那知王浚下楼船。","华清月照阑干。","怅多时粉本，流落人间。","可惜当初，丹青妙手，如何不画淩烟。","风景极凄然。","写一行衰柳，几处哀蝉。","展卷沈吟，昏鸦蔓草故宫前。"]},{"t":"水调歌头 咏美人秋千","f":"古风","c":["昨夜湔裙罢，今日意钱回。","粉墙正亚朱户，其外有铜街。","百丈同心綵索，一寸双文画板，风飐绣旗开。","低约腰间素，小摘鬓边牌。","翩然上，掠绿草，拂苍苔。","粉裙欲起未起，弄影惜身材。","忽趁临风回鹘，快作点波新燕，糁落一庭梅。","向晚半轮玉，隐隐照遗钗。"]},{"t":"法曲献仙音 咏铁马同云臣赋","f":"古风","c":["赤兔无成，乌骓不逝，屈作小楼檐马。","碎佩琮琤，丛铃戛咭，依稀客窗閒话。","更鸟雀，时相触，霜欺兼雨打。","几悲咤。","想多年、战场猛气，矜蹴踏、万马一时都哑。","流落到而今，踠霜蹄、寄人篱下。","潦倒馀生，尽闲身、蛛丝同挂。","又西风唤起，仍旧酸嘶中夜。"]},{"t":"沁园春 咏菜花","f":"古风","c":["极目离离，遍地濛濛，官桥野塘。","正杏腮低亚，添他旖旎，柳丝浅拂，益尔轻飏。","绣袜才挑，罗裙可择，小摘情亲也不妨。","风流甚，映粉红墙低，一片鹅黄。","曾经舞榭歌场。","却付与空园锁夕阳。","纵非花非草，也来蝶闹，和烟和雨，惯引蜂忙。","每到年时，此花娇处，观里夭桃已断肠。","沈吟久，怕落红如海，流入春江。"]},{"t":"洞仙歌 咏慈仁寺古松寿纪伯紫","f":"古风","c":["摩空翠鬣，万古知难老。","色作青铜雪霜饱。","似杜甫惊人，马卿慢世，二子者，可以状君兀奡。","托根燕市侧，游戏支离，一笑风尘此鸿爪。","任丝管喧阗，貂蝉赫奕，更七姓、鞭丝醉袅。","只西风、吼处作涛声，对凤阙龙墀，吾存吾傲。"]},{"t":"杏花天 咏滇茶","f":"古风","c":["秾春冶叶朱门里，弄东风、红妆初试。","残莺天气香绵坠，怊怅最宜著此。","见多少、江南桃李，斜阳外、翩翩自喜。","异乡花卉伤心死，目断昆明万里。"]},{"t":"喜迁莺 咏滇茶","f":"古风","c":["胭脂绣缬。","正千里江南，晓莺时节。","绛质酣春，红香宠午，惟许茜裙亲折。","小印枕痕零乱，浅晕酒潮明灭。","春园里，较琪花玉茗，娇姿更别。","情切。","想故国。","万里日南，渺渺音尘绝。","灰冷昆明，尘生洱海，此恨拟和谁说。","空对异乡烟景，蓦记旧家根节。","春去也，想蛮花犵鸟，泪都成血。"]},{"t":"解蹀躞 夜行荥阳道中","f":"古风","c":["峡劈成皋古郡，人杂猿猱过。","断崖怒走，苍龙立而卧。","此乃广武山乎，噫嚱古战场哉，悲来无那。","卸鞍坐，烟竹吹来入破。","一林纤月堕。","雁声不歇，砧声又搀和。","历历五点三更，马前渐逼荥阳，城头灯火。"]},{"t":"金浮图 夜宿翁村时方刈稻苦雨不绝词纪田家语","f":"古风","c":["为君诉。","今年东作。","满目西畴，尽成北渚。","雨翻盆、势欲浮村去。","香稻波飘，都作沈湘角黍。","咽泪频呼儿女。","瓮头剩粒，为君殷勤煮。","话难住。","茅檐点滴，短檠青荧，床上无乾处。","雨声乍续啼声断，又被啼声，剪了半村雨。","摇手亟谢田翁，一曲淋铃，不抵卿言苦。"]},{"t":"贺新郎 奉赠蘧庵先生仍用前韵","f":"古风","c":["识得词仙否。","起从前、欧苏辛陆，为先生寿。","不是花颠和酒恼，豪气轩然独有。","要老笔、万花齐绣。","掷碎琵琶令破面，好香词、污汝诸伶手。","笑馀子，徒雕镂。","秦宫汉苑描难就。","矗中原、怒涛似箭，断崖如臼。","我有铜人千行泪，扑地狮儿腾吼。","声撼落、橘中棋叟。","鹤发鸡皮人莫笑，忆华年、曾奉西宫帚。","家本住，金台口。"]},{"t":"琵琶仙 泥莲庵夜宿同子万弟与寺僧閒话","f":"古风","c":["倦客心情，况遇著、秋院捣衣时节。","惆怅侧帽垂鞭，凝情伫寥泬。","三间寺、水窗斜闭，一声磬、林香暗结。","且啜茶瓜，休论尘世，此景清绝。","询开士、杖锡何来，奈师亦、江东旧狂客。","惹起南朝零恨，与疏钟呜咽。","有多少、西窗閒话，对禅床、剪烛低说。","渐渐风弄莲衣，满湖吹雪。"]},{"t":"西江月 雨","f":"古风","c":["故国金戈铁马，衰年退笔残书。","心情浑似欲栖乌，偏惹连天丝雨。","风掣红旗纵猎，雨昏银烛呼卢。","此声记得不曾无，那便凄凉如许。"]},{"t":"八声甘州 客有言西江近事者感而赋此","f":"古风","c":["说西江、近事最销魂，啼断竹林猿。","叹灌婴城下，章江门外，玉碎珠残。","争拥红妆北去，何日遂生还。","寂寞词人句，南浦西山。","谁向长生宫殿，对君王试鼓，别鹄离鸾。","怕未终此曲，先已惨天颜。","只小姑、端然未去，伴彭郎、烟水月明间。","终古是，银涛雪浪，雾鬓风鬟。"]},{"t":"西河 春日偶过亳村故居","f":"古风","c":["前村里。","落梅阵阵风起。","旧家池馆暂经过，玉栏漫倚。","粉英也为主人来，雨中和泪梳洗。","画檐损，月榭圮。","蘼芜蛱蝶盈砌。","颓垣败井剧关心，那能遣此。","赚人连夜卸烟帆，半篙埋怨春水。","一天丝雨洒不止，总难寻、旧日邻里。","祇有点波燕子。","上雕梁絮语，墨花帘底。","似话王家当年事。"]},{"t":"莺啼序 春日游平山堂即事","f":"古风","c":["三月雷堂口，多少游丝浴鹭。","正潋滟、文縠初平，金沟种满芳树。","屏幕津楼斜蘸水，秋千春院閒吹絮。","喜夹衣初试，艇子一双摇去。","阵阵鬓丝，层层帘影，齐问平山渡。","隔船纱、袅袅亭亭，影落绿波深处。","照菱花，水面明妆，唱竹枝，风前诗句。","又东园、芍药才红，金铃争护。","兰桡小拢，看绕径裙花，漾尘微步。","渐铺遍氍毹，玉笋飞觥，春纤拂素。","红子低敲，青梅小摘，栏杆却立频回顾。","蓦地见、玉钩斜下路。","伤心吊古，黯然偷注横波，此处是隋皇墓。","几番怊怅，流水东风，往事浑无据。","且趁江流正滑，好放蜻蛉，慢摇纨扇，重歌金缕。","暝翠将沈，船头欲转，茱萸湾子红桥下，妒游童、宝马将人觑。","可怜此际归来，两岸榆钱，一天丝雨。"]},{"t":"鹊踏花翻 春夜听客弹琵琶作隋唐评话","f":"古风","c":["雨滴梅梢，雪消蕙叶，入春难得今宵暇。","倩他银甲凄清，铁拨纵横，声声迸碎鸳鸯瓦。","依稀长乐夜乌啼，分明湓浦邻船话。","腕下。","多少孤城战马。","一时都作哀湍泻。","今日黑闼营空，尉迟杯冷，落叶浮清灞。","百年青史不胜愁，两行银烛空如画。"]},{"t":"唐多令 春愁","f":"古风","c":["蝉鬓隔花阴，香肌压翠衾。","风前一笑掷千金。","记得那时明月底，刚半线，露丹襟。","银钥杳沈沈，朱楼阻信音。","流莺啼破绿窗深。","清泪未弹红泪滴，流不了，到如今。"]},{"t":"唐多令 春暮半塘小泊","f":"古风","c":["水榭枕官河，朱栏倚粉娥。","记早春、栏畔曾过。","关著绿纱窗一扇，吹钿笛，是伊么。","无语注横波，裙花信手搓。","怅年光、一往蹉跎。","卖了杏花挑了菜，春纵好，已无多。"]},{"t":"过涧歇 显德寺前看枫叶","f":"古风","c":["岚翠浓于草鞋夹。","绕坡细流，潨潨暗通苕霅。","谷声遝。","下落乱泉声里，愀悄如相答。","此间景，纯得关仝巨然法。","寺松三百本，雨溜苍皮，霜彫黛甲。","秃干争欹压。","笑语同游，黄叶鸣檐，丹枫裹寺，如何不荷埋身锸。"]},{"t":"戚氏 柬程村文友","f":"古风","c":["想当年。","黄公垆畔兴翩翩。","盘马雕龙，春风门下盛貂蝉。","有邹阳董相，一时赏誉重琅玕。","略记旗亭游处，都相似、尔我周旋。","自许上流，人称名士，终朝蹋臂萦牵。","更儿呼德祖，弟畜灌夫，意气无前。","忆唱绿帻金丸。","风流放诞，并坐响鹍弦。","髣髴是、巷名金线，幕号红莲。","回中下杜，油壁雕鞍。","曾经坠粉遗钿。","狂奴减未，痴人死未，诟厉语亦相怜。","分携成旧雨，酒阑追省，一往凄然。","同学少年虽健，奈酒徒、散尽不堪言。","道政坊头，延秋门外，忆了千千万。","论窥帘、映柱人何限，都分付、碎雨零烟。","念故人、一样艰难。","总萧瑟、江南庾子山。","写瑶琴怨，我弹未了，又怕君弹。"]},{"t":"一萼红 癸丑除夕","f":"古风","c":["响铜签，许多年旧事，和恨压眉尖。","记得当初，后堂弟妹，团圞围定红帘。","饮尽了、屠苏千盏，挝画鼓、憨笑赌黄柑。","十里春城，金蛾暗扑，火凤交衔。","自后也逢除夕，叹此身长是，弟北兄南。","第宅俱非，颠毛都换，每因令节生嫌。","只万点、官桥夜火，风吹零乱映疏檐。","羡煞邻家岁酒，隔巷春衫。"]},{"t":"满江红 秋日经信陵君祠","f":"古风","c":["席帽聊萧，偶经过、信陵祠下。","正满目、荒台败叶，东京客舍。","九月惊风将落帽，半廊细雨时飘瓦。","桕初红、偏向坏墙边，离披打。","今古事，堪悲咤。","身世恨，从牵惹。","倘君而尚在，定怜余也。","我讵不如毛薛辈，君宁甘与原尝亚。","叹侯嬴、老泪苦无多，如铅泻。"]},{"t":"夜游宫 秋怀四首 其三","f":"古风","c":["箭与饥鸱竞快。","侧秋脑、角鹰愁态。","骏马妖姬秣燕代。","笑吴儿，困雕虫，矜细欬。","龌龊谁能耐。","总一笑、浮云睚眦。","独去为佣学无赖。","圯桥边，有猿公，期我在。"]},{"t":"夜游宫 秋怀四首 其四","f":"古风","c":["一派明云荐爽。","秋不住、碧空中响。","如此江山徒莽苍。","伯符耶，寄奴耶，嗟已往。","十载羞厮养。","孤负煞、长头大颡。","思与骑奴游上党。","趁秋晴，蹠莲花，西岳掌。"]},{"t":"夜游宫 秋怀四首 其二","f":"楚辞体","c":["秋气横排万马。","尽屯在、长城墙下。","每到三更素商泻。","湿龙楼，晕鸳机，迷爵瓦。","谁复怜卿者。","酒醒后、槌床悲诧。","使气筵前舞甘蔗。","我思兮，古之人，桓子野。"]},{"t":"沁园春 秋夜听梁溪陈四丈弹琵琶","f":"古风","c":["瑟瑟阴阴，嗟哉此声，胡为乎来。","似灵龟夜吼，狂崩断岸，角鹰秋起，怒决荒台。","忽漫沈吟，陡焉掩抑，细抵游丝缀落梅。","冰弦内，惹一宵涕泪，万种悲哀。","十年前记追陪。","乍握手霜灯暗自猜。","叹朱门酒肉，谁容卿傲，梨园子弟，总妒君才。","牢落关河，聊萧身世，迸入空庭小忽雷。","颠狂甚，骂人间食客，大半驽骀。"]},{"t":"贺新郎 秋夜呈芝麓先生二首 其一","f":"古风","c":["掷帽悲歌发。","正倚幌、孤秋独眺，凤城双阙。","一片玉河桥下水，宛转玲珑如雪。","其上有、秦时明月。","我在京华沦落久，恨吴盐、只点愁人发。","家何在，在天末。","凭高对景心俱折。","关情处、燕昭乐毅，一时人物。","白雁横天如箭叫，叫尽古今豪杰。","都只被、江山磨灭。","明到无终山下去，拓弓弦、渴饮黄獐血。","长杨赋，竟何益。"]},{"t":"减字木兰花 秋雨过红板桥","f":"古风","c":["当年此地，销魂人记销魂事。","妙舞轻歈，不是柔奴定态奴。","西风古道，二十年来人渐老。","漠漠迢迢，秋雨重经红板桥。"]},{"t":"水龙吟 秋感","f":"古风","c":["夜来几阵西风，匆匆偷换人间世。","凄凉不为，秦宫汉殿，被伊吹碎。","祇恨人生，些些往事，也成流水。","想桃花露井，桐英永巷，青骢马，曾经繫。","光景如新宛记。","记相逢、瑶台殊丽。","微烟淡月，回廊复馆，许多情事。","今日重游，野花乱蝶，迷濛而已。","愿天公还我，那年一带，玉楼银砌。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其六","f":"古风","c":["四月荆南桑柘美。","泥就蚕房，雪净无尘滓。","红帖糊门多禁忌，家家阿妇劳纤指。","笑语小姑应夜起。","好事今冬，早把衣裳备。","推却缫车佯不理，小姑为恼前言戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其八","f":"古风","c":["五月荆南秧早莳。","黄纸飞来，温语从天至。","见说东南民力敝，秋租减半明年事。","比屋欢腾还雪涕。","只恐来年，还似常年例。","我语村农休过计，官家自古言无戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其四","f":"古风","c":["六月荆南闲也未。","一月停忙，暂缓官粮比。","闻道开徵今日始，新丝卖了来城市。","不信何花名茉莉。","却与侬家，白豆花相类。","笑煞长桥桥上子，市儿惯取村儿戏。"]},{"t":"贺新郎 贺阮亭三十","f":"古风","c":["牛马江东走。","陪满座、邹枚上客，为君称寿。","七叶貂蝉连凤阙，坐拥银筝翠袖。","又兄弟、才雄八斗。","三十王郎年正少，拾黄金、铸印双悬肘。","此意气，古无有。","淡黄十里隋堤柳。","更多少、竹西歌吹，樊川诗酒。","满目关山原不恶，只是繁华非旧。","算惟有、文章不朽。","簌簌珠帘人不捲，看使君、灯火春城口。","依稀羡，欧阳守。"]},{"t":"贺新郎 送三韩李若士省亲之楚","f":"古风","c":["秋到离亭暮。","羡风前、珊鞭玉靶，翩然竟去。","借问此行何所向，笑指巴烟郢树。","是乌鹊、惯南飞处。","路入南荒休骋望，有陶公、战舰空滩雨。","酾热酒，浪花舞。","严君坐拥貔貅旅。","厌江流、一军下濑，目无黄祖。","昨夜月明亲飨士，要奏新填乐府。","都不用、陈琳阮瑀。","手掣红旗翻破阵，看郎君、下笔惊鹦鹉。","猿臂种，气如虎。"]},{"t":"贺新郎 送邵兰雪归吴门仍用前韵","f":"古风","c":["易水严装发。","休回首、故人别酒，帝城高阙。","九曲黄河迎马首，淼淼龙宫堆雪。","说不尽、天涯白月。","君去故侯瓜可种，向西风、莫短冲冠发。","人世事，总毫末。","长洲鹿走苏台折。","叹年少、当歌不醉，此非俊物。","试到吴东门下问，可有吹箫人杰。","有亦被、怒潮磨灭。","来夜天街无酒伴，怕离鸿、叫得枫成血。","亦归耳，住何益。"]},{"t":"贺新郎 送姜西溟入都","f":"古风","c":["去矣休回顾。","尽疏狂、长安市上，飞扬跋扈。","谁道天涯知己少，半世人中吕布。","仗彩笔、凭陵今古。","伏枥悲歌平生恨，肯车中、闭置加穷绔。","君莫信，文章误。","杨花细糁京江渡。","恰盈盈、租船吹笛，柁楼挝鼓。","屈指帝城秋更好，寄语冰轮玉兔。","为我照、望诸君墓。","相约当年荆高辈，唤明驼、倒载琵琶女。","葡萄酒，色如乳。"]},{"t":"水调歌头 送恽南田之钱塘并柬毛稚黄","f":"古风","c":["蹑屩上灵隐，吹笛下吴淞。","送君恰值新爽，纤月印船篷。","犹忆冷泉亭上，百道跳珠喷雪，飞瀑挂杉松。","一别十八载，吾老渐成翁。","故人去，携笔墨，写空濛。","不知老已将至，挥洒醉偏工。","为讯盐桥毛子，果否别来无恙，底事断诗筒。","人世作达耳，长邑郁焉穷。"]},{"t":"扬州慢 送蘧庵先生之广陵并示宗定九孙无言汪蛟门舟次诸子","f":"古风","c":["十里珠帘，半城画艇，百年花月维扬。","有君家丞相，梅岭旧祠堂。","每年到、清明赛社，倾城士女，愁弄丝簧。","只无情堤柳，舞腰还斗宫妆。","扁舟上冢，听邻船、重话兴亡。","奈石马嘶风，银蚕吊月，往迹全荒。","我亦当年薄倖，曾吹过、一帽红香。","问桃花认否，风前前度刘郎。"]},{"t":"念奴娇 钜鹿道中作","f":"古风","c":["雄关上郡，看城根削铁，土花埋镞。","十月悲风如箭叫，此地曾称钜鹿。","白浪轰豗，黄沙苍莽，霜蚀田夫屋。","车中新妇，任嘲髀里生肉。","太息张耳陈馀，当年刎颈，末路相倾覆。","长笑何须论旧事，坻水依然微绿。","欲倩燕姬，低弹赵瑟，一醉生平足。","井陉日暮，乱鸦啼入枯木。"]},{"t":"水调歌头 夏五大雨浃月，南亩半成泽国，而梁溪人尚有画舫游湖者，词以寄慨","f":"古风","c":["翠釜一朝裂，铜狄尽流船。","江南五月天漏，炼石补仍穿。","骤若淫龙喷沫，狂比长鲸跋浪，庐舍没长川。","菱蔓绕床下，钓艇繫门前。","今何日，民已困，况无年。","家家秧马，闲坐墟井断炊烟。","何处玉箫金管，犹唱雨丝风片，烟水泊游船。","此曲纵娇好，听者似啼猿。"]},{"t":"长亭怨慢 夏日吴门道中寄内","f":"古风","c":["记睡醒、纱巾轻堕，又促移床，树阴中卧。","院悄人稀，举首閒数碧星颗。","井华浴簟，渐月映、中门锁。","唤绿茗盈盈，恰一缕、红生廊火。","几朵。","是才开茉莉，小傍苧衫斜亸。","抽书赌背，总排定、夜分幽课。","弄不了、茭粉菱丝，写难尽、偷声入破。","惹万种、思量凭仄，烟桡风舸。"]},{"t":"摸鱼儿","f":"古风","c":["是谁家、本师绝艺，檀槽搯得如许。","半弯逻逤无情物，惹我伤今吊古。","君何苦。","君不见、青衫已是人迟暮。","江东烟树。","纵不听琵琶，也应难觅，珠泪曾乾处。","凄然也，恰似秋宵掩泣。","灯前一队儿女。","忽然凉瓦飒然飞，千岁老狐人语。","浑无据。","君不见、澄心结绮皆尘土。","两家后主。","为一两三声，也曾听得，撇却家山去。"]},{"t":"西江月 喜见狮儿四首 其一","f":"古风","c":["猛兽产于绝域，骁腾来自安西。","一呼百物尽披靡，何论猘奴鹞子。","我顾灰颓若此，儿应跳荡如斯。","神仙将相讵难为，万事取之以气。"]},{"t":"西江月 喜见狮儿四首 其三","f":"古风","c":["儿已健如黄犊，翁何此日才来。","怒涛雪浪吼长淮，兵火连天四载。","细听吴音小却，戏投粔籹旋回。","怪娘奁畔有于思，笑问客家何在。"]},{"t":"凤凰台上忆吹箫 秣陵怀古","f":"古风","c":["红板桥南，锦衣仓北，金陵从古皇州。","记离宫墙外，年少潜游。","忽听九重仙乐，东风细、声度龙楼。","依稀认，宁王玉笛，贺老箜篌。","悠悠。","南朝风景，看几遍桃红，白了人头。","算刘郎易老，嬴女难留。","三十六宫何在，斜阳外、隐隐离愁。","伤心极，后湖菱蔓，一片渔舟。"]},{"t":"念奴娇 读孚若长歌即席奉赠仍用孚若原韵","f":"古风","c":["霆轰电掣，算君才、真似怒涛千斛。","百感淋漓风骤起，劈裂满堂桦烛。","公醒而狂，人憎欲杀，抵鹊何须玉。","春衫老泪，鲛珠瓣瓣堪掬。","不记三十年前，灌夫使气，嚄唶惊邻屋。","弹指蓬莱今又浅，短发可能长绿。","诗酒前缘，莺花小劫，世事弹棋局。","关山笛破，欲吹吹不成曲。"]},{"t":"念奴娇 读屈翁山诗有作","f":"古风","c":["灵均苗裔，羡十年学道，匡庐山下。","忽听帘泉豗冷瀑，豪气轶于生马。","亟跳三边，横穿九塞，开口谈王霸。","军中毬猎，醉从诸将游射。","提罢匕首入秦，不禁忍俊，缥缈思登华。","白帝祠边三尺雪，正值玉姜思嫁。","笑把岳莲，乱抛博箭，调弄如花者。","归而偕隐，白羊瑶岛同跨。"]},{"t":"好事近 郯城南倾盖亭下作","f":"古风","c":["落日古郯城，一望秃碑苍黑。","怪底蜗黄虿紫，更苔痕斜织。","我来怀古对西风，歇马小亭侧。","惆怅共谁倾盖，只野花相识。"]},{"t":"贺新郎 鸳湖烟雨楼感旧十用前韵","f":"古风","c":["水宿枫根罅。","尽沽来、鹅黄老酿，银丝鲜鲊。","记得筝堂和伎馆，尽是仪同仆射。","园都在、水边林下。","不闭春城因夜宴，望满湖、灯火金吾怕。","十万盏，红毬挂。","重游陂泽偏潇洒。","剩空潭、半楼烟雨，玲珑如画。","人世繁华原易了，快比风樯阵马。","消几度、城头钟打。","惟有鸳鸯湖畔月，是曾经、照过倾城者。","波织簟，船堪藉。"]},{"t":"喝火令 偶忆","f":"古风","c":["架上红鹦鹉，帘边玉辟邪。","兜娘懒上卓金车。","鬌?一窝，浓绿未成鸦。","娆我吹春笛，邀人夜斗茶。","如今庭院隔天涯。","记得沿街，一树粉梨花。","记得花阴微露，几扇绿窗纱。"]},{"t":"送入我门来 寄书","f":"古风","c":["香茗才情，簪花模样，斜舒蜜色笺儿。","霜毫才吮，早已泪如丝。","楚天楼上湘娥倚，奈湘雨湘烟十二时。","说与天涯游子，近日恹恹春病，生怕难支。","为趁双鱼，无物寄相思。","真珠滴向红绡满，怕绡滑珠圆难寄伊。"]},{"t":"满江红 梁溪顾梁汾舍人过访赋此以赠兼题其小像","f":"古风","c":["二十年前，曾见汝、宝钗楼下。","春二月、铜街十里，杏衫笼马。","行处偏遭娇鸟唤，看时谁让珠帘挂。","只沈腰、今也不宜秋，惊堪把。","且给个，金门假。","好长就，旗亭价。","记炉烟扇影，朝衣曾惹。","芍药才填妃子曲，琵琶又听商船话。","笑落花、和泪一般多，淋罗帕。"]},{"t":"摸鱼儿 清明感旧","f":"古风","c":["正轻阴、做来寒食，落花飞絮时候。","踏青队队嬉游侣，只我伤心偏有。","休回首。","新添得、一堆黄土垂杨后。","风吹雨溜。","记月榭鸣筝，露桥吹笛，说著也眉皱。","十年事，此意买丝难绣。","愁容酒罢微逗。","从今纵到岐王宅，一任舞衣轻斗。","君知否。","两三日、春衫为汝重重透。","啼多人瘦。","定来岁今朝，纸钱挂处，颗颗长红豆。"]},{"t":"祝英台近 善权寺相传为祝英台旧宅，寺后一台，云其读书处也。壁间旧有谷令君一词，春日与云臣、远公披藓读之，共和其韵","f":"古风","c":["傍东风，寻旧事，愁脸界红箸。","任是年深，也有繫人处。","可怜黄土苔封，绿罗裙坏，只一缕、春魂抛与。","为他虑。","还虑化蝶归来，应同鹤能语。","赢得无聊，呆把断垣觑。","那堪古寺莺啼，乱山花落，惆怅煞、台空人去。"]},{"t":"临江仙 寒柳","f":"古风","c":["自别西风憔悴甚，冻云流水平桥。","并无寒叶伴飘飖。","乱鸦三四点，愁坐话无憀。","雪压西村茅舍重，怕他榾柮同烧。","好留蛮样到春宵。","三眠明岁事，重斗小楼腰。"]},{"t":"鹧鸪天 寓兴用稼轩韵同蘧庵先生作三首 其一","f":"古风","c":["斫屧吹箫吴市间，恨无大药驻红颜。","诗情浩荡风前絮，身计微茫海外山。","耽放浪，恣萧闲，烟波境界十分宽。","新衔曲部兼茶部，旧署园官并橘官。"]},{"t":"鹧鸪天 寓兴用稼轩韵同蘧庵先生作三首 其二","f":"古风","c":["曾倚瑶台喝月行，嗔他鸾鹤不相迎。","当时酒态公然好，今日诗狂太瘦生。","千百辈，尽容卿，问谁堪与耦而耕。","灌夫已去袁丝死，沦落人间少弟兄。"]},{"t":"念奴娇 游京口竹林寺","f":"古风","c":["长江之上，看枝峰蔓壑，尽饶霸气。","狮子寄奴生长处，一片雄山莽水。","怪石崩云，乱岗淋雨，下有鼋鼍睡。","层层都挟，飞而食肉之势。","只有铁瓮城南，群山羸秀，画出吴天翠。","绝似小乔初嫁与，顾曲周郎佳婿。","竹院盘陀，松寮峭茜，最爱林皋寺。","徘徊难去，夕阳烟磬沈未。"]},{"t":"贺新郎 登上方寺铁塔","f":"古风","c":["栏楯浮空去。","划玲珑、榴皮石发，青红无数。","看尽宣和风景好，又看宫娥北渡。","有多少、梨花夜雨。","西望铜驼荆榛里，算千秋、老辈惟吾汝。","晋宋事，总尘土。","鸿濛一气凭㪺取。","蹑丹梯、千盘百级，上通元圃。","根插中原维地轴，其下黄河一缕。","曾经过、怒潮煎煮。","无限西风神州恨，倩相轮、做尽兴亡谱。","铃铎响，自相语。"]},{"t":"蓦山溪 感旧","f":"古风","c":["碧云薄暮，画角谁家奏。","深院火荧荧，好风轻、翠帏微皱。","冰轮徐上，无语掩屏山，金钩瘦，鲛绡透，人在银灯后。","年时小苑，良夜曾携手。","低扫淡黄蛾，漫垂垂、玉人红袖。","如今人去，门巷也依然，红桥口，香街右，一带青青柳。"]},{"t":"少年游 感旧和柳屯田","f":"古风","c":["奉诚园内小斜桥，曾记近花朝。","簸钱庭院，筑毬天气，春草绿裙腰。","而今不道心情换，飘泊堕江皋。","眼底人疏，心头事满，斜凭木兰桡。"]},{"t":"贺新郎","f":"古风","c":["天畔蚕丛路。","记当日、锦城丝管，华阳士女。","一自愁云霾蜀栈，飞下桓家宣武。","有多少、花钿血污。","十万娥眉齐上马，过当年、花蕊题诗处。","葭萌驿，鹃啼苦。","春宵高宴元戎府。","明月下、玉容黯淡，有人低诉。","妾本成都良家子，叹息鸾分钗股。","客亦为、泪零如雨。","掷却黄金归破镜，问德言、还识菱花否。","吾事毕，拔身去。"]},{"t":"满庭芳 蜀山谒东坡书院","f":"古风","c":["水拍晴桥，山衔春店，飞花落絮悠飏。","打鱼放鸭，四月好年光。","此地林峦绝胜，家家足、碧涧幽篁。","斜坡上，碎瓻败甓，零乱补围墙。","鸣榔。","思往事，峨嵋仙客，曾驻吾乡。","惹溪山千载，姓氏犹香。","今日紫姑圣女，喧村赛、画鼓明妆。","残碑在，独怜野草，渐没古祠堂。"]},{"t":"愁春未醒 墙外丁香花盛开感赋索京少蕺山和","f":"古风","c":["攀来尚隔，望处偏清。","算开到此花，阑珊春已在长亭。","滴粉搓酥，小红墙角倍分明。","年年此际，笼归马上，递遍春城。","昨岁看花，有人秃袖，擘阮挨筝。","怅新来、梁间燕去，往事星星。","只有邻花，依依不作路旁情。","夜深难睡，缤纷花影，筛满空庭。"]},{"t":"木兰花慢 歌筵感旧","f":"古风","c":["谁家摇步障，明月夜、赏花天。","正壁带红稠，帘衣绿绉，夹路钗钿。","从前。","也曾听处，渐如尘、似梦记难全。","遮莫延秋门里，不然道政坊边。","铜仙。","有泪泻如铅。","揽镜恼华颠。","讵飘零江海，重归故国，再上珠筵。","龟年。","莫停歌拍，怕举头、皓魄不常圆。","正月新蒲细柳，满场横竹么弦。"]},{"t":"醉落魄 咏鹰","f":"古风","c":["寒山几堵，风低削碎中原路。","秋空一碧无今古。","醉袒貂裘，略记寻呼处。","男儿身手和谁赌。","老来猛气还轩举。","人间多少闲狐兔。","月黑沙黄，此际偏思汝。"]},{"t":"沁园春 题徐渭文钟山梅花图同云臣南耕京少赋","f":"古风","c":["十万琼枝，矫若银虬，翩如玉鲸。","正困不胜烟，香浮南内，娇偏怯雨，影落西清。","夹岸亭台，接天歌板，十四楼中乐太平。","谁争赏，有珠珰贵戚，玉佩公卿。","如今潮打孤城，只商女船头月自明。","叹一夜啼乌，落花有恨，五陵石马，流水无声。","寻去疑无，看来似梦，一幅生绡泪写成。","携此卷，伴水天閒话，江海馀生。"]},{"t":"河渎神 题秦邮露筋祠","f":"古风","c":["湖上水连天，湖光捲尽寒烟。","玉娥一去几千年，尽日凝妆俨然。","漠漠雨丝飘碧瓦，人在女郎祠下。","一树红梨开谢，明朝又是春社。"]},{"t":"贺新郎 题曹实庵珂雪词","f":"古风","c":["满酌凉州酝。","爱佳词、一编珂雪，雄深苍稳。","万马齐瘖蒲牢吼，百斛蛟螭囷蠢。","算蝶拍、莺簧休混。","多少词场谈文藻，向豪苏、腻柳寻蓝本。","吾大笑，比蛙黾。","爇残桦烛刚馀寸。","叹从来、虞卿坎坷，韩非孤愤。","耳热杯阑无限感，目送塞鸿归尽。","又眼底、群公衮衮。","作达放颠无不可，劝临淄、且傅当筵粉。","城柝沸，夜乌紧。"]},{"t":"贺新郎 赠成容若","f":"古风","c":["丹凤城南路。","看纷纷、崔卢门第，邹枚诗赋。","独炙鹅笙潜趁拍，花下酒边閒谱。","已吟到、最消魂处。","不值一钱张三影，尽旁人、拍手揶揄汝。","何至作，温韦语。","总然不信填词误。","忆平生、几枝红豆，江东春暮。","昨夜知音才握手，笛里飘零曾诉。","长太息、钟期难遇。","斜插侍中貂更好，箭?鸣、从猎回中去。","堂堂甚，为君舞。"]},{"t":"贺新郎 赠何生铁","f":"古风","c":["铁汝前来者。","曷不学、雀刀龙笛，腾空而化。","底事六州都铸错，孤负阴阳炉冶。","气上烛、斗牛分野。","小字又闻呼阿黑，讵王家、处仲卿其亚。","休放诞，人笞骂。","萧疏粉墨营邱画。","更雕镵、渐台威斗，邺宫铜瓦。","不值一钱畴惜汝，醉倚江楼独夜。","月照到、寄奴山下。","故国十年归不得，旧田园、总被寒潮打。","思乡泪，浩盈把。"]},{"t":"沁园春 赠别芝麓先生即用其题乌丝词韵三首 其一","f":"古风","c":["四十诸生，落拓长安，公乎念之。","正戟门开日，呼余惊坐，烛花灭处，目我于思。","古说感恩，不如知己，卮酒为公安足辞。","吾醉矣，才一声河满，泪滴珠徽。","昨来夜雨霏霏。","叹如此狂飙世所稀。","恰山崩石裂，其穷已甚，狮腾象踏，此景尤奇。","我赋将归，公言小住，归路银涛百丈飞。","氍毹暖，趁铜街似水，赓和无题。"]},{"t":"贺新郎 赠苏昆生","f":"古风","c":["吴苑春如绣。","笑野老、花颠酒恼，百无不有。","沦落半生知己少，除却吹箫屠狗。","算此外、谁欤吾友。","忽听一声河满子，也非关、雨湿青衫透。","是鹃血，凝罗袖。","武昌万叠戈船吼。","记当日、征帆一片，乱遮樊口。","隐隐柁楼歌吹响，月下六军搔首。","正乌鹊、南飞时候。","今日华清风景换，剩凄凉、鹤发开元叟。","我亦是，中年后。"]},{"t":"贺新郎 蘧庵先生五日有鱼酒之饷醉后填词","f":"古风","c":["蒲酒浓如乳。","更为我、东溟斫鲙，大鱼就脯。","携酒石榴花下醉，还选腹腴亲煮。","耳热也、休提今古。","只有寒潮围故国，叹龙舟、寂寞无寻处。","风乍起，瘦蛟舞。","何须远望悲荆楚。","暗想像、广陵旧事，泪多于雨。","火照佛狸城下水，丞相孤军难渡。","记时节、也邻重五。","儿女谁知英雄恨，辟兵符、戏向钗头赌。","葵影绿，小窗午。"]},{"t":"卜算子 阻闸瓜步","f":"古风","c":["风急楚天秋，日落吴山暮。","乌桕红梨树树霜，船在霜中住。","极目落帆亭，侧听催船鼓。","闻道长江日夜流，何不流侬去。"]},{"t":"好事近 夏日史蘧庵先生招饮即用先生喜余归自吴阊过访原韵","f":"古风","c":["分手柳花天，雪向晴窗飘落。","转眼葵肌初绣，又红欹栏角。","别来世事一番新，只吾徒犹昨。","话到英雄失路，忽凉风索索。"]},{"t":"贺新郎 伯成先生席上赠韩修龄","f":"古风","c":["月上梨花午。","恰重逢、江潭旧识，喁喁尔汝。","绛烛两行浑不夜，添上三通画鼓。","说不尽、残唐西楚。","话到英雄儿女恨，绿牙屏、惊醒红鹦鹉。","雕笼内，泪如雨。","一般怀抱君尤苦。","家本在、扶风盩厔，五陵佳处。","汉阙唐陵回首望，渭水无情东去。","剩短蜡、声声诉与。","绣岭宫前花似雪，正秦川、公子迷归路。","重酌酒，尽君语。"]},{"t":"夜游宫 秋怀四首 其一","f":"古风","c":["耿耿秋情欲动。","早喷入、霜桥笛孔。","快倚西风作三弄。","短狐悲，瘦猿愁，啼破冢。","碧落银盘冻。","照不了、秦关楚陇。","无数蛩吟古砖缝。","料今宵，靠屏风，无好梦。"]},{"t":"南乡子 邢州道上作","f":"古风","c":["秋色冷并刀，一派酸风捲怒涛。","并马三河年少客，粗豪。","皂栎林中醉射雕。","残酒忆荆高，燕赵悲歌事未消。","忆昨车声寒易水，今朝。","慷慨还过豫让桥。"]},{"t":"点绛唇 夜宿临洺驿","f":"古风","c":["晴髻离离，太行山势如蝌蚪。","稗花盈亩，一寸霜皮厚。","赵魏燕韩，历历堪回首。","悲风吼，临洺驿口，黄叶中原走。"]},{"t":"清平乐 夜饮友人别馆听年少弹三弦限韵三首 其二","f":"古风","c":["檐前雨罢，一阵凄凉话。","城上老乌啼哑哑，街鼓已经三打。","漫劳醉墨纱笼，且娱别院歌钟。","怪底烛花怒裂，小楼吼起霜风。"]},{"t":"虞美人 无聊","f":"古风","c":["无聊笑撚花枝说，处处鹃啼血。","好花须映好楼台，休傍秦关蜀栈战场开。","倚楼极目添愁绪，更对东风语。","好风休簸战旗红，早送鲥鱼如雪过江东。"]},{"t":"醉太平 江口醉后作","f":"古风","c":["钟山后湖，长干夜乌。","齐台宋苑模糊，剩连天绿芜。","估船运租，江楼醉呼。","西风流落丹徒，想刘家寄奴。"]},{"t":"同邓孝威集许元锡雪庵仿康乐体","f":"古风","c":["萧晨憩高斋，水木迭清映。","绿筱卫华廊，红泉鉴明镜。","??文禽喈，噭噭羁雌竞。","结衿更褰帷，疑义互谭诤。","图史何稠华，琴尊复幽靓。","仆类次公狂，近效长卿病。","秉志协崎崟，抗怀谢尘阱。","久客四节遒，多难百忧盛。","一随彼美游，披藻奋妍咏。","曛黑宁知疲，玉衡渐西柄。"]},{"t":"从天宁寺后望迷楼蜀冈一带遗址","f":"五言古诗","c":["秋原何淡沱，荒溪奔相互。","清潭最明迥，丹嶂极修嫭。","我来驻精蓝，回飙已凝冱。","手招出泽臞，目协沧洲趣。","影堂枕独冈，塔院背双树。","丽瞩果不穷，流怀获所遇。","飒沓缭垣秋，窈窕寒塘暮。","绕郭垣陂陀，攀萝匝狐兔。","缅思仁寿年，遗踪倏成故。","忧来多颓基，乐往鲜完祚。","萧萧紫极宫，恻恻红颜墓。","坐深暝翠沈，松花落如雨。"]},{"t":"冬日过水绘园作","f":"五言古诗","c":["萧晨行散罢，沿溪恣回转。","屡听白社钟，时遇青林笕。","名园构城阿，绮阁俯荒畎。","风物果泬，襟抱况修缅。","元冬花尚开，亭午露犹泫。","繁条结危嵏，明流挂层巘。","而我伫山椒，支筇更登践。","沓嶂红灭没，回冈碧清浅。","雨歇邻塘深，日霁遥墟显。","下有古钵池，溪毛绿如藓。","皎镜一以开，生绡问谁剪。","始信境象幽，高下任遴选。","我生疲津梁，何能学淟涊。","旷识协林峦，高怀薄轩冕。","庶几和天倪，幽默获所遣。"]},{"t":"酬赠山阴张雏隐","f":"五言古诗","c":["西筝不只弹，东瑟贵双鼓。","结发慕交游，少小爱徒侣。","伊予痗夙心，烦冤甬谁语。","十月百卉腓，零露亦以湑。","灌木鸣惊禽，沙洲矫修羽。","居者遗贱贫，行者眷羁旅。","沈吟送别言，俯首泪如雨。","愿子崇景光，前修以相与。"]},{"t":"春杪同诸子饮刺梅园古松下","f":"五言古诗","c":["晨兴思出游，茫然惑所向。","或云刺梅园，景物颇萧旷。","入门苔色净，到眼杂花放。","杯来互沈吟，兴剧迭歌唱。","两年缚朝衫，小心事卿相。","同袍四五人，各各色惆怅。","春山未得归，遇酒且跌宕。","君看落红堆，下有昔人葬。","及今不作达，后此欲谁望。","老松无赖极，横若攫拿状。","我时倚酒豪，竟上骑其项。","龙鳞陡相嗔，鼓作天风浪。"]},{"t":"得桐城方尔止先生四月二十九日书感赋兼怀密之先生","f":"古风","c":["鲤鱼风打江潮利，五月荆州估船至。","船载沙门宝月师，附得枞阳故人字。","我家垩庐同鸡栖，负薪昼夜孤儿啼。","开函伸纸未及半，申胡觱栗声酸嘶。","书亦不能读，泪亦不能止。","忆昔芳华十五时，与君同作金陵子。","金陵九门门九重，白靴校尉如游龙。","贱子文名杨德祖，先君风表郭林宗。","三千宾客遨游遍，流兔飞英谁不羡。","家伎新传张敞眉，游童暗认王珉扇。","桐山诸子尽江萧，侨寓家家朱雀桥。","风暖侯家春击鼓，月明戚里夜吹箫。","樱桃小幄沉香火，杨柳藏乌门不锁。","密约呼鹰出每迟，私邀盘马期常左。","此日清流气绝尘，此时修竹弹文新。","诸王已见愁签帅，郡国还闻捕党人。","阿童江上军船动，毳帐连天驰绣鞚。","一载昭阳恨已经，两朝太学知何用？","怜我袁家一悯孙，拾橡萧萧归墓门。","君不见孙郎战没周郎老，龙眠前辈独君好。","君家尚有始兴公，卧看祗园生白草。"]},{"t":"方竹杖歌为莱阳董樵赋","f":"古风","c":["山东董樵忽见访，入门手持方竹杖。","我亦生平屠狗人，对此苍然屹相向。","董樵董樵真吾徒，胸中豪气无时无。","谈兵肯事东诸侯，作骚直学屈大夫。","翻然南下浮东吴，亦复窈窕寻仙都。","广陵城外秋风冽，黄须半作猥毛磔。","唤我同登大酒楼，此竹由来为予说。","今年三月游金华，丹梯绀壁凌朱霞。","采芝偶入乌伤地，看竹闲过卫铄家。","此竹檀栾不易得，爱之拍手徒咨嗟。","倪家女子非恒流，知有人间韩伯休。","斸来恰赠一竿竹，伴我名山禽向游。","我闻此言挥百杯，醉余不合成悲哀。","潇湘斑竹竟谁在，九疑荒冢生苍苔。","况闻官军大战胜，今年邛杖西南来。","方圆枘凿不相入，尔持此杖胡为哉？","劝君携归玉女盆前住，不尔此杖骁腾作龙去。"]},{"t":"顾尚书家御香歌","f":"古风","c":["猎猎朔风翻毳帐，营门紫马屹相向。","陈生醉拗珊瑚鞭，蹀躞闲行朱雀桁。","顾家望近尺五天，顾家父子真好贤。","开门揖客客竟入，留客不惜青铜钱。","玉缸泼酒酒初压，秦筝促柱弹银甲。","绿鬟小史意致闲，却爱微红添宝鸭。","陈生此时闻妙香，欲言不言神茫茫。","心知此香世间少，得非迷迭兼都梁？","主人重取兰膏爇，此香旧事还能说。","忆昔初赐长安街，金瓯天下犹无缺。","至尊桂殿日斋居，千首青词锦不如。","绿章夜上龙颜喜，第一勋名顾尚书。","嵯峨紫塞榆关道，白雁黄沙风浩浩。","万马奔腾夜有声，三关萧瑟春无盗。","尚书辛苦镇居延，络绎黄封赐日边。","非关小物君恩重，为许名香国史传。","镂金小盒宫门出，中涓一骑红尘疾。","亲题万颗小金丸，犹是昭阳内人笔。","只今沧海已成田，留得天香几百年。","拢来绮袖人谁问，熏罢银篝味不全。","白杨已老尚书墓，世间万事都非故。","主人语罢客亦愁，留客牵衣客不住。","君不见客衣零落讵堪论，半渍香痕半泪痕。","忍看天宝年间物，我亦东吴少保孙。"]},{"t":"送孙无言由吴阊之海盐访彭十骏孙","f":"古风","c":["具区之峰七十二，莫釐缥缈群巑岏。","吴宫废苑日萧瑟，洞庭春水空瀰漫。","狂夫七载客江表，旧游冷落增长叹。","松陵高士推顾况，谓顾茂伦。","献岁寄我云中翰。","铜坑老梅数百树，何不刺艇来盘桓。","我时正作广陵客，吴娘蝉鬓相逢难。","佛狸城畔遇孙子，大叫锲臂同追欢。","红桥丝柳酒帘挂，见此讵复愁眉攒。","无何告我渡江去，布帆径欲游盐官。","问尔作装有底急，鲥鱼正美堆冰盘。","君言一事系怀抱，越中彭十今秦观。","红牙小令风格妙，字字可付吴姬弹。","我行适越苦为此，千里那顾行蹒跚。","孙郎语竟杯已乾，陈生送客春将残。","横江估舶大笑汝，白昼浊浪生波澜。","韦庄牛峤好词句，此事何与卿饥寒。","舟行傥过王珣宅，切莫怀古心悲酸。"]},{"t":"寄赠侯叔岱","f":"古风","c":["萧萧大梁城，莽莽悲风起。","洛阳诸女儿，竞说侯公子。","侯家公子不可当，谈兵说剑声琳琅。","酒后能骑赭白马，兴酣作使邯郸倡。","睢阳城下日将夕，箭如饥鸱叫平泽。","确磝贼火动地来，两手如飞左右射。","归来犹未散鸣钟，琥珀压酒葡萄浓。","旦夕长安赐甲第，不然辟谷寻赤松。","黄河之水流不极，世间万事安可测。","男儿五十不作官，那得常常好颜色。","珊瑚之辔白玉卮，与君作歌君莫疑。","侯家公子竟憔悴，何况洛阳诸女儿。","今岁广陵城，小弟雎阳至。","谓四弟子万。","相逢蹋臂说侯生，白日明明照天地。","人言侯生狂，定识侯生乐。","斗鸡下鄢陵，呼鹰上宛洛。","余卧江东二十春，眼中知己半沈沦。","何时策马繁台去，一访当年屠狗人。"]},{"t":"宣铜垆歌为桐城方坦庵先生赋","f":"古风","c":["龙眠老人颜鬓皤，街前卖字书擘窠。","生平爱古入骨髓，玩好不惜三摩挲。","一垆温润制绝异，肌色肉好神清和。","戗金铸耳备工料，制器尚象穷雕磨。","洼隆丰杀中规格，红黄绀紫蟠雷蝌。","我时捧视肃然敬，俨若清庙陈彝牺。","音莎。","忆昔此垆始宣庙，百物充斥供搜罗。","宫闺澹泊厌淫巧，垆韝精慎无偏颇。","百金重购拟和璧，旃檀作匣犀牛䭾。","后来市估杂赝鼎，苏铸甘蔡皆幺縻。","乱真每被魍魉卖，怀宝或受蛟龙呵。","我来感旧发深喟，抚汝不异双铜驼。","一垆虽小岁月古，列圣德泽相渐摩。","我今为公作此歌，万事以往何其多。","歌成烦公书大字，明日且换山阴鹅。"]},{"t":"左宁南与柳敬亭军中说剑图歌","f":"古风","c":["宁南嚄唶大出师，军中百戏无不为。","浔阳战舰排千里，夜阑说剑孤军里。","虎头瞋目盘当中，其意自命为枭雄。","说时帐前卷秋月，说罢耳后生悲风。","军中语秘听者死，寂不闻声夜如水。","左坐一将军，右坐一辩士。","辩士者谁老无齿，魋颜摺胁丑且鄙。","得非齐蒯通，乃是柳麻子。","此翁滑稽真有神，少年趫捷矜绝伦。","青春亡命盱眙市，白发埋名说事人。","宁南置酒军中暇，爱翁说剑真无价。","横刀讵趣提汤烹，洗足宁来踞床骂。","飘零大树蔓寒烟，翁也追思一惘然。","西风设祭悲鼓越，夜雨传神倩郑虔。","感恩恋旧缠胸臆，故国无家归不得。","恶少王侯尽可怜，三更镫火披图泣。"]},{"t":"卖字翁歌为方坦庵先生赋","f":"古风","c":["龙眠老子真豪雄，一生破浪乘长风。","行年七十正矍铄，自号城南卖字翁。","雪花打门月在地，破屋槎丫矗三四。","广陵城中醉尉多，老翁自卖床头字。","韭花帖上骨格殊，春蚕锦虿光模糊。","洞庭霜柑三百颗，不数凤尾还官奴。","拦街小儿拍手笑，老翁掉头只长啸。","此翁游戏无不为，忆昔金门大隐时。","大儿扈跸五柞馆，小儿从猎黄山陲。","红墙海户奇毛净，玉粒思秋北风劲。","诏赐从官尽击鲜，羽林年少知名姓。","一朝赭衣出国门，牛车万里探河源。","破讷沙头断行迹，康居城外愁人魂。","吾闻神仙狡狯不可当，此翁亦复非寻常。","作吏但未作仆射，流官讵止流夜郎。","即今七十材力强，子孙满前身乐康。","翁起弹筝余击缶，翁亟向前掩余口。","人生万事难具陈，卖字且换东家酒。"]},{"t":"三月三日山涂豹人约同上金山修禊阴雨不果长歌纪事","f":"七言古诗","c":["三月三日风刁刁，鲸鱼跋浪声悲号。","金焦极望不可渡，连樯巨筏何坚牢。","忆昨乞食射堂下，方孙二叟还相遭。","官衙蹋臂一大噱，话旧滚滚如波涛。","五丁二酉被驱使，秦碑汉篆供爬搔。","是夜满城作寒食，鲚鱼新傅吴娘糟。","程公爱客入骨髓，意便不欲留官醪。","老兵欲睡愁我曹，负墙耳语骂老饕。","别时拦街不肯散，约我上巳离城壕。","妙高台上一片石，可以痛饮歌《离骚》。","讵料此意那便遂，恶风浊浪心烦劳。","作诗一笑报二豪，毋令怀抱长忉忉。","晴雨岂妨吾作达，誓凌阊阖扬其尻。","诘朝米尽饿不死，直须足踏金山坳。","下视人世皆秋毫。"]},{"t":"送大司马合肥公还朝长歌述怀","f":"七言古诗","c":["九秋江水平于掌，我公巨舰排空上。","柁楼被酒愿一言，历历为公叙畴曩。","忆昔鄙人甫束发，尔时长啸凌一往。","鹞子盘空陡健举，狮儿堕地飒森爽。","那知天上剩星辰，不信人间足厮养。","即云口吃善谈谐，况复肠肥工跳荡。","皇天澒洞运抢攘，从此诗书遂卤莽。","世许轻肥让后生，天留沟壑填吾党。","乍能牧豕学公孙，差许斗鸡逐袁盎。","公乎念我在泥涂，崧也作人本脏肮。","骥老宁羞刍秣恩，鹰饥不断风云想。","斯言虽狂公定赏，快若麻姑搔背痒。","歌阑万马忽然嘶，醉听催船鼓挝响。"]},{"t":"春日范龙仙前辈相约读书芝兰堂长句奉赠兼呈宋既庭李西渊金谷似王升吉钱宫声韩元少诸子","f":"七言古诗","c":["四十男儿学干谒，朝游江淮暮吴越。","漫将衣食累朱门，讵有文章动金阙。","倦游屡岁赋归欤，故人相值还唏嘘。","劝我莫作千里客，留我共读三冬书。","忆别吴阊一年久，为我糟床压春酒。","入座争迎作赋才，当筵更觅弹筝手。","酒酣慷慨唤奈何，风光一往如流波。","女坟湖北莺犹少，短簿祠南雨正多。","君家奇书一千轴，锦袱牙签光历碌。","愿随潘左伴青缃，羞与金张斗华毂。","嗟余短鬓日苍浪，太息忧来未可忘。","鼓挝马槊差亦得，若问读书非我长。"]},{"t":"开河","f":"古风","c":["前年大水庐舍没，今年无雨井泉竭。","江南江北尽开河，官司夜点开河卒。","朝开河，暮开河，河身龟坼将如何？","千夫畚锸竞邪许，淤泥堆积成陂陀。","三日开一尺，五日开十步。","监河使者河上住，虎须锦伞一何怒。","岢峨大艑谁家子，枫林祭赛刲羊豕。","船头打鼓催发船，那得河中一杯水。","官舱骂吏吏骂夫，尔曹饱饭何为乎？","河夫闻言泪双堕，家贫路远夫常饿。","君不见河乾田焦冬复春，滂沱须赖皇天仁。","缺钗淘得送沽酒，官莫枉却开河人。"]},{"t":"古歌留别季沧苇先生 其一","f":"七言律诗","c":["江头旅店一月坐，蜗涎疥壁蝙蝠大。","街泥滑滑不肯乾，夜长挛缩谁能那。","急鼓拉杂恰二更，老客羁孤刚一个。","隔县故人归未归，路长力短徒歔欷。"]},{"t":"古歌留别季沧苇先生 其二","f":"七言律诗","c":["江风吹客速如箭，车轮历碌过君县。","到门恰值君入门，失喜堕车狂欲旋。","老颠掀却头上笠，洗脚燎衣一相见。","呼朋连臂登君堂，我心明明镫烛光。"]},{"t":"古歌留别季沧苇先生 其三","f":"七言律诗","c":["昨冬堂堂岁欲徂，玉枪雪片椽烛粗。","春蚕食纸响不歇，倡予和女歌乌乌。","讵知一别即相见，陶陶孟夏重欢呼。","鸾飘凤泊辞乡国，索米不成饥亦得。"]},{"t":"古歌留别季沧苇先生 其四","f":"七言律诗","c":["主人饯客夜未终，乱鸦飒沓啼酸风。","腰下宝刀欲斫地，行间硬句真盘空。","男儿颠踣傥不死，负此一饭非英雄。","歌阑酒竭唾壶缺，大笑登车与君别。"]},{"t":"马殿闻筵上食河㹠作长句示湖中吴志伊诸子","f":"古风","c":["东风吹雨磨作丝，青鸠飞上缃梅枝。","野夫懒惰何所作，食指不动如悬槌。","朱门设食并叶我，蹒跚肯俟细马骑。","江南二月縠纹滑，雏莺才唤苟出篱。","鹅肪鸡蹠色映碗，野鲜海蚕膏流匙。","鯸鲐出水倍隽永，汁滓点滴成玻璃。","吴娘作脍攘皓腕，霍若跨马黄鲜卑。","赪盘高堆春雪乳，霜刀乱剁轻红肌。","老饕据几便啖嚼，上客辍食频嗟咨。","俱言鲑肝药人物，脱复下咽难为治。","我时放箸大嗢噱，所见毋乃诚偏陂。","诸君浙产旧滨海，鲎帆蜑雨恒迷离。","雪山一片吼蛟沫，紫飓万斛腥龙漦。","红蚶绿蛎顿顿食，鱼叉苎网家家持。","胡为睹此便瑟缩，却当属餍翻然疑。","岂逢王郎惧水厄，或误尔雅笺蟛蜞。","君不见鸣钟列鼎具五毒，藿食亦复谁期颐。","侯鲭染指讵俊物，禁脔垂涎非可儿。","羊羹熊蹯召大衅，何地不愁人命危。","我生堕地负骨格，深爪出目鳞之而。","孱躯要与麒麟斗，虫豸琐屑何能为。","幡然进七不相劝，腹腴独飨惭吾私。"]},{"t":"题梅渊公画松为愚山先生赋","f":"古风","c":["施侯沃我以绿雪，不数壑源鹰爪奇。","啜余示我一幅画，长松十丈纷离披。","牙须蚴蟉猛兕跳，鳞鬣蹙踏苍龙驰。","抹眵询问谁所作，乃克肖此形支离。","答言柏枧一诗老，两手惯放枯松枝。","五日十日画一本，波涛舂激鼪鼯悲。","昨蒙携画脱相赠，令我久看忘饥疲。","子之作诗兴颇王，亦如此翁作画时。","请为拗笔写长句，配此秃干苍茫姿。","嗟乎吾家松树老无比，三年偃蹇空园底。","何时秉耒去锄理，矮茅檐下拾松子，不尔身入画里。"]},{"t":"寄上柏乡魏贞庵先生","f":"七言古诗","c":["戊申蹑屩走碣石，公也正坐中书堂。","沙堤才下火城散，趣呼门士谭文章。","是年都城水大至，九门一望俱混茫。","忆公召饮恰七夕，浑河放溜声礌硠。","狂飙卷雨舞轩砌，树梢瓜蔓森开张。","我公挥麈坐自若，穿穴理窟雄辞场。","赋诗句必慑韩杜，阐性论足排荀扬。","顾谓小子汝可语，许汝负笈循我墙。","手书往复慰且诲，赫蹄每月盛一囊。","隆冬别公适梁宋，给我屝屦资我粮。","人生岁月算不得，破空乌兔何奔忙。","霍如庄叟快说剑，奋迅僄疾谁能当。","公归东山又十载，晞发暂驻恒山阳。","嗟予垂老倏遭际，献赋获缀鹓鸾行。","宣武门边赁老屋，与公旧邸还相望。","秋经向所命酒处，葡萄压架榴拆房。","佳节矧逢仍七夕，昔游瓜果真难忘。"]},{"t":"赠宋楚鸿","f":"五言律诗","c":["公子云间秀，才情不可当。","僧弥原是弟，公瑾尚呼郎。","赠我金条脱，随人蜡凤凰。","昨来成艳曲，流诵满平康。"]},{"t":"同梅杓司夜泊河桥","f":"五言律诗","c":["一片河桥月，经年照客舟。","不知春已尽，犹傍尔同游。","镫火烟中暝，人家水上浮。","浊醪拚醉倒，莫问大刀头。"]},{"t":"冬日过农部伯父园亭感赋 其一","f":"古风","c":["凄凄华屋事，俯仰忆生存。","红药自成路，春流直到门。","王家无虎豹，楚畹有兰荪。","已识升沈理，方从荷论。"]},{"t":"冬日过农部伯父园亭感赋 其二","f":"五言律诗","c":["赐第南山近，为园下杜偏。","小儿二千石，中妇十三弦。","缓夜弹银甲，宜春贴锦钿。","几回行乐处，战伐自年年。"]},{"t":"赠汪舟次兼怀吴野人","f":"五言律诗","c":["旅舍愁无那，浓秋把汝诗。","驿楼临水处，凉月挂城时。","更忆东淘客，吟成老泪垂。","乾坤二子在，萧飒莫深悲。"]},{"t":"雨后同卢龙孙金廓明羊月生朱嗣殷过饮刘睿生家纪事","f":"五言律诗","c":["雨脚今晨歇，翩然挈伴行。","径须谋薄醉，不可负微晴。","老屐缘村响，危桥趁涧成。","剪蔬兼斸笋，坚坐看经营。"]},{"t":"郯城","f":"五言律诗","c":["未了青才到，相看破客颜。","孤城郯子国，斜日马陵山。","柿叶遮残堠，荞花拥断关。","千秋征战地，旷望一追攀。"]},{"t":"盱眙","f":"五言律诗","c":["晓发盱眙县，烟岚极望遥。","东风吹泗水，残雪未全消。","乱岭藏山驿，微波拍板桥。","昔贤高咏处，遗迹自迢迢。"]},{"t":"圆通阁寺门即目","f":"五言律诗","c":["残城延古寺，细岸夹春塘。","寂寂落暝翠，幽幽闻野香。","花深垂钓客，竹罨浣衣娘。","趺坐少言说，吾师斋磬凉。"]},{"t":"京邸岁暮送其白弟暂返梁园即赴南昌郡幕 其一","f":"五言律诗","c":["尔到睢阳郭，多应四节除。","难沾分岁酒，差胜寄家书。","久客妻孥瘦，长贫兄弟疏。","愁悰翻倒极，白发漫盈梳。"]},{"t":"京邸岁暮送其白弟暂返梁园即赴南昌郡幕 其二","f":"五言律诗","c":["皖口还西上，庐峰紫翠偏。","江声连故国，驿路入新年。","铁树旌阳宅，红霞贾客船。","子安吟眺处，彩笔至今传。"]},{"t":"余访子建东回而王谷从朝宗西去赋寄","f":"七言律诗","c":["吴山吴水片帆开，驿使惊传江上梅。","君过侯嬴虚左待，我从宋玉大招回。","月明长水三江冷，雪满当湖万马哀。","同作征人怜更远，北风吹处一登台。"]},{"t":"赠冒巢民先生","f":"七言律诗","c":["当年镫火隔江繁，回首秦淮合断魂。","十队宝刀春结客，三更银甲夜开尊。","乱余城郭雕龙散，愁里江山战马屯。","今日凄凉依父执，乌衣子弟几家存。"]},{"t":"赠吴人陈敬仲 其一","f":"七言律诗","c":["紫蟹黄花节物新，他乡斗酒亦情亲。","樽前赖尔能吴语，泽畔怜余类楚臣。","夜月钿蝉弹法曲，秋风石燕说遗民。","江东年少休相问，七十何戡是旧人。"]},{"t":"赠吴人陈敬仲 其二","f":"七言律诗","c":["秣陵黛色接天浮，忆昔轻狂作冶游。","西曲名倡人窈窕，南朝公子态风流。","歌终绿帻楼头见，舞罢金丸袖口收。","二十余年成往事，秋槐落叶不胜愁。"]},{"t":"赠吴人陈敬仲 其三","f":"七言律诗","c":["贺老琵琶定老成，陇西门第旧知名。","百年台榭青苔没，一片江天白发生。","丝绣平原终有恨，玉为棋局岂忘情。","酒酣重说崎岖事，无数黄沙落雁声。"]},{"t":"招林茂之先生刘公㦷比部小饮红桥野园越日茂之先生赋诗枉赠奉酬","f":"七言律诗","c":["迟日和风汎绿蘋，飞花落絮罥红巾。","此间帘影空于水，何处琴丝细若尘。","池上管弦三月饮，坐中裙屐六朝人。","独怜长板桥头客，白发淮南又暮春。"]},{"t":"过广陵福缘庵瞻礼德公遗像","f":"七言律诗","c":["步屟间经占上方，岧峣金刹映寒塘。","青枫历历人千里，白月濛濛雁几行。","千古玉钩隋帝墓，一枝斑竹赞公房。","寺前正有关门水，尽日潺湲到影堂。"]},{"t":"花朝待毛亦史不至","f":"七言律诗","c":["春云千缕卷灵绡，次第风光度绮寮。","最不分明惟燕语，绝无聊赖是花朝。","芜城作客肠应断，娄水怀人信转遥。","一树辛夷开未谢，夜来微雨更潇潇。"]},{"t":"南阳怀古","f":"七言律诗","c":["古庙巍峨石兽蹲，胎簪、桐柏矗龙门。","涛冲古岸莓苔坼，派划长江竹箭浑。","四渎躬桓缠虎节，百王薪楗荐牺尊。","从来渭水称河胃，廷算深知费讨论。"]},{"t":"南阳追感彭禹峰先生","f":"七言律诗","c":["碧鸡霸府重人豪，金马都堂拥节旄。","万里丹崖凭管钥，三年彩笔杂弓刀。","苴兰质子槟榔酒，僰爨降王赤罽袍。","一自渡泸人不返，冠军城结怨云高。"]},{"t":"邺中怀旧临漳令万大士","f":"七言律诗","c":["阿兄昔作临漳宰，飞盖西园继昔贤。","铜爵砚傍春判牍，鸬鹚坡上夜回船。","五湖归隐头今白，昨夜思君月正圆。","小弟邺城长侧帽，西陵歌舞事如烟。"]},{"t":"送钱塘翁武原同知黄州","f":"七言律诗","c":["御柳宫莺媚远天，金箫玉管醉离筵。","青春佐郡名方起，彩笔题诗句可传。","两岸野花弦子国，五更新月楚人船。","黄州尔去应怀古，铁戟消沈又几年。"]},{"t":"送子万弟还黎城署","f":"七言律诗","c":["小弟朝来别我行，正逢京国逼清明。","一鞭晚宿临洺驿，三月人归上党城。","远道梦随春水阔，微官装抵柳花轻。","阿兄索米尤堪哂，可及哦松格调清。"]},{"t":"九月十九日同贲黄理田公燮登慈仁寺内毗卢阁分赋登高二韵录一","f":"七言律诗","c":["四围铃铎响刁骚，一线穿云缔搆牢。","且以登楼当戏马，何妨啜茗代持螯。","天连赵魏晴俱出，松历金元腊更高。","目断昆明池畔将，何时归镫压靴刀。"]},{"t":"春日吴阊杂诗","f":"七言绝句","c":["春欲寒时雨正浓，小楼残烛话重重。","关山兄弟飘零后，同听吴江晓寺钟。"]},{"t":"枕上口号","f":"七言绝句","c":["夜凉茉莉绽庭西，大有乡心不敢题。","谁界窗棂数行月，可堪啼煞汝南鸡。"]},{"t":"春暮杂忆和彭羡门韵","f":"七言绝句","c":["渚鸟汀花各自愁，清江一别两经秋。","东皇枉费无边绿，搓得溪头似鸭头。"]},{"t":"竹枝 其一 粤东词","f":"七言古诗","c":["番君庙后鹧鸪飞。","素馨花落蛮娘归。"]},{"t":"题虞山友人种菊图","f":"七言绝句","c":["画师不见黄公望，暖翠晴岚尚插天。","何日结邻同种菊？","溪锄对把破山前。"]},{"t":"竹枝 其二 粤东词","f":"七言古诗","c":["花田三月黎人多。","珠江无风春自波。"]},{"t":"竹枝 其三 粤东词","f":"七言古诗","c":["罗浮人家红蕉布。","谁裁郎衣侬所作。"]},{"t":"竹枝 其四 粤东词","f":"七言古诗","c":["槟榔酒酿郁林春。","郁林儿女多绛唇。"]},{"t":"二十字令 咏便面上栀子花为陆汉标赋","f":"古风","c":["纨扇上，谁添栀子花。","搓酥滴粉做成他。","凝蝉纱。","夭斜。"]},{"t":"望江南 岁暮杂忆十首 其一","f":"古风","c":["江南忆，忆得上元时。","人斗南唐金叶子，街飞北宋闹蛾儿。","此夜不胜思。"]},{"t":"望江南 岁暮杂忆十首 其二","f":"古风","c":["江南忆，最忆善和坊。","猿臂醉擎刘白堕，莺喉娇唱小秦王。","花月去堂堂。"]},{"t":"望江南 岁暮杂忆十首 其六","f":"古风","c":["江南忆，更忆是芜城。","兰叶寒塘盘马路，梨花微雨筑毬声。","风景逼清明。"]},{"t":"望江南 岁暮杂忆十首 其七","f":"古风","c":["江南忆，忆杀到如今。","白玉堂深人一笑，真珠帘暖夜千金。","十载尚关心。"]},{"t":"望江南 岁暮杂忆十首 其八","f":"古风","c":["江南忆，最好是清歈。","一曲琵琶弹贺老，三更弦索响柔奴。","此事艳东吴。"]},{"t":"望江南 岁暮杂忆十首 其十","f":"古风","c":["江南忆，不羡五侯鲭。","狎客后堂春说饼，厨娘小阁夜尝羹。","餔歠足平生。"]},{"t":"如梦令 赠友","f":"古风","c":["记得西陵小弄，风里金鞭双控。","今日又逢君，恰值春波微动。","如梦，如梦，白发何戡情重。"]},{"t":"长相思 赠别杨枝","f":"古风","c":["漱金卮，阁金卮。","不是樽前抵死辞。","今宵是别离。","撚杨枝，问杨枝。","花萼楼前踠地垂。","休忘初种时。"]},{"t":"相见欢 初夏行舟","f":"古风","c":["睡馀独自推篷，海陵东。","一带人家都住，柳丝中。","黄茆屋，清江曲，绿蓑翁。","正是雨馀斜阁，水车红。"]},{"t":"调笑令 咏古七首 其一 张女郎","f":"古风","c":["张家二女天人姿，西风秦陇吹空祠。","吴兴瘦沈美风调，邂逅一笑难为持。","客亭惝恍婵娟子，翠幰珠軿去如驶。","酒坐琴声箜篌声，姊妹双双落红水。","红水。","啼难止。","弄罢箜篌相顾起。","女郎祠掩西风里。","绣幌明帘徙倚。","兰香姨与智琼姊。","怀恨多年同此。"]},{"t":"调笑令 咏古七首 其二 汜人","f":"古风","c":["湘中蛟娣号汜人，楚天冉冉红罗巾。","一钩晓月洛桥下，风光冶丽偏相亲。","别来愁绪纷难理，鄂渚微波嬉上巳。","烟裙雾鬓惊淼茫，画舻回首人千里。","千里。","湘中水。","江面微风翻绣被。","轻别玉娥归去矣。","泪滴龙堂青绮。","十年重遘蛟宫娣。","愁绝楚天上巳。"]},{"t":"调笑令 咏古七首 其三 茝奴","f":"古风","c":["崔家女弟世所无，弹筝自命为茝奴。","重泉犹作人间曲，摧藏掩抑声嗟吁。","当时旧事心犹省，长秋一曲红窗影。","梦里曾陪元舍人，银筝凄苦人清冷。","清冷。","虚无境。","手拨银筝心自省。","长秋一曲红窗影。","弦里分明悲哽。","泉台不少人间景。","后苑君王巡幸。"]},{"t":"调笑令 咏古七首 其四 安妃","f":"古风","c":["九华安妃游玉乡，交裙携带招帝郎。","情缠双好发朗唱，紫清琐掖排银房。","杨羲自是神仙子，不比人间许长史。","左宫亦有王夫人，红颜调笑斟琼醴。","琼醴。","调芳旨。","天上风流聊复尔。","杨家自是神仙子。","双笑欢兼昔旨。","一幅青书鸾凤纸。","为授真妃灵纪。"]},{"t":"调笑令 咏古七首 其五 刘丽华","f":"古风","c":["通波亭畔风日清，会稽王子愁经行。","中流佚女遘烟舫，波光脸态交盈盈。","风吹裙带红丝缠，箜篌歇拍声声颤。","西轩夜静月又低，春条为尔歌宛转。","宛转。","羞相见。","月白风清人婉娈。","洛灵罗袜来波面。","良夜随郎游衍。","小婢箜篌歌又颤。","徙倚春流都遍。"]},{"t":"调笑令 咏古七首 其六 蔡家娘子","f":"古风","c":["西堂花茵侬好持，此间风月堪咏诗。","溢奴小儿若冰雪，紫缓绿酒饶神姿。","竟陵判司大懊恼，夜寒空馆眠难好。","翠簪腻滑促传觞，口吃微闻唤鸾老。","鸾老。","头脑好。","善谑群真堪绝倒。","夜寒空馆人声悄。","地下为欢须早。","南邻娘子翘翘小。","共泛玻璃清醥。"]},{"t":"调笑令 咏古七首 其七 瑶芳公主","f":"古风","c":["槐安贵主名瑶芳，秾春游戏摇鸣珰。","相牵贪看石延舞，寺前暗调淳于郎。","兰摧玉折一何苦，青春又葬同昌主。","淮南裨将惯酒悲，恸哭繁华黯无语。","无语。","奈何许。","忆在寺门魂暗与。","布衣真尚瑶芳主。","一霎日斜归去。","大槐安国飞红雨。","肠断旧游何处。"]},{"t":"点绛唇 咏枕","f":"古风","c":["忆得年时，红绵妆叠红蕤滟。","笙囊绿掩，浓笑钗痕闪。","说尽山盟，不料巫云敛。","残荷燄，斜铺楚簟，多了啼红点。"]},{"t":"女冠子 本事二首 其一","f":"古风","c":["黄絁剪就，慵上鸳机刺绣。","镇葳蕤。","水绿青溪庙，花红白石祠。","愔愔春似梦，漠漠雨如丝。","仙洞胡麻熟，有谁知。"]},{"t":"女冠子 本事二首 其二","f":"古风","c":["始青天上，小织龙绡几两。","路茫茫。","度海云鬟乱，还宫绣带长。","琼枝春袅袅，金磬夜琅琅。","拨尽天风曲，说兴亡。"]},{"t":"浣溪沙 赠王郎","f":"七言古诗","c":["十五吴儿渲额黄，鹅笙炙罢口脂香。","依稀记是小王昌。","未解褰帘通暗语，已能映柱恼回肠。","个侬年纪未须防。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其一","f":"古风","c":["流苏小揭人初起，博山烟袅屏风里。","红日映帘衣，梁间玉剪飞。","回眸惊瞥见，笑倚门中扇。","准拟嫁文鸯，灯花昨夜双。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其二","f":"古风","c":["象牙局上金星吐，香闺戏博红鹦鹉。","深院对挑棋，厌厌春昼迟。","娘输笼玉手，佯靠纱窗口。","细撚柳绵儿，花冠报午时。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其三","f":"古风","c":["银河斜坠光如雪，碧虚浅浸天边月。","月色太婵娟，行来刚并肩。","阑干浑倚倦，小漾裙花茜。","风细语难闻，亭亭双璧人。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其四","f":"古风","c":["后堂恰与中门近，当时日傍飞蝉鬓。","犹记捉迷藏，水晶庭院凉。","侍儿前后逻，何计将他躲。","匿笑颤花枝，鞋尖露一丝。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其五","f":"古风","c":["回廊碧甃芭蕉叶，鸭垆瑞脑薰犹热。","春笋抱琴弹，一行金雁寒。","声声松宝串，弹到昭君怨。","促柱鼓潇湘，风吹罗带长。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其六","f":"古风","c":["秦淮水阁多斑竹，平康院院烧灯读。","竹响似行人，檀郎回顾频。","恰逢红粉面，送茗来琼扇。","刚是早回头，夜深侬睡休。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其七","f":"古风","c":["梨花簌簌飞红雪，狸奴夜扑氍毹月。","物也解雄雌，教奴恣意窥。","潜踪殊未惯，猛被萧郎看。","羞走晕春潮，门边落翠翘。"]},{"t":"菩萨蛮 题青溪遗事画册同邹程村彭金粟王阮亭董文友赋八首 其八","f":"古风","c":["桃笙小拥楼东玉，红蕤浓亸春鬟绿。","宝篆镇垂垂，珊瑚钩响时。","花阴瑶屈戍，小妹潜偷觑。","故意绣屏中，剔他银烛红。"]},{"t":"菩萨蛮 江行二首 其一","f":"古风","c":["东风吹绿江南道，行人却说江南好。","红豆两三枝，低垂圣女祠。","渌波明似眼，来往人何限。","斜日运租船，西风跂脚眠。"]},{"t":"减字木兰花 渡江宿弟斐玉家","f":"古风","c":["江南江北，握手相看那易得。","今夜重逢，翠筱黄花伴烛红。","浮杯大嚼，顾我何如家弟乐。","车马湖边，明日西风绝可怜。"]},{"t":"减字木兰花 广陵旅邸送三弟纬云南归","f":"古风","c":["佛狸城下，兄弟禅房通夜话。","红土山头，兄往吴陵弟亳州。","一鞭春暮，重过竹西三日住。","江上斜晖，弟作归人兄未归。"]},{"t":"减字木兰花 送四弟子万","f":"古风","c":["前年飞絮，我到故园君已去。","今岁青山，君又南行我未还。","吴云郢树，泪洒临歧无一语。","再唱离歌，六幅蒲帆奈汝何。"]},{"t":"减字木兰花 送五弟阿龙","f":"古风","c":["阿龙最小，失母随兄偏了了。","四岁离乡，今日重逢断我肠。","阮家姑母，犹子情深思汝久。","此去相依，莫以怀吾泪湿衣。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其一","f":"古风","c":["天涯飘泊，湖雨湘烟无定著。","暗数从前，汝嫁黔娄二十年。","当时两小，乐卫人誇门第好。","零落而今，累汝荆钗伴藁砧。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其二","f":"古风","c":["余年二十，粗晓读书兼射猎。","三十蹉跎，鼓瑟吹篪奈若何。","堪怜阿堵，垂老讵曾亲识汝。","沟水东西，何用男儿意气为。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其三","f":"古风","c":["今年离别，石畔梅花开似雪。","骏马驰坡，又见流光换碧罗。","归鞍暂息，看汝机边还作织。","秋月当头，重附租船江岸游。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其四","f":"古风","c":["地名破冢，郭璞墓前波浪汹。","细剔银缸，话尽秋宵角枕凉。","橘红橙绿，九月敬亭山畔宿。","水鸟斜飞，又逐孤篷一夜归。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其五","f":"古风","c":["曲阿湖上，重看縠纹平似掌。","及到邗沟，丝雨斜风水驿愁。","败荷衰柳，且罢程邮红玉酒。","群盗如毛，月黑邻船响箭刀。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其六","f":"古风","c":["吴霜点鬓，客况文情都落尽。","检点行装，泪滴珍珠叠满箱。","并州曾到，也拟开怀还一笑。","尘务相牵，执手云郎送上船。"]},{"t":"减字木兰花 岁暮灯下作家书竟再繫数词楮尾七首 其七","f":"古风","c":["客船风雨，冷雁湿猿齐夜语。","欲作家书，腹转车轮一字无。","经年如此，愁里光阴能有几。","预报归期，又在梅开似雪时。"]},{"t":"柳含烟 本事","f":"古风","c":["灵和柳，弄晴春，轻飐江南绿水。","东风陌上又河边，得人怜。","乱搭琼楼丝一把，故与玉郎牵惹。","而今香絮滚斜晖，几时归。"]},{"t":"好事近 坐姜家墩怀吕黍字","f":"古风","c":["闲坐竹林边，绿暗暮禽啁唽。","跂脚科头笑傲，更主人投辖。","万竿丛筱昼阴阴，风动声敲戛。","忆昔悲歌痛饮，有疏狂吕八。"]},{"t":"荆州亭 题扇上琵琶行图","f":"古风","c":["苦竹黄芦想像，湓浦浔阳怊怅。","半幅小丹青，画出东船西舫。","白傅青衫已往，商妇琵琶犹响。","无限断肠声，只在行间纸上。"]},{"t":"眉峰碧 春夜见新月","f":"古风","c":["宝马萦帘押，金斗薰珠袷。","一团醉玉怯春寒，斜向红裯压。","无语抛银甲，且自偎香鸭。","半钩纤月柳梢头，问谁偷把青天搯。"]},{"t":"武陵春 舟次虎邱","f":"古风","c":["四面吴山争窈窕，浓绿罨归舟。","寺外人家桥上楼，春水尽情流。","主簿祠前斜日漾，惹起旧时愁。","石上苔痕青未休，曾做少年游。"]},{"t":"阮郎归 为灵雏题画","f":"古风","c":["吴绫一幅滑如脂，江南好画师。","长松几树碧离离，斜添斑竹枝。","烟似水，雨如丝，梅花帘外垂。","更题半阕断肠词，樊川杜牧之。"]},{"t":"桃源忆故人 人日感旧","f":"古风","c":["画帘垂处春光乱，百感最难消遣。","记得风斜彩燕，小立珍珠院。","岁华又到黏鸡宴，砌下春兰尚浅。","人日春人不见，日近人儿远。"]},{"t":"桃源忆故人 春日过澹生校书所居旧址","f":"古风","c":["酒阑曾过平康宿，风飐绣帘簌簌。","红板桥连西曲，微雨樱桃熟。","而今风景伤春目，不见沿溪花竹。","荠麦平畴摇绿，蛱蝶和烟逐。"]},{"t":"摊破浣溪沙 雨泊秦邮","f":"古风","c":["十顷盂湖碧似烟，四围蒲稗水连天。","渚鸟群飞声格格，戏长川。","独对烟波思往事，那堪风物又残年。","且贳秦邮城下酒，拨湘弦。"]},{"t":"摊破浣溪沙 冬闺","f":"古风","c":["绮疏六扇掩玻瓈，花影罘罳漾衵衣。","学绾翻荷新样髻，日将西。","有恨篝前银鸭睡，无情筝上钿蝉啼。","独对水仙花絮语，太悽迷。"]},{"t":"朝中措 平山堂怀古用欧公原韵","f":"古风","c":["我来吊古傍隋宫，板渚雨濛濛。","依旧平山堂外，淡烟疏柳长空。","年年此地，漫天榆荚，著地东风。","太息韶华几换，游人犹想仙翁。"]},{"t":"海棠春 闺词和阮亭原韵四首 其一","f":"古风","c":["春闺金麦微微响，青凤胫、轻移银网。","睡眼恰初瞤，一片红酥漾。","邻姬眉黛遥山样，怪昨日、邀侬相赏。","遮莫绣帘前，有个人张敞。"]},{"t":"海棠春 闺词和阮亭原韵四首 其二","f":"古风","c":["惺忪春梦何时足，拚昼掩、银屏六曲。","绣倦歇鸳针，藏在沈香褥。","藕花衾压桃花肉，微睡醒、低呼小玉。","何处弄琮琤，似戛潇湘竹。"]},{"t":"海棠春 闺词和阮亭原韵四首 其三","f":"古风","c":["韩冯啄破秋千影，琼扇里、春酲初醒。","半晌卸金虫，小试兰汤冷。","后堂憎杀青铜镜，怕照见、云鬟未整。","莫道少人窥，天上堆金饼。"]},{"t":"海棠春 闺词和阮亭原韵四首 其四","f":"古风","c":["红蕤枕上啼红雨，且坐听、玫瑰双杵。","纤手剔兰煤，楼外宾鸿语。","马蹄连夜堂堂去，偏无赖、三更谯鼓。","难捉是萧郎，不比床头麈。"]},{"t":"海棠春 题美女图为闺人称寿","f":"古风","c":["智琼年小逢珍偶，多少事、灯前酒后。","夜合自开花，摇动珠帘口。","檀奴戏觅南朝手，图倩女、为娘称寿。","一笑溜横波，媚靥红于酒。"]},{"t":"眼儿媚 过城南小曲感旧","f":"古风","c":["青楼斜拂小春池，池上绿杨枝。","态奴歌管，念奴弦索，唱尽新词。","重来行过章台弄，往事少人知。","半湖碧浪，满园斑竹，万种凄其。"]},{"t":"三字令 闺情","f":"古风","c":["红蕤枕，卓金车，两相于。","酒醒后，梦来初。","挽郎祛，郎欲去，且徐徐。","烦塞马，倩江鱼，寄他书。","休信宿，莫踌躇。","锦鸡城，金雁驿，是郎居。"]},{"t":"极相思 夜饮友人所阿云待余不至留词而去归后和之","f":"古风","c":["如尘如梦如丝，脉脉意谁知。","归来恨晚，休摇屈戍，慢叩罘罳。","一阵碧虚窗外雨，三通鼓，人去多时。","空留彩句，蜜花笺淡，凤胫灯攲。"]},{"t":"西江月 咏史","f":"古风","c":["姊嫁猘儿孙策，妹归顾曲周瑜。","雀台高处瞰三吴，羡尔清歌妙舞。","一望江东人物，孝廉枉逞雄图。","朱桓前捋大王须，文有才高子布。"]},{"t":"西江月 过投金濑怀古","f":"古风","c":["有女江头击絮，何人道上吹篪。","我来吊古怅空祠，旷望几重云水。","覆楚争誇伍相，沼吴又说西施。","淮阴往事亦如斯，成败皆由女子。"]},{"t":"西江月 题六合孙公树捧书图","f":"古风","c":["李白开元供奉，当年恩礼偏隆。","赐书稠叠出深宫，玉轴牙签郑重。","绝妙文孙才调，翩翩王谢门风。","捧来乱帙悉当胸，月落华清如梦。"]},{"t":"偷声木兰花 怀戴无忝客成都","f":"古风","c":["前年建业秋将暮，今岁蚕丛春又去。","别后思君，望尽南天不见云。","竹郎祠畔红棉好，濯锦江头红鲤少。","湘雨巴烟，不寄成都十样笺。"]},{"t":"茶瓶儿 咏茗","f":"古风","c":["绿罨苕溪顾渚，拍茶妇、绣裙如雨。","携香茗，轻盈笑语。","记得鲍娘一赋。","邀陆羽，煎花乳，红闺日暮。","玉山半醉绡帏护，且消酪奴佳趣。"]},{"t":"忆秦娥 梦至石城盘马觉后赋此","f":"古风","c":["桃花埒，依稀醉犯青溪雪。","青溪雪，草头一点，玉骢明灭。","骠骑桁前人欲别，锦衣仓后钟初绝。","钟初绝，一场春梦，晓莺时节。"]},{"t":"忆馀杭 东皋客舍待毛亦史不至","f":"古风","c":["一树梅花千顷碧，耐尽春寒眠不得。","閒愁如雨雨如愁，点点在心头。","飘零心事谁知道，又是天涯寒食到。","春江尽处是娄江，目断水云乡。"]},{"t":"醉花阴 重阳和漱玉韵","f":"古风","c":["满院黄花趖白昼，丝雨筛铜兽。","今夜是重阳，不捲珍珠，阵阵西风透。","一从秋怨关心后，泪黦轻罗袖。","生怕小楼寒，慢去登高，坐到垆烟瘦。"]},{"t":"雨中花 雨中看桃花","f":"古风","c":["丝丝春雨催侬去，依依人柳留侬住。","住也无聊，去还有恨，去住浑无据。","今岁桃花千百树，去年人面应非故。","万点胭脂，一行清泪，总是消魂处。"]},{"t":"雨中花 咏薰笼","f":"古风","c":["一架红篝凉似水，相偎靠、玲珑莫比。","斑竹无尘，疏篁偏瘦，小鸭中间睡。","纵向彤奁多转徙，也只在、帘前被底。","绣幔萦时，锦鞋阁处，往事难提起。"]},{"t":"鹧鸪天 赠吴中狎客","f":"古风","c":["白帽红靴态可怜，短箫横笛兴翩翩。","曾教锦瑟房中曲，惯请朱门灞上田。","人似月，夜如年，何须彩笔赋甘泉。","朝来蜡泪堆红雨，犹拥庐儿醉意钱。"]},{"t":"鹧鸪天 秋日拨闷作","f":"古风","c":["一派凉秋似镜湖，西风萧瑟雁衔芦。","楼头竹暗晴难妥，枕底橙香酒易酥。","伤老大，笑髯癯，霜红露白转踌躇。","鳆鱼苦笋拦街贱，不见钳奴并态奴。"]},{"t":"摘红英 咏落花","f":"古风","c":["真珠络。","仓琅钥。","如尘似梦连天落。","香车暝。","朱阑凭。","留他不住，唤他不应。","花前约。","春前诺。","玉娥含泪思量著。","黏犀钉。","铺鸳径。","憎他荡子，怜他薄命。"]},{"t":"南乡子 咏春兰","f":"古风","c":["三月玉街寒，锦雨丝丝不肯乾。","飘得卖花声到了，春兰。","一种清芬胜麝檀。","对此忆家山，手折红苕不忍看。","还记那年寒食夜，幽欢。","人在花香鬓影间。"]},{"t":"玉楼春 生日邀陆景宣崔不雕饮广陵酒家醉后题壁","f":"七言律诗","c":["天涯作客伤心极，广陵花月无消息。","百钱且上酒家楼，终当埋我陶家侧。","此儿自是难衣食，相逢幸是曾相识。","左呼陆厥右崔骃，四十今年余竟得。"]},{"t":"虞美人 渡江","f":"古风","c":["白蘋花尽凋寒玉，舴艋摇空渌。","秋潮恰比簟纹平，趁此日斜风细、剪江行。","最怜黄歇坟头土，多少今和古。","年来生怕说兴亡，笑指楚天新雁、两三行。"]},{"t":"虞美人 咏镜","f":"古风","c":["香奁凉鉴蟠金兽，背压蛟螭钮。","玉人偏妒小菱花，惯是团圆两字、不如他。","翠鸾莫道心如铁，春笋曾提挈。","红尘涴处奈他何，我亦受人怜惜、为人磨。"]},{"t":"夜行船 月下汎舟水绘园同冒巢民先生赋","f":"古风","c":["兰桡轻点春流碧，蘸垂杨、丝丝无力。","百顷簟纹，一泓香黛，人在短篷吹笛。","更爱月华墙上白，影娥池、水禽飞拍。","醉吸玉鳞，狂呼霜兔，可认骑鲸仙客。"]},{"t":"醉落魄 春夜微雪","f":"古风","c":["春闺日暮，轻寒已著樱桃树。","博山小篆飘香缕。","斜掩青楼，一阵销魂雨。","夜深珂雪偏难住，金尊小泛兰陵醑。","酒红渐入香肌去。","懒剔金荷，细对菱花语。"]},{"t":"踏莎行 舟次河桥","f":"古风","c":["别酒才醒，离程乍远。","兰桡斜阁烟中饭。","霜华昨夜湿银篝，夜深记有人低唤。","肠断难禁，魂销何限。","邻舟商妇筝声换。","一分明月照河桥，桥头船里愁千万。"]},{"t":"踏莎行 咏帐钩","f":"古风","c":["玉色无痕，粉光欲砑。","一生管住春风罅。","纱幮凝望碧如烟，怜伊荡漾何曾挂。","颤处轻盈，控来低亚。","流苏络在银毬下。","月明风细渐琮琤，依稀似说春宵话。"]},{"t":"虞美人 春夜舟行","f":"古风","c":["红泉碧杜殊清丽，白舫纱窗闭。","春江人在镜中行。","船楼凤胫一枝横。","梦难成。","渔蛮踏浪寻村酒，烂醉歌铜斗。","虾笼湾口赛黄牛。","三更珠露湿船头。","似清秋。"]},{"t":"七娘子 春闺","f":"古风","c":["红檠斜照人无语，圆冰对漾春无绪。","陌上莺啼，梁间燕乳，梦中怕到销魂处。","小楼春色留难住，斜桥春水流将去。","三月时光，一年节序，水晶帘外廉纤雨。"]},{"t":"临江仙 偶作","f":"古风","c":["忆在冶城公膝下，围棋年少知名。","石头儿女本轻盈。","象床春纵博，珠袷夜弹筝。","倏忽过江门第换，沧桑飞渡群伧。","吴霜点鬓不胜情。","案头无鬼论，肘后净名经。"]},{"t":"临江仙 酬赠崇川陶月峤床","f":"古风","c":["四十男儿方坠地，家声列戟风流。","翩翩挟弹少年游。","兄居长乐尉，主尚富平侯。","讵料蹉跎空老大，逢君楚尾吴头。","酒阑话向北风愁。","无家徐仆射，有泪白江州。"]},{"t":"蝶恋花 纪艳十首 其一","f":"古风","c":["刘氏三娘双姊妹。","生小繁华，家住鸡鸣埭。","梵字阑干花影碎，妆楼恰与春波对。","两小后堂曾博簺。","阿母帘前，此日教重会。","传语翾风空至再，蝉钗只靠秋千背。"]},{"t":"蝶恋花 纪艳十首 其二","f":"古风","c":["帘外桐花闲弄影。","不便相辞，悄语传声请。","犹自眉峰烟不定，避人奁内添宫饼。","说道今宵天色冷。","且自留停，莫撼猧儿醒。","珠斗斓斑斜又整，人间第一消魂景。"]},{"t":"蝶恋花 纪艳十首 其三","f":"古风","c":["犀蒜银钉红玉槅。","小小帘栊，不与金堂接。","斗草又慵弹阮怯，邀郎今夜抛金叶。","百子枝花香粉浥。","兰是桩家，好把豪犀厌。","小负红潮生两颊，绐郎博进惟榆荚。"]},{"t":"蝶恋花 纪艳十首 其四","f":"古风","c":["凉夜金街天似洗。","打叠银篝，薰透吴绫被。","作剧消愁何计是，鬓丝扶定相思子。","对漾红绳低复起。","明月光中，乱捲潇湘水。","匿笑佳人声不止，檀奴小绊花阴里。"]},{"t":"蝶恋花 纪艳十首 其五","f":"古风","c":["栀子帘前斟鹊脑。","隔著屏山，爱听银筝好。","唱尽红盐人不晓，依稀记是萧郎稿。","偷得新声三两调。","悄学春莺，唇绽樱桃小。","银蒜轻摇郎到了，和羞吹灭兰缸早。"]},{"t":"蝶恋花 纪艳十首 其六","f":"古风","c":["亚字阑干花一朵。","每到花朝，春梦偏难妥。","女伴相携争婀娜，迷藏小捉妆楼左。","鬓枣微松蝉翼亸。","怕有人窥，轻合黄金锁。","戏罢偎人苔砌坐，日移交网花阴簸。"]},{"t":"蝶恋花 纪艳十首 其八","f":"古风","c":["一带红墙刚六幅。","忽听箫声，欲断还将续。","知是东邻吹凤竹，邀来教弄相思曲。","风起落花红簌簌。","香睡猩绒，小印琅玕束。","故说玉人吹未熟，明朝重到黄金屋。"]},{"t":"蝶恋花 纪艳十首 其九","f":"古风","c":["年少双文能劝酒。","笑折花枝，今夜为郎寿。","红烛厌厌笼翠钮，饮深忘却春宵久。","若下乌程春酿厚。","却笑佳人，腰似三眠柳。","明日绿纱窗外走，手摇屈戍妆成否。"]},{"t":"蝶恋花 纪艳十首 其十","f":"古风","c":["满院姊归啼恻恻。","隔著中门，怅望游丝织。","讯至方知娘小极，潜来小揭蜻蜓翼。","怕响金梯行不得。","半晌徘徊，才到菱花侧。","立久微闻轻叹息，春阴帘外天如墨。"]},{"t":"蝶恋花 春闺同周文夏赋","f":"古风","c":["芳草萋萋人脉脉。","绿遍东西，不空南和北。","满院春晴无气力，海棠花下挨时刻。","惆怅去年逢玉勒。","酒市红桥，此际曾相识。","往事不堪重忆得，饧箫阵阵催寒食。"]},{"t":"唐多令 广陵上巳","f":"古风","c":["板渚柳枝横，津楼酒旆轻。","旧繁华、犹记芜城。","正是秾春逢上巳，多少事，丽人行。","年少爱风情，红妆识姓名。","杜紫薇、此地曾经。","今日鬓丝真老大，和燕子，语平生。"]},{"t":"摊破丑奴儿 纪艳","f":"古风","c":["隔帘挼碎相思苣，斜著乌云。","漾著红巾。","袅袅亭亭一段春。","是耶，难道是、昨宵人。","戟门阖却葳蕤锁，花气氤氲，月色缤纷。","墙角猧儿吠夜分。","非耶，谁道是、昨宵人。"]},{"t":"渔家傲 宣城道上","f":"古风","c":["古木丛祠山径细，野花斑竹黏天际。","萧瑟峥泓谁可拟。","墟烟起，家家水驿门斜闭。","三秋摇落悲游子，一鞭自袅西风里。","歇马溪桥人乍倚。","樵夫指，麻姑大好朝来髻。"]},{"t":"渔家傲 闻西樵方为京口三山之游却寄","f":"古风","c":["晴日南徐风景异，蒲帆饱趁春涛驶。","一片江山千古事。","同儿戏，伯符志业何曾遂。","月下租船人咏史，使君大有淩云气。","满目茫茫愁对此。","横笛里，妙高台上吹新水。"]},{"t":"定风波 怀颍川刘公㦷，记与茂之、公㦷小饮红桥，几一年矣，故有此作","f":"古风","c":["昨岁行歌古竹西。","广陵三月柳绵飞。","谁更扶筇郊外走。","林叟。","开元遗事说依稀。","时序飙流惊又换。","春半。","风光虽似旧游非。","绿到江南清颍尾。","春水。","潺湲好为寄相思。"]},{"t":"醉春风 艳情","f":"古风","c":["月暗兰缸冥，风细花阴冷。","紫茸帐底拍萧娘，醒。","醒。","醒。","良夜难逢，幽欢可惜，休教酩酊。","活火初烹茗，宝篆犹生鼎。","红妆枕畔语檀郎，等。","等。","等。","城上人行，笼中鸟唤，如何便肯。"]},{"t":"青玉案 咏糟蛏","f":"古风","c":["春酲未析三更后。","橙片切、莼丝糅。","食品厨娘偏解斗。","滑应凝盌，松难胜齿，几瓣嫣红透。","金刀小向霜天剖。","越衬出、春纤消瘦。","捧处红糟先欲溜。","小姬无语，老饕狂叫，把与梅同嗅。"]},{"t":"青玉案 咏油车螯","f":"古风","c":["击鲜海错金盘泻。","绝称是、春寒夜。","轻点吴酸魂已化。","和酥为卤，带脂成酿，二月花前榨。","生平斫鲙兼行炙。","枉行遍、屠门蟹舍。","风味似伊休论价。","差宜下酒，雅堪斗茗，携向江南诧。"]},{"t":"青玉案 咏醉白虾","f":"古风","c":["半笼春水溶如镜。","早倾向、金盘净。","一片空明娇掩映。","霜鬐半呷，雪肌半挺，似带春酲病。","寻常虾菜空相竞。","谁解得、高阳心性。","细忆风姿心自省。","十分酒气，三分生气，羞与侯鲭并。"]},{"t":"隔浦莲近拍 饮小三吾亭前古梅下","f":"古风","c":["今朝秾春天气，袨服为佳耳。","人在梅根冶，暗香疏影迢递。","盏内红生，杯中绿汎，小吸宜城蚁。","消魂死。","那人蛾绿，料应玉貌如此。","难凭春驿，折寄一枝千里。","横笛谁吹东风起。","生怕玉鳞，飞著春水。"]},{"t":"风入松 上巳后二日洗钵池汎舟即事同亦史山涛赋","f":"古风","c":["蜻蛉小泊断桥东，人在橹声中。","水面残霞飞不定，春波静、暝翠玲珑。","夹岸缃桃斑竹，半船淡月微风。","纱窗尽摘簟纹融，心事暗惺忪。","小拂丝杨人语细，春衫碧、恰似新桐。","可惜小浯溪上，明朝更与谁同。"]},{"t":"祝英台近 咏橘","f":"古风","c":["水濛濛，烟袅袅，红遍江南树。","小陆怀中，数颗偏怜汝。","笑他梅子心酸，莲儿心苦，都让尔、甘芳如许。","憎悽楚。","记得解橘春纤，指冷偎人处。","一别吴娘，往事浑无据。","自从那日传柑，几番元夜，总则是、泪珠如雨。"]},{"t":"红林檎近 咏佛手柑","f":"古风","c":["芳树来瓯越，名同吴下柑。","风调轶橙橘，芳华擅闺襜。","玉人夜凉酒醒，怪底薰透红衫。","此际宝鸭休添，香气十分沾。","月底偏濯濯，枕畔故掺掺。","佳人笑说，雪山花瓣曾拈。","自尘情未断，佛犹如此，合掌长思伴玉纤。"]},{"t":"蓦山溪 天穿节次葛鲁卿韵","f":"古风","c":["晓寒侧侧，绣户凉如水。","灯市火初收，不十日、春喧北里。","都城士女，结队踏天穿，珠络鼓，画楼旗，漾在东风里。","江南词客，生长烟花地。","可惜是秾春，最难忘、梦华遗事。","倚阑怊怅，暗里忆当年，新雨后，板桥西，那处人家醉。"]},{"t":"蕙兰芳引 咏木瓜花","f":"古风","c":["绿水人家，有一树、垂垂红雪。","瘦影亚雕阑，啼尽春禽百舌。","玉娥睡醒，问何处、麝兰偷泄。","恰侍儿报道，枝上名花才结。","记得良人，曾经渍粉，去秋时节。","叹虽有好香，不比此香清绝。","那知花朵，一般芳冽。","爱清芬、莫对傍人轻说。"]},{"t":"蕙兰芳引 洗钵池中有赠","f":"古风","c":["客里无憀，瞥见处、绣帘斜轴。","恰暮雨潇潇，低唱伤心人曲。","相逢却扇，板桥西、数枝春竹。","正笼中鹦鹉，叫醒一窝红玉。","携上吴装，一声欸乃，碧天如沐。","爱香藕花轻，偏打向船窗簌簌。","娇歌妙舞，明眸曼睩。","记昨宵、水色半城都绿。"]},{"t":"早梅芳近 咏玉蝶梅","f":"古风","c":["整偏佳，斜更好，风格那能到。","粉笺欲赋，除是多才李清照。","亭亭情意厚，袅袅腰肢小。","正入春阴重，白处妆楼晓。","梦无凭，愁不了，从古江南道。","天寒日暮，此意惟花堪共表。","文犀慵再掠，金鸭羞轻抱。","撚梅花，今年驿使杳。"]},{"t":"簇水 春雪","f":"古风","c":["有影无声，小楼一夜堆琼稷。","撒盐萦絮，舞遍天涯六出。","最爱轻松纤软，雅称红闺客。","遮不住、空青帘翼。","春阴积。","怪此际、晓寒何重，围红兽、偎窗隙。","楼前莫管，一任腾腾瑟瑟。","且瀹鲍家香茗，雪水倾来白。","红日照、消入一池深碧。"]},{"t":"步月 本意","f":"古风","c":["小市门东，板桥巷北，暗中瞥见芳姿。","明眸腻脸，夜静漾帘衣。","碧柳映、几层衫子，红蕖露、一辆鞋儿。","斜靠著、江梅一树，刚到半开时。","铜驼街又敞，奈珠屏似水，此恨谁知。","弄春纤、香橙代解，回秋水、罗帕亲携。","归去也，一钩春月水仙祠。"]},{"t":"鱼游春水 春阴闺思","f":"古风","c":["尽日香闺悄，才縆额东风料峭。","可惜红芳，如此匆匆过了。","做暝遥天浑似墨，妆阴野水愁难晓。","独对菱花，横波淼淼。","惆怅更谁知道。","漫消受、绿篝烟袅。","何日剪破层阴，依然春好。","料得藁砧愁远泊，也无灯火来相照。","怪底今宵，黄昏偏早。"]},{"t":"宣清 春夜闻雁","f":"古风","c":["春夜红蕤枕，怪宾鸿月底，哀鸣如昨。","惹青衫泪甚时乾，引红闺睡何曾著。","记得当初，楚天烟水，碧湘楼阁。","搀玉轸，和金徽，自分西风冷落。","一霎年光，又逢春社，万里乡心作。","忆淼淼萧关，茫茫沙漠。","故园归欤行乐。","花柳江南，尽让他、莺啼燕掠。"]},{"t":"法曲献仙音 寄严览民钱宝汾顾华峰三舍人","f":"古风","c":["蜀肆先生，汉家夫子，新谒帝承明殿。","最喜金闺，璧人联辔，吴郡顾荣挥扇。","更惊闻，三株树，钱起湘灵怨。","人传遍。","思往日、江东婉娈，红烛下、挟瑟鸣筝公宴。","讵料凤凰池，三子者，一时妙选。","十里朱帘，争看煞、黑头王椽。","只淩云一赋，杨意何时方荐。"]},{"t":"东风齐著力 花朝","f":"古风","c":["春困初浓，春愁难妥，又是花朝。","虾须半轴，蛾绿不曾描。","记得去年玉勒，相逢在、丝雨长桥。","秋千社，绣旗不定，画鼓频敲。","流水渌迢迢。","人不见、妆成知为谁娇。","秾春病酒，双脸印红潮。","欲借鸳机论恨，回文字、带泪斜挑。","肠断也，百花生日，只是无聊。"]},{"t":"绛都春 咏蛱蝶","f":"古风","c":["谁家佛助，想一缕裙花，做成红雨。","青草如烟，渌水如罗，被阵阵东风，吹向晴空舞。","又傍平芜来去。","桃花门巷，菜花天气，轻狂无数。","娇嫭。","留他不住。","更砌畔濛濛，墙头栩栩。","飘零荡漾，一春梦里曾如许。","料伊也为多情误。","只愁扑蝶园中，痴憨儿女。"]},{"t":"满江红 怅怅词五首 其一","f":"古风","c":["咄汝青衫，奚不去、白杨荒漠。","叹是处、病兰不笑，瘦琴空削。","邺酒红来心久死，越娘紫去怀长恶。","猛耳酣、追忆玉笺河，惊流落。","东箫屐，西纨芍。","北金谷，南铜雀。","只词流骚艳，供伊谈噱。","百不怜人游猎赋，一生误我灵光作。","向要离、冢上以呼余，余曰诺。"]},{"t":"满江红 怅怅词五首 其三","f":"古风","c":["腰綵唇朱，浑妆就、腐儒花靥。","堪喷饭、骚肠赋骨，也来帖括。","儿辈不关诗酒事，乃公偶堕文章劫。","看他年、百队罽如霞，夔州猎。","缃千卷，浇元蝶。","螺千缚，漂丹蜐。","也扶风歌弹，陈留花镊。","栀子街前捎粉盗，凤凰桥下薰香侠。","更偏军、夜绕甑山城，师常捷。"]},{"t":"满江红 怅怅词五首 其四","f":"古风","c":["一亩书斋，白杨树、今番满矣。","想十载、墨池滋味，不过如此。","芍药风流可赐绯，丁香年少宜衣紫。","问奚为、蹀躞鹔鹴桥，无聊子。","箫欲哭，红冰玺。","琴欲笑，元霜蕊。","叹骚茵墨宝，命侪歌婢。","砚缔半车兰叶鬼，诗斟一斛茶花髓。","也红颜、绝代可怜人，因谁死。"]},{"t":"满江红 怅怅词五首 其五","f":"古风","c":["白柳黄羊，宛绘出、伤心片幅。","酸切处、短霜供爨，古烟供读。","觞弄于君何必怒，飘浮似我原堪哭。","听黄陵、矶畔夜深船，凄凉曲。","梨园内，丝憎肉。","田园内，花欺粟。","更枲麻谤锦，薋葹谗菊。","百队钱刀争作横，一身风雅单为仆。","倚酒悲、乱击紫珊瑚，鸣如筑。"]},{"t":"满江红 咏雪叠韵八首 其一","f":"古风","c":["雪洒彤墀，看帝里、风光不恶。","恰喜是、银装绛灌，琼雕卫霍。","粉椽班中年尚少，玉儿宫里腰初约。","更太平、天子坐当中，帘垂著。","御沟畔，争寒雀。","宝鼎外，山呼却。","喜臣心似雪，朕之良药。","瑟瑟六花笼翠幄，泠泠万点敲金钥。","向鹓行、谁擅郢中才，从头索。"]},{"t":"满江红 咏雪叠韵八首 其二","f":"古风","c":["连日微阴，梅花外、数声姑恶。","憔悴是、净持小女，儿家姓霍。","春梦昼寒偏易醒，鬓丝指冷应难约。","思沈沈、独自抱银筝，人猜著。","钗梁燕，鞋帮雀。","簪处颤，移来却。","看糁平鸳瓦，铺明红药。","沾湿怕污郎白马，玲珑不辨奴青钥。","问何时、乾鹊噪香奁，从天索。"]},{"t":"满江红 咏雪叠韵八首 其三","f":"古风","c":["万里茫茫，穹庐畔、风狂雪恶。","叹当日、汉家苏武，功高卫霍。","迢递南天鸿雁信，凄凉北海羝羊约。","纵饥来、朔雪亦堪吞，无衣著。","传书犬，衔环雀。","忠孝事，难忘却。","看诗誇同泽，史讥尝药。","梦到龙楼飘瑞雪，六宫夜宴黄金钥。","正醒时、芦笛起边愁，风萧瑟。"]},{"t":"满江红 咏雪叠韵八首 其四","f":"古风","c":["六出花飞，侧耳听、金铃犬恶。","正滕六、撒盐飞絮，瀰漫挥霍。","縆罢额黄帘四捲，妆成蛾绿钩双约。","任楼头，倚遍玉阑干，难安著。","歌竹子，弹翎雀。","旧时曲，都抛却。","悔姮娥清冷，多因偷药。","烧尽深闺红兽炭，阖残别院文鳞钥。","只雪沙、淅沥打空阶，秋千索。"]},{"t":"满江红 咏雪叠韵八首 其五","f":"古风","c":["四世三公，袁高士、人身不恶。","也不羡、东朝田窦，西京金霍。","大雪不知秦与汉，平生讵习从衡约。","笑本初、公路亦家驹，争残著。","穿花蝶，衔梅雀。","土锉冷，高轩却。","纵蒲轮束帛，误人之药。","暖足那须东阁被，安心自守空山钥。","任门前、白尽汉江山，休相索。"]},{"t":"满江红 咏雪叠韵八首 其六","f":"古风","c":["大猎城南，此年少、王家镇恶。","何况是、姿容比玠，从奴胜霍。","带雪能骑千里马，杀人不受三章约。","正射雕、时候暮云平，弓弦著。","能逐兔，能探雀。","挥杯饮，休辞却。","向诸君笑语，此非鸩药。","旦日醉从屠狗博，昨宵怒夺城门钥。","看踠骝、玉色雪中驰，难追索。"]},{"t":"满江红 咏雪叠韵八首 其七","f":"古风","c":["举举师师，正春病、心情小恶。","蚤则是、雪飞宝篆，寒生锦霍。","无力浑如侬样性，难凭恰似郎边约。","倚银篝、小语骂轻狂，偏偎著。","萦帘蒜，腾钗雀。","斜复整，行还却。","好捣残玉杵，和他面药。","睡眼初瞤惊六出，曲中小响仓琅钥。","又平康、狎客唤银瓶，褰帘索。"]},{"t":"满江红 咏雪叠韵八首 其八","f":"古风","c":["大雪江天，笑万里、北风作恶。","拚只向、屠门大嚼，磨刀霍霍。","季布田中亡命客，卢家堂后消魂约。","正雪深、兀坐酒楼中，思量著。","车中妇，山头雀。","恨不了，愁难却。","总无如一醉，胜他行药。","小妇且擎红玉椀，金吾漫锁春城钥。","拍糟床、极爱酒家郎，频呼索。"]},{"t":"满江红 江村夏咏十首 其一","f":"古风","c":["百顷风潭，镇日展、风漪八尺。","向此处、未妨饮啖，且须琴弈。","篱笋细腌红缕豉，吴盐小下银丝鲫。","待体中、脱复有佳时，哦周易。","北垞外，寒云白。","西崦畔，苍烟积。","更水凫将子，纵横飞拍。","老子难抛白玉麈，少年喜拓黄金戟。","总风情、输与牧牛儿，斜阳笛。"]},{"t":"满江红 江村夏咏十首 其三","f":"古风","c":["略彴东头，有蟹舍、斜连荻市。","追凉处、田夫说饼，风情靡靡。","馎饦溜匙姜韭滑，餦餭胶口椒橙美。","更传闻、樱笋贱如泥，今年里。","叉手舞，揎拳起。","缸面酒，长腰米。","想大官厨味，不过如此。","老我田园河射角，笑他宦仕车生耳。","滆湖风，刚趁此时来，欣然喜。"]},{"t":"满江红 江村夏咏十首 其四","f":"古风","c":["碧浪初圆，凭水阁、脱巾独立。","谁作伴、数竿篱竹，一瓯茗汁。","似有声来茶硙转，断无人处村舂急。","正日长、拨闷枕书眠，斜川集。","槿花上，珠堪吸。","豆花底，凉堪裛。","看瀰茫一派，雨蓑烟笠。","抟黍鸟啼勤又懒，鲥鱼风起吹还涩。","恰冲泥、邻叟垫巾来，芒鞋湿。"]},{"t":"满江红 江村夏咏十首 其五","f":"古风","c":["雨欲成时，听村北、村南鹎鵊。","行乐处、崖门藤束，溪腰树夹。","水剪越罗吴縠样，山临范缓倪迂法。","任科头、箕踞受松风，新凉霎。","何必学，呼名鸭。","且自荷，随身锸。","尽一邱一壑，此生宁乏。","云起怒排临阵马，涧鸣冷试搊筝甲。","更归来、滴滴玉蛆声，糟床压。"]},{"t":"满江红 江村夏咏十首 其六","f":"古风","c":["丁字畦边，见一带、阴阴夏木。","扶疏甚、钓丝斜漾，菱丝大熟。","莺暖鮰鱼新上市，草香蚕子齐登簇。","喜炊烟、一缕袅江边，燃湘竹。","茭鸡唱，溪流足。","姑恶叫，山光绿。","听樵歌正断，渔歌又续。","泥滑妇愁微雨馌，村深儿趁朝凉读。","更柳塘、吹起牛风，波如縠。"]},{"t":"满江红 江村夏咏十首 其七","f":"古风","c":["罨画铜官，都缭绕、吾庐左右。","论生计、蹲鸱一顷，菰蒲百亩。","矮屋村扉多蘸水，澄潭钓艇斜依柳。","恰月明、渔网截江来，歌铜斗。","烟渐敛，笼鸦舅。","雨又作，鸣鸠妇。","正湖风侧帽，林花堕酒。","戏就摊钱淮估语，闷思斫鲙吴娘手。","待明朝、重榨瓮头齑，呼溪友。"]},{"t":"满江红 江村夏咏十首 其八","f":"古风","c":["泽国人家，门以外，水田渺渺。","无过是、明潭浅濑，烟蒲风筱。","雪浪江帆喧昼夜，鸡头菱角知多少。","泊数行、笭箵忒玲珑，渔蛮绕。","新暑退，芦塘窅。","残月映，溪堂皎。","且榜他碧石，沽来清醥。","一雨平湖凉思满，数声林笛离情悄。","正水云、空阔晚冥冥，沙鸥矫。"]},{"t":"满江红 江村夏咏十首 其九","f":"古风","c":["天水空濛，芦花内、茆庵一个。","长夏里、溪干乘兴，短篷掀簸。","十里烟波鸥世界，半盂茗汁僧功课。","更寺门、竹翠剧怜人，如何唾。","洗钵罢，苔阴坐。","捶琴歇，花关卧。","爱栗留声脆，枇杷叶大。","便住随师听浴鼓，再来何日开烟柁。","约搓橙、剖橘好时光，还重过。"]},{"t":"满江红 江村夏咏十首 其十","f":"古风","c":["三伏炎熇，吴牛喘、老颠欲裂。","讵便少、池荷半亩，山松百尺。","赤日红尘那可耐，哀梨并剪无从觅。","且临风、快读剑南诗，倾一石。","堂堂处，装何急。","咄咄处，人都逼。","算功名马槊，关山梁益。","绿鬓双螯寒夜擘，白头猛虎霜天射。","渐卷终、不觉海风生，冰车砉。"]},{"t":"满江红 岁暮渡江用宋荔裳观察曹顾庵太史王西樵考功倡和原韵","f":"古风","c":["六幅蒲帆，掠江下、玻璃绿涨。","中流处、举杯遥贺，焦先无恙。","一片乡愁残垒下，五更僧语空舲上。","喜网来、白小不论钱，渔蛮饷。","看蟹舍，沙头漾。","听铜斗，船头唱。","喝岷江有水，速成醇酿。","估客使船都似马，吴儿踏浪何须杖。","剪烛花、醉眼看鱼龙，离奇状。"]},{"t":"满江红 舟次润城谒程昆崙别驾仍用前韵","f":"古风","c":["此地孙刘，想万马、川腾谷涨。","公到日、雄关铁索，东流无恙。","上党地为天下脊，使君文在先秦上。","更纵横、羽檄气偏豪，筹兵饷。","天上月，波心漾。","隔江笛，楼头唱。","叹江山如此，可消官酿。","侧帽高张临水宴，掀髯勇策登山杖。","踞寒崖、拂藓剔残碑，猿猱状。"]},{"t":"满江红 闻阮亭罢官之信并寄西樵再叠前韵","f":"古风","c":["鼎鼎朱门，满眼是、膨脝腹涨。","谁得似、心情半懒，风情微恙。","阿堵考君材最下，孔方阻尔书难上。","算人间、只有芰荷裳，堪相饷。","华不注，樵风漾。","辕固里，蚕娘唱。","使渐离和曲，杜康佐酿。","才子为官休亦好，弟应荷筱兄携杖。","记相人、原说使君非，痴肥状。"]},{"t":"满江红 乙巳除夕立春仍用前韵二首 其一","f":"古风","c":["爆竹一声，吾庐外、千门烟涨。","喜今夜、新春残腊，田园无恙。","南国旧游稀眼底，西京遗事来心上。","记黏鸡、彩燕廿年前，拦街饷。","沧桑换，都抛漾。","头颅老，休歌唱。","且左烧红烛，右倾家酿。","郁垒欹斜头上帽，神荼脱落腰间杖。","笑人怜、桃偶偶怜人，同斯状。"]},{"t":"满江红 乙巳除夕立春仍用前韵二首 其二","f":"古风","c":["父念儿耶，珠泪迸、溪流同涨。","屈指算、四时作客，三秋抱恙。","山左未寻周栎下，广陵且觅王贻上。","乍榴花、时节载愁还，堪谁饷。","弱女嫁，罗衣漾。","诸弟隔，羁鸿唱。","又匆匆去买，高邮雪酿。","寒夜才归阳羡棹，灯前拟试金焦杖。","向泉台、泣数一年间，飘零状。"]},{"t":"满江红 将为邓尉看梅之行先寄吴中诸子叠前韵","f":"古风","c":["二陆三张，曾轰饮、剑池春涨。","吾语女、千年花草，至今无恙。","柳絮微风胥渡口，梨花细雨皋桥上。","自别来、仆病负诸君，莼鲈饷。","伥伥甚，游丝漾。","芒芒极，雏莺唱。","渐欲寒欲暖，暗将梅酿。","我意巾车还跃马，君其挈榼兼扶杖。","待月明、饱玩万山巅，横斜状。"]},{"t":"满江红 赠朱亦岩先生再叠前韵 先生楚人","f":"古风","c":["湘入潇波，极望处、楚天碧涨。","来领袖、五湖词赋，齐盟无恙。","萧帝宅荒葭菼外，昭君村在秭归上。","羡风骚、两地仗斯人，从天饷。","珠玉走，龙蛇漾。","白雪和，幽兰唱。","看江花狼籍，班香酝酿。","他日定为公子绣，此时敬撰先生杖。","谢君侯、未面已怜余，疏狂状。"]},{"t":"满庭芳 纪梦","f":"古风","c":["黄入东风，绿来南内，梦中春水竛竮。","个侬香粉，髣髴也曾经。","还是簸钱堂上，当年事、有影无形。","高楼外，珠圆莺脆，隔院已闻声。","衷情。","浑欲诉，新愁点点，旧恨星星。","奈一场春梦，不甚分明。","此际银灯耿耿，罗衾湿、红泪如冰。","难分手，满街细雨，愁煞梦回程。"]},{"t":"凤凰台上忆吹箫 闰六月七日为牛女作懊恼词","f":"古风","c":["翠鹊桥虚，珠匏路杳，懊侬情思无憀。","奈粉河一望，灵匹难招。","寄语天边织室，双鸳杵、纤指休抛。","停梭怨，金徒箭永，青女妆遥。","迢迢。","常时此夜，正微褰麝㡠，小驾龙轺。","记衣香鬓影，髣髴今宵。","屈指经年离别，依然又、泪滴红绡。","差喜是，凉秋不远，准备魂消。"]},{"t":"凤凰台上忆吹箫 和漱玉词","f":"古风","c":["蘸水垂杨，漫天丝柳，千条万绪楼头。","正圆冰清浅，斜靠帘钩。","拟把玉容重整，才匀面、怊怅还休。","恹恹甚，今春三月，忒似深秋。","堪羞。","韶华纵好，奈旧情已换，往事难留。","只梁间玉剪，劝我登楼。","帘押朦胧未捲，青山外、不忍凝眸。","无过是，潇潇春雨，点点离愁。"]},{"t":"水调歌头 被酒与客话","f":"古风","c":["老子半生事，慷慨喜交游。","过江王谢子弟，填巷哄华驺。","曾记兽肥草浅，正值风毛雨血，大猎北冈头。","日暮不归去，霜色冷吴钩。","今老大，嗟落拓，转沈浮。","畴昔博徒酒侣，一半葬荒邱。","闭置车中新妇，羞缩严家饿隶，说著亦堪愁。","我为若起舞，若定解此不。"]},{"t":"水调歌头 题余氏女子绣西施浣纱图为阮亭赋","f":"古风","c":["婀娜针神女，春昼绣西家。","闻道若耶溪上，渌水漾明沙。","为忆吴宫情事，蓦地养娘来至，羞脸晕朝霞。","忙向屏山畔，背过鬓边鸦。","一春愁，三月雨，满栏花。","西施未嫁，当初情绪记些些。","靠著绣床又想，拈著鸳针又放，幽思渺无涯。","一幅鲛绡也，错认越溪纱。"]},{"t":"夏初临 本意","f":"古风","c":["麦浪挼晴，槐阴撋雨，小楼无限思量。","九十韶华，谁怜归去堂堂。","屏山敞尽潇湘。","渐淩波、玉剪飞忙。","此时天气，今年情绪，大抵伥伥。","天涯羁旅，煞甚凄凉，惯推中酒，怕说思乡。","江东故苑，正逢樱笋时光。","何日吴装。","傍柳绵、小泊斜阳。","倚虫娘。","一春愁病，说与端详。"]},{"t":"八声甘州 月夜守风江店","f":"古风","c":["对清光、一碧倚江城，独立怨飘蓬。","最恼人怀抱，危樯匝地，残堞当空。","遥想故园妆阁，拥袖侧金虫。","叹息藁砧去，烟水濛濛。","一派银涛雪浪，泻青铜镜底，白雁声中。","料嫦娥清冷，此际与人同。","且消停、三更茅店，任隔垣、紫马夜嘶风。","消魂也，江愁卫玠，月想王恭。"]},{"t":"倦寻芳 早春偶过农部伯父废园感赋","f":"古风","c":["败屋东头，偶然行散，十分情重。","满地苔钱，雨榭烟廊都空。","蘸水燕雏晴故掠，荫街丝柳风偏弄。","伤情处，是旧家年少，登山一恸。","记当日、孝标姊妹，僧绰儿郎，嬉游曾共。","多少春衫，斜著金鞭閒控。","一自攀髯人去早，江南莺燕成何用。","拚此生，绣户珠帘，付之一梦。"]},{"t":"玉人歌 杨枝今岁二十为于齐纨上作小词","f":"古风","c":["当日事，记陌上青丝，垂垂踠地。","拖烟蘸雨，已解藏鸦未。","真珠帘额香毬坠，做尽轻狂意。","影濛濛、红日三竿，白花十里。","水驿飘零子。","谢青眼相看，绾人征骑。","露叶如啼，直得消魂死。","如今渐长黄金穗，不在长街里。","羡画楼有主，舞腰同倚。"]},{"t":"八节长欢 乙巳元日","f":"古风","c":["淑景惊催。","画梁日影，蚤漾妆台。","曈昽金母帐，潋滟玉人杯。","宜春帖子簪花格，渐闺中、珠网争开。","多少屏摇翠柏，胜飐红梅。","长安车骑朝正，青丝辔，火城影里初回。","宫阙暖祥云，嬉游罢，谁怜江左邹枚。","休怊怅，喜吴娘、已榨春醅。","屈指又、试灯挑菜，且拾遗钗。"]},{"t":"无闷 春日见城上游女甚盛戏作此词","f":"古风","c":["绮陌芉眠，上日妖冶，弥望玉楼金埒。","正挑菜年光，湔裙时节。","阵阵内家车子，漾绡帏、吹乱千堆雪。","无人处，悄把春纤小揭，都无分别。","络绎。","碾香尘，铺玉席。","总向子城斜处，女墙弯里，惹人怜惜。","此际春心愁绝。","愁九十、春光如过隙。","那堪轻暝轻寒，朝来想作寒食。"]},{"t":"琐窗寒 昔年楼上","f":"古风","c":["此地当年，萧娘妆阁，绿窗幽靓。","伤春情思，正日暖人微病。","撚花枝、悄近罗衣，眉峰送语烟难定。","掩屏风六幅，看他縆额，安黄端正。","那更。","人别后，冷落旧妆楼，温家玉镜。","无端又上，银蒜零星还剩。","只从前、箫局桃笙，看来不似今朝景。","便化为、玉剪重来，还认红香径。"]},{"t":"花犯 咏浩然堂后池上白山茶用周美成梅花韵","f":"古风","c":["封西风，亭亭一树，个侬好风味。","和烟和月，也无人怜惜，不胜清丽。","水晶帘额深深倚。","天寒私自喜。","似小玉、夜长无伴，上床铺粉被。","珠窗一层障疏花，似无还似有，共人憔悴。","愁杀是、青霜轻坠。","记一种、红颜窈窕，曾开在、三春台榭里。","只薄命、年年流落，秋天凉著水。"]},{"t":"念奴娇 与任青际饮","f":"古风","c":["乾坤飒飒，且沽将枫叶，细评今昔。","笑问幽州今夜雪，可似鹴裘寒色。","市上吹萧，桥头卖酱，泪洒吴枫赤。","苏貂空黑，谢郎今已破贼。","不如冶叶昌条，青楼白社，磨灭人年月。","沥尽并刀悲壮血，看有何人怜惜。","白草关河，黄沙唐宋，只对孤鸿说。","醉浇三国，周郎江岸千尺。"]},{"t":"念奴娇 云间陈徵君有题余家远阁一阕秋日登楼不胜蔓草零烟之感因倚声和之","f":"古风","c":["得怜堂后，有丹楼飞起，当年争羡。","阳夏门庭能咏絮，那更溪山葱茜。","带雨房栊，和烟帘幕，零乱东湖面。","碧阑干里，有人斜映琼扇。","可惜人去匆匆，而今楼下，秋水帆如箭。","老我三吴好男子，绿鬓忽然衰贱。","蔓草霜浓，丛祠露悄，白昼鼪鼯现。","舍南舍北，乱飞王谢家燕。"]},{"t":"念奴娇 题顾螺舟小影","f":"楚辞体","c":["如此佳人，是王家养炬，谢家遏末。","三世貂蝉连北阙，年少东华释褐。","傅粉宫前，薰香殿侧，顾盼真英发。","临春结绮，旧游似有瓜葛。","而今零落堪怜，文园多病，赢得相如渴。","满目关河愁恨极，衰草浓烟涂抹。","醉矣堪呵，灰兮可溺，田也供人夺。","茫茫哀乐，四条弦子空拨。"]},{"t":"念奴娇 纬云弟三十作此词因和其韵同半雪赋","f":"古风","c":["醉拍阑干，叹去者苦多，光阴倏忽。","知我平生悲愤事，惟有当头明月。","准拟骑鲸，不然射虎，一吐胸中郁。","吴钩负汝，好将衫袖频拂。","追想红烛呼庐，青楼赌酒，往事推华阀。","小季已称三十岁，何况暮年黄歇。","斜阁秦筝，横摊越绝，烧尽炉中柮。","凭高远望，江流一线如发。"]},{"t":"念奴娇 送子万弟携五弟之睢阳并令二弟三弟四弟同和他日一展齐纨便成聚首也","f":"古风","c":["悲哉秋也，况登山临水，黯然欲别。","千里长江流夜月，万里长城空阔。","白板船开，青枫树老，极目徒悲切。","君归梁苑，汉家何限陵阙。","畴昔让枣推梨，谢家兄弟，才气人争说。","一夜西风吹苍莽，吹散封胡遏末。","兄作楚囚，弟成秦赘，枕上鹃啼血。","阿龙超甚，教他长诵明发。"]},{"t":"念奴娇 次夜韩楼灯火甚盛仍听诸君弦管复填一阕叠前韵","f":"古风","c":["红烛如山，请四筵满座，听侬挝鼓。","此日天涯谋作达，事更难于缚虎。","仆本恨人，公皆健卒，不醉卿何苦。","金元院本，月明今夜重作。","总是狎客南朝，佳人北里，占断芜城路。","好景也知容易散，一别沈鳞羁羽。","狂受人憎，醉供人骂，老任雏姬侮。","扬州灯火，明朝人定传语。"]},{"t":"念奴娇 乙巳中秋用东坡韵寄广陵诸旧游","f":"古风","c":["月明如此，问江山今古，几多陈迹。","谁把桂轮今夜里，碾破楚天新碧。","玉臼无声，银河有影，一片清虚国。","醉馀莫笑，旧游吾尚历历。","记得杜牧司勋，江湖落拓，曾作扬州客。","爱杀打头天上月，管甚中秋七夕。","一别凄然，吾生可惜，塌尽鹍鹏翼。","夜云深矣，依稀楼外吹笛。"]},{"t":"念奴娇 酬归德侯仲衡","f":"古风","c":["天阴岁暮，正情如中酒，人初赋别。","忽接繁台书一纸，飞下梁园白雪。","悼远伤离，抚今追昔，字字皆辛切。","狂歌数阕，唾壶之口都阙。","每欲窄袖轻衫，碻磝道上，小犯寒风洌。","耳后弓弦声霹雳，一片风毛雨血。","雅愿终违，壮游未果，世事多枝节。","中宵辗转，布衾今夜难热。"]},{"t":"瑶华 秋雨新晴登远阁眺望","f":"古风","c":["青山如黛，渌水如罗，映真珠帘罅。","金闺瑟瑟，正青砧、隔院捣衣才罢。","登楼远望，见一带、碧云轻泻。","更萧关征雁濛濛，愁煞江南此夜。","几回搔首沈吟，叹今日深秋，前朝初夏。","流光递换，问何处、更觅钿车罗帕。","伤心故苑，依然似、天涯客舍。","对秋风、强举金尊，又是夕阳西下。"]},{"t":"高阳台 题余氏女子绣高唐神女图为阮亭赋","f":"古风","c":["巫峡妖姬，章台才子，赋成合断人肠。","绣阁停针，含情想像高唐。","渚宫旧迹今何在，不分明、水殿云房。","亸蝉鬟，忆著行云，恰费商量。","蘅皋暮雨凄凉。","只楚天一碧，与梦俱长。","雾縠霓旌，几时重得侍君王。","小唾红绒思好事，却剪刀、声出回廊。","更添些，红杜青蘋，做出潇湘。"]},{"t":"东风第一枝 咏绿萼梅和吕圣求韵","f":"古风","c":["粉界檀腮，烟笼腻颈，玉奴素质轻约。","风前乍坼红须，月下低含绿萼。","一枝水上，也不管、莺啼燕掠。","最怜他、不甚分明，飞破潇湘白鹤。","隔蝉翼、层层都薄。","打稷雪、泠泠又落。","有情故亚楼头，无聊自开屋角。","日高慵起，慢摇动、绿纱帘箔。","看苔钱、色上花枝，碧透何郎官阁。"]},{"t":"解语花 咏美人捧茶和王元美韵","f":"古风","c":["蕃马屏风，雏莺庭院，竹下茶声细。","妆楼小倚。","阑干外、汲取春流浅试。","乳花银蕊。","烟袅上、绿鬟千缕。","溜横波、炉火初红，尽带娇态意。","捧处轻摇蝉髻。","问阿谁年少，消受纤指。","珠鲜玉脆。","语笑处、故惹檀郎惊起。","沈香亭婢。","只领略、凝酥佳丽。","怎如伊、生小江南，偏解旗枪味。"]},{"t":"解语花 咏美人捧觞和王元美韵","f":"古风","c":["楚天卵色，吴地莺声，惹得愁千斛。","春衣慢赎。","且泥他、粉白斟来蚁绿。","莲钩小蹙。","行过了、银屏六曲。","亸烟鬟、缥色杯轻，帐里围颓玉。","笑颤流苏影簇。","怪佯酲不醒，罚依金谷。","玉郎低嘱。","沈醉也、休作难人题目。","芳心暗逐。","羡杯底、鸳鸯同宿。","趁花酣、双抱红篝，图取春眠足。"]},{"t":"夜合花 为丁子硁催妆","f":"古风","c":["人柳腰眠，圣檀额注，犊车催下屏风。","胜常道罢，腮边春晕微红。","呼燕燕，唤虫虫。","桂堂西、小著轻容。","问伊姓氏，父名郑季，母号樊通。","莺声夜半玲珑。","多少帐前细咳，尔汝欢浓。","今宵夜冷，劝郎文籍休攻。","兰缸细，鸭垆浓。","卸花簪、早傍薰笼。","羡他大妇，偏怜敬礼，代掩珠栊。"]},{"t":"换巢鸾凤 咏烛","f":"古风","c":["暝色初临。","正金荷灼灼，凤胫沈沈。","烧残终有泪，剪断岂无心。","馋脂注得十分深。","光翻金粟，影动琼林。","春檠上，看带笑、花开似锦。","瘦沈。","踌躇甚。","曾记华堂，半灭情难禁。","金钥传时，玉堂㸐处，对对红酥翠沁。","莲灯缓导上元游，兰膏浓挽平康饮。","如今绛蜡，照人长是孤寝。"]},{"t":"曲游春 花朝","f":"古风","c":["秾春无限好，正云剪春罗，水铺明镜。","满目红芳，记淡烟斜日，江南时景。","红板桥西路，有万缕、绿杨拖径。","更怜次第风光，巧斗吴娘花胜。","回首夭桃露井。","忆檀板银罂，那时偎并。","人在花朝，有婵娟姿格，玲珑情性。","自后堂分袂，长则是、如酲似病。","可惜憔悴兰成，凄凉家令。"]},{"t":"绛都春 乙巳元夜","f":"古风","c":["春宵三五，正碧云合处，冰轮斜挂。","暗省年光，漫数韶华偏沾惹。","平生旧事都忘也。","难忘是、凤城鸳瓦。","无灯无火，有花有月，偶然吟写。","此夜。","追欢买笑，有天街似水，暗尘随马。","讵料而今，几阵东风谯楼下。","吹去了、香车罗帕。","春衣卸、思量如乍。","且寻故老开元，月明閒话。"]},{"t":"石州慢 忆旧用高季迪韵","f":"古风","c":["醉拍雕阑，思忆从前，泪珠频洒。","东阳倦沈，多愁多病，瘦躯堪把。","水市津楼，奈他绣被浓香，旧时閒事偏萦惹。","颠倒觅乌丝，检霜毫细写。","妖冶。","此夜虫虫，曾嘱监奴，葳蕤慢下。","且趁湘簟银灯，邀人白打。","摘尽铜签，小婢故恼人行，任他嘶断门前马。","懊恼后堂前，又年光换也。"]},{"t":"玲珑四犯 月下闻笛","f":"古风","c":["三五良宵，看云月澄鲜，幽辉盈抱。","羁旅无眠，愁思几番萦绕。","满园春水空濛，映翠竹、枝枝斜袅。","恰嘹喨、谁家入破，遥想小楼空悄。","因思天宝梨园队，有金雁、钿蝉绝妙。","更偷把、宁王玉笛，吹彻谁知道。","一自华清人散，缭垣外、閒花野草。","叹此生头白，天涯再听，伊凉别调。"]},{"t":"霓裳中序第一 咏水仙花次尹梅津咏茉莉韵","f":"古风","c":["珠栊寒粉靥。","偎罢银篝红兽热。","恰值青霜骚屑。","有一种瑶芳，白花翠叶。","海天皓月。","羡玉娥、生长绡阙。","斜春渚、竟川含绿，一笑嫣然绝。","妙绝。","顿成离别。","长则伴、儿家妆箧。","有时坠落帘茀。","看尽人间，多少蜂蝶。","五铢寒到骨。","怅千里、洞庭飞雪。","伤情也、旧家何处，悄对素梅说。"]},{"t":"忆旧游 寄嘉禾俞右吉朱子葆子蓉","f":"古风","c":["松陵东去路，记水程、烟驿几多般。","鸳鸯湖里泊，重城灯火，一派潺湲。","船楼玉人行酒，碧浪泻红颜。","更幂䍥丹鳞，绵濛黛甲，上下哀湍。","十年。","成间别，想怪侣狂朋，一样啼斑。","纵玉清归去，怕满天风露，犹忆人间。","只是南湖柳色，憔悴不堪攀。","长望语儿亭，故人为我且加餐。"]},{"t":"齐天乐 暮春风雨","f":"古风","c":["小楼昨夜东风到，吹落满园空翠。","时有茶烟，绝无人影，好个他乡天气。","凄凉欲死。","见燕剪平芜，柳拖春水。","暗省从前，如尘似梦最难记。","当年曲院寒食，饧香花更暖，许多情事。","金斗犹温，玉钗还响，已送愁人到此。","也思宽慰。","奈把酒听歌，几番不是。","暮雨潇潇，记吴娘曲子。"]},{"t":"瑞鹤仙 上元和康伯可韵","f":"古风","c":["昔游思后苑。","记天上月圆，人间月半。","六街笑声满。","看火蛾金茧，春城飞遍。","琳宫琼观。","随处挂、鳌山灯烂。","最销魂、深巷残更，小颤门边双钏。","休羡。","无多胜景，有限芳辰，不堪追玩。","红篝熏暖，和衣卧，谁低唤。","怪流光一去，钿车罗帕，吹煞东风不转。","只玉梅、梢上冰轮，依然相见。"]},{"t":"瑞鹤仙 邹程村母夫人寿","f":"古风","c":["千金今夜直。","羡阿母白发，珠袍一色。","称觞蓬阆侧。","有南路豪家，东朝贵客。","华驺列戟。","向尊前、箜篌醉擘。","倩何人、笑问君家，家本难忘易识。","犹忆。","曾陪董相，閒过邹阳，读书骑射。","贤哉湛母，截剃亲为置食。","看怀清台畔，夫人城上，无论功名赫奕。","只膝前、有子谈天，生儿亦得。"]},{"t":"南浦 泊舟江口","f":"古风","c":["吴樯晚眺，看隔江、螺髻碧离离。","龙虎销沈无据，往事不胜悲。","忆昔曹公饮马，对江流、横槊赋新诗。","羡三吴人物，伯符公瑾，年少更雄姿。","今古芒芒天堑，捲神鸦、日暮舞空祠。","多少南朝事业，断岸矗残碑。","月白估船铜斗，唱西风、云水正弥弥。","叹多愁洗马，销魂偏在渡江时。"]},{"t":"氐州第一 秋日怀东皋诸子用周美成韵","f":"古风","c":["千片芰荷零乱，帘捲西风，人倚楼小。","横竹泠泠，峭风历历，一碧远天缥缈。","非淡非浓，飐水国、村村斜照。","中酒心情，欲寒天气，暗催人老。","三十六鳞江上少。","奈无限、旧愁缭绕。","沙鸟将雏，江凫傍母，秋水柴门抱。","正搓橙、时候也，题糕近、龙山欢笑。","写尽吴笺，盼晴空、翠屏都晓。"]},{"t":"绮罗香 清明感旧","f":"古风","c":["绿水楼台，青春院落，又是韶华百五。","饧粥榆钱，过了匆匆时序。","怕今年、玉剪来时，是去年、钿车停处。","最难凭、轻暖轻寒，天涯羁客甚情绪。","少年此日嬉游，有窥帘绮态，当垆俊侣。","一自飘流，冷落夭桃门户。","西楼外、几阵莺花，北邙上、一堆羊虎。","向斜阳、断碣残碑，多少横官路。"]},{"t":"绮罗香 初夏连夜于许茹庸仲修席上看诸郎演牡丹亭有作","f":"古风","c":["许掾多情，清和佳节，连夕娇歌妙舞。","料得眉峰，碧到愁时都聚。","记昨宵、银瑟初停，又此夜、红牙再补。","看一群、灯下诸郎，依稀尽解此情苦。","独有江东词客，为家山路远，倍增悽楚。","回首朱门，略记虫娘庭户。","好院本、全部笙箫，没心情、半生羁旅。","比年时、携手听歌，多了黄昏雨。"]},{"t":"金盏子 咏灯","f":"古风","c":["一盏红釭滟玉膏，鸳绡皱处偏凝。","春夜照梳头，莲筹杳、凄清牙蒜犀钉。","便教煎尽银荷，奈芳心耿耿。","敲翠竹、悄唤绿翘檐前，兰灯将暝。","唤遍无人应。","且独自、纤手靠妆台，挑凤胫。","宛转处，重思省。","当时风细人静。","曾偎璧带流苏，剔银釭潜等。","红裯冷，空对并蒂灯花，怎生相称。"]},{"t":"永遇乐 京口渡江用辛稼轩韵","f":"古风","c":["如此江山，几人还记，旧争雄处。","北府军兵，南徐壁垒，浪捲前朝去。","惊帆蘸水，崩涛飐雪，不为愁人少住。","叹永嘉、流人无数，神伤只有卫虎。","临风太息，髯奴狮子，年少功名指顾。","北拒曹丕，南连刘备，霸业开东路。","而今何在，一江灯火，隐隐扬州更鼓。","吾老矣、不知京口，酒堪饮否。"]},{"t":"尉迟杯 别况","f":"古风","c":["春江上。","见鸂鶒、濛濛飞碧浪。","草间珠露犹垂，岸左红兰才长。","东风斜日，小玉门前缆乌榜。","正离人、好梦初醒，双拥红篝凝想。","因念十载漂零，长则在、水驿烟程来往。","手把金尊和泪说，枉说是、画眉张敞。","如今便、花开花谢，祇凭得、红襟梁上讲。","送朗行、独凭小楼，橹声水面摇响。"]},{"t":"二郎神 春寒感怀","f":"古风","c":["饾饤天气。","况是天涯羁旅。","怊怅类、浮萍飘泊久，伤情处、黯然无语。","且检红绵灯下看，瞥见了、深闺针缕。","想当日、执手叮咛，预料春寒如许。","凝伫。","沈吟欲著，几番推去。","任春衣、红藤箱底阁，甘领受、疏风懒雨。","拟向春江传此意，奈江上、双鱼无据。","恨点点杨花，叠叠青山，遮人归路。"]},{"t":"二郎神 咏梅子","f":"古风","c":["一株梅子，正累累、粉红墙后。","问叶底枝头，为谁酸楚，却又为谁消瘦。","太息春归谁来问，记不起、莺花如绣。","向杳杳帘栊，阴阴院落，伴人长昼。","纤手。","几番小摘，已醒残酒。","更撚向妆台，玉娥低说，曾见依稀如豆。","翠已漫空，黄偏做雨，又到伤心时候。","算颗颗、冷香松脆，想尔料难胜口。"]},{"t":"合欢带 为吴陵宫掌雷赋催妆词","f":"古风","c":["羡绯罗、烛吐银墙。","灯影背、响鸣珰。","夹路如花还似雾，戟门前、步步荀香。","剧怜春夜，花融锦瑟，月亚金堂。","况画眉夫婿，清河小弟，杜曲诸郎。","纱笼徐引，绣幕斜张。","蓝桥捣就元霜。","琼岛仙花偏并蒂，珠帘畔、一朵笙囊。","朝来更喜，五铢裙细，百子钗长。","问傍人、宜称何如，生憎唤作宫妆。"]},{"t":"花发沁园春 月夜布席绿萼梅花下同友人小饮","f":"古风","c":["借月为花，将花做月，濛濛一树皴玉。","银椀筛春，琼箫暖夜，值得珍珠几斛。","冰肌睡足。","更掩映、生绡六幅。","念月姊彻夜孤寒，梅妃自小幽独。","花影风摇簌簌。","任春城夜阑，画鼓频续。","金炉烬处，珠斗斜时，月与梅花微绿。","清辉满目。","拚吹灭、枝枝银烛。","夜深沈、我醉休扶，和月和花同宿。"]},{"t":"潇湘逢故人慢 题余氏女子绣柳毅传书图为阮亭赋","f":"古风","c":["龙绡一幄，有灵芸针线，刺凤描鸾。","秋水漾波澜。","正洞庭归客，憔悴思还。","牧羊龙女，恰相逢、雨鬓风鬟。","看多少、沙明水碧，一天愁绪漫漫。","却又早来橘浦，见儿家、绡宫璇阙生寒。","贵主下云端。","更箱开青玉，珀映红盘。","海天良夜，论恩情、可似人间。","绣到此、料应长叹，眉峰斜蹙湘山。"]},{"t":"潇湘逢故人慢 送王亦世归汉阳兼寄怀人","f":"古风","c":["西风湘楚，正湘竹如啼，湘禽如舞。","湘岸飞湘雨。","更渌水微波，青山可数。","几幅烟帆，采不尽、白蘋红杜。","想此际，仙令归舻，一派江山今古。","女娥祠，巴子国，看历历晴川，萋萋芳树。","风外催津鼓。","恰人在洞庭，秋盈橘浦。","官舫瑶琴，总弹破、沙清月苦。","倩楚塞、白雁同归，并寄阿戎此语。"]},{"t":"泛清波摘遍 咏沼内红鱼","f":"古风","c":["吴娘水阁，几曲金塘，时听红鱼跳波响。","翳然花竹，日高舟尾浮菰蒋。","妆台上。","伤春天气，中酒心情，斜溜明矑还细相。","照水钗倾，投饵鬟偏，几遍惆怅。","朝霞漾。","寄到啼椷染血，带得落花铺绛。","爱尔绝代红妆，水云高旷。","浑无恙。","娇鸟笼底去来，美人影中生长。","莫管画溪笠泽，黏天风浪。"]},{"t":"击梧桐 酒阑感赋","f":"古风","c":["被酒阳狂，当歌慨慷，几遍雄心肮脏。","芦中人，灶下养。","市南屠狗，城东卖酱。","更邀昔日知交，白掷剧饮，掀髯抵掌。","击碎唾壶，拍碎胡琴，旧事流波一往。","想像衣香，沈吟手粉，十载后堂情状。","灯灺后，梦回时，曾否玉人无恙。","醉后猛然思省，人生何必定多情，且潦倒、短衣射虎，学蓝田李广。"]},{"t":"一萼红 寒食纪事","f":"古风","c":["玉津园，记个侬门巷，渌水漾罘罳。","社燕低飞，饧箫轻弄，东风隋柳如丝。","正客里、禁烟天气，趁流莺、啼处立多时。","蒜押双摇，药栏九转，瞥见师师。","十五破瓜年纪，恰梳头才了，縆额偏迟。","红玉勾人，碧虚留客，篆烟半袅金猊。","魂断是、琼闺有缝，迸他修竹两三枝。","料尔一春寒侧，长倚腰肢。"]},{"t":"薄倖 赋得水晶帘下看梳头","f":"古风","c":["戟门春暖。","红日漾、圆冰清浅。","算一带、茱萸窗网，便是个侬妆院。","素领巾、半幅烟绡，行来刚被微风捲。","更点点斜红，溶溶泓黛，娇面欲匀还懒。","恰十载、伤心事，忆钗响、衣光何限。","只玉纤撩鬓，春葱縆额，一番回想肠应断。","风流放涎。","记千金艳质，妆成爱映春流看。","别来香阁，峭冷尖寒应满。"]},{"t":"风流子 南徐春暮程昆崙别驾招饮南郊外园亭同方尔止孙豹人谈长益邹程村何雍南程千一赋","f":"古风","c":["来时寒食近，且近耳、讵料竟残春。","正仆本多愁，何妨作达，官如不醉，遮莫伤神。","见此际、酒旗斜唤客，榆叶弱萦人。","燕子风前，是何言语，柳条烟里，别样腰身。","名园行乐处，追欢笑，何限宝马香轮。","况遇风流刺史，潇洒遗民。","奈东望蒋州，春潮拍拍，北来瓜渚，暮雨纷纷。","还怕当歌对酒，忽又沾巾。"]},{"t":"翠楼吟 席上赠伎时伎三日后即落乐籍","f":"古风","c":["银甲挨筝，珠绦络鼓，清歌屈柘如缕。","人到离筵里，尽眉黛、愁将碧聚。","纵横玉箸。","似绿柳萦烟，红兰著露。","欹雁柱。","一场春梦，没些情绪。","他日纵过侯门，只光延坊畔，樱桃一树。","奈铜舆催上，更糁遍、一街丝雨。","横波重注。","看斜侧帽檐，销魂无语。","红蜡底。","新官旧主，一般胡觑。"]},{"t":"小梅花 其一 感事括古语效贺东山体","f":"古风","c":["君莫喜。","羊叔子。","何如铜雀台前伎。","拍檀槽。","横宝刀。","屠门大嚼，亦足以自豪。","人生有情泪沾臆。","虽寿松乔竟何益。","捋黄须。","眺五湖。","如此江山，应出孙伯符。","伤心史。","可怜子。","卿复何为尔。","大江东。","一帆风。","来往行人，閒坐说元宗。","连昌宫中满宫竹。","白项老乌暗上屋。","穆提婆。","萧摩诃。","且自吾为楚舞、若楚歌。"]},{"t":"小梅花 其二 感事括古语效贺东山体","f":"古风","c":["咸阳树。","骊山路。","可怜当日作事误。","殷仲文。","王卫军。","国家此辈，要是可惜人。","忆君清泪如铅水。","奴见大家心亦死。","令壶龃。","收中吾。","聊且酒酣，耳热歌呜呜。","莫栎釜。","行学估。","羞与哙等伍。","金屈卮。","杨叛儿。","阿奴今日，不减向子期。","生子当如李亚子。","奴价今年大胜婢。","毂朱丹。","作高官。","未若小楼吹彻、玉笙寒。"]},{"t":"女冠子 咏美人坐禅和彭羡门原韵","f":"古风","c":["萧萧禅榻，百和旃檀薰透。","花冠啼罢，乌龙睡熟，紫竹清幽黄帔瘦。","小袒裶罗袖。","双垒湘裙红吐，花边一绺。","最怜他、趺坐桃笙，一派秋江绿皱。","灵山参破风幡后。","奈十年前事，终向心头有。","佳人不偶。","记惜玉情怀，窃香时候。","迦文消夙垢。","正值钟声报午，苔阴移昼。","问笼中、白雪衣娘，一卷名经完否。"]},{"t":"洞庭春色 甲辰除夕怀西樵司勋阮亭主客","f":"楚辞体","c":["归去来兮，斗鸡走狗，闾巷沈浮。","叹臣之壮也，如人何事，身将隐矣，于世焉求。","四十男儿悲老大，笑那便、车前少八驺。","填胸事，看人奴笞骂，一半封侯。","回首风尘萍梗，怪年来、长傍迷楼。","记广陵风景，青山绿水，琅琊兄弟，长史司州。","名士终朝能妄语，更头没杯中笑不休。","红烛夜，对故园椒酒，想尔风流。"]},{"t":"玉山枕 咏白鹦鹉","f":"古风","c":["小院清丽。","蜻蜓翼、空如水。","杨花门户，梨花院落，风漾金笼，蹁跹不止。","雪衣檐畔诵迦文，恰生小、怕施朱翠。","有玉奴、梦醒无憀，撚琼枝、向月中调戏。","尉佗台上当年事。","心儿内、重提起。","抛家离井，好风良夜，肠断三年，魂消万里。","从来薄命玉容人，也只是、飘零如此。","倩银鸿、问讯珠娘，素馨花、想此时开矣。"]},{"t":"沁园春 广陵客邸送纬云弟之归德","f":"古风","c":["客里送行，萧统楼头，且尽一杯。","正节近清明，柳丝渐长，时逢上巳，燕子将来。","兄往淮阴，弟游河北，两地翻飞立马催。","斜阳外，见各天鸿雁，顾影徘徊。","市楼轰饮如雷。","笑我辈岂常贫贱哉。","奈花号将离，尔心欲碎，地名芜苑，我赋偏哀。","此去睢阳，也知怀古，有日经过古吹台。","还应问，有兔园上客，狗肆奇才。"]},{"t":"沁园春 山东刘孔集招饮广陵酒家系故郭石公宅","f":"古风","c":["鲁国刘生，笑拉宝鞭，携上糟邱。","更一时意气，徐陵袁绍，六朝才调，绿帻红鞲。","如此人生，奈何不乐，况值离鸿叫暮秋。","凭栏望，见风廊水榭，丹漆雕锼。","当年此地风流。","记画戟门开沟水头。","羡羊侃侍儿，弯弓贴地，李波小妹，走马当楼。","蔓草斜阳，空园丝雨，争说汾阳郭细侯。","还长啸，只眼中花月，谁似扬州。"]},{"t":"沁园春 冒天季五十书赠","f":"古风","c":["慷慨悲歌，旁若无人，进君一觞。","更四弦入破，声哀以思，三更被酒，臣醒而狂。","末路崎岖，旧游零落，哀乐纵横不可当。","生平事，曾短衣匹马，锦瑟红墙。","岁华一去堂堂。","又半百蹉跎黯自伤。","叹醉必沾襟，是儿可念，飞而食肉，此志难忘。","人道买臣，今年富贵，路鬼挪揄笑一场。","重酌酒，看玉山筵上，今夜颓唐。"]},{"t":"沁园春 泊舟惠山看六朝松井艮岳石","f":"古风","c":["昔岁我来，乘白羊车，著紫鼠裘。","爱支离者叟，霜皮黛甲，玲珑者丈，雁荡龙湫。","王谢家儿，宣和遗老，尔正愁时我亦愁。","曾经过，看累朝兴废，百代王侯。","别来岁月如流。","叹赴壑修蛇掣不休。","又风吹雨溜，几场儿戏，藤缠藓蚀，一样蜉蝣。","石岂能言，树犹如此，何怪书生竟白头。","重来到，吹一声铁笛，叫破孤秋。"]},{"t":"沁园春 为泗州谢震生广文题照兼送其之任山阳","f":"古风","c":["我爱先生，其冷者官，其热者肠。","羡康乐宣城，君之家世，蠙珠浮磬，此是家乡。","人道马曹，我知鱼乐，苜蓿堆盘也不妨。","吴绫上，问传神阿堵，何物长康。","才成半阕凄凉。","忽念尔将离黯自伤。","记淡月微风，曾经批抹，好花新茗，相与平章。","此去淮阴，古多恶少，我欲来游醉几场。","君求我，在韩侯台下，漂母祠旁。"]},{"t":"贺新郎 云郎合卺为赋此词","f":"古风","c":["小酌酴醾酿。","喜今朝、钗光簟影，灯前滉漾。","隔著屏风喧笑语，报道雀翘初上。","又悄把、檀奴偷相。","扑朔雌雄浑不辨，但临风、私取春弓量。","送尔去，揭鸳帐。","六年孤馆相依傍。","最难忘，红苏枕畔，泪花轻飏。","了尔一生花烛事，宛转妇随夫唱。","努力做、藁砧模样。","只我罗衾浑似铁，拥桃笙、难得纱窗亮。","休为我，再惆怅。"]},{"t":"贺新郎 瓜步与姜子翥","f":"古风","c":["佛狸祠下别。","看此处、江花如练，江烟似织。","忆昔结交坚戴笠，江左周郎英发。","正烂醉、金钗之侧。","宋玉计倪俱大侠，更颖川、年少风流客。","仰天啸，冠缨绝。","十年往事同陈迹。","恰传闻、洛阳金尽，栎阳狱急。","一旦二桃疑尽释，广柳车中人出。","又买得、如花小妾。","送客惊心千万里，但销魂、此际真愁绝。","吾自有，蒯通舌。"]},{"t":"贺新郎 月夜看梅花","f":"古风","c":["皓魄光微渌。","喜东风、琼枝璧月，清辉。","顾影娉婷无一语，吴女纤腰初束。","斜倚在、珠阑曲曲。","看到夜深风露冷，浸檐前、一片圞圆玉。","吾醉矣，共花宿。","愁肠被酒还相触。","且狂歌、莫言兴尽，再斟醽醁。","忽忆开元当日事，中有梅妃蛾绿。","何必羡、玉奴新浴。","可惜楼东三十树，雨霖铃、都作连昌竹。","花应叹，睡难足。"]},{"t":"贺新郎 乙巳端午寄友用刘潜夫韵","f":"古风","c":["醉凭阑干吐。","倚清狂、横陈冰簟，后堂无暑。","闻说吴儿工作剧，吊屈龙舟似虎。","我欲唱、公乎无渡。","累自沈湘卿底急，枉教人、挝碎回帆鼓。","楚江畔，苇花舞。","陡然磊块多如许。","唤灵均、前来共语，酹君椒醑。","呵壁荒唐何必问，死累人间角黍。","尚不及、伍胥涛怒。","忽发狂言惊满座，料诸公、知我心中苦。","酒醒后，重怀古。"]},{"t":"贺新郎 为冒君苗催妆","f":"古风","c":["迟日娇莺啭。","簸轻风、半栏芍药，参差人面。","珠络流苏犀压角，十里龙绡微捲。","料好梦、一春曾选。","节近菖蒲喧笑语，借五丝、先做同心缠。","画梁上，乳双燕。","笙歌沸处莲筹转。","剪银灯、红酥檀晕，暗窥韩椽。","小弟陆家工赠妇，春蚓花笺蟠遍。","何况是、丹青能擅。","百种烟峦俱易画，远山眉、第一须葱茜。","看小试，君苗砚。"]},{"t":"夏云峰 夏雨","f":"古风","c":["楚簟生波，湘帘著水，夏浅胜春时候。","豆棚底、心情小恶，楝花外、年光空逗。","记三春、帽影衣香，漫细数、疏狂未居人后。","奈六幅蒲帆，归吴虽健，却又愁如中酒。","况是梅天丝雨僽。","尽挼蓝野水，点来都皱。","一生事、秧车催去，四月景、蚕房撋就。","倚小楼、看尽吴田，只漠漠阴阴，不堪回首。","且白练裙，绿苔钱，閒写小词怀友。"]},{"t":"引驾行 柬既庭","f":"古风","c":["全吴馆内，破楚门边，十年事、记冶游作使，与卿并倚吴阊。","清狂帘前壁月，桥头画縠，钿辕畔、游閒公子，红烛银筝，醉玉温香。","平康。","况曾经邂逅，枇杷巷口扫眉娘。","想那日妖娆，唤马药栏，微雨碧城凉。","难忘。","无端一别，腰身瘦尽东阳。","奈晓风残月，梦回酒醒，往事微茫。","堂堂。","问江东士女，涂辙谁令我辈妨。","料章华才子，也应点、两鬓吴霜。"]},{"t":"兰陵王 春恨","f":"古风","c":["香腮托。","人与梨花俱弱。","东风外、斜压香衾，蹙损潇湘远山角。","镜鸾空掩却。","愁觑玉肌减削。","又不是、中酒伤春，尽日沈吟倚妆阁。","唾花裙上落。","奈紫栈才温，红绵正薄。","水晶帘额轻寒络。","更阵阵春雨，恹恹残日，小楼欲睡那便著。","且自漱春酌。","飘泊。","旧时约。","只柳绵花絮，年年如昨。","绿遍平芜天又各。","念马嘶门外，听来常错。","清明寒食，无限恨，燕子觉。"]},{"t":"十二时 偶忆","f":"古风","c":["绵濛二月如酥雨，做出销魂天气。","更独客、冷清清地。","拚只向、红篝倚。","灯灺香焦，天寒酒醒，往事难提起。","想那日、元夜迷藏，禊日秋千，人在绿杨丝里。","更当初、戟门嬉戏。","一部烟花轶记。","帘畔分钗，屏间惜曲，无限恹恹意。","便海棠月上，夜深谁放花睡。","奈几年、飘零羁旅，已隔千山万水。","昨岁铜街，记曾一见，隐隐卓金车子。","恰柳花如梦，又早香输过矣。"]},{"t":"大酺 七夕坐客大合乐漫赋","f":"古风","c":["历历银飙帘外落，又是一番节序。","今宵停宝杼，正南部烟花，西风牛女。","端正窥帘，轻狂换盏，多少良俦俊侣。","有白发何戡，青春张绪，流商刻羽。","渐露湿瓜筵，月穿针孔，纱幮无暑。","醉摇栀子树。","是郁金堂后西偏路。","谁知道、三生杜牧，前度刘郎，重来还到听歌处。","钿盒一朝分，记不起、长生私语。","算此际、情偏苦。","离多会少，岂独天边河鼓。","客且歌完金缕。"]},{"t":"多丽 题余氏女子绣陈思洛神图为阮亭赋","f":"古风","c":["问多情，今古谁堪雄长。","也无如、曹家天子，西陵台上虚帐。","更传闻、东阿子建，少年情绪骀荡。","水上明珠，波间翠羽，洛神一赋，神飞魂怆。","只一事、家王薄行，难对中郎将。","恐他日、黄须儿子，亦起非望。","又剪出、轻云态度，绣成流雪情状。","叹香闺、一双纤手，比似文心谁瑜亮。","便使当年，袁家新妇，自临明镜图娇样。","也还怕、传神阿堵，宛转须相让。","凝眸处、婀娜华容，千秋无恙。"]},{"t":"多丽 为李云田周小君宝镫题坐月浣花图","f":"古风","c":["暖红篝，月轮斜挂妆楼。","恰雅称、香闺心性，下阶小试莲钩。","好风筛、窗纱影碎，凉露浸、簟縠纹流。","裙带微飘，玉奴私语，人生易值此宵不。","何况是、楚天巫峡，嫦娥别种清幽。","羡此夜、月光人面，端正温柔。","渐满砌、竛竮红药，如啼欲睡疑羞。","倩轻绡、秋棠宜盥，央小玉、夜合将收。","更与传言，月波堪舀，莫问银床玉井头。","想像处、花前人月，永夜费凝眸。","还只怕、画图难肖，搦管增愁。"]},{"t":"六丑 孙坦夫招饮女史澹容家分赋","f":"古风","c":["转瓣莲巷左，见梵字、粉红墙角。","恰直个侬，晓妆匀面药。","花冠喔喔。","正蝉窗象格，西风轻飐，有碧桐花落。","亵纨秀鬋工调谑。","人是双文，艺精六博，种种玉纤花弱。","喜宿酲微析，春心犹恶。","酒狂如昨。","但人生行乐。","此际秋娘，最怜轻薄。","樽前况有韩嫣，碧云天偷擪，鸾箫低学。","更主是、多才孙绰。","平康巷、膝席分曹，满座雄谈马槊。","嘱金吾、莫收更钥。","别来时、斜倚朱阑口，偶然思著。"]},{"t":"六丑 丙午元夕雨","f":"古风","c":["听今宵疏雨，也算做、一年元夕。","旧事流波，一往如何觅。","香街马迹。","记常年灯市，鞭丝帽影，有许多相识。","阑珊灯火梅精立。","雅淡衣裳，轻盈姿格，人月同时一色。","便旁人也道，此是秦虢。","萍踪顿隔。","怕旧时李益。","昔日君平，无人怜惜。","檐前点点滴滴，似替人流泪，学人悽恻。","拚此去、花朝寒食。","都只向、雨雨风风，趖尽春光九十。","红篝拥、夜寒侧侧。","拟此情、并春柑传与，何由寄得。"]},{"t":"夜半乐 春夜观小伶演葛衣剧","f":"古风","c":["当时江左才调，乐安任仿，风丽推无偶。","记骠骑陪轩，秘书把袖。","青宫好士，朱门结客，更闻出入宫辇，翱翔苑囿。","奈玉树、人世偏难久。","诸郎憔悴至此，西华东里，南容北叟。","漫细数、平生密亲懿友。","葛帔谁嗟，练裙畴惜，可怜野鲜动轮，门稀渍酒。","相此事、将毋古今有。","阅此不觉，满泻琼舟，狂斟玉斗。","我论绝交君信否。","倘然疑，君再听、当筵红豆。","算兰簿、何必筹身后。","清歌且喜帘垂绣。"]},{"t":"六州歌头 邗沟怀古","f":"古风","c":["江东愁客，隋苑暗经行。","莺语滑，游丝细，夹衣轻。","正清明。","追忆当年此际，楼台外，秋千畔，棠梨树，垂杨渚，玉箫声。","一自风烟满目，伤心煞、水绿山青。","看江都虽好，旧迹已飘零。","憔悴兰成。","意难平。","念寄奴去，黄奴老，今古事，可怜生。","回头望，隔江是，石头城。","草纵横。","楼船南下日，君王醉，未曾醒。","宫车出，晚鸦鸣，使人惊。","惟有一江春水，依稀似、旧日盈盈。","想参军鲍照，欲赋不胜情。","此恨曾经。"]},{"t":"小诺皋 夏雨","f":"古风","c":["密洒修梧，轻敲疏竹，一雨碧天如此。","正日长亭院无憀，羁人徙倚。","满目烟潭草阁，多少红兰白芷。","更明珠、泻向荷钱容裔。","极浦沈沈，前汀瀰瀰。","又小楼、玉箫和雨。","吹入愁人心里。","无限事，思量起。","此际凭阑，几回推枕，总是故园千里。","忘不了、冰簟生寒，玉钗著水。","风景而今依旧，无奈鬓丝不似。","拚流落、楚尾吴头而已。","今夜楼中，明朝篷底，便潇湘、宋玉悲秋，未必此情堪比。","天欲暮，雨不止。"]},{"t":"宝鼎现 甲辰元夕后一日次康伯可韵","f":"古风","c":["星桥未琐，火树仍放，风光清绮。","浑不散、游童白马，杂沓笙箫阗宝砌。","香奁畔、又夜情思整，笑看兰缸结蕊。","渐耿耿、金波万顷，一派天街似水。","昨夜孤负无眠意。","枉费尽、描朱刷翠。","问天上、素娥因甚，杳若秦楼嬴女吹。","倚桂树、盼广寒车骑。","无质雾迷三里，元宵夜、一钩残月，仄在碧云堆里。","幸值今宵，重轮现、泰阶重履。","只邹枚渐老，何日宸游陪侍。","趁良夜、向春城醉。","醉语如花伎。","叹光景、好处难圆，月也与人无二。"]},{"t":"怨朱弦 寄淄川毕载积使君","f":"古风","c":["忆水嬉、天气鲜新。","兰叶离离，燕子纷纷。","卖饧时候，韶光妖冶撩人。","乐游原上，平康曲里，舞衫歌扇如云。","更广陵水色，半是堆蓝，半是拖银。","楼上珠轩九曲，船上湘帘四面，一样无尘。","还争羡、绿杨低处，刺史留宾。","正吴娘、细鲙红鳞。","玉箫作使，绣簟横陈。","小史菱花，妖童荷叶，宜笑宜嗔。","娇歌一曲，美酒千巡。","忽见夕阳零乱，且随著、袅袅金鞭，隐隐香轮。","早办两行灯火，留待参差归骑，同入城闉。","奈此日、依稀记省，事已前春。"]},{"t":"三台 春景用万俟雅言清明原韵","f":"古风","c":["又红闺挂残斜月，香尘镂完微雨。","整飞蝉、一望碧虚前，见皎镜、溶溶南浦。","风光汎、渐蘸垂杨缕。","三春景、如花似雾。","秋千社、淡日浓烟，蹴鞠队、繁筝急鼓。","料凤城、钿车宝毂，不住纷纷来去。","唤桂子、小玉报花香，日暖与、隔墙邻女。","踏青须、结伴东郊路。","看多少、绣帘珠户。","喜今日、满院晴丝，怕明朝、一庭落絮。","更杜宇唤取春老，榆钱压将春暮。","忆去年、元夜玩灯时，曾立在、火阑珊处。","转盼又、星桥燃蜡炬。","闹蛾儿、红楼紫府。","休沾惹、窃玉閒愁，且安排、寻香公务。"]},{"t":"抛毬乐 咏美人蹴鞠","f":"古风","c":["闻道凝妆多暇，蝉鬓娇嫭。","匀面才了，縆额初竟，纤纤眉妩。","蘸画毂、翠羽低飞，垒香阁、红襟新乳。","正好作剧寻欢，小叠鱼笺，遍约嬉春女。","向暖日红楼，商量细数，氤氲粉泽，喧阗笑语。","算白打秋千，和格五、总然无意绪。","且水晶帘畔，斜穿鞠域，相邀同去。","此际绰约轻盈，娇花百朵，琼枝一树。","宝钗松，罗袜小，争漾绛绡穷裤。","玉醉花欹，吹乱红巾几缕。","一泓香雪，临风慢舞，髣髴似滚琼闺絮。","更香毬将坠，最怜小玉多能，傍衬淩波微步。","渐蹴罢春憨，扶鬓影、娇喘浑无语。","小换轻容，满身红雨。"]},{"t":"哨遍 咏弹筝","f":"古风","c":["何处放娇，砑罗裙上，一寸销魂地。","倚桃笙、恰恰罢梳头，正是恹恹天气。","上青楼、轻拢鬓枣，乍挨纤笋，万种情如水。","正搭定鲛绡，妆完羲甲，十二钿蝉栉比。","对玉荷、清影颤琼枝。","又小语、流莺上柳丝。","慢撚斜搊，鬟亸衫偏，那人情味。","似秋夜楚天，急雨弹入空舲里。","鼓神弦、含商嚼徵尽伶俐。","拍碎棠梨，唱残红豆，一双玉剪低还起。","印粉痕圆，凝愁声重，碧到眉峰无际。","怪窗前、簌簌落红轻坠。","见十五、檀奴绿窗西。","要窃听、曲中私意。","不觉阁住银筝，婉转筹身世。","种玉前缘，簸钱旧事，脉脉萦牵不已。","家乡秦陇几时归。","此曲可怜犹在耳。"]},{"t":"早发望亭","f":"五言古诗","c":["水宿弭旅情，挂席愆宾饯。","泄云映寒涘，绪风扇轻艑。","暝增梁溪深，霁觉胥台缅。","棹歌写风波，群动互辗转。","沙鸨伫空明，江菼覆清浅。","红泉雨后流，白露草间泫。","周览虽言烦，幽默亦云阐。","远望姑苏城，绮罗若在眼。","舞基想馀粉，歌梁痗遗啭。","餐霞趣未慰，折麻务堪践。","寄谢区中缘，扬舲恣婉娈。"]},{"t":"刘逸民隐如","f":"五言古诗","c":["昔余丙申岁，读书长洲县。","章华宋大夫，相与共笔砚。","夹河幽巷绕，入市清溪漩。","风物本芳嘉，追随悉英彦。","刘惔宋家邻，尤与陈生善。","流连说生平，跌宕多顾盼。","君也性温慎，十步必缱绻。","及其感慨时，焱然闪岩电。","酷爱《湖海集》，搜录日不倦。","虿尾与银钩，错落铺黄绢。","吴城七月秋，别我赴京甸。","同门八九人，联袂临流饯。","君时醉起舞，长袖风中卷。","赠以珊瑚鞭，饰以黄金钿。","莫矜红颜好，宫中妒娇面。","莫言白璧完，连城轻自眩。","运至慕荣华，愁来忆贫贱。","刘生方策名，欻遘贤关变。","是时盛苞苴，富人工汲援。","铜山砉然开，中有集贤院。","乌裸作主司，郑白朕翩荐。","谁令黔娄生，误厕时流选。","昆冈一旦焚，玉石何由见？","刘生恬淡人，竟受谗言煽。","白月照阛扉，不是昭阳殿。","凄凄范蔚宗，恻恻书团扇。","戍君玄菟郡，插君白羽箭。","君躯绝短小，何以能征战？","君身非金石，何以堪忧怨？","刘琨绕指柔，夙昔曾百炼。","江东西风起，莼鲈可以膳。","待君君不来，泪下如流霰。"]},{"t":"酬许元锡","f":"古风","c":["嘉隆以后论文笔，天下健者陈华亭。","梅村先生住娄上，斟酌元化追精灵。","忆昔我生十四五，初生黄犊健如虎。","华亭叹我骨格奇，教我歌诗作乐府。","二十以外出入愁，飘然竟从梅村游。","先生呼我老龙子，半醉披我赤霜裘。","此生阑入铜驼路，可怜老作《江南赋》。","头上不畏咸阳王，眼前只认丁都护。","晚交许子怀抱开，看尔不合长悲哀。","手提一诗来赠我，十幅错落红玫瑰。","我年三十馀，清狂爱儿戏。","旁人见我笑不休，安知我有填膺事。","日间击鼓夜击鲜，行乐安得千万年。","何肯龌龊学章句，三日新妇殊可怜。","许子赠诗逾一月，念欲报之久不发。","昨宵饱看冒家灯，一寸管城老龙渴。","掀髯狂作许生歌，食纸春蚕响不歇。","明朝归客正扬舲，海色苍茫青更青。"]},{"t":"赠李研斋太史","f":"古风","c":["人云蜀道如青天，君家乃在青天上。","蚕丛鸟道不得归，一度思归一惆怅。","去年石头城，道遇李谪仙。","手持白玉麈，囊乏青铜钱。","一言称意百不愁，邀我直上秦淮之酒楼。","城南杨花白如雪，一一乱扑胡姬裘。","笑谓金陵姬，何似巫山女？","十年枉作《剑阁铭》，白盐赤甲奈何许！","昔住锦官城，乐事不可当。","木棉花发处，斜对碧鸡坊。","桃笙賨布居民卖，蒟酱江鱼过客尝。","此时二月粉水香，巴僮巴女发浩唱。","赕钱夜市成都酒，歈歌春赛武都王。","别来旧事心茫茫，传闻李特屠残疆。","卧龙跃马竟谁是，天彭井络空苍凉。","前者百丈船，牵过钟山郭。","忽见三巴人，欻然万金落。","诸葛祠堂尽棘榛，谯周子弟俱俘掠。","当时婉娈直铜龙，都堂香药掖门松。","自从丧乱著芒屩，飘零已复成吴侬。","一身虽在不自保，何况盗贼多于蜂。","瞿塘恶浪千万重，念之只复愁心胸。","安能吹我落天外，蹲鸱饱作西川农。","语君且饮勿愀怆，眼前万事太卤莽。","故里新年栈道开，官军已缚邛笮长。"]},{"t":"钱唐浴马行","f":"七言古诗","c":["杭州八月秋风早，极目江头皆白草。","凤山门前铁骑横，花马营中水泉好。","阿谁黄须称奚官，白靴毳帐红罽袄。","是日牵来一万匹，云锦连天色杲杲。","钱塘江渚多菰蒲，晴江空翠微卷舒。","嬉游尽向此间去，边儿十岁名花奴。","忽闻一声吹觱篥，千群争放桃花驹。","红泉骀宕自然丽，凡鬃灭没何其都。","一匹娇嘶一匹啮，十匹骄矜汗流血。","须臾五花浮满红，万顷寒涛蹴飞雪。","龙堂少女神悄绝，雾鬣烟蹄半明灭。","少焉不动齐徜徉，江流欲静江云凉。","极浦湘娥鼓文瑟，中流江妾拖红裳。","此时观者倾城国，中有军人泪沾臆。","自言十五隶金吾，滁阳苑马亲承直。","犹见先皇校猎时，金风初到万年枝。","青骢细食雕胡饭，翠拨轻笼杨柳丝。","天育忽逢沧海变，从此麒麟罢欢宴。","苜蓿翻栽太液池，骅骝直上昭阳殿。","紫台青海日从征，马上琵琶塞上情。","温泉十载无消息，忍唱钱塘《浴马行》。"]},{"t":"寄黄黎洲先生求为先人志墓","f":"七言古诗","c":["熹宗之朝盗窃柄，国事稠浊由诸阉。","刊章告密满天下，劫火烈烈昆冈炎。","忠端骨鲠置牢户，少保强项遭髡钳。","《三朝要典》乱白黑，尔曹病热徒狂谵。","膺滂之后爱名节，翁与吾父均酸咸。","忠泉出井流不涸，孝笋拔地天能参。","东都坛墠立名字，西园邸阁纷袿襜。","怀宁乱贙老逾怒，矫尾直拂钟山岩。","我师秋浦魁垒士，便树颐颏张须髯。","一呼袒裼暴猛兽，笔阵霍若霜锋铦。","妖么得志逞报复，一网尽矣心所甘。","王师南下明社屋，人头畜鸣尽夷歼。","四十年来市朝换，曜灵急景奔惊帆。","崇文门外党碑倒，沙石磨治苔纹嵌。","平生先子胶漆友，半作黄叶经秋芟。","晨星落落只翁在，开元轶事馀谁谙？","先朝钩党有本末，冰玉硌礐秋阳暹。","今人往往咎过激，毋乃丑正丛讥谭。","呜呼吾父没已久，墓门郁郁愁松杉。","累翁一片道旁碣，请放健笔为雕镵。"]},{"t":"忆贵池吴师","f":"五言律诗","c":["当代论兵会，谁人可擅场？","刘琨归朔北，孙策入丹阳。","一诺轻车骑，千言破混茫。","灵旗如仿佛，毅魄想飞扬。"]},{"t":"捧读石斋黄公所撰先少保神道碑赋此追感","f":"七言律诗","c":["周侯池畔树苍苍，遗碣岧峣屹此乡。","哀诔南朝颜特进，碑铭东汉蔡中郎。","千秋定论归青史，一夜悲风起白杨。","此日踌躇肠欲断，漳南高冢亦昏黄。"]},{"t":"喜汉槎入关和健庵先生原韵","f":"七言律诗","c":["当时彩笔撼江关，数子声名天地间。","讵料文章遭贝锦，偏教冰雪炼朱颜。","廿年苦语三更尽，万里流人二月还。","不信娥眉真见赎，感恩我亦泪潺湲。"]},{"t":"秋日怀幔亭先生二首 其一","f":"七言律诗","c":["百二山河极望残，一门群从尽南冠。","谁怜鹦鹉笼中语，大有琵琶塞上弹。","寂寞金鸡双阙迥，飘零石马七陵寒。","锒铛夜宿昭阳殿，疑作西宫月影看。"]},{"t":"秋日怀幔亭先生二首 其二","f":"七言律诗","c":["秋色苍茫上佩刀，故人消息梦魂劳。","石城剧报收袁粲，鲁国惊闻捕孔褒。","雪窖羝羊双涕泪，锦官杜宇一悲号。","好凭万骑平南将，急趁江风挂战袍。"]},{"t":"送张若水出关","f":"七言律诗","c":["祖母秦州父锦州，卢家少妇又邗沟。","百年骨肉抛三地，万死悲哀并九秋。","欲赠愧无银络索，将离怕听钿箜篌。","汉庭早晚流人赦，望尔归鞭度陇头。"]},{"t":"别紫云","f":"七言绝句","c":["二度牵衣送我行，《并州》才唱泪纵横。","生憎一片江南月，不是离筵不肯明。"]},{"t":"赠歌者陈郎","f":"七言绝句","c":["天涯踪迹半旗亭，谱遍《龟兹》不忍听。","怜尔少年非失意，逢人也唱《雨霖铃》。"]},{"t":"新荷叶 采莲","f":"古风","c":["水郭开奁，酿成一片湖光。","翠盖亭亭，扶他几队红妆。","谁家女伴，采莲歌、竞下横塘。","吹来笑语，竟川雾鬓风裳。","日暮归来，画船犹剩馀香。","此际冰轮，天边又送新凉。","觅莲得藕，心儿苦、隐隐商量。","今宵莲子，劈来生怕空房。"]},{"t":"沁园春 送友入山采茶","f":"古风","c":["十里溪山，竹粉缨峦，兰风藻川。","有蒙茸萝葛，蔽亏曦月，坦迤涧壑，向背林泉。","夕渡遄归，晨渔缓出，谷唱潭吟韵邈绵。","居此者，是秦时毛女，汉代琴仙。","人家四月开园，送君去、刚逢谷雨天。","恰晴村绿崦，数间僧灶，清江翠箬，一带商船。","拍处盈盈，焙馀冉冉，归卧回廊瘦石边。","松涛沸，正龙团乍碾，蟹眼初煎。"]},{"t":"贺新郎 中秋前五日看早桂","f":"古风","c":["灏气收残暑。","恰金飙、夜来染就，小山幽树。","丛桂离离香满径，正值秋棠开处。","掩映也、倍添娇妩。","红烛三条围锁院，记妲娥、不肯相怜取。","平生恨，那堪数。","思量旧事多如雨。","忆前生、婆娑曾在，清虚之府。","沦谪红尘三十载，却羡广寒清苦。","忘不了、花阴玉兔。","月到中秋光定满，折花枝、吾欲骖鸾去。","再快作，霓裳舞。"]},{"t":"水龙吟 咏杜鹃花","f":"古风","c":["小楼日日轻阴，花枝映得纱窗曙。","恰推窗看，玉栏干外，红香无数。","樱笋时光，秋千院落，衬他娇嫭。","只一枝怯雨，泫然却想，故乡也，知何处。","自别西川万里，拟消受、江南歌舞。","讵料年年，每当开日，便成春暮。","甚日重逢，锦城丝管，华阳士女。","待化为蜀魄，枝头唤道，不如归去。"]},{"t":"天香 咏桂","f":"古风","c":["灵隐门前，番禺城里，秋花一种清绝。","碧海冷冷，金风阵阵，压下数堆黄雪。","山斋湖舫，说不尽，幽芬清洌。","金粟一番开谢，冰轮几回圆缺。","曾经托根瑶阙。","几曾羡、人间风月。","相伴蟾孤兔冷，羿犯偷折。","自与广寒轻别，记不起、霓裳旧时阕。","带恨才开，和愁细结。"]},{"t":"河传 杨花","f":"古风","c":["藏鸦时候。","当初绾住，永丰坊口。","丝丝踠地蘸春波，雨后。","和烟笼翠牖。","如今满院喧晴雪。","香绵积。","滚尽东风力。","茜袂遮。","翠幰斜。","杨花。","一生不著家。"]},{"t":"秋夜月 蛟桥望月","f":"古风","c":["月儿圆也。","趁金风，舒皓彩，碧空斜挂。","浸著两溪玉浪，一城霜瓦。","水楼上，招红袖，许多妖冶。","閒话、都笑蟾孤兔寡。","桥头月下。","记当年，周子隐，曾将虎射。","千古灵旗飒飒，英姿堪画。","到而今，嗟满目，渔村蟹舍。","涛声、偏只共更声打。"]},{"t":"鱼游春水 秋日过金鱼池","f":"古风","c":["韦曲光颓澹，有半亩金塘潋滟。","一般红鲤，衬著绿波摇飐。","色分凤阙丹初滴，光映银墙红欲淡。","芳饵轻投，縠纹微蘸。","尚隔金沟紫缆。","难望见、宫娥阿监。","输他百子池中，天香亲染。","废馆何来箫鼓到，空潭只被菰蒲糁。","独对西风，几番伤感。"]},{"t":"翠楼吟 三月十五日虎邱即景","f":"古风","c":["桃花水绛，卵色天青，早烟著人如醉。","风光日夜换，换不了、吴宫罗绮。","千年霸气。","只莺啭山房，鸦啼水寺。","当年事。","断崖老树，依稀能记。","冶丽。","簇队成团，有钗虫落磴，裙梅飘砌。","剑池苔藓黑，越显得、明妆绝世。","佛前私誓。","怕乱水东流，夕阳西逝。","凭阑望，五湖晴爽，碧空无际。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其一","f":"古风","c":["重五节，记得在金陵。","绿水没腰连夜雨，锦帆衔尾半河灯。","往事思腾腾。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其二","f":"古风","c":["重五节，记得在南徐。","红板闸喧停画鹢，翠花磁湿贮黄鱼。","踏浪最怜渠。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其三","f":"古风","c":["重五节，记得在扬州。","歌板千群游法海，酒旗一片写高邮。","茉莉打成毬。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其四","f":"古风","c":["重五节，记得在吴门。","北寺墙头兰叶鬓，桐桥船里墨花裙。","那许不销魂。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其五","f":"古风","c":["重五节，记得在西湖。","万马钱塘堤上戏，六桥士女镜中趋。","髣髴射潮无。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其六","f":"古风","c":["重五节，记得在嘉兴。","也共朱郎湖上饮，菖蒲花底醉难胜。","别后见何曾。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其七","f":"古风","c":["重五节，记得在如皋。","小展簟纹融似水，杨枝低唱紫云箫。","回首路迢迢。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其八","f":"古风","c":["重五节，记得在前门。","庙市花盆笼蟋蟀，门摊锦袋养鹌鹑。","榴火帝城春。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其九","f":"古风","c":["重五节，记得在家乡。","麝粉细调蛾子绿，虎钗新破茧儿黄。","扼臂五丝长。"]},{"t":"望江南 宛城五日追次旧游漫成十首 其十","f":"古风","c":["重五节，今岁在南阳。","墙脚蜗牛行艾叶，檐牙鸠妇话榴房。","丝雨湿年光。"]},{"t":"望江南 商邱杂咏五首 其一","f":"古风","c":["商邱忆，忆煞冶游人。","㔩叶绿鞲檠兔鹘，闹花锦袋贮鹌鹑。","飞鞚逐黄尘。"]},{"t":"望江南 商邱杂咏五首 其二","f":"古风","c":["商邱忆，绮席笑颜酡。","脆滑韭芽黄胜靥，松圆粔籹白于罗。","扶路酒人多。"]},{"t":"望江南 商邱杂咏五首 其三","f":"古风","c":["商邱忆，马客似幽凉。","枣子集头调犬路，木兰庙角斗鸡场。","自许尽轻狂。"]},{"t":"望江南 商邱杂咏五首 其四","f":"古风","c":["商邱忆，梳裹胜江淮。","青漆车儿垂绣幔，乾红靴子隐弓鞋。","相遇宋城隈。"]},{"t":"望江南 商邱杂咏五首 其五","f":"古风","c":["商邱忆，春景浩无涯。","坐上一尊桑落酒，门前千亩牡丹花。","踞坐拨筝琶。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其一","f":"古风","c":["如皋忆，最忆小三吾。","隔水红墙春冉冉，拍波绿箬雨苏苏。","隐几一愁无。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其二","f":"古风","c":["如皋忆，忆得暮云天。","著醋红蛏经酒脆，带糟紫蛤点羹鲜。","日日醉花前。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其三","f":"古风","c":["如皋忆，记坐得全堂。","几缕椒鸡闲说饼，半罂花露静焚香。","弦索夜枨枨。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其四","f":"古风","c":["如皋忆，如梦复如烟。","满院嫩晴歌板脆，一城纤月酒旗偏。","过了十多年。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其五","f":"古风","c":["如皋忆，犹忆看春人。","夹巷帘栊空胜水，后街香粉碾成尘。","看煞不曾嗔。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其六","f":"古风","c":["如皋忆，曾记卧湘中。","万点水花笼夜碧，半岩火树落春红。","飏起妓衣风。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其七","f":"古风","c":["如皋忆，忆看小桃花。","水绘园门通小寺，春堤一道不曾斜。","千树烂晴霞。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其八","f":"古风","c":["如皋忆，往事倍盈盈。","水郭题名新怅望，板桥话别旧心情。","双鬓可怜生。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其九","f":"古风","c":["如皋忆，数子总疏狂。","刚中酒时思许掾，恰伤春处念曹王。","香茗记张郎。"]},{"t":"望江南 寄东皋冒巢民先生并一二旧游十首 其十","f":"古风","c":["如皋忆，按谱砌香词。","传语东君须婉转，此情莫遣外人知。","除说与杨枝。"]},{"t":"潇湘神 盱眙舟中作","f":"古风","c":["淮水流，淮水流，蛮弦铜鼓不胜愁。","骊山金盌无消息，六月园陵冷胜秋。"]},{"t":"桂殿秋 淮河夜泊","f":"古风","c":["波淼淼，月胧胧，神巫争赛禹王宫。","船头水笛吹晴碧，樯尾风灯飐夜红。"]},{"t":"桂殿秋 偶记","f":"古风","c":["春漠漠，雨疏疏，绮窗偷访薛涛居。","凝情低咏年时句，人在东风二月初。"]},{"t":"南乡子 江南杂咏六首 其一","f":"古风","c":["天水沦涟。","穿篱一只撅头船。","万灶炊烟都不起。","芒履。","落日捞虾水田里。"]},{"t":"南乡子 江南杂咏六首 其二","f":"古风","c":["夔魍喧豗。","枫根渍酒纸成灰。","泽国不知山国苦。","铜鼓。","醉觋夜深作蛮语。"]},{"t":"南乡子 江南杂咏六首 其六","f":"古风","c":["笳盖从风。","旌竿十丈压桯红。","卜式相如争匿笑。","惊告。","同辈屠沽并佣保。"]},{"t":"南乡子 清明后一日吴阊道中作二首 其一","f":"古风","c":["才过清明，东风怯舞不胜情。","红袖楼头遥徙倚，垂杨里，阵阵纸鸢扶不起。"]},{"t":"南乡子 清明后一日吴阊道中作二首 其二","f":"古风","c":["捲絮搓绵，雪满山头是纸钱。","门外桃花墙内女，寻春路，昨日子规啼血处。"]},{"t":"杨柳枝 本意","f":"七言绝句","c":["袅娜丝杨水面生，波光柳态两盈盈。","搅来风色昏于梦，不许春江绿不成。"]},{"t":"法驾导引 饥乌","f":"古风","c":["饥乌噪，饥乌噪，毛羽忒摧颓。","故国稔经霜雪满，他乡错料稻粱肥。","曛黑只飞飞。"]},{"t":"法驾导引 曹南耕表弟礼斗甚虔词以纪之四首 其一","f":"古风","c":["铜芝盖，铜芝盖，缥缈结祥烟。","碧柰□开忉利市，紫阳宫近夜摩天。","一枕小游仙。"]},{"t":"法驾导引 曹南耕表弟礼斗甚虔词以纪之四首 其二","f":"古风","c":["西风动，西风动，阆苑一愁无。","毛女弄琴红捍拨，井公戏博紫樗蒱。","閒话鲍家姑。"]},{"t":"法驾导引 曹南耕表弟礼斗甚虔词以纪之四首 其三","f":"古风","c":["元始殿，元始殿，瑶陛一层层。","丹灶几声仙院笛，碧池千盏醮坛灯。","人静露华凝。"]},{"t":"法驾导引 曹南耕表弟礼斗甚虔词以纪之四首 其四","f":"古风","c":["梅庐闭，梅庐闭，长日不曾闲。","绛帔黄絁晨控鹤，绿章赤篆夜扶鸾。","来往总仙官。"]},{"t":"甘州子 新霁同南耕散步潘原白园亭主人不在题壁而去二首 其一","f":"古风","c":["沁园春在画桥西，花月价，贱如泥。","碧城高与粉墙齐，拟把数行题。","题未了，斜日乱莺啼。"]},{"t":"甘州子 新霁同南耕散步潘原白园亭主人不在题壁而去二首 其二","f":"古风","c":["铜环半面涩虾蟆，鹦鹉睡，懒呼茶。","胭脂新湿小窗纱，柳线渐胜鸦。","无人到，开遍一园花。"]},{"t":"思帝乡 夏夜","f":"古风","c":["花底萤，高低穿绣扃。","惯照人间閒事，一星星。","待展轻纨小扑，怯还停。","又向墙边竹，去冥冥。"]},{"t":"长相思 月夜看花作","f":"古风","c":["掩柴门，步篱门。","夜色茫茫碧一痕。","微酣过别村。","梨花繁，李花繁。","错道溪昏月又昏。","风吹银浪浑。"]},{"t":"醉太平 戏咏钱效宋人独木桥体四首 其一","f":"古风","c":["红闺簸钱，绿窗意钱。","姬人小字钱钱，佩男钱女钱。","花骢铁钱，兰橑绮钱。","癖同和峤惟钱，问直他几钱。"]},{"t":"醉太平 戏咏钱效宋人独木桥体四首 其二","f":"古风","c":["青苔印钱，朱荷贴钱。","空囊谁笑无钱，更漫空荚钱。","文臣爱钱，娼家数钱。","世间万事由钱，向天公贳钱。"]},{"t":"醉太平 戏咏钱效宋人独木桥体四首 其三","f":"古风","c":["吹箫乞钱，贩脂鬻钱。","西风江岸摊钱，负茶商进钱。","西邻醵钱，东邻打钱。","明朝去索碑钱，付黄公酒钱。"]},{"t":"醉太平 戏咏钱效宋人独木桥体四首 其四","f":"楚辞体","c":["篯兮古钱，镠兮后钱。","箧中剩五铢钱，是秦钱汉钱。","可儿使钱，阿奴惜钱。","逢花休愬无钱，看风吹纸钱。"]},{"t":"醉太平 题孙无言半瓢居","f":"古风","c":["颜渊一瓢，先生半瓢。","傍人笑问团瓢，是吟瓢酒瓢。","巢由饮瓢，先生住瓢。","行窝何处非瓢，任肩挑坏瓢。"]},{"t":"昭君怨 咏柳","f":"古风","c":["谁把软黄金缕，袅在最临风处。","低蘸绿波中，太濛濛。","愁杀花花絮絮，半是风风雨雨。","一树倍堪怜，寺门前。"]},{"t":"春光好 桐川道中作","f":"古风","c":["鴶鵴叫，戍楼平，漆灯明。","一路春田四月、少人耕。","恶木丛中古驿，乱山缺处孤城。","安得短衣看射虎、过残生。"]},{"t":"柳枝 人日过畹仙校书家三首 其一","f":"古风","c":["几阵帘风漾雪肤，正春初。","小姑年小理清歈，怯氍毹。","浅道胜常钗胜转，红幡软。","笼中鹦鹉为谁呼，似留予。"]},{"t":"柳枝 人日过畹仙校书家三首 其二","f":"古风","c":["兰焰平明一缕微，弄馀辉。","含娇和梦换春衣，傍床帏。","手拈红绶通眉语，凭郎主。","郎看筝雁会翻飞，便须归。"]},{"t":"柳枝 人日过畹仙校书家三首 其三","f":"古风","c":["雪净春瓷隐绿光，发茶香。","手擎江橘颤钗梁，玉纤凉。","放夜传闻今岁早，银灯好。","再来须尽十分狂，省萦肠。"]},{"t":"点绛唇 江楼醉后与程千一","f":"古风","c":["绝忆生平，蹉跎祇为清狂耳。","酒酣直视，奴价何如婢。","断壁崩崖，多少齐梁史。","掀髯喜，笛声夜起，灯火瓜洲市。"]},{"t":"点绛唇 题延令张燕孙秋词 燕孙园次婿","f":"古风","c":["吴苑初晴，阳山大好朝来髻。","相逢却是，山抹微云婿。","一幅词儿，满纸悲哉气。","冬深矣，重添秋意，秋在君词里。"]},{"t":"点绛唇 舟行秋望","f":"古风","c":["历乱烟村，推篷爱煞晴秋爽。","柴门栗橡，风定谁敲响。","野鸭濛濛，懒漫勤依桨。","鱼蛮莽，惊飞两两，触损玻璃样。"]},{"t":"点绛唇 和成容若韵","f":"古风","c":["并坐燕姬，琵琶膝上圆冰薄。","轻拢浅抹，巧把羁愁豁。","竟去摇鞭，点草霜鬉渴。","西风恶，数声城角，冷雁濛濛落。"]},{"t":"中兴乐 秋夜","f":"古风","c":["水边小弄靠烟廊，秋宵正掩书窗。","忽有人声，飘来画墙。","不辨衣香水香，太微茫。","分明有个，玉簪花底，暗舀新凉。"]},{"t":"纱窗恨 蝴蝶和毛文锡韵","f":"古风","c":["闹红咂翠何时了，漾春心。","一生轻薄谁拘管，粉墙阴。","花架底潜防纨扇，画梁前巧斗红襟。","袖上鸳裙摺，费泥金。"]},{"t":"浣溪沙 癸丑东溪雨中修禊","f":"七言古诗","c":["春水挼蓝接远汀，晚山愁黛矗银屏。","绿杨城外画船停。","燕剪轻阴拖水榭，莺翻嫩雨湿兰亭。","半溪灯火酒微醒。"]},{"t":"浣溪沙 春日同史云臣远公买舟山游小泊祝陵纪事","f":"七言古诗","c":["春水平如簟一般，茶铛棋局委潺湲。","好风吹去不须还。","二月新晴锄绿笋，半村微雨卖青山。","垂杨低处隐禅关。"]},{"t":"浣溪沙 偶憩清和庵即事","f":"七言古诗","c":["垒石缘流一径斜，寺门幽似野人家。","西风黄叶响篱笆。","紫入鹦哥名是菊，红归鸦舅色如花。","僧雏竹下自煎茶。"]},{"t":"浣溪沙 咏橘四首 其一","f":"七言古诗","c":["秋染包山树树苍，高低斜缀绛纱囊。","西风飘过满湖香。","未免为奴供饮啖，微闻有叟话沧桑。","霜红露白尽徜徉。"]},{"t":"浣溪沙 咏橘四首 其二","f":"七言古诗","c":["髣髴轻躯十八娘，生憎柑子道家妆。","石榴裂齿也寻常。","擘罢春纤丹液冷，传来罗帕玉肌凉。","昨宵酒恶倍思量。"]},{"t":"浣溪沙 咏橘四首 其三","f":"七言古诗","c":["船入荆溪思豁然，曾传此语自坡仙。","拟将种树遣萧闲。","今日亭台无楚颂，旧时橘柚满吴天。","风流人去一千年。"]},{"t":"浣溪沙 咏橘四首 其四","f":"七言古诗","c":["藻耀霜林八月中，累累赪卵石湖东。","篾包箬裹满筠笼。","天上渴乌偷样好，铸成一点橘般红。","蓬莱夜半已曈昽。"]},{"t":"浣溪沙 山塘即事","f":"七言古诗","c":["窈窕山塘半酒家，浣衣归去笑吴娃。","东风吹得绣裙斜。","琴几砑光麋绿竹，楸枰敲落水仙花。","碧纱窗影浸山茶。"]},{"t":"浣溪沙 蚌埠即事","f":"七言古诗","c":["漭漭淮河杳似年，森森蚌岭远攒天。","风来吹作鲎帆圆。","柰熟叟擎千颗雨，柳浓儿浴一溪烟。","黄瓜凉粉趁墟船。"]},{"t":"浣溪沙 雨中由枫桥至齐门","f":"七言古诗","c":["料峭春寒恰未消，鹁鸪啼急水迢迢。","半船微雨过枫桥。","荠菜绿平齐女墓，梨花雪压伍胥潮。","柳枝和恨一条条。"]},{"t":"浣溪沙 月夜虎邱纪所见","f":"七言古诗","c":["小立山塘玩暝烟，市楼灯火未阑珊。","暗中依约遇婵娟。","风里绣裙吹浪皱，雨馀红屐印泥圆。","一钩春月寺门前。"]},{"t":"浣溪沙 陆上慎移居东郊二首 其一","f":"七言古诗","c":["背郭沿溪路不遥，杏花村里菜花桥。","故人和燕定新巢。","药裹暖分花影晒，渔蓑闲受柳绵飘。","小楼长听雨潇潇。"]},{"t":"浣溪沙 陆上慎移居东郊二首 其二","f":"七言古诗","c":["水驿家家看打鱼，晴檐日日唤提壶。","知君高卧一愁无。","乍可小词填幼妇，不妨新论著潜夫。","明年花下引鹓雏。"]},{"t":"浣溪沙 逮下为阎牛叟赋","f":"七言古诗","c":["频笑王家九锡文，犊车麈尾事纷纭。","蔡充儿语最传闻。","每遣白公留阿素，却教坡老买朝云。","红闺若个不输君。"]},{"t":"酒泉子 咏画上香橼为祖仁渊赋","f":"古风","c":["拌蜡匀檀，搓得软罗圆皱。","西风抛打赭黄毬，堕高楼。","翠瓷红架贮清幽，分外宜秋。","凭皓腕，劈春绒，和麝粉，络床头。"]},{"t":"天门谣 汲县道中作","f":"古风","c":["已过秋千节，看汲冢、苔钱铺缬。","淇流咽，说古今兴灭。","比干庙、年年啼百舌，月与铜盘都缺。","愁恨织。","花落处，棠梨成血。"]},{"t":"添字昭君怨 竹逸约过城南僧舍看梅以雨不果词以柬之","f":"古风","c":["梅压板桥玉皱，人隔寺墙香透。","昨朝花下约同游，散春愁。","准趁平芜携手，还傍粉帘赊酒。","今朝细雨太绵绵，且高眠。"]},{"t":"添字昭君怨 夜泊銮江","f":"古风","c":["今夜月明江上，绿染吴天新样。","万家帘幕火微明，佛狸城。","一点瓜洲玉糅，半笏金山雪透。","乱帆飒飒响秋江，泻银泷。"]},{"t":"菩萨蛮 和龚伯通寄于生用原韵","f":"古风","c":["撩人最是眉烟皱，勾人不在春弓瘦。","红烛奈他何，相看泪孰多。","别来浑不寐，梦里人谁至。","拚倚钿筝眠，娇音落枕边。"]},{"t":"菩萨蛮 代于生答伯通仍用前韵","f":"古风","c":["舞馀叠得衫儿皱，酒阑趱得人儿瘦。","郎口似隋何，相思谎最多。","昨宵刚小寐，书与砧同至。","砧响伴人眠，寄书人那边。"]},{"t":"菩萨蛮 春日忆西湖次陆荩思徐竹逸倡和原韵","f":"古风","c":["划波曾到西泠去，掠入绿痕难睡处。","疏簟杂眠鸥，真成自在游。","如今佳兴歇，闷过春三月。","刚见摘兰芽，山村又焙茶。"]},{"t":"菩萨蛮 柬云臣讯牡丹消息","f":"古风","c":["银铃油幕安排巧，刚刚只等花期早。","闻说药栏东，娇香将晕红。","连朝天欲雨，苦勒春寒住。","何日一枝开，侬应侧帽来。"]},{"t":"菩萨蛮 云臣招看牡丹以雨未赴小词奉柬并柬是日赏花诸子","f":"古风","c":["堂前劝酒清尊急，阑前著雨红妆湿。","多分酒醒时，娇香和泪辞。","留花花不可，索性将花躲。","拚做薄情人，恹恹睡一春。"]},{"t":"菩萨蛮 遥题广陵吴元式棣友堂","f":"古风","c":["驱车昨过田真里，千年想像荆花紫。","今日广陵城，惟君继令名。","休歌一斗粟，羡汝东西屋。","准拟到华堂，来眠大被旁。"]},{"t":"菩萨蛮 过云臣宅看牡丹归有作","f":"古风","c":["满城争放花千朵，狂夫那肯家中坐。","才得过西邻，东家唤又频。","径须冲酒去，那怯廉纤雨。","日日为花颠，何曾让少年。"]},{"t":"菩萨蛮 吴门将归为姜学在题岁寒图","f":"古风","c":["濒行不折阊门柳，殷勤只劝皋桥酒。","笑指岁寒图，交情如不如。","领君珍重意，树乃犹如此。","题罢上归船，孤帆入暝烟。"]},{"t":"菩萨蛮 为竹逸题徐渭文画紫牡丹","f":"古风","c":["年时斗酒红栏下，一丛姹紫真如画。","今日画花王，依稀洛下妆。","徐熙真逸品，浅晕葡萄锦。","挂在赏花天，狂蜂两处喧。"]},{"t":"菩萨蛮 将发吴门时庭际海棠盛开用香严词韵","f":"古风","c":["年年惯作他乡客，今年怕与花离别。","花也替侬愁，春江无尽头。","不如双粉蝶，镇日团花侧。","花发唱骊歌，人归花若何。"]},{"t":"菩萨蛮 为友人题像","f":"古风","c":["万山槲叶西风起，黛痕滴入衫痕里。","砚匣净无尘，依稀陆子春。","他时须献赋，细马朝天去。","相映柳毵毵，宫娥报捲帘。"]},{"t":"菩萨蛮 燕市赠相者","f":"古风","c":["虎坊桥畔逢唐举，西风酌酒为君语。","齃鼻与魋肩，何尝直一钱。","浮云卿眼见，富贵非吾愿。","酒尽拨三弦，狂歌菩萨蛮。"]},{"t":"菩萨蛮 为阎牛叟新纳姬人催妆二首 其一","f":"古风","c":["悼亡才写菖蒲幅，定情又索消魂曲。","淮估附书来，红椷和笑开。","鹊桥填已久，侬是催妆手。","老去漫情多，颠狂奈尔何。"]},{"t":"菩萨蛮 为阎牛叟新纳姬人催妆二首 其二","f":"古风","c":["雕香刻翠飞琼像，多时供在妆楼上。","拣个女如花，纤腰同拜他。","白家蛮柳在，浅漾东风外。","情绪惯瞒伊，欺他尚小时。"]},{"t":"菩萨蛮 赠梁陶侣 棠村夫子小阮","f":"古风","c":["邯郸年少春衫绿，鸣筝竞唱棠村曲。","檀板鹧鸪天，丛台月正圆。","谢公犹子在，才调空群辈。","谁爱紫罗囊，书签玳瑁装。"]},{"t":"采桑子 送李云田之吴门迎侍儿扫镜二首 其一","f":"古风","c":["一群荡子扬州住，帘底红牙。","门畔金车，邀笛藏钩乐事赊。","如何短李先辞我，云有吴娃。","生小如花，日上江楼候客楂。"]},{"t":"采桑子 送李云田之吴门迎侍儿扫镜二首 其二","f":"古风","c":["我言息国夫人好，何不归哉。","早到妆台，湘水今秋绿胜苔。","君言聊复为欢耳，谜语应猜。","庄语非诙，神物须知是手推。"]},{"t":"采桑子 题画兰小册 其一 兰为横波夫人所绘","f":"古风","c":["回思吮粉调铅日，紫菂缃芽。","露蕊烟葩，压倒南唐落墨花。","杜兰香去多时了，碎绵零纱。","飘泊谁家，剩有眉楼小篆斜。"]},{"t":"采桑子 题画兰小册 其二 兰为横波夫人所绘","f":"古风","c":["后堂丝管亲曾醉，衮遍筝琶。","舞煞蛮靴，百幅红兰出内家。","左徒弟子今谁在。","只有章华。","沦落天涯，忍看灵均九畹华。"]},{"t":"采桑子 题潘晓庵斗酒百篇小像","f":"古风","c":["画师貌出高人态，梧竹澄鲜。","庭户萧然，道是诗颠并酒颠。","玉山百罚颓唐甚，醉汉琼筵。","纱帽微偏，击唾壶歌宝剑篇。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其二","f":"古风","c":["轻轻过了元宵也，春雪才融。","零雨还濛，雨细如愁糁碧空。","孤灯炙罢和衣睡，莫打晨钟。","绣毂银骢，准拟今宵梦里逢。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其六","f":"古风","c":["添丁屈指今三岁，未识而翁。","睡去朦胧，耳畔呼耶语句工。","关河梗绝书难达，何日相逢。","绣褓亲缝，颠倒天吴短褐中。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其七","f":"古风","c":["有人来自尚书墓，燕子楼中。","红粉成空，树树衰杨夜起风。","非公人尽嫌余懒，絮酒难从。","疏散谁容，头白羊昙路已穷。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其八","f":"古风","c":["昨冬并说西樵死，送尽英雄。","祇剩衰翁，寒日西颓贯白虹。","从兹东海无奇气，鱼眼波红。","鳌背霜浓，瑶岛琼台何处峰。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其九","f":"古风","c":["年来怕作伤心句，双袖龙钟。","左耳新聋，莫把箜篌唱懊侬。","不如且作消愁计，卖药无终。","鬻畚山东，自署人间亡是公。"]},{"t":"采桑子 正月二十日从吴天石处获读纬云弟京邸春词因和其韵声情拉杂百感风生一夕遂得十首不自知其所云也 其十","f":"古风","c":["今朝吾弟悬弧日，四十匆匆。","谁荐扬雄，谒者监门孰与通。","耦耕毕竟家山好，山黛初浓。","杏靥才烘，迟汝风光一笑同。"]},{"t":"采桑子 吴门遇徐松之问我新词赋此以答","f":"古风","c":["当时惯做销魂曲，南院花卿。","北里杨琼，争谱香词上玉笙。","如今纵有疏狂兴，花月前生。","诗酒浮名，丈八琵琶拨不成。"]},{"t":"采桑子 其一 为汪蛟门舍人题画册十二帧","f":"古风","c":["郁金堂后相思树，花月珑璁。","庭院迷濛，凤胫兰膏潋滟红。","双心一气沈香火，娇小乌龙。","斜压薰笼，笑尔葡萄宝幔空。"]},{"t":"采桑子 其二 为汪蛟门舍人题画册十二帧","f":"古风","c":["是何年少朝天客，火满东华。","漏歇南衙，蝶梦才归尚恋花。","麝衾兽炭团花褥，休数其他。","一例豪奢，不是田家即窦家。"]},{"t":"采桑子 其三 为汪蛟门舍人题画册十二帧","f":"古风","c":["八盘腻手香蝉委，红粉轻调。","画的轻描，直得春魂为尔销。","道书偏怪郎耽读，百幅霞绡。","十斛龙膏，何必蓬山访碧桃。"]},{"t":"采桑子 其四 为汪蛟门舍人题画册十二帧","f":"古风","c":["李皇周后年双小，玉树宫墙。","金缕鞋帮，胆怯潜提出洞房。","秣陵往事千年矣，如此疏狂。","莫管兴亡，便破家山也不妨。"]},{"t":"采桑子 其五 为汪蛟门舍人题画册十二帧","f":"古风","c":["金笼鹦鹉新来哑，柳样腰身。","月样精神，小小房栊少四邻。","只愁绕院千竿碧，戛触疏筠。","断续停匀，几阵琤琮似有人。"]},{"t":"采桑子 其六 为汪蛟门舍人题画册十二帧","f":"古风","c":["浪花槅子冰纹槛，绿沁肌肤。","凉浸眉须，还有炎威半点无。","水明楼上人梳裹，旁立鸦雏。","秀鬋清矑，爱看荷盘泻露珠。"]},{"t":"采桑子 其七 为汪蛟门舍人题画册十二帧","f":"古风","c":["苍松陡作金虬舞，似此云山。","不像人间，嵓畔相逢吴綵鸾。","情缘未了前尘在，扇子团圞。","暗惜韶颜，饭罢胡麻趁早还。"]},{"t":"采桑子 其八 为汪蛟门舍人题画册十二帧","f":"古风","c":["鹧鸪斑晕鸬鹚杓，玉润犀香。","酒圣诗狂，浓淡屏山墨几行。","牙签叠架粗于笋，蕃锦珠囊。","宋榻唐装，也抵豪门笏满床。"]},{"t":"采桑子 其九 为汪蛟门舍人题画册十二帧","f":"古风","c":["红樱斗帐空如水，烟月罗罗。","人到南柯，一片松涛枕畔过。","雀翘蝉鬓端然坐，裙带微挼。","纤指频呵，甚处巫云入梦多。"]},{"t":"采桑子 其十 为汪蛟门舍人题画册十二帧","f":"古风","c":["簟纹绿暖玻璃皱，极望芙蕖。","来往谁欤。","风幔烟桡满太湖。","琐儿不忿双栖鸭，波溅红襦。","潮晕春酥，阿姊身边竟有夫。"]},{"t":"采桑子 其十一 为汪蛟门舍人题画册十二帧","f":"古风","c":["搓酥滴粉瑶台侣，要使微赪。","戏问幽情，眉黛全低恚旋成。","红丝蝇拂拈来打，何事干卿。","口语偏轻，薄怒徐回媚转生。"]},{"t":"采桑子 其十二 为汪蛟门舍人题画册十二帧","f":"古风","c":["盈盈对坐翻经史，琳笈琼函。","粉印脂钤，夜冷春葱下几签。","在旁蜡烛能知状，茗苦香甜。","月小风纤，咏絮才高笑撒盐。"]},{"t":"减字木兰花 上巳后一日途次洧川","f":"古风","c":["花红草绿，昨日浓春经阮曲。","碎雨零烟，今日愁人过洧川。","三春去半，半付邮亭和驿馆。","溱洧潺湲，上巳无人出采兰。"]},{"t":"减字木兰花 过惠山九华庵 系某氏废园","f":"古风","c":["石蹲奇兽，兀奡玲珑真险秀。","涧束春罗，窈窕空明足淡沲。","閒庭谁到，只许碧空悬冷瀑。","些事消魂，剩有秋千断板存。"]},{"t":"减字木兰花 酷暑马上口占","f":"古风","c":["阳乌酣战，身似吴牛偏易喘。","缓辔彷徨，我有田园万斛凉。","桐廊茗汁，此事如今那可得。","黄鸟多情，小店风潭啭一声。"]},{"t":"减字木兰花 题彭爰琴小像","f":"古风","c":["隋宫丝管，曾醉倡家红玉椀。","瘦马芦沟，又上燕姬卖酒楼。","十年一别，往事濛濛那可说。","画里逢君，同把扬州月色分。"]},{"t":"减字木兰花 题山阴何奕美小像","f":"古风","c":["多年枯树，屈铁拗铜阴翠冱。","野涧萧林，闲坐幽人抱膝吟。","传家碧血，怕听子规啼夜月。","莫便还乡，霸国山川冷夕阳。"]},{"t":"减字木兰花 佐家为阎牛叟赋","f":"古风","c":["鱼租雁税，健妇持门心力瘁。","黾勉钱刀，助得男儿意气豪。","家缘中落，轧轧机床拚织作。","国士桥边，剩有萧萧冷砚田。"]},{"t":"减字木兰花 题恽南田为潘原白所画绛帻横秋图二首 其一","f":"古风","c":["花冠粉距，昂首晴秋羞哙伍。","恼杀诗翁，得失偏呶鸡与虫。","乾坤夜黑，何日一鸣天下白。","角角堪惊，总是秦关过客声。"]},{"t":"减字木兰花 题恽南田为潘原白所画绛帻横秋图二首 其二","f":"古风","c":["陈仓祠古，当日霸王全繫汝。","丛桂天空，舐药还闻伴八公。","而今老大，笑尔会稽鸡太哑。","莫管昏晨，斯世谁为起舞人。"]},{"t":"散馀霞 十六夜即景","f":"古风","c":["昨宵皓月凉于粉，浸万家蝉鬓。","花下几两车儿，翠盈盈偏稳。","今夜红灯成阵，被雨丝淹尽。","一只银鸭床头，镇厌厌春困。"]},{"t":"好事近 隔院听琵琶","f":"古风","c":["拍遍小阑干，何限塞鸿明灭。","老去怕逢节候，正落红时节。","沙场病卒搯檀槽，隔著邻垣说。","似诉少年陈事，有玉楼金埒。"]},{"t":"好事近 丙辰早春得云间张洮侯寅冬所寄书","f":"古风","c":["春水锦鳞通，忽把故人墨迹。","一纸三年才到，讶红笺无色。","当初高宴五茸城，尽江东裙屐。","记得傀俄酒态，有琼筵醉客。"]},{"t":"好事近 食蟹忆南耕 时南耕以礼斗斋宿道院","f":"古风","c":["溪友馈霜螯，细捣蛮姜慢吃。","更听糟床细注，赏半窗晴碧。","游仙今夜忆曹唐，正锁旌阳宅。","料在醀坛深处，倚石床吹笛。"]},{"t":"渔父家风 赠梁溪赵叟","f":"古风","c":["十年小阁自埋名，不爱卖丹青。","随身并少林逋鹤，人比惠泉清。","花一树，酒三升，了浮生。","朝来微醉，拍手凭阑，雨后新晴。"]},{"t":"琴调相思引 元夕后二日夜雨即事","f":"古风","c":["绮陌将收五夜灯，后堂锁到第三层。","画檐残烛，细雨恐难胜。","歌板敲愁飞火凤，枕函贮梦结红冰。","觉来还记，踏月六街曾。"]},{"t":"误佳期 偶作","f":"古风","c":["枕上春酲犹害，楼上东风偏大。","金笼鹦鹉唤人来，忙出花阴外。","不肯把箫吹，那便将花戴。","脸波底事十分红，莫误将人怪。"]},{"t":"清平乐 长至前五日适吴门诸子有填词社初集之举同集余澹心秋雪斋是夜风雨","f":"古风","c":["关山如许，不醉卿何苦。","酒泼鹅黄娇似乳，领受高斋夜雨。","莫愁湿透芒鞋，道傍醉倒须埋。","不见长洲苑里，年年落尽宫槐。"]},{"t":"清平乐 友人以哭女诗见示作此以代写哀","f":"古风","c":["红珠辞掌，絮果因风飏。","跌碎菱花楼上响，人与舞鸾同往。","昨宵粉壁金闺，今宵孤冢棠梨。","思子台前月落，女坟湖畔鸦啼。"]},{"t":"清平乐 夜饮友人别馆听年少弹三弦限韵三首 其一","f":"古风","c":["夜香烧罢，桦烛通宵话。","曲项檀槽声不哑，银甲凭伊搯打。","只图慢撚轻笼，谁怜双袖龙钟。","少日红筝北里，年来白发西风。"]},{"t":"清平乐 夜饮友人别馆听年少弹三弦限韵三首 其三","f":"古风","c":["欢场才罢，去对孤檠话。","欲击唾壶声尽哑，可惜孤城浪打。","一宵柳簇花笼，何时万户千钟。","尘世风波似海，狂奴谈笑生风。"]},{"t":"忆少年 秋日登保安寺佛阁","f":"古风","c":["半村红蓼，半村乌桕，半村黄叶。","寺楼偏作势，欲斜穿山胁。","槛外霜枫眠正贴，被西风陡添鳞鬣。","阁中僧夜语，有猿吟相接。"]},{"t":"画堂春 小春","f":"古风","c":["不寒不暖好年光，依然人在江乡。","春人偷嫁与冬郎，便小何妨。","记得年时岭外，梅妃犹未胜妆。","如今花满纸糊房，红紫成行。"]},{"t":"鬲溪梅令 小寺","f":"古风","c":["花前小寺背春城，不知名。","淼淼夕阳金刹、著波平。","风光难画成。","阿师洗钵趁新晴，隔溪行。","闲锁阶前梅萼、一枝横。","僧雏学弄笙。"]},{"t":"海棠春 闺词再和阮亭韵四首 其一","f":"古风","c":["依稀听得菱花响，三竿日、红完蛛网。","半晌注横波，无数鬘云漾。","妆成谁见灵蛇样，分付与、百花闲赏。","一座丽春楼，尽把轩屏敞。"]},{"t":"海棠春 闺词再和阮亭韵四首 其二","f":"古风","c":["昼长嫌煞乌三足，谁耐唱、摩诃池曲。","好梦远如天，落絮平于褥。","彤墀火迸红榴肉，簪不稳、一枝寒玉。","怯暑那成眠，走觅银塘竹。"]},{"t":"海棠春 闺词再和阮亭韵四首 其三","f":"古风","c":["夜堂月上无人影，小鹦鹉、困酣难醒。","正好试金盆，一斛红泉冷。","浴馀借得蟾为镜，谁爱取、冠儿重整。","低髻卸偏荷，茉莉圈成饼。"]},{"t":"海棠春 闺词再和阮亭韵四首 其四","f":"古风","c":["丝丝烛泪多如雨，捣尽了、月中孀杵。","镜听拟来朝，私卜帘前语。","坐深裙子红都去，早又是、三通谯鼓。","谈解小郎围，权拔钗为麈。"]},{"t":"桃源忆故人 秋日晒扇见故人王湛斯画柳赋此志感","f":"古风","c":["天涯乍遇宣城叟，御苑听砧时候。","曾写几行疏柳，劝我青门酒。","别来往事消沈久，只有齐纨在手。","露叶烟条依旧，解与愁眉斗。"]},{"t":"桃源忆故人 重游惠山寄畅园怀秦对岩检讨","f":"古风","c":["松湍百道喧晴雪，冷瀑何年才歇。","水上瘦梅如铁，眠补红桥缺。","从军年少巴陵客，三载金笳画戟。","莫听楚天百舌，千里同明月。"]},{"t":"山花子 送姜学在由吴门之宛陵清明扫墓","f":"古风","c":["鲁国男儿是孔融，如今流落号吴侬。","燕子柳条能酿恨，旧江东。","谢朓楼边栾布社，琴高潭上石尤风。","送尔片帆春上冢，雨濛濛。"]},{"t":"眼儿媚 冬夜听梧轩举填词第二集","f":"古风","c":["风剪兰煤夜渐深，泉响答清音。","官斋此夜，鲈腮斫玉，梅蕊含金。","茂苑酒醒刚几日，浮拍又如今。","十年红豆，五湖黄叶，费尽行吟。"]},{"t":"朝中措 客中杂忆十首 其一","f":"古风","c":["层层帘幕静焚香，萦篆袅缥缃。","翠鸭娇擎磁鼎，红狮满贮铜釭。","如今寂寞，孤灯黯淡，细雨淋浪。","料尔春纤拨火，为侬也费思量。"]},{"t":"朝中措 客中杂忆十首 其二","f":"古风","c":["家乡绿雪蓊南山，采摘不曾难。","三径风垆瓦铫，半廊竹濑松湍。","昨朝悔未，携将茶董，同上长干。","却忆苏门四友，曾经日给龙团。"]},{"t":"朝中措 客中杂忆十首 其三","f":"古风","c":["看花常傍隔村篱，携取折枝归。","沙绿胆瓶磬口，矮红棐几乌皮。","端相侧正，屏当疏密，用尽幽思。","记得临行嘱汝，香绵裹好军持。"]},{"t":"朝中措 客中杂忆十首 其四","f":"古风","c":["灯昏酒尽不胜情，倚幌听三更。","恶草邻墙马龁，乱莎别馆虫鸣。","家园此际，小楼半掩，纤月初生。","多少幽坊冷市，绿窗一片枨枨。"]},{"t":"朝中措 客中杂忆十首 其五","f":"古风","c":["疏狂子野住台城，擪笛旧知名。","劈裂铁龙醉吼，连环狞凤娇鸣。","消磨岁月，千场蜡炬，一夜鹅笙。","今日偶然闲想，因缘已似前生。"]},{"t":"朝中措 客中杂忆十首 其六","f":"古风","c":["画栏雕槛尽临河，帘内水仙多。","记得半塘初买，小船细雨鸣蓑。","磁盆归贮，红泥密垄，锦石斜迤。","今夜烟廊雨幔，谁人与尔婆娑。"]},{"t":"朝中措 客中杂忆十首 其七","f":"古风","c":["赪苞檀萼缀萧斋，幽韵袭人来。","乍可酒边私嗅，偏宜鬓底微开。","而今不见，踏残小径，寻遍苍苔。","侧帽临风不语，几般怆旧情怀。"]},{"t":"朝中措 客中杂忆十首 其八","f":"古风","c":["画眉斜挂画帘东，爱汝语音工。","食器官窑涨碧，药栏小架扶红。","人今牵绊，一般惆怅，两处羁穷。","寄语怜香旧侣，风前早为开笼。"]},{"t":"朝中措 客中杂忆十首 其九","f":"古风","c":["红鱼明鲦映沦漪，相间倍离离。","卵色天装玳瑁，桃花水染胭脂。","休嗟盆沼，外边雪浪，风骇涛飞。","输尔翠涟拍甃，有人濠上相知。"]},{"t":"朝中措 客中杂忆十首 其十","f":"古风","c":["半生书癖墨成庄，气压邺签强。","寒夜添香炙砚，调娱闲弄朱黄。","一身作客，牛腰易束，鹤背难装。","羡杀千年老蠹，钻穿故纸休粮。"]},{"t":"太常引 坐积翠阁同吴园次赋","f":"古风","c":["古苔绣壑乱泉鸣，呜咽说生平。","耳畔恍挨筝，是落叶声耶雨声。","画廊泼翠，茶铛翻雪，趺坐證三生。","碧透小铜瓶，斜插朵黄梅更清。"]},{"t":"归去来 忆石亭老桂兼寄竹逸云臣","f":"古风","c":["忆醉石亭山坞，倚桂丛深处。","下是谁家高人墓，落英飘下如雨。","苍莽中原路，并不见、秋香一缕。","月中只剩团圞树，斟芳醑、相怜取。"]},{"t":"河渎神 临津古城隍庙下作","f":"古风","c":["石竹响飕飕，一行断垄荒邱。","无人野渡水争流，土城蔓草含愁。","古庙阴森凉气泻，枫叶映来都赭。","门外寒涛暗打，错疑箫鼓村社。"]},{"t":"醉乡春 秦对岩携具寄畅园举填词第三集","f":"古风","c":["银甲闹时偏悄，绿水昏时胜晓。","双粲枕，百娇壶，好景世间都少。","人对烛花微笑，袖向蘋风轻舀。","玉山倒，脸波横，酒痕一点红窝小。"]},{"t":"醉乡春 咏茶花","f":"古风","c":["鼎内乳花将溜，瓶里玉花先逗。","真皓洁，太竛竮，雪暗茶园如绣。","叶与花情相斗，花与叶芬相糅。","将嫩蕊，比幽兰，幽兰还逊三分瘦。"]},{"t":"极相思 忆梦","f":"古风","c":["湿云未敛香蝉，斜倚枕屏前。","分明昨夜，依稀往事，院后廊边。","下了红帘擎翠鉴，悄不觉，笑靥微圆。","濛濛脉脉，如尘似影，记也难全。"]},{"t":"西江月 夜宿何雍南斋中","f":"古风","c":["一榻奇书缭绍，三间老屋欹斜。","天寒沽酒拨琵琶，消尽丹徒客夜。","南浦零箫剩管，西风社鼓神鸦。","他年梦亦识君家，家在寄奴山下。"]},{"t":"西江月","f":"古风","c":["莫道从无绛雪，眼前花雨通红。","枉劳烧肉梵王宫，食指朝来不动。","云把芒鞋滑滑，拟听腰鼓鼕鼕。","如何也懒趁斋钟，君笑曰吾从众。"]},{"t":"西江月 喜见狮儿四首 其二","f":"古风","c":["昔日游梁枚叔，儿生此地名皋。","滑稽敖弄解诙嘲，曼倩同时绝倒。","我意殊为不尔，诗书莫误儿曹。","凭他上树日千遭，长大耘瓜扑枣。"]},{"t":"西江月 喜见狮儿四首 其四","f":"古风","c":["牵狗高辛集上，呼鹰垤泽门边。","愿儿无若宋人然，庄岳之间不远。","六岁定归家塾，有甥与汝齐年。","西风亟趁下江船，虾菜东吴正贱。"]},{"t":"留春令 感旧","f":"古风","c":["灯前喝雉，楼头繫马，山腰射虎。","曾放颠狂百千场，要数遍、何从数。","一霎浑河风叶舞，卷旧游何处。","谁滴他乡万般心，是隔个、窗儿雨。"]},{"t":"怨三三 秋怀","f":"古风","c":["离离秋水正拖蓝，滑又如簪。","拟峭烟帆南崦南，浮笠泽、把黄柑。","夏时曾种风楠，与邻叟、追凉笑谈。","今日得霜酣，树犹如此，人则何堪。"]},{"t":"偷声木兰花 雨中同吴天篆过饮徐竹逸斋头次天篆韵","f":"古风","c":["熟梅时候苏苏雨，遥望君家疑隔浦。","我垫巾来，小坐欧公画舫斋。","觥船何用频催酒，鹰爪凤团须瀹取。","说鬼谈经，风味依稀退院僧。"]},{"t":"偷声木兰花 题范女受小像","f":"古风","c":["君挑独夜江船火，隔舫有人呼似我。","仔细披图，骨瘦髯清我不如。","孤松峭壁疑无路，啸向此中寻药去。","可许狂生，化作猿猱逐队行。"]},{"t":"偷声木兰花 题关东席端伯小像","f":"古风","c":["画师要写萧疏意，先画绿杨丝踠地。","斑竹阑干，傍倚高人兴邈然。","五侯七贵枌榆盛，家本辽阳争借问。","总不关渠，只爱荷香扑异书。"]},{"t":"偷声木兰花 题南水上人诗卷尾","f":"古风","c":["六朝僧话三生事，雨后人归花下寺。","我最怜渠，不数琴聪与蜜殊。","借师禅板为歌板，唱到江东春又晚。","晴絮茫茫，纵使无愁也断肠。"]},{"t":"偷声木兰花 咏钱","f":"古风","c":["青蚨铸就开元字，相看似有团圞意。","欲簸还慵，恼煞轻狂小沈充。","掷来好卦全无准，买来好事多无分。","榆荚由他，偏逐东风不著家。"]},{"t":"城头月 秋月感怀","f":"古风","c":["西风吹得冰轮淡，桂影平于簟。","深巷疏砧，严城哀柝，做出秋声惨。","月中一片朱旗闪，粉堞青霜染。","万里关河，百年身世，倚幌听更点。"]},{"t":"城头月 月下","f":"古风","c":["冰轮偏向城头挂，河汉寥寥夜。","一片关山，千秋楚汉，万帐更齐打。","何如移向东湖舍，照豆棚瓜架。","草响溪桥，水明山店，儿女追凉话。"]},{"t":"河传 五色莺粟","f":"古风","c":["晓莺无赖，也把啼痕，花间沾洒。","几丝绒线，东风分派，暗将浓淡配。","绣匀白白红红态，黄和黛。","野圃层层界。","朝来小摘帘外，趁他微雨卖。"]},{"t":"河传 煨芋","f":"古风","c":["黄茅新盖，土锉温黁，霜檐低矮。","撩人几阵，芋香无赖。","送来篱落外。","凝脂沃雪融仙瀣，馀甘在。","塞上酥堪赛。","黄粱未熟休待。","饱迎朝旭晒。"]},{"t":"河传 豆荚","f":"古风","c":["陇上。","晓莺低唱。","豆荚初娇。","小姬一色绿裙腰。","迢迢幂野桥。","悲歌杨恽家居久。","三杯后。","惯种南山豆。","豆花棚下月毵毵。","溪南闲寻渔叟谈。"]},{"t":"秋夜雨 本意","f":"古风","c":["小楼细袅愁丝绿，和烟扶上庭竹。","飞来檐瓦响，都泻作、奔浑秋瀑。","雨肥越显孤灯，展夜衾、欲睡难熟。","别院弦柱促，正滚入、淋铃哀曲。"]},{"t":"醉红妆 立春前一夕寄畅园小饮时有柳姬翩何在座同园次赋","f":"古风","c":["残年屈指不盈旬。","晚峰愁，翠黛颦。","玉杯饯腊漾红鳞，风动处，酒微皴。","柳条偷报隔宵春。","歌宛转，态横陈。","来早春休园内讨，鸳帐底，有春人。"]},{"t":"玉团儿 初冬写怀","f":"古风","c":["西风吹老清秋节，迸寒空、萧萧老铁。","几片疏砧，数行落雁，一城枫叶。","斜阳雨后明还灭，映千年、残碑断碣。","太息何为，有杯休放，逢花须折。"]},{"t":"探春令 庚戌元夜","f":"古风","c":["去年客里度元宵，人正恹恹病。","撚偃师、廨后黄梅嗅，想洛下、春灯盛。","今年准拟酬春兴，奈阴晴难定。","拥香篝仍剔，残灯半盏，似去年心性。"]},{"t":"探春令 咏窗外杏花","f":"古风","c":["崇仁宅靠善和坊，旧雕阑都坏。","问玉楼、人醉今何处，只一树、花还在。","红香笼帽归鞭快，更何人能戴。","到如今和了，满城微雨，频上街头卖。"]},{"t":"探春令 试灯夜对雪","f":"古风","c":["六街料理做元宵，奈雪儿偏下。","小鹦哥、隔著秋千架，将六出、花轻骂。","满城何处寻罗帕，掩重门睡罢。","想年时多少，画桥深巷，一片红灯挂。"]},{"t":"南柯子 蝶庵花下送苏生仲补游京师","f":"古风","c":["带醉翻楸局，佯憨恼绮筵。","笑他柯烂不知年，输尔才拈红子、便通仙。","挟瑟龙池上，鸣鞭凤阙前。","妙龄绝艺有人怜，可忆江南分手、落花天。"]},{"t":"南柯子 席上赠让侯时客有语及蒋大鸿者因并忆之","f":"古风","c":["菊瘦人回棹，橙香客砑筝。","相逢曾在凤凰城，记尔飞扬跋扈、旧时名。","萍梗成遗叟，嶒嵘任老兵。","停杯忽忆杜陵生，今夜一钩新月、若为情。"]},{"t":"南柯子 午睡","f":"古风","c":["磁枕摇新竹，藤床荫瘦桐。","人间亦有广寒宫，半亩荷亭几阵、藕丝风。","簟滑凉于水，帱虚翠若空。","花阴得失闹鸡虫，觉后掀髯一笑、夕阳红。"]},{"t":"迎春乐 本意四首 其一","f":"古风","c":["东儿似水裙儿复。","斜绾著、黄金犊。","趁嫩晴、半醉谁拘束。","穿遍了、闲坊曲。","鬓亸绣幡簪百福。","早暗里、品红裁绿。","方胜飐银蛾，春已在、钗头簇。"]},{"t":"迎春乐 本意四首 其二","f":"古风","c":["诃梨领子蝤蛴项。","都倚在、斜桥望。","指春竿、百尺随风漾。","早一对、春人上。","队队勾芒笼綵仗。","狂煞了、六街鞋䩫。","尽道打春归，银蜡底、家家唱。"]},{"t":"迎春乐 本意四首 其三","f":"古风","c":["韭黄溲就牢丸巧。","红酥滑、银匙搅。","正内家、恰斗樱桃小。","争觅取、金盘咬。","从此春城春未了。","有无数、春花春鸟。","扑蝶与听莺，且次第、将春讨。"]},{"t":"迎春乐 本意四首 其四","f":"古风","c":["春衣围定春来路。","花似海、香成雾。","嘱今年、春到春休去。","拚一世、和他住。","嘱罢东皇心暗许。","向鬓影、盈盈低语。","来岁杜鹃声，谁听恁、催春暮。"]},{"t":"醉花阴 至吴门喜晤澹心园次展成既庭石叶诸君感旧有作","f":"古风","c":["昔年相见皋桥下，总是清狂者。","惜别泰娘家，泪黦胭脂，冰了鲛绡帕。","如今渔火枫桥夜，照沈腰堪把。","黄叶似情人，也爱飘零，不肯归来也。"]},{"t":"醉花阴 初秋刘笃甫以词招饮次韵奉酬","f":"古风","c":["簟纹柳浪相零乱，浅立烟廊畔。","徙倚早凉天，斗茗捶琴，短帻由他岸。","南华手注才踰半，听得提壶唤。","一醉莫思乡，只恐江东，莼鲙招张翰。"]},{"t":"醉花阴 夏日小有堂中看邱近夫朱致一叶九来诸子投壶","f":"古风","c":["满院松风鸣瓦铫，碧净苔阶好。","乔木翳新蝉，水槛闲凭，又贴荷钱小。","人间万事何时了，无计除烦恼。","激矢跃莲花，出手成骁，暂博天公笑。"]},{"t":"醉花阴 扑萤","f":"古风","c":["齐纨似粉谁新砑，爱把潭香惹。","金屋夜无人，熠耀初流，笑觅轻罗打。","迎凉不是闲贪耍，指定花阴骂。","千古好雷塘，总是伊家，做出兴亡话。"]},{"t":"红窗睡 冬夜","f":"古风","c":["花影枝枝墙上界。","晴月把、小红楼晒。","三更巷口西风大，惹猧儿寒吠。","轻薄杨花心性改。","知何处、酒旗戏鼓，轻狂难耐。","薰笼银鸭，却恹恹长在。"]},{"t":"红窗睡 咏樱桃花","f":"古风","c":["一树垂垂摇绣幌，光映得、小楼都绛。","无风谁触花枝响，堕繁红两两。","细雨似闻莺细讲。","香阶下、美人休折，让花全放。","待他成颗，斗白家唇样。"]},{"t":"河传 新茗","f":"古风","c":["谷雨。","娇女。","微遵绿崦，轻携翠筥。","拍茶初。","樱笋厨。","一缕。","夜涛煎雪乳。","酒恶愁将绣衾涴。","龙团破。","顿觉春酲妥。","藉庭莎。","啜茗柯。","罗罗。","北窗幽兴多。"]},{"t":"河传 黄蔷薇","f":"古风","c":["樱桃已谢。","牡丹开罢。","蔷薇满榭。","夕阳漫漫一架。","低亚。","檀痕污粉帕。","黄鹂一色枝头骂。","朦胧怕。","谁迸金丸打。","画廊东。","绣花丛。","芳绒。","施朱近也慵。"]},{"t":"河传 紫蛱蝶花","f":"古风","c":["低亸墙阴，微晕帘罅，露濯烟梳。","满园奼紫趁晴铺。","萦纡。","傍裙裾。","玉娥扑遍花间路。","谁飞去。","纨扇今番误。","有时粉翅凝花须。","轻扶。","问伊如不如。"]},{"t":"河传 虞美人花","f":"古风","c":["楚歌四面。","战旗一片。","岁岁江东。","此花渍透，还是垓下重瞳。","旧啼红。","刘郎原庙空千古。","咸阳树。","银雁飞何处。","英雄儿女。","谁怜总付东流。","野花愁。"]},{"t":"怨王孙 咏观音柳","f":"古风","c":["小卉清绮，笼窗拂水。","柳宿垣中，河阳县里。","春絮枉自夭邪，不成花。","烟姿露叶依然袅，腰逾小。","添得花枝好。","莫抛隋苑，好向水月金瓶，听潮音。"]},{"t":"怨王孙 立春戏柬园次时夜有柳校书在寓","f":"古风","c":["柳色如此，住为佳耳。","未到飘绵，已经蘸水。","隔巷赵女弹筝，没心情。","博山熏彀沈香火，衫儿亸。","微觉东风大。","麝衾梦醒，惊问还是寒宵，是春朝。"]},{"t":"徵招调中腔 冰雪兼旬试灯前一夕始有春意","f":"古风","c":["是谁错料春光黠，费几许、东皇周折。","昨始绣完半丝儿，觉暖红、上双颊。","雏暄嫩煦增妍悦，似乍嫁、新娘生怯。","小糁树边一些春，已渐滑、小禽舌。"]},{"t":"雨中花 雨窗咏梅和南耕作","f":"古风","c":["连日春工寒勒住，绣不满、枝头娇嫭。","一点胭脂，半廊香雪，开在无人处。","漫倚画檐垂玉箸，我含泪、细为花诉。","四海青衫，六宫红粉，几阵风和雨。"]},{"t":"杏花天 题震修杏花小照","f":"古风","c":["虎头食肉通侯相，君本是、词场飞将。","纷纷馀子真厮养，自署五湖之长。","慈恩寺、春从蝶酿，红绫宴、饼如月样。","杏园指日鞭丝漾，闹煞卖花深巷。"]},{"t":"浪淘沙 专诸巷看谷梁买鼓槌","f":"古风","c":["绿水滑如油，涨满铜沟。","柳花伴我作閒游。","青漆鼓槌红架子，别样风流。","买了且归休，单绞岑牟。","世间定有此人不。","须向金阊亭下路，打散春愁。"]},{"t":"浪淘沙","f":"古风","c":["酒尽恰天寒，鹿柴恒关。","漫劳曲米想云安。","尽日疗饥惟黛色，多谢青山。","花县忽分餐，猿鹤齐欢。","溪南村老杖藜观。","怪汝炊烟飘一缕，瑞雪同看。"]},{"t":"浪淘沙 夏雨写怀","f":"古风","c":["才恼听啼鹃，又奏林蝉。","青蚨谁为买流年。","旧日榆钱都使尽，且换荷钱。","阴雨太绵绵，泪一般般。","霞红惊射粉篱边。","谁道晚霞偏酿雨，明日依然。"]},{"t":"浪淘沙 题园次收纶濯足图","f":"古风","c":["滟滪几千堆，溅雪轰雷。","巨鳌映日挟山来。","舞鬣扬鬐争跋浪，昼夜喧豗。","濯足碧溪隈，一笑沿洄。","龙窝蛟窟莫相猜。","我有珊瑚竿不用，不是无才。"]},{"t":"浪淘沙 和容若韵","f":"古风","c":["凤胫罨残灯，抹丽中庭。","临歧摘阮要人听。","不信一行金雁小，有许多声。","今夜怯凉更，茶沸笙瓶。","梦中梦好怕他醒。","依旧刺桐花底去，无限心情。"]},{"t":"浪淘沙 雪中舟次语溪","f":"古风","c":["枯柳挂疏汀，夜火星星。","昨宵西水驿边停。","犹记津楼绡幔底，谁唤银瓶。","寒气逼空舲，客梦初醒。","乱帆又过语儿亭。","我与六花同一例，随路飘零。"]},{"t":"恋绣衾 春暮二首 其一","f":"古风","c":["瞢腾春梦弄夹衣，压阑干、凭损玉肌。","小玉向、纱窗报，坼红墙，园笋乍肥。","马蹄得得穿花外，正邻家、荡子早归。","叹樱桃、都谢了，怪伊行没个信儿。"]},{"t":"恋绣衾 春暮二首 其二","f":"古风","c":["昏昏绿水乳燕飞，蹙香红、堆满地衣。","梳洗罢、登楼望，见长天，一碧四围。","行人更在天之外，问地名、甚处武威。","想郎处、枝头鸟，并无杜宇劝归。"]},{"t":"月照梨花 送纬云弟渡江之广陵","f":"古风","c":["铁瓮隐隐，怒涛滚滚。","簸宋掀梁，淘吴洗晋。","谁泛水调清讴。","是邻舟。","望中一抹斜阳恨。","可怜消尽、六代金粉。","老夫还记旧扬州。","红袖悠悠。","满江楼。"]},{"t":"河传 玫瑰","f":"古风","c":["疏篱半掩。","轻风斜飐。","浓香几点。","药阑边，才绽。","盈盈紫艳，粉蛾匀睡脸。","频呼小玉私搴取。","提笼去。","小摘盈阶雨。","扑幽芬。","沿藓痕。","缤纷。","刺兜金缕裙。"]},{"t":"河传 榆钱","f":"古风","c":["荡漾。","谁傍。","轻如蝶翅，小于钱样。","抛家离井若为怜。","凄然。","江东落絮天。","年年苦被东君铸。","啼鹃诉。","贱卖韶光去。","涨晴湖。","剪春芜。","模糊。","漫空下五铢。"]},{"t":"鹧鸪天 咏宋子京赐内人","f":"古风","c":["路出繁台遇玉颜，柳花如梦扑雕鞍。","倚他才子吟红杏，博得君王赐绿鬟。","莺呖呖，鸟关关，粉娥笑语绣帷间。","郎君然烛修唐史，底事邀灵李义山。"]},{"t":"鹧鸪天 七夕后一夕路次淮阴作","f":"古风","c":["袁浦西风响乱滩，楚州纤月卧微澜。","今宵新惹双星怨，此地原嗟一饭难。","车历碌，轴斑兰，故园回首好溪山。","赤车应诏浑閒事，赢得征尘涴旅颜。"]},{"t":"鹧鸪天 谢史蘧庵先生惠新茗","f":"古风","c":["竹院风炉梦正长，绢封箬裹十分香。","龙团捣罢云生臼，蟹眼熬成雨沸窗。","拚冷淡，尽奔忙，不如閒事好商量。","人间别有真南董，新注茶经四五章。"]},{"t":"鹧鸪天 苦雨和蘧庵先生四首 其一","f":"古风","c":["檐溜淙淙彻夜闻，晓山没却髻螺痕。","风掀竹尾敲诗梦，雨凝花须湿茗魂。","抛短杖，阁清樽，蒙头败絮睡昏昏。","谁倾铜狄千年泪，泻入瞿塘两峡门。"]},{"t":"鹧鸪天 苦雨和蘧庵先生四首 其二","f":"古风","c":["入夏端然似涉秋，粉云阴重不曾收。","那知四月之间雨，做就中年以后愁。","儿女恨，霸王筹，濛濛都付两溪流。","碧天何日红霞衬，晕遍江南小画楼。"]},{"t":"鹧鸪天 苦雨和蘧庵先生四首 其三","f":"古风","c":["曾控吟鞭驿馆遥，红毡马上梦初消。","雪登麦积秦筝苦，雨歇丛台赵女娇。","泥滑滑，鬓萧萧，故园仍傍斩蛟桥。","老夫输却龙孙健，挟雨齐抽十万梢。"]},{"t":"鹧鸪天 苦雨和蘧庵先生四首 其四","f":"古风","c":["阆苑仙人杖过眉，陡然春去也成悲。","新愁洛下铜驼晓，旧事尧年老鹤知。","闲握槊，闷弹棋，漫天丝雨且题诗。","寄来数阕淋铃曲，我在街南中酒时。"]},{"t":"鹧鸪天 寓兴用稼轩韵同蘧庵先生作三首 其三","f":"古风","c":["罂粟阑边已放芽，枝头梅子著些些。","勤过小圃招晴蝶，闲倚疏林数暝鸦。","无个事，帽檐斜，风光消得晚还家。","陡然却忆前生事，看遍蓬莱碧柰花。"]},{"t":"鹧鸪天 元夕前二日闻南耕原白诸子雪中有龙池之游作此调之","f":"古风","c":["㶁㶁街泥未肯晴，群公高兴爱山行。","一行翠榜欹烟滑，几队红毡映雪明。","真寂历，剧凄清，寺桥犹欠一声莺。","归来更值街灯落，两地风光醉不成。"]},{"t":"鹧鸪天 赠庄山人七十","f":"古风","c":["雨后晴鬟翠可扪，风前画縠绿成痕。","桃花开遍防渔父，蝴蝶飞来认耳孙。","书满架，酒盈尊，举家耕读任乾坤。","也知丸药今晨懒，偶爱听莺过别村。"]},{"t":"鹧鸪天 赠李匪莪","f":"古风","c":["箧里还存宝剑篇，舍旁已买瀼西田。","蓼莪久废中年后，鸿雁难寻绝塞边。","扑帽雪，隔篱烟，绿杨丝隐钓鱼船。","难封休恨君家广，仙李由来结大年。"]},{"t":"金凤钩 春夜同展成饮御之斋头感旧","f":"古风","c":["东风里，绛桃树。","蓦记得、年时见汝。","红芳正好，浓香乍饱，俊眼相看如许。","如今花放长洲路。","只是我、朱颜非故。","旧情如梦，閒愁似海，闷搯花须细数。"]},{"t":"河传 新笋","f":"古风","c":["新笋。","初引。","烟梢坠粉。","花阑蒸菌。","斑痕隐隐。","舞透银墙翠畛。","小园春已尽。","釜中一斛潇湘碧。","霜刀劈。","糁芼河㹠白。","留几围。","笼涧扉。","他时。","成龙破壁飞。"]},{"t":"河传 樱桃","f":"古风","c":["丹颗。","倭堕。","雨萧萧。","昨夜前村板桥。","筠篮两岸卖樱桃。","娇娆。","玉纤曾乱招。","搓絮替将金弹打。","流莺骂。","含惯流丹液。","妆阁东。","飏晚风。","朦胧。","翠楼都染红。"]},{"t":"河传 青梅","f":"古风","c":["认否。","如豆。","春归不久。","亚槛青垂，映檐绿透。","纤笋小摘轻搓。","奈他翠滑何。","粉娥贪结累累子。","才拈起。","触著酸心事。","将梅仁妾意。","两样试郎怀。","定怜谁。"]},{"t":"鹊桥仙 咏竹逸斋头紫牡丹","f":"古风","c":["欧家碧好，彭门红好，总让伊行清绮。","画栏才放数枝花，映百丈、银墙都紫。","相公袍带，头厅印绶，凡艳那堪相比。","试将花色细形容，烟凝得、暮山如此。"]},{"t":"鹊桥仙 七夕同蘧庵先生暨诸公饮桢百堂中漫赋","f":"古风","c":["天边枕簟，人间瓜果，比夜嫩凉分取。","次公原是醒而狂，谁耐乞、七襄残缕。","穿针楼下，凭肩殿角，何限喁喁私语。","只因乌鹊事荒唐，误尽了、许多儿女。"]},{"t":"鹊桥仙 蒙城舟中读云臣蝶庵词","f":"古风","c":["满河伧楚，盈船蒜酪，郁郁吾其谁语。","江东词客盛如云，别去伴、长淮盐估。","红莲半绽，碧鲈正得，醉任无情今古。","读完半卷蝶庵词，吹铁笛、洒然而去。"]},{"t":"厅前柳 本意","f":"古风","c":["晚妆前。","有一树，黄金缕，倍婵娟。","秦楼上，蛮腰样，只思眠。","才欲抱，便如烟。","谢绣幕、轻萦姿愈俊，胜长街、抛掷堪怜。","莫倚轻狂甚，便成绵。","飘陌上，舞河边。"]},{"t":"玉楼春 春夜同云臣远公天石诸子宴集原白池亭次云臣原韵","f":"七言律诗","c":["绊人最爱金虫软，障烛更凭罗袖展。","酒船风动蹙红鳞，歌板烟笼啼紫燕。","城头侧听三更转，玉漏渐深还道浅。","明朝重揭绣帘斜，花底氍毹应未捲。"]},{"t":"南乡子 夏日午睡","f":"古风","c":["新竹罨中庭，荷盖初齐水面亭。","屋小如㡓无客到，常扃。","棐几藤床矮纸屏。","蝶梦翅冥冥，行向槐安国内经。","正拜南柯真太守，还醒。","一片松涛沸枕楞。"]},{"t":"南乡子 萤","f":"古风","c":["露井坐三更，无数幽辉印水精。","忽地流将深竹去，身轻。","却把深闺绣幔萦。","惆怅记前生，鸳瓦曾经弄月明。","閒话江都隋炀帝，含情。","扇亸轻罗扑不成。"]},{"t":"南乡子 咏吕仙堂葡萄","f":"古风","c":["谁放白毫光，万串晶毬缀讲堂。","髣髴诸天璎珞会，飖飏。","珠母轻盈出海洋。","碧椀泻琼浆，何必金茎肺始凉。","寄语蛮姬休浪哂，须尝。","似否卿家十八娘。"]},{"t":"南乡子 和放公春暮感旧原韵","f":"古风","c":["老去杜樊川，怕学啼红小蜀鹃。","花谢花开关底事。","风前。","捲了蓑衣上钓船。","回想也徒然，往事如尘又似烟。","偏是阿师忘不了，情牵。","满院莺声卖酒天。"]},{"t":"南乡子 捣衣","f":"古风","c":["悄倚缭垣阴，蓦听谁家响暮砧。","不是此声听不得，关心。","自惜离愁万种深。","夜梦别秋衾，趁了西风返故林。","满巷砧声都一样，沈吟。","黄叶村扉那处寻。"]},{"t":"虞美人 灵璧县虞姬墓下作","f":"古风","c":["八千子弟来江左，单剩喑呜我。","谁欤歌者楚声高，还是吾家旧日典连廒。","美人骏马英雄槩，一死千秋在。","荒祠莫恨枕寒田，贱妾孤坟长在大王前。"]},{"t":"虞美人 端午闺词四首 其一","f":"古风","c":["绿窗轻剖鹅黄茧，更把红绒剪。","制成一对小于菟，傍嵌累丝㔩叶碎真珠。","盈盈暗繫绡裙下，但愿无惊怕。","莫嫌此物逊鸳鸯，会忏虎儿明岁出兰房。"]},{"t":"虞美人 端午闺词四首 其二","f":"古风","c":["朱砂撚入银壶酒，此意郎知否。","与郎染就好心肠，休恋菖蒲北里别家香。","粉和冰麝金盘内，雨过荷珠碎。","一生多子是红榴，更爱萱花小字号忘忧。"]},{"t":"虞美人 端午闺词四首 其三","f":"古风","c":["灵符飐上香云腻，绣虎钗头睡。","守宫蜥蜴粉蟾蜍，还剩元绡半捻裹蜘蛛。","灯前笑把檀郎蹴，谁道诸般毒。","东家蝴蝶过西家，多恐薄情心性劣于他。"]},{"t":"虞美人 端午闺词四首 其四","f":"古风","c":["年年竞渡喧歌唱，雪屋崩银浪。","如今不见木兰桡，门掩一庭微雨读离骚。","风前皓腕缠红缕，往事依稀数。","多时忘却辟兵符，今岁重新提起暗嗟吁。"]},{"t":"虞美人 吴门遇嘉禾沈馨闻追感延令旧游赋赠","f":"古风","c":["与君且醉枫桥酒，往事思量否。","夜乌筵上尽情啼，曾看两行红粉黛鬟低。","建封去后秋娘老，燕子楼空了。","阿谁留得最长条，重倚东风再斗沈郎腰。"]},{"t":"虞美人 题徐渭文画花卉翎毛便面","f":"古风","c":["帘栊水浸刚初夏，夏浅胜春也。","数枝白白与红红，飘到一双蛱蝶粉濛濛。","愁看刘项兴亡史，且读南华子。","漆园栩栩过墙来，笑尔闲花还傍月明开。"]},{"t":"虞美人 赋得一枝红牡丹","f":"古风","c":["绿窗浓昼逢初夏，满院花都谢。","昨宵丝管醉沈香，重放一枝栏角斗红妆。","曲廊软幔娇难画，提起开元话。","杨妃带笑绽红鲜，不数阿姨粉面夜朝天。"]},{"t":"虞美人 秦园小憩","f":"古风","c":["绿莎厅折风廊去，是我曾眠处。","万条柳线罨帘栊，无限狂奴春梦在其中。","花间郭橐驼来了，也较年时老。","海棠枝上坐流莺，认否刘郎前度问他声。"]},{"t":"虞美人 吴门春暮重见杨枝","f":"古风","c":["千丝万缕隋堤柳，往事思量否。","杨花飞雪暮春时，又向专诸巷口见杨枝。","酒旗漾在皋桥下，醉杀休论价。","半襟鹃血染东风，可似尚书筵畔舞衣红。"]},{"t":"虞美人 夏日登舟遇雨小泊北郊却寄南耕天篆二子","f":"古风","c":["银涛作阵溪花舞，双桨如何去。","半欹绿箬舀潭香，分取水禽飞处一丝凉。","秃衿翠茗煎花乳，可少留侬处。","湖山大似有乡情，故遣石尤迟我不成行。"]},{"t":"虞美人 泊舟垂虹桥不及过晤舍妹同纬云弟怅然赋此","f":"古风","c":["碧鲈红稻江村市，淼淼重经此。","夜深水调起邻船，记得不曾听已十多年。","北风渐酿篷窗雪，心事和谁说。","匆匆忘发大雷书，望里汀花沙鸟暗南湖。"]},{"t":"虞美人 过青驼寺感旧寄示冒子青若","f":"古风","c":["鲁山更比吴山翠，路入青驼寺。","乱峰怪石甃围墙，墙里人家一半枣花香。","当初有个卿家燕，与汝天涯见。","晓风残月忆从前，不道因循过了十馀年。"]},{"t":"踏莎行 西村邻叟饷予梅子豆荚玫瑰蔷薇满器赋此谢之","f":"古风","c":["北郭浇花，南山种豆。","筠篮入市纷如绣。","半肩爱惹蜂蝶争，一生怕听蛟龙斗。","问讯邻翁，寄声溪友。","向时风景依稀否。","前村渡已绿多时，野桥梅定黄如旧。"]},{"t":"踏莎行 夏夜感旧","f":"古风","c":["月挂楼梢，风吹沼面。","水天閒话人微倦。","些些只许枕头知，星星生怕流萤见。","街鼓三更，泪痕一串。","如今旧事思量遍。","他生须读净名经，小楼已署回心院。"]},{"t":"踏莎行 南耕花径成","f":"古风","c":["杂卉葳蕤，群葩葱峭。","红英紫萼纷相照。","藤萝深巷碧如天，蔷薇低架平于帽。","韵事堪矜，痴情可笑。","隔邻蜂蝶都知道。","今年僮为乞花忙，明春客定提壶闹。"]},{"t":"惜分钗 偶作","f":"古风","c":["击剑罢，追风射。","当时旁若无人者。","过横塘，唤名倡。","痛饮狂歌，说霸论王。","堂。","堂。","花枝谢，人儿嫁。","无端梦醒西楼下。","袖郎当，泪淋浪。","一种心情，满院斜阳。","伥。","伥。"]},{"t":"临江仙 赋得睡起宛然成独笑数声渔笛在沧浪为园次题帐额画幅","f":"古风","c":["西塞山前无六月，半间草阁临流。","晚来都聚打鱼舟。","笛声四起，划碎一江秋。","正值南柯初罢郡，槐阴蚁战刚休。","兼天波浪打闲鸥。","寄声三老，今夜转船头。"]},{"t":"花间虞美人 为广陵何茹庵题像 像在荷塘竹岙间旁有两姬人侍","f":"古风","c":["角弓硬箭黄金弝，须上淩烟画。","不然脱帽五湖天。","藕丝篁粉伴茶烟。","亦前缘。","雄心毕竟轻馀子，知我佳人耳。","双挼裙带绕花行。","凉轩水槛十分清。","说平生。"]},{"t":"小重山 泊舟松陵城外未及一晤舍妹赋此写怀","f":"古风","c":["帆如阵马骤晴空，一条银练吼、走虬龙。","回头烟树失吴宫。","灵岩寺，塔影尚茏苁。","槲叶满湖红。","樯灯和估笛、点空濛。","夕阳船已过垂虹。","无由泊，心事一杯中。"]},{"t":"临江仙 咏竹夫人二首 其一","f":"古风","c":["孤竹君原称苦节，晚遗弱息江村。","夜凉荐寝暂承恩。","斑留江上点，冷浸月中魂。","青女秋来休见妒，此身自有根源。","化为横笛响夔门。","但凭关塞曲，吹裂小龙孙。"]},{"t":"临江仙 咏竹夫人二首 其二","f":"古风","c":["十载萧萧湘岸住，捎烟惹雨参差。","如今枕畔露华滋。","身居清暑殿，梦到竹郎祠。","琢就细腰冰几尺，宵来御辇频辞。","一生疏直许谁知。","霜砧来别院，纨扇忆同时。"]},{"t":"临江仙 春日过访友人村居值其往郡城题词壁间而去 友人城居为余比邻","f":"古风","c":["早起隔墙花弄影，忽然空馆相思。","邻家已换燕空飞。","许多惆怅事，诉与落红知。","百里烟航遥访戴，柴门锁向春矶。","沈吟暗咏壁间诗。","径开山以麓，村在水之湄。"]},{"t":"临江仙 武塘赠钱岩烛","f":"古风","c":["黄竹篙儿如雁叫，西风直放江船。","橹声摇破鹤湖烟。","园林排水次，甲第矗花前。","公子才华尤绝胜，翩翩气压幽燕。","新词脱手万人传。","暗香姜白石，残月柳屯田。"]},{"t":"临江仙 赠柯翰周","f":"古风","c":["玉树三柯偏竞秀，枝枝黛色嶙峋。","一枝才茁便淩云。","车从新市出，衣用异香薰。","此日相逢犹未晚，当年真恨离群。","狂歌莫问水犀军。","好将肠断句，写遍石榴裙。"]},{"t":"七娘子又一体 汲女","f":"古风","c":["柴门之外清江晓。","两三枝、映竹夭桃小。","斗茗偏忙，浇花趁早。","铜瓶翠绠深深抱。","汲馀閒数双栖鸟。","坐晴矶、红上梨涡悄。","窣地许防，有人低笑。","浣衣娘又盈盈到。"]},{"t":"蝶恋花 春闺和漱玉词","f":"古风","c":["晓起春酥呵又冻。","风捲西楼，似怯红栏动。","欲倚自怜无与共，和愁况是纤腰重。","花影看看移半缝。","呆觑庭阴，蹴损鞋尖凤。","莫怪难凭惟好梦，鹊声也把愁人弄。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其一","f":"古风","c":["四月荆南山更翠。","山下人家，都被岚光腻。","南郭莺声才满市，东邻榆荚还缒地。","问讯茶园开也未。","谷雨过头，记起旗枪事。","自是茗柯饶实理，酪奴水厄休相戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其二","f":"古风","c":["四月荆南堪买醉。","雪片鲥鱼，触网连湖起。","色斗新鹅松粉细，樱红笋绿玫瑰紫。","更有莼羹才下豉。","一盏醺醺，醉倒新沙嘴。","射虎屠龙非我事，天晴且趁游蜂戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其三","f":"古风","c":["四月荆南山雨至。","淅淅濛濛，碧窨双溪尾。","水槛科头闲徙倚，笛声吹得波纹碎。","小院日长惟好睡。","睡足挥毫，自笑无新意。","满幅诅神兼骂鬼，先生惯以文为戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其四","f":"古风","c":["四月荆南春去矣。","点点花飞，别我弹红泪。","所幸东街连古寺，木香莺粟还堆砌。","汲水浇花心暗喜。","小啜龙团，管甚人间世。","更上危巢探鹊子，老来爱与群儿戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其五","f":"古风","c":["四月荆南多赛会。","隔浦丛祠，日日村巫醉。","午后楝花风乍起，打门社首分鹅胾。","一饱欣然无个事。","走趁杨花，飘荡东村里。","腰鼓盲词随处是，分棚又看梨园戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其七","f":"古风","c":["四月荆南天著水。","浓淡溪山，染做修蛾翠。","拂晓家童呼入市，半笼携得含桃至。","一幅斜阳红到寺。","新笋排枪，数遍那能记。","浴佛人归深径里，邻闺儿女灯前戏。"]},{"t":"蝶恋花 魏里钱尔斐先生向有四月蝶恋花戏字韵词病中偶次其韵并索蘧庵珍百竹逸云臣和八首 其八","f":"古风","c":["四月荆南风景异。","乍雨还晴，晴雨都无次。","欲认前村浑不似，茫茫万顷黄云腻。","一巷柴门谁夜闭。","打麦声中，隐隐猧儿吠。","酒辣饼香真足喜，灶前抟黍添丁戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其一","f":"古风","c":["五月荆南梅雨至。","好贮天泉，竞涤空斋器。","豕腹龙头堆满砌，庭前新改瓶罂肆。","溅沫倾珠差足喜。","亟唤樵青，活火须先炽。","道是茶声还不是，依稀松鬣拿风戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其二","f":"古风","c":["五月荆南饶好味。","笋脯茶油，都上蛟桥市。","细切黄瓜凉欲嚏，厨香正熟长腰米。","饱饭风前贪美睡。","剥啄谁欤，佳客催人起。","库里葛衣新岁质，迎宾且学披裘戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其三","f":"古风","c":["五月荆南花未已。","各色戎葵，浓淡摇轩砌。","闻道街南花更丽，殷勤乞取三升子。","待得明年栽满地。","簇绣铺茵，便作花城矣。","此是贫家真富贵，人间富贵还如戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其四","f":"古风","c":["五月荆南新涨至。","一片茭芦，总把川光翳。","阁外溪风来也未，阴阴先作铿鍧势。","水郭涟漪逾十里。","买件蓑衣，走入渔翁队。","日落笛声篷背起，封侯不换垂纶戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其五","f":"古风","c":["五月荆南蒸湿翠。","墙角苔生，础润垣衣腻。","院静日长沈水费，瞢腾兀坐思陈事。","忆看京江江万里。","烂若银盘，倒插金山寺。","雪片崩涛飞彩帜，妙高台下龙舟戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其六","f":"古风","c":["五月荆南佳节至。","角黍堆盘，嫩绿窗前醉。","绛缕丝丝斜缠臂，钗符颤罢帘痕碎。","五毒罗囊裙带繫。","始信人生，骑虎非难事。","折得海榴红染袂，蒲根镂作葫芦戏。"]},{"t":"蝶恋花 五月词仍用前韵八首 其七","f":"古风","c":["五月荆南多酒会。","蜜蟹糟蛏，新自江船寄。","杏酪搅酥偏沁肺，桃膏红透冰瓷内。","万事苍茫休问矣。","餔啜吾生，此举强人意。","闲看雨丝蛛网缀，分明空里穿珠戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其一","f":"古风","c":["六月荆南村贴水。","蒲苇成丛，屋傍渔庄尾。","溘溘野风波面起，湖梢直灌桥门里。","白发老翁无个事。","掩罢柴扉，选块阴凉地。","招手老妻牵稚子，团团听话隋唐戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其二","f":"古风","c":["六月荆南天似醉。","雨嫩如无，恰又吹来细。","赢得遥山都欲睡，模糊失却青螺髻。","檐溜渐删删不已。","忽见中庭，一缕晴虹起。","那禁群儿争笑指，碧翁也著斑斓戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其三","f":"古风","c":["六月荆南蒸暑气。","过了梅天，市上无兼味。","白小黄鱼稀少至，老饕镇日涎垂地。","红糯新炊淘苋滓。","蚬酱葵羹，也自饶风致。","鼓腹陶然吾足矣，瓜棚之下閒游戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其五","f":"古风","c":["六月荆南多水市。","鞋样凉船，柳树根头舣。","茭白菱红排氿尾，渔翁又粜鸡头米。","一望风荷兼雨芰。","才见钱钱，又早田田矣。","剥罢莲蓬何处使，挼来做个人儿戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其六","f":"古风","c":["六月荆南蝉早沸。","做暝连阴，夏已赊秋意。","莫谓晚凉饶爽致，田禾最怕床头被。","长日经营无好计。","枕上诗成，记又无头尾。","且拾厨中青鸭子，糊他一盏萤灯戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其七","f":"古风","c":["六月荆南人早起。","倚阁看云，云气朝朝异。","夭矫轩腾兼蔚跂，火云烧却铜峰翠。","蜃国那须誇海市。","换狗更衣，反覆须臾耳。","若问世间还胜此，天公聊学人情戏。"]},{"t":"蝶恋花 六月词再用前韵八首 其八","f":"古风","c":["六月荆南门屡闭。","壁上乌巾，挂著多时矣。","客到蕉窗时一启，不迎不送贪徒跣。","问我新编今有几。","叩首主臣，夜火烧残矣。","消夏祇馀词一纸，君休哂我篇篇戏。"]},{"t":"蝶恋花 夏日睡起即事","f":"古风","c":["几日戎葵阶下长。","烟腻吴天，难得心情爽。","风袅茶烟斜翠幌，燕雏争把香泥抢。","窗小绿阴偏簸荡。","梦觉循墙，暗地闲来往。","谁打楼前铜砌响，熟梅自落中门上。"]},{"t":"蝶恋花 本意","f":"古风","c":["记在绣裙亲见汝。","深院潜行，蓦又花间遇。","缀绿黏红无定处，濛濛扑遍东园路。","艳粉退来还几度。","天若多情，休遣春光暮。","拆了秋千飞却絮，成团滚过墙头去。"]},{"t":"蝶恋花 咏水仙花","f":"古风","c":["小小哥窑凉似雪。","插一瓶烟，不辨花和叶。","碧晕檀痕姿态别，东风悄把琼酥捻。","滟潋空濛天水接。","千顷烟波，罗袜行来怯。","昨夜洞庭初上月，含情独对姮娥说。"]},{"t":"蝶恋花 清明同诸子集原白斋中","f":"古风","c":["柳线黄时雏燕乳。","为拣芹泥，掠尽廉纤雨。","今日风光刚百五，新晴斗煞新妆妩。","须听尊前喧画鼓。","照眼花枝，负了卿何苦。","不信试看风起处，乱红砌满春归路。"]},{"t":"后庭宴 春日同仲震过谯岩先生斋看牡丹 斋名壶天","f":"古风","c":["天宝名花，蓬莱新筑。","君家最有仙家福。","洛阳千里锦年光，摄来都向壶中缩。","盈盈复蹬回廊，袅袅娇丝脆竹。","绿窗低唱，换了华清曲。","历乱夜灯红，被帘风小蹴。"]},{"t":"一剪梅 吴门客舍初度作","f":"古风","c":["风打孤鸿浪打鸥。","四十扬州，五十苏州。","半生习气破除休。","少日倡楼，老去僧楼。","故垒萧萧芦荻秋。","说甚曹刘，只羡孙刘。","专诸巷内且淹留。","烽火边愁，风雪羁愁。"]},{"t":"一剪梅 七夕由虞城渡河至单县","f":"古风","c":["客里流光迅逝波。","五日才过，七夕将过。","殊乡令节巧蹉跎。","星渡银河，人渡黄河。","剧怜良夜不如他。","天上情多，地上离多。","红闺两地蹙愁蛾。","大妇停梭，小妇停梭。"]},{"t":"钗头凤 艳情","f":"古风","c":["蔷薇罅，秋千架。","中门阖锁声才罢。","银墙侧，铜扉直。","记来约略，行来疑惑。","黑。","黑。","黑。","幽窗下，红灯射。","夜阑绿水昏如画。","花纹槅，玲珑极。","剪刀尚响，冠儿未摘。","嚇。","嚇。","嚇。"]},{"t":"钗头凤 读蘧庵先生词用原韵","f":"古风","c":["啄月手，谈天口。","胸中云梦吞须九。","宁游戏，非文字。","问他作者，几人曾会。","未。","未。","未。","情丝镂，啼珠溜。","断肠怕学屯田柳。","羞溱洧，翻清徵。","笛吹江阁，帆骑峡水。","似。","似。","似。"]},{"t":"朝玉阶 冬日过惠山下一梅亭","f":"古风","c":["曲径斜桥涧影迤。","空山亭子好，趁闲过。","小轩飐水似残荷。","石栏经雨涩，遍青莎。","短墙丛竹受风多。","一声渔磬杳，湿烟蓑。","黄梅著色斗新鹅。","折来堪作供，佛头螺。"]},{"t":"唐多令 夜饮纪事","f":"古风","c":["无梦觅封侯，随缘做浪游。","尽颠狂、锦瑟红篝。","听得关山刚入破，重惹起，半生愁。","心事付沙鸥，闲身伴杜秋。","问乾坤、何地埋忧。","月到五更还未落，人倚在，水明楼。"]},{"t":"唐多令 重九后食蟹半醉作","f":"古风","c":["无菊底须愁，桂花香正幽。","与诸君、且筑糟邱。","不记昨宵重九节，风雨里，怕登楼。","半醉睨吴钩，吾生行且休。","任古来、割据孙刘。","龙额岸头浑不羡，偏只爱，内黄侯。"]},{"t":"唐多令 拥被","f":"古风","c":["早漏减银虬，新寒警画楼。","漾罘罳、红日惊眸。","幄里余温犹可恋，才欲起，又还休。","花好懒抬头，帘垂怕上钩。","恼檐前、闹雀喧鸠。","护惜衾窝留梦在，莫捲去，半床愁。"]},{"t":"繫裙腰 咏裙","f":"古风","c":["满园草色绿迢迢。","都吹上，小裙腰。","栖鸾宿蝶风流甚，暗晕红潮。","轻飏处，称垂髫。","有时沈在帘儿底，依稀微露轻绡。","隔花绣带无风转，浅立春宵。","想应拂遍，落梅娇。"]},{"t":"明月逐人来 惠山山麓谒睢阳祠","f":"古风","c":["坏廊径仄，哀湍响激。","松杉外、层层夜色。","悲歌南八，箭著浮图甓。","铁像贺兰苔涩。","斟得一杯，黛沈几瓯茗汁。","依稀见、云旗下食。","恰逢泓底，龙啸潭风急。","又认戍楼闻笛。"]},{"t":"赞成功 忆梁园客夏，避暑开元寺南湖草堂，与徐恭士、宋牧仲家、亦人别驾、子万四舍弟、僧雪笠日夕谈宴。别来遂及一载，词以志忆","f":"古风","c":["好风凉夜，新月疏桐。","一年前事尚濛濛。","记曾避暑，梁孝园中。","野塘水碧，古寺墙红。","溪友词客，雨笛霜篷。","弄人衫子钓丝风。","别来一载，憔悴江东。","南湖鱼鸟，定也怜侬。"]},{"t":"似娘儿 舟过娄门即事","f":"古风","c":["渡口绿蓑斜，绕子城、碧浪周遮。","谁知我是元真子，卖饧天气，凭桡心事，荡桨生涯。","水面小窗纱，响枨枨、谁摘琵琶。","东风似梦回头望，绝无人影，粉墙之内，一树桃花。"]},{"t":"青杏儿 本意","f":"古风","c":["六尺小帘漪。","交网外、杏子累累。","流光暗换无人觉，才看绿绽，俄惊茜透，忽讶黄垂。","回首忆芳菲。","记二月、花正开时。","匀圆拟把筠篮摘，怪他墙上，谁家飏过，红画竿儿。"]},{"t":"定风波 赠牧仲歌儿阿陆","f":"古风","c":["蝴蝶成团榆荚飞。","轻狂恰称五铢衣。","若问年华刚几许。","数数。","晚峰十二正愁时。","莫道梁园非故土。","且住。","得人怜处不须归。","问控郎君堂后马。","偷跨。","陆郎从古爱斑骓。"]},{"t":"定风波 又赠歌儿阿增","f":"古风","c":["持底尊前赠阿增。","浓纤一幅缭红绫。","上写蝇头无数字。","须记。","千丝万缕意层层。","好向歌楼并舞院。","常见。","细腰束罢怕难胜。","莫到春街闲赌戏。","轻弃。","他年知否忆来曾。"]},{"t":"定风波 紫薇花","f":"古风","c":["一树曈昽照画梁。","莲衣相映斗红妆。","才试麻姑纤鸟爪。","袅袅。","无风娇影自轻飏。","谁凭玉阑干细语。","尔汝。","檀郎原自紫藤郎。","闻道花红无百日。","难得。","笑他团扇怕秋凉。"]},{"t":"定风波 九来半茧园东偏，为余新辟一浴室，解衣盘礴，致甚适也，词以纪之","f":"古风","c":["身是荆南白鹭群。","拍波只爱絮纷纷。","自笑此生饶水癖。","为客。","那能长弄画溪云。","竹径粉墙泉又冽。","清绝。","人从何处有尘氛。","浴罢簟痕冰雪做。","闲卧。","快吹长笛送斜曛。"]},{"t":"定风波 齐世家为阎牛叟赋","f":"古风","c":["华阀由来数济阳。","国风从古说齐姜。","轻唤红闺名更好。","仙窈。","盈盈林下是闺房。","记得诗人佳号否。","牛叟。","果然织女配牛郎。","门内双丁尤异事。","姊妹。","刘家还有第三娘。"]},{"t":"苏幕遮 咏栀子花","f":"古风","c":["玉罗松，檀晕嫭。","朵朵同心，开在帘垂处。","茉莉闽兰犹未乳。","早绽琼葩，借与人消暑。","不禁风，时怯雨。","浴罢鬟偏，摘向栏边去。","翠帐阴阴宵未午。","月黑花明，凝得房栊曙。"]},{"t":"渔家傲 三月十八雨中，同杜茶村、韩尔铉、黄稚曾过饮钱础日十峰草堂，同用范希文原韵","f":"古风","c":["说鬼谈天矜博异，自循短发无生意。","醉舞仙仙鸲鹆起。","深径里，怕窥狂态门须闭。","何用扊扅嗟百里，吾生自有驱愁计。","却笑天公烦恼地。","浑如寐，朝朝只洒花间泪。"]},{"t":"渔家傲 新秋即事和云臣韵二首 其一","f":"古风","c":["蜩响才将馀火送，砧声又迫秋情动。","天上双丸谁播弄。","閒愁重，人间白发凭伊种。","一枕瑶妃斟绿瓮，骖鸾翳鹤群真哄。","觉后匡床无与共。","真成梦，乱云封却华阳洞。"]},{"t":"渔家傲 新秋即事和云臣韵二首 其二","f":"古风","c":["晨唤青童沿砌扫，待他一叶占秋早。","浣取幽墀如镜好。","秋已到，碧天万斛银潢倒。","莫使秋光容易老，等閒黄了天涯草。","静听跳珠荷叶闹。","临流钓，忘机不怕群鸥恼。"]},{"t":"渔家傲 羊流店怀古 叔子故里","f":"古风","c":["太傅千秋存故里，我来削面西风起。","欲问遗踪何处是。","傍人指，乱碑没入寒芜里。","今日江山仍战垒，野花阅尽前朝史。","儒将雍容能有几。","休相戏，何如铜雀台前伎。"]},{"t":"渔家傲 齐河县","f":"古风","c":["旬日崎岖行左担，征车确荦投山店。","鲁酒何如愁思酽。","心情减，白头彩笔浑相赚。","竟有估帆三四点，枫根也繫斜阳缆。","新月初黄偏滟滟。","铺竹簟，笛声快作伊州犯。"]},{"t":"破阵子 江上作","f":"古风","c":["千顷晴漪皱绿，四围晚髻黏红。","蛋户鲎帆来海外，犀液龙漦贮月中。","寒潮打故宫。","雁叫酸然欲雨，鼍吟砉若成风。","刘毅宅边堆蔓草，郭璞坟前拥断篷。","秋江愁杀侬。"]},{"t":"破阵子 拟过竹逸斋前探梅辄因雨阻词以柬之","f":"古风","c":["昨夜雏寒侧侧，今晨小雨濛濛。","屡拟寻花过涧北，屡约听莺到水东。","心情无那慵。","丽景偏怜易谢，冶游最惜难逢。","四百八十南朝寺，二十四番花信风。","鹃啼催落红。"]},{"t":"落灯风 冬闺","f":"古风","c":["五更一阵寒偏准，冷焰挑来才半寸。","无语拨香灰，天应要糁铜街粉。","怪底霜风紧。","帘外乌龙眠不稳。","城河小，结冰犹嫩。","江梅入旧年，掀破床头残历本。","岁尽愁难尽。"]},{"t":"凤衔杯 偶感","f":"古风","c":["弱柳丝丝街前漾。","正初学、小蛮腰样。","有隔水红墙，翠楼倒映墙头上。","听楼内、三弦响。","恰重经，人已往。","帽檐斜、倚风凝想。","只似梦如烟，柳花扑地漫天放。","寻不出、伊门巷。"]},{"t":"凤衔杯 观音山游暮归即景","f":"古风","c":["香红暖翠风吹散。","依旧在、心头嵌满。","恰残梦懵腾，墙围青粉谁家馆。","正隔水、飘歌板。","柳丝楼，梨花苑。","雨濛濛、画船归晚。","剩荠菜连天，檀心娇煞无人管。","黄了春城一半。"]},{"t":"醉春风 上巳阴雨忆乙巳暮春与王阮亭主客修禊洗钵池上慨然成咏","f":"古风","c":["风约飞红趁，雨涴香泥印。","春归算隔几多时，近。","近。","近。","挑菜人稀，湔裙节过，卖饧声紧。","已少寻春分，好把閒愁论。","那年却记共王郎，韵。","韵。","韵。","丝管精详，宾朋妥帖，心情安顿。"]},{"t":"醉春风 春日饮远公海棠花下和竹逸作","f":"古风","c":["榨就真珠味，泻向玻瓈内。","劝花花只苦推辞，醉。","醉。","醉。","靥浅潮生，杯浓晕重，恼郎多事。","满院春深闭，六幅帘垂地。","抱花花又苦推辞，睡。","睡。","睡。","娇极难胜，困酣难醒，笑郎无谓。"]},{"t":"醉春风 春暮","f":"古风","c":["红老莺偏趁，绿暗窗难认。","等閒飏起楝花风，闷。","闷。","闷。","妆阁凭殷，舞衫叠黦，玉钗敲璺。","不放东皇闰，权取榆钱赆。","送春暂去几时归。","问。","问。","问。","明岁新年，水边郭外，候伊来信。"]},{"t":"麦秀两岐 为周贞女题词","f":"古风","c":["既许驱金犊，便合歌黄鹄。","断肠花，贞女木。","碧海孤鸾宿。","嫁箱提上秋坟鬻，蘼芜难绿。","何必谐花烛，长愿镌冰玉。","梦中魂，看未熟。","想像髽而哭。","夸娥有意扶坤轴，愧他臣仆。"]},{"t":"侍香金童 题闺秀画扇用湘瑟词韵","f":"古风","c":["蕃马平沙，六角屏风摺。","映的的、腮涡红晕颊。","擘阮砑筝都未惬。","只把檀槽，粉偎酥贴。","偶临花蕊样，闲将螺管捻。","衬几笔、烟条露叶。","料尔前身枝上蝶。","乍搯齐纨，燕窥莺踏。"]},{"t":"献衷心","f":"古风","c":["记故人家在，水墅之东。","荷十里，白濛濛。","想兔园残雪，尚缀藕塘中。","偏作态，将腻粉，换香红。","花隐约，月朦胧。","此身疑在广寒宫。","算最难忘得，雨幔烟篷。","今何夕，人怅望，水连空。"]},{"t":"芭蕉雨 咏秋雨","f":"古风","c":["似梦如尘淅淅，乍无还乍有、何时歇。","夜永三更将绝。","正值曲巷砧鸣，颓墙蛩咽。","阵阵罗衾凉彻。","愁共小屏摺。","逢白雁北来、和人说。","说道汉寝唐陵，今夜雨洒丹枫，尽流红血。"]},{"t":"芭蕉雨 春雨","f":"古风","c":["轻暖轻寒时节，东风将柳絮、搓香雪。","暗惹翠蛾千结。","绝似细雨红桥，情人乍别。","绿窗花影半摺，待折未曾折。","尽草上轻狂、双黄蝶。","乱扑著雨和烟，搅得今岁韶光，不成三月。"]},{"t":"芭蕉雨 骤雨","f":"古风","c":["日午绛云烘墨，渴乌偏掉尾、威胡赫。","一霎溪风凉激。","谁取十万冰弦，辊来霹雳。","急雨琤琮裂帛，万瓦战金铁。","轰馀怒犹思、坏墙壁。","此际白苧凉衫，独上快阁临风，须如猬磔。"]},{"t":"辊绣毬 纪游","f":"古风","c":["淡荡刺梅园，被紫蝶、成团勾去。","杂花眠砌，雏莺梳院，赤栏银井，想经昨夜，一场新雨。","门外天寒如许。","小楼上、有人知否。","断无消息，可胜惆怅，两层门内，惟闻弦响，枨枨不住。"]},{"t":"品令 夏夜","f":"古风","c":["夜色凉千顷。","携笛簟、依金井。","辘轳清冷。","一天松籁，半规晶饼。","慢泻流光，渐映素瓷绿茗。","微茫杳冥。","水廊外、风荷整。","阑干碎拍，旧游何处，瑶京路永。","簸满空庭，帘影树影鬓影。"]},{"t":"酷相思 冬日行彰德卫辉诸处马上作","f":"古风","c":["赵北燕南多驿路。","见一带、霜红树。","又天外乱山青可数。","丛台也，知何处。","雀台也，知何处。","一鞭袅袅临官渡。","雁叫酸如雨。","尽古往今来誇割据。","漳水也，东流去。","淇水也，东流去。"]},{"t":"淡黄柳 道院中见黄木香词以咏之","f":"古风","c":["蜂黄褪了，争上枝头簇。","嫩蕊成丛蒙涧竹，覆遍书窗小屋。","揉入红槽碎珠续，压醅熟。","萧疏乱秋菊。","引柔蔓，暗香触。","月昏黄、料尔伤幽独。","折上鍊师，通明冠子，雅称厌禳装束。"]},{"t":"玉梅令 南耕所葺书舍，颜曰梅庐。昨始移得古梅一株，遽以誇我，走笔戏柬","f":"古风","c":["旧营梅舍，不见些梅也。","今朝真见梅精嫁。","看藓铺铁鬣，并石绣铜柯，黛色成围，涛声暗泻。","癖处疑颠，狂来相诧。","说此乐、甚于仆射。","撚横枝微嗅，何必待花开，香已在、枕棱窗罅。"]},{"t":"玉梅令 同云臣诸子过放庵禅院看梅时积雨新霁","f":"古风","c":["禅房甚绮，有粉英娇倚。","连宵雨、几枝临水。","恰小停响屐，檐隙已微红，纱窗日影，顿添半指。","茶鎗酒灶，都饶名理。","只轩外、怕东风起。","嘱成团香雪，休去舞春城，须片片、堕金尊里。"]},{"t":"锦缠道 将发玉峰寄纬云弟村居","f":"古风","c":["老去江东，拚向渔樵寄傲。","问何为、冲炎席帽。","年年作苦杂佣保，赤日红尘，怕相嘲程晓。","想西溪草堂，雨杉烟筱。","傍苔阴、置笔床茶灶。","晚凉濯足欹湖，恰估船笛响，风定菱丝袅。"]},{"t":"锦缠道 冬日溪行","f":"古风","c":["红叶攒天，烘得柴门如醉。","板桥南、昏鸦成队。","遥村界得寒林碎，一派疏罾，更绕遥村背。","夕照炫红黄，半陂明晦。","且停船、荻花以内。","被沙禽唤起西风，激千层银沫，乱把晴矶碓。"]},{"t":"厌金杯 戏咏萤灯","f":"古风","c":["小似香囊，空于湘水，映疏萤、纱痕逾翠。","墨花几幅，面面小徐熙，凉夜戏。","茉莉梢头轻缀。","频吹难灭，不剔长鲜，耿耿处、无情有思。","楼昏月黑，嫌煞烛笼明，冰簟底。","窥见一星星事。"]},{"t":"垂丝钓 戏咏猫","f":"古风","c":["房栊潇洒，狸奴嬉戏檐下。","睡熟蝶裙儿，皱绡衩。","梅已谢，撒粉英一把，将伊惹。","正风光艳冶。","寻春逐队，小楼窜响鸳瓦。","花娇柳奼。","向画廊眠藉，低撼轻红架。","鹦鹉怕，唤玉郎悄打。"]},{"t":"行香子 为李武曾题扇上美人同弟纬云赋","f":"古风","c":["烟样罗裯，月样银钩。","人立处、风景全幽。","谁将纨扇，细写风流。","有一分水，一分墨，一分愁。","天街似水，迢迢凉夜，十年前、事上心头。","双飘裙带，曾伴新秋。","在那家庭，那家院，那家楼。"]},{"t":"行香子 同岵云上人鲁望弟过徐氏园亭","f":"古风","c":["垒石支泉，架壑招烟。","小桥外、老屋斜川。","洁何忍唾，静欲成眠。","恰半栏花，数陂竹，一湖莲。","距村背郭，嶒泓萧瑟，似蜗庐、又似渔船。","无冬无夏，非陌非阡。","尽昼呼卢，朝说剑，夜鸣弦。"]},{"t":"行香子 回舟即事","f":"古风","c":["红树槎枒，绿水周遮。","荡舟回、水驿烟斜。","一樽似梦，万事如麻。","叹吾衰也，行不得，住为佳。","极天烽火，依然此地，小楼前、人戴黄花。","船头侧听，不是悲笳。","是前溪口，新月底，拨琵琶。"]},{"t":"青玉案 移寓积翠阁用艺香词韵","f":"古风","c":["梯空架就羊肠路。","领俊鹘、穿烟去。","窗豁正当山破处。","天风澒洞，吹完今古，只剩龙窝住。","松毛纯碧腾猩鼠。","下嵌寒潭瘦蛟舞。","老树得风都作语。","半床泉气，一帘山雾，晴昼家家雨。"]},{"t":"青玉案 夏日怀燕市葡萄","f":"古风","c":["风窗冰椀谁消暑。","记百颗、堆盘处。","掬罢盈盈娇欲语。","轻明晶透，芳鲜圆绽，小摘西山雨。","长安万事俱尘土。","惟有高情难忘汝。","暗想风姿奚似许。","爽疑燕筑，醇如刁酒，滑类华清乳。"]},{"t":"青玉案 雁字","f":"古风","c":["未乾墨迹遥天外。","闲付与、斜阳晒。","狂扫八分临阿买。","赪红霞尾，蔚蓝天色，好幅乌丝界。","年年未了衔芦债。","入塞几时还出塞。","盘作擘窠鬈作虿。","凭谁偷仿，十三行帖，写上银筝背。"]},{"t":"凤凰阁 元夕后一日同云臣放庵过安乐禅院","f":"古风","c":["枉东风费力，陌头飘掠。","无灯何处好吹落。","独有一枝梅蕊，春意先觉。","且步过、寺桥溪阁。","一声幽磬，香气暗萦林薄。","寺门小立盼寥廓。","流水外，远山尖，积雪埋却。","甚日睹、翠螺如削。"]},{"t":"凤凰阁 汴京夜雨","f":"古风","c":["被东风送到，东京更鼓。","又添隔巷数声杵。","暗想半生沦落，廿载羁旅。","总不比、今番凄楚。","朦胧枕畔，不断吴娘鸣橹。","醒来有甚好心绪。","人瘦也，怪黄花，瘦也如许。","滴不了、秋檐夜雨。"]},{"t":"凤凰阁 虎邱喜遇侯记原大年","f":"古风","c":["记摘船吟雨，倚楼题柳。","樊川水榭暂携手。","一自消魂赋别，几度回首。","沈家令、带围较瘦。","帽檐微侧，斟酌桥边闲走。","故人忽遇半塘口。","知尹绿，小轩前，丛桂开久。","却底事、还眠虎阜。"]},{"t":"感皇恩 晚凉杂忆六首 其一","f":"古风","c":["记得镇淮门，风篷竞举。","都歇荷潭最深处。","绿蓑乌榜，雁翅玲珑无数。","嫩凉三万顷，谁先取。","茱萸湾冷，山光寺古。","玉斝频倾水天暮。","酒红上面，笑拊冰肌销暑。","三年浑一梦，扬州路。"]},{"t":"感皇恩 晚凉杂忆六首 其二","f":"古风","c":["记趁过江船，远帆疑豆。","北固喧豗怒涛吼。","江山如此，消得几场诗酒。","举杯遥酹取，黄公覆。","水云轇葛，阳阴杂糅。","奇石成狮破空走。","竹林僧老，坐我秋林闲昼。","半枝邛竹杖，如人瘦。"]},{"t":"感皇恩 晚凉杂忆六首 其三","f":"古风","c":["记在百泉山，盘涡漩洑。","杂佩丛铃暗相触。","涧花如雪，了了遥明山屋。","苏门蒸彩翠，添银瀑。","谁家园子，沿流嵌麓。","晚饭家家?湘竹。","流连河朔，此地从无三伏。","中原生爽籁，天新沐。"]},{"t":"感皇恩 晚凉杂忆六首 其四","f":"古风","c":["记在玉河桥，天街无赖。","被酒狂歌禁门外。","蒲桃晶透，选取招凉珠赛。","冷萤流殿瓦，冰初卖。","倦听太液，蝉声一派。","想像宸游甚时再。","飘红坠粉，凤艒经秋都坏。","燕丹门下客，皆安在。"]},{"t":"感皇恩 晚凉杂忆六首 其五","f":"古风","c":["记在鲁蒙阴，霜枫浓淡。","叠巘层崖幻苍绀。","秋生海市，红日一轮孤陷。","晚凉催卸驮，投关店。","云迷石匮，烟零玉检。","翠羽金支半明暗。","秦松西笑，华掌碧莲初染。","齐州青八九，才如点。"]},{"t":"感皇恩 晚凉杂忆六首 其六","f":"古风","c":["记在涌金门，冷云成画。","落月高楼水明夜。","佯狂脱帽，行到宋诸陵下。","碧羊缠石藓，眠官野。","一湖莲叶，半城樵舍。","西子嫣然晚妆罢。","隔江雪浪，隐隐天风樯马。","狂思横万弩，迎潮射。"]},{"t":"天仙子 赠寒松和尚同云臣赋 和尚曾驻锡善权，今掩关北郭","f":"古风","c":["玉洞银楼垂碧乳，夜夜老猿吟冷树。","山僧兴到爱溪山，飞锡住，浮杯渡。","结个茆庵山下路。","尘界茫茫无定据，雪里飞鸿风里絮。","山僧兴尽别溪山，一笑去，谁回顾。","明月满山无觅处。"]},{"t":"天仙子 书周我成先生旅叹赋后 先生少年时曾赴马贵阳之宴，酒酣骂座，竟以此贾门户祸","f":"古风","c":["辇上列侯开夜宴，年少挥鞭奔赤电。","酒酣夺得紫檀槽，褰绣幔，人惊散。","裂却当筵丞相面。","门户凋残风物换，白发渐离谁作伴。","荒江破屋谱牢愁，游侠传，无家叹。","月底栖乌声历乱。"]},{"t":"殢人娇 早过友人斋头书所见","f":"古风","c":["庭院清清，漾起捲帘风大。","帘底露、粉郎闲坐。","消停半晌，又氍毹横卧。","无甚事、吹得小池萍破。","曲本慵翻，歌场懒作。","绿莎上、戏将钱簸。","惯寻人事，却嗔人真个。","唤不应、走弄菊花残朵。"]},{"t":"殢人娇 闲况","f":"古风","c":["屋对晴山，黛影离离争泫。","山梅瘦、递香窗眼。","细煎绿雪，注乳花盈椀。","隐几坐、笺竟黄庭下卷。","饲鹤斜桥，听莺空馆。","更相邀、两三狂狷。","看云选石，趁闲身尚健。","此外事、付与天公总管。"]},{"t":"殢人娇","f":"古风","c":["记得君家，踠地垂杨低亸。","更紫艳、临风千朵。","每逢花发，绿窗边有我。","与两三、禅侣词人闲坐。","今岁吴天，君浮越舸。","压烟江、一帆斜簸。","家园春景，说依然婀娜。","无人处、一树浓香深锁。"]},{"t":"殢人娇 晚浴","f":"古风","c":["几阵蝉嘶，趖了一枝花影。","帘底下、井华冰冷。","绡裳乍解，更红酥寒凝。","似素藕、浸勾碧湖千顷。","浴罢凭阑，晚妆慵整。","且消受、凉花绿茗。","盈盈皓月，渐低窥金井。","又画就、深院夜香风景。"]},{"t":"佳人醉 梁溪道中积雨乍霁","f":"古风","c":["一夜春篷淅沥，声乱樵歌渔笛。","正吴娘橹拨，参差水面，夜景如墨。","鸡唤津桥梦醒，恰何来新霁，穿樯隙。","推窗起坐，九点龙峰，遥苍暖翠，迎著空舲滴。","吟情剧。","吮毫微笑，一片晴村历历。"]},{"t":"江城子 戏写姬人领巾","f":"古风","c":["石头城下小萧娘。","眼波长，鬓云光。","少小随耶，飘泊到睢阳。","恰遇游梁病司马，刚一笑，结鸳鸯。","晓寒呵手点梅妆。","雪轻飏，怕开箱。","只是新年，郎又渡春江。","且把木瓜还渍粉，欹枕待，到秋凉。"]},{"t":"江城子 题邹九揖像","f":"古风","c":["昔年同学半吴中。","饮千钟，笔如风。","钗馆毬门，脱帽夜过从。","看到江南红豆熟，分散了，各西东。","年来汝客晋阳宫。","草黏空，没孤鸿。","落照壶关，匹马吊英雄。","一笑画师真鹘突，偏画汝，做衰翁。"]},{"t":"江城子 石榴","f":"古风","c":["茜裙提出锦箱中。","向花丛，斗娇容。","裙影花光，都到十分浓。","记得夜凉低压鬓，偏爱把，绿云笼。","如今朱实画檐东。","乱薰风，缀晴空。","极望累累，高下绽房栊。","欲摘又怜多子甚，相对笑，瓠犀红。"]},{"t":"江城子 秋怀","f":"古风","c":["商飙飒沓响高天。","砉雕弦，散空烟。","荡樾摇林，一夜透吴关。","恰值角鹰西极到，侧脑视，色苍然。","野夫江阁拨书眠。","笛声圆，倚阑干。","那管草间，狐兔剧喧阗。","且拢撅头船一只，蒲苇里，钓秋鳊。"]},{"t":"江城子 鲍让侯载酒汎舟，同于皇、仲震、商原、佩纫、家弟鲁望，小泊城南诸寺，纪所见","f":"古风","c":["西风脱叶响高天。","酒如泉，发狂颠。","蓦遇娇红，澹粉佛堂边。","恰似湿云欹一朵，扶不定，竹栏前。","老夫侧帽兴翩然。","晚妆鲜，屧痕圆。","何事匆匆，又上菊花船。","市火风帘十万户，人不见，水成烟。"]},{"t":"江城子 春雨新晴过吴城西禅寺登摩利支天阁同澹心园次云臣南水赋","f":"古风","c":["连宵怯雨思难裁。","鹊声催，曙光开。","且逐晴丝，荡漾绕城隈。","我比晴丝还更懒，风送我，转徘徊。","千寻佛阁倚崔巍。","眺胥台，漫生哀。","阁外遥山，幅幅叠春苔。","争学诸天螺髻样，青万朵，逼窗来。"]},{"t":"江城子 郊游即事","f":"古风","c":["心情早起太聊萧。","出晴郊，涉兰皋。","云水茫茫，不认路条条。","只拣暗香深处去，还趁著，卖饧箫。","春流碧到第三桥。","野梅娇，绽篱腰。","何处丝杨，和了酒旗飘。","遥望前村偏隔水，亟唤个，小船摇。"]},{"t":"江城子 秋日同雪笠家弟子万过恭士南郊书舍","f":"古风","c":["开元寺外水云宽。","竹檀栾，岸巑岏。","晴翠飞来，湿透几曾乾。","碧碧黄黄都滴向，篱落外，远林摊。","茅堂恰对此中安。","荻花滩，菊花阑。","长昼携僧，同注马蹄篇。","忽见荒城苍铁色，百战后，箭成瘢。"]},{"t":"江城子 沙随感旧","f":"古风","c":["思量往事极分明。","小徐卿，昵云英。","萧寺幽窗，檀板劝银罂。","两小一双瞄不尽，红烛下，态盈盈。","西风捲去隔年情。","寺钟鸣，记前生。","落叶中原，恰又趱离程。","淡月晓风昏似梦，和泪也，出层城。"]},{"t":"小桃红 如皋冒天季，自署信天翁，向予索词，因有此赠，每句中俱暗用禽言及鸟名","f":"古风","c":["得过还须过。","力作如何作。","说甚饼焦，管他泥滑，且图著火。","任陇山，秦吉了聪明，好瞢腾些个。","姑恶谁能那。","急急归休错。","提罢葫芦，世间那有，凤凰如我。","叹连朝，行不得哥哥，信天翁且坐。"]},{"t":"月上海棠 游顾龙山 山在金沙城外相传明太祖曾驻跸此山","f":"古风","c":["一拳小结青莲瓣。","有离离、金刹铺烟阪。","闻说当年，翠华巡、朱旗暗卷。","残碑在，摇落空扪苔藓。","京江北固千秋显。","傍南朝、易惹伤春眼。","何似埋名，却依然、丹崖苍巘。","春花落，莺啭空山斋馆。"]},{"t":"归田乐引 题王石谷晴郊散牧图","f":"古风","c":["散牧凉秋月。","或树根、痒而摩者，或饮寒湫窟。","渡者，人立者，啼者，鸣者，喜则相濡怒相龁。","矜秋露毛骨，昂首森然如陵阙。","缘崖被坂，亏蔽满林樾。","驼一，塞马七，豕牛羊百三十，牧笛一声日西没。"]},{"t":"归田乐引 题春郊禊饮图","f":"古风","c":["粉墨真潇洒。","绿杨天、楼台金碧，阵阵湔裙社。","枰也，茗椀也，竹也，丝也，掩映花丛柳绵下。","风帘烟际挂。","墙里莺啼秋千架。","抱琴童子，穿过春山罅。","咏者，立饮者，奕者，讴者，一幅龙眠西园画。"]},{"t":"西施","f":"古风","c":["偶然小驻卓金车，听曲傍帘纱。","司空筵上，十队拍红牙。","就里双鬟，不肯施铅粉，一缕鬓堆鸦。","三年重到芜城路，空流落、可怜花。","银墙绿柳，愁煞那人家。","他日江船，倘遇啼衫客，休轻拨琵琶。"]},{"t":"西施 玉峰公宴席上赠施校书","f":"古风","c":["半街丝柳带烟拖，深巷入官河。","画船银蜡，赵李夜经过。","闻说虫娘，新自茸城到，唤取奏清歌。","阑花簌簌闻歌落，重趁拍、小婆娑。","地衣翠滑，扶不稳鸾靴。","嫌煞流莺，偏在东风底，学唱定风波。"]},{"t":"千秋岁 寿柏乡魏相国二首 其一","f":"古风","c":["黑头台鼎，画戟牙门整。","文笔健，风裁正。","芙蓉丞相府，屈轶中书令。","论事业，从来魏自同于丙。","北斗斜珠柄，南苑陈金镜。","司马相，臣民庆。","明堂朝玉帛，太庙编钟磬。","鱼水乐，千秋不数贞观盛。"]},{"t":"千秋岁 寿柏乡魏相国二首 其二","f":"古风","c":["沙堤隐隐，直接丹霄近。","臣稷契，君尧舜。","天留黄阁老，月照头厅印。","还说道，秋期今日悬弧准。","帘外凉飙紧，阶下新桐引。","仙酝熟，宫袍俊。","地居卿贰上，骨带神仙分。","齐献祝，恒山苍翠堆千寸。"]},{"t":"千秋岁 咏纸鸢二首 其一","f":"古风","c":["翩翩自喜，跌宕青天里。","麦铁杖，鸢肩子。","盘空筝夜叫，削草鹰秋起。","轻俊也，一场搬弄真儿戏。","三十年前事，触著难忘记。","杨花港，桃花寺。","邻童谁更在，老眼频经此。","重拈看，原来依旧情如纸。"]},{"t":"千秋岁 咏纸鸢二首 其二","f":"古风","c":["摩空决起，此事偶然耳。","材最小，风偏利。","轻狂应有恨，浩荡凭谁致。","须记取，青春牢把长绳繫。","已自飞腾遂，也算云霄器。","莫浪语，休私喜。","送来天上便，望向城头悸。","真险著，老夫只合街头睡。"]},{"t":"千秋岁 沧州戴浴扶以人日悬弧作词以赠","f":"古风","c":["新鹰决眦，已作摩空势。","笔阵快，词锋锐。","温邢何足道，燕许真同辈。","才八斗，綵毫人是青云器。","鹂砭君家事，三礼笺完未。","才地盛，门风贵。","新春欢七日，小令歌千岁。","微醉也，斜飞玉燕东风细。"]},{"t":"离亭燕 雨中将发梁溪，云臣拉赴竹逸斋头看梅，小饮数巡，匆匆判袂，升舻若失，怅赋小词","f":"古风","c":["花妮行人小惹，莺怪行人低骂。","正值小楼开似雪，抵死只将帆挂。","粉泪脸边明，脉脉含情待话。","嘱付梅清月寡，暂耐雨婚烟嫁。","此去春江帆正满，路隔才踰一舍。","待汎惠泉归，相赏水边篱下。"]},{"t":"于飞乐 鸳鸯","f":"古风","c":["彩翼文禽，一生睡暖涟漪。","葡萄春涨初齐。","度朱栏，穿绿浪，做弄葳蕤。","画楼低处，金塘好、漾尽红衣。","孔雀楼头，锦鸡关上，让他毛羽芳菲。","惹黄莺，和乳鸭，妒尔双栖。","生憎杜宇，东风里、只向人啼。"]},{"t":"隔帘听 听旧家歌伎隔墙度曲","f":"古风","c":["十载画楼烟月，凝想归何处。","黄絁新作瑶妃侣。","怅碧海茫茫，琼楼清苦。","无一语。","掩纱窗、低笼雁柱，将情诉。","妆楼一所，红粉墙围住。","歌声偏透红墙去。","想他墙内，新愁万缕。","伊知否。","隔墙一般悽楚。"]},{"t":"师师令 席上同云臣咏雏姬","f":"古风","c":["匀红剔翠，掷星眸斜卖。","春娇尚未忒玲珑，却已会、三分无赖。","笑匿花丛衫影在，怨风吹罗带。","银筝砑紧鸡鸣快，做殢人情态。","玉船频到只推辞，道酒病、昨宵曾害。","挼碎红梅庭下洒，骂粉郎心坏。"]},{"t":"隔浦莲近拍 夏日村居","f":"古风","c":["空村如浣静悄，不用邻翁扫。","水栅罾声响，沙映水，逾潇照。","傍岸松半老，闲来靠。","漫理晴江钓，钓丝袅。","凉飔暗袭，得风丛竹都笑。","帆投极浦，兀兀橹声将杳。","兴倦收纶起荷蓧。","恰好，窥人一点月小。"]},{"t":"隔浦莲近拍 暮秋江上偶步万佛林即黄介子先生旧宅","f":"古风","c":["西风吹响古木，乱叶埋僧屋。","略彴铺苍藓，攀树瘿，穿崖腹。","江郭围枫槲，登山麓。","遥望银涛矗，駴心目。","王珣池馆，沙鸥浦鸭争浴。","一声斋磬，彷佛雨霖铃曲。","踏遍缭垣寻断镞。","茶熟，老僧带暝归独。"]},{"t":"隔浦莲近拍 夏日寓吴门花溪草堂与西溟夹水而居赋示西溟","f":"古风","c":["玲珑云水几处，借我闲消暑。","掠槛沙鸥过，潭香触，碎成雨。","千顷风荷举，红妆嫭。","缃菂中心苦，最怜汝。","披襟脱帽，新凉随意搴取。","松风细响，绿雪暗翻花乳。","林际濛濛皓月吐。","四鼓，隔波尚有人语。"]},{"t":"隔浦莲近拍 赏荷同南耕纬云赋","f":"古风","c":["空明云水浩淼，渚濑丛幽筱。","绿净谁能睡，琼奁启，帘漪悄。","啁唽腾翠鸟，菱潭窈。","红藕花开了，数枝袅。","莲娃极浦，罗裙争荡清晓。","盈盈翠榜，烟舸竞将红闹。","摘得荷房缥菂小。","月皎，兀波柔橹声杳。"]},{"t":"传言玉女 雨中舟次吴阊不及过晤园次同纬云子万寄怀","f":"古风","c":["记得寻君，才过匆匆灯市。","伯通桥下，挽征衫且憩。","垂柳几树，临别倚栏斜指。","再来看汝，定鹅黄矣。","柳已鹅黄，撅头船恰又至。","满船丝雨，捲春蓑困睡。","微茫驿楼，料想水城将闭。","知他花下，已应微醉。"]},{"t":"传言玉女 舟经怀远访淩道一","f":"古风","c":["半载繁台，忆杀别来秋水。","今朝重见，喜碧犹如此。","无数笭箵，零乱烟桥夜市。","估船夹岸，乡愁千里。","闻道君家，在街头、黄叶里。","情亲小话，唤篙师暂舣。","峥泓淡沲，隐隐江楼笛起。","关山一望，何其明绮。"]},{"t":"百媚娘 春日忆洛下旧游","f":"古风","c":["草把裙儿腰比，花与脸儿潮似。","恰听枝头莺语滑，眉逗一丝新喜。","闻说酒旗歌板地，多少嬉游子。","忆在洛桥晴市，又向洧川烟涘。","一斛柳绵飘不定，扑著车如流水。","无数秋千墙角里，天半红绳起。"]},{"t":"百媚娘 送亩仙校书落籍次友人韵","f":"古风","c":["日午莺犹贪梦，风定花谁摇弄。","闻说长条新有主，纵与缠绵何用。","虽不干卿愁却种，懒把春钩送。","夹路香尘将动，一曲红绡权奉。","从此真成千里隔，只有月明相共。","戏语小楼燕赤凤，掌舞休嫌重。"]},{"t":"剔银灯 佛手柑不至词以寄慨","f":"古风","c":["记得常年此际，风送闽天柑子。","珠舶帆轻，花洋浪细，香遍吴头楚尾。","武夷仙使，向缥缈、鲤湖传至。","讵料岩关笳吹，竟隔千山万水。","天竺烟深，潮音月落，今日不知何世。","匆匆弹指，都不道、江山如此。"]},{"t":"剔银灯 春景","f":"古风","c":["阵阵兰情水意，队队描朱刷翠。","小巷蘼芜，斜街皂荚，都被雨酥烟腻。","东风多致，簸弄做、卖饧天气。","莫负年光韶媚，早办渔樵家计。","故国繁华，前生诗酒，身似浔阳江伎。","且拚沈醉，做蝴蝶、向花间睡。"]},{"t":"剔银灯 灯节前一日雨中云臣招同桢百大士雪持集饮蝶庵即事","f":"古风","c":["记得升平佳丽，此夜是、上元天气。","圆月打头，暗尘随马，阵阵梅边水际。","茜裙珠髻，喧笑处、香街声沸。","今岁冷清清地，未晚禁城先闭。","一盏灯昏，千家门掩，酿就春寒恁细。","雨丝飘砌，展几叠、小屏图醉。"]},{"t":"解蹀躞 秋雨夜宿田舍","f":"古风","c":["淼淼孤村断垄，只浪花翻舞。","疏檠自绿，茅檐伴人住。","休问红糯黄粱，总搴菰米茭丝，湿烟难煮。","夜将曙，白项鸦啼棠树。","树西近官路。","丛丛古庙，老巫击铜鼓。","敢倖今岁西成，祇祈暂歇床头，淙淙秋雨。"]},{"t":"下水船 暮次丹阳宿周丹申斋中同汤谷宾夜话","f":"古风","c":["风吼庱亭树，曛黑难投逆旅。","径诣君家，呼酒喃喃尔汝。","此间路。","一派涛轰沙莽，几阵烟凄风苦。","凭栏顾，霸气荒终古。","笑问寄奴何处。","若为吾歌，吾为若拍张舞。","天将曙。","起扫车箱冰花，争火仆夫寒语。"]},{"t":"碧牡丹 牡丹鲜碧者向在鄢陵曾见之追赋是词","f":"古风","c":["隔叶寻难著。","胜玉树，欺红药。","缥色衣裳，睡熟沈香亭角。","一朵云鬟，被雨梳风掠。","趁花容，亸烟萼。","柳阴薄，色向苔钱落。","波痕皱，眉痕弱。","鹦鹉笼中，也整绿衣偷学。","一别名花，怅碧云天各。","倩青鸾，到湘阁。"]},{"t":"风入松 苦暑戏与客语","f":"古风","c":["炎炎火镜正烧空，避暑苦无从。","客言安得匡庐瀑，还移取、华井秦松。","玉女盆边吸露，水仙祠畔餐风。","答言计总未为工，不若在军中。","平驱十万横磨剑，涛声怒、硬箭强弓。","恶浪千堆蹙黑，战旗一片摇红。"]},{"t":"风入松 纳凉","f":"古风","c":["当年结夏映层潭，脱帽卸轻衫。","柳丝斜飏阴篷捲，钓槛外、碧色微添。","桥背嫩凉瑟瑟，村头老树毵毵。","水天閒话对谁谈，城市我何堪。","采菱放鸭江乡伴，无人问、老子溪南。","浮世飞鸿雪爪，故山乱叶茅庵。"]},{"t":"风入松 寒鸦","f":"古风","c":["欹斜懒漫遍燕关，僵冷甚袁安。","谁将水墨濛濛画，做边城、一抹荒寒。","小日曾藏柳叶，前身惯上钗鬟。","无端误点早朝班，髣髴认龙颜。","六宫怕有人争妒，带昭阳、日影飞还。","惆怅旧游何处，孤村流水之间。"]},{"t":"婆罗门引 题露筋祠","f":"古风","c":["露筋祠下，寒篷淼淼去何之。","停桡一问灵旗。","怊怅千年古庙，陈迹几人悲。","只风前燕子，雨后棠梨。","俯仰歔欷，凭吊处，更怜谁。","惟有淮阴漂母，一样蛾眉。","估船争泊，问何人、拂藓一题诗。","依稀见、玉佩珠衣。"]},{"t":"婆罗门引 香橼","f":"古风","c":["晚风千颗，累累才与画檐平。","绽来刚趁秋晴。","怪底匀圆如许，青女手搓成。","乍回廊小摘，冷韵旋生。","冰瓷翠罂，压叠在、小红檠。","弄影夕阳黄处，檀晕偏明。","空香如雨，最宜人、昨夜恰微酲。","何须数、西崦霜橙。"]},{"t":"荔枝香 早春校香严词竟寄孙无言于扬州","f":"古风","c":["雨后春梅初浣，开箧衍。","试取红杏尚书，小令闲编纂。","几番拍遍新词，绝调千秋罕。","翻惹簌簌，轻尘画梁满。","书写竟，正江上、楚山晚。","鸭绿粼粼，笑倩双鱼寄远。","到及广陵，明月桥头夜箫暖。","早付竹西歌管。"]},{"t":"拍阑干 过蝶庵书事","f":"古风","c":["沈吟槛外，分明有个人儿在。","隔著软帘闻细欬。","转过屏间，做就生疏态。","夜来曾否春酲害。","底事无言，只撚箜篌带。","晓寒佯脱红绵耐。","检出香词，细觅檀奴解。","嗔人暗把风情卖。","嚼烂花笺，碎向粉墙抛洒。"]},{"t":"祝英台近 元夕后一日同雪持京少饮云臣斋头","f":"古风","c":["软帘垂，孤馆悄，灯烬穗还亸。","才过元宵，便有嫩阴做。","幸值俊侣嬉春，狂朋选夜，摒挡得、心情较妥。","斟红糯。","醉后多恐尘寰，无计容留我。","小海传闻，种露桃千颗。","与君擪笛宫墙，扫花洞府，剪几阕、霓裳偷和。"]},{"t":"祝英台近 舟夜闻箫","f":"古风","c":["水烟昏，塘月午，欸乃乱更鼓。","飒沓空樯，浪急打枫树。","恰逢羁客停船，谁家楼上，忽飘堕、箫声一缕。","泪如雨。","对此万里清光，旧家在何处。","人世何声，更似此凄苦。","依稀记宿江州，芦汀蓼渚，有十万、夜猿齐语。"]},{"t":"祝英台近 题季柔木小影兼志别怀","f":"古风","c":["红韎韐，紫罗囊，小缚黄皮裤。","快马健儿，装急凭君作。","更闻历落崎嵚，交游然诺，依稀是、君家之布。","岁行暮。","可怜雪浪烟帆，来朝趁人渡。","呵手敲冰，为君一题句。","他年展轴哦诗，怀人顾影，好频寄、江东鱼素。"]},{"t":"祝英台近 糊窗","f":"古风","c":["砑光笺，白地锦，糊就几楞雪。","玉净珠融，不怕冱寒冽。","亏他贮旭娱冬，留香伴夜，惹月练、和烟萦缬。","寸心折。","那得蜂咂莺穿，漏个针尖缺。","归梦徜徉，免被琐窗截。","翻思故国茅檐，残缸拥背，听败纸、战乾风叶。"]},{"t":"祝英台近 春游偶憩静山禅院","f":"古风","c":["隔溪村，临水店，行处误偏好。","趁寺寻钟，钟响冷于瀑。","粉梅才绽些儿，被谁烘坼，算晴色、朝来逾峭。","乱帆杳。","一半消入烟中，空潭剧幽窅。","小憩经房，无言只微笑。","此时正定吟魂，浦禽多事，又踏折、一枝烟筱。"]},{"t":"祝英台近 维摩天女恰同参为阎牛叟赋","f":"古风","c":["水精帘，翡翠锁，不许俗尘涴。","绣罢鸯摩，窗畔茜绒唾。","分明檐卜林香，楞伽寺静，只多了、阿奴旁坐。","归去可。","好趁水月潮音，早上雪山座。","怪煞萧郎，弹指景光错。","请伊试看人间，闲花浪朵，总一霎、笛声吹破。"]},{"t":"祝英台近 送陆云士之任郏县","f":"古风","c":["雁头筝，龙尾拨，曾记殢侬处。","转眼画旗，袅袅引君去。","遥知小陆风流，来春县里，种紫艳、红香无数。","郏县路。","淼淼晚渡秋山，我昔作行旅。","一发中原，风起浊河怒。","君经洛水平桥，陆浑小店，定和我、藓墙题句。"]},{"t":"祝英台近 杞梁妻祠下作 在齐河县长城铺","f":"古风","c":["画旗飘，灵幄捲，彩翠剥如雨。","玉貌明妆，隐隐怨蛾聚。","可怜枳壳花开，凝丹点绛，尽千载、啼斑偷注。","黯凝伫。","满壁水墨全昏，犹把断肠谱。","绣帔尼师，指点向廊柱。","怪他哭后长城，崩馀粉堞，忒画得、周遭如许。"]},{"t":"四园竹 题西陵陆荩思绕屋梅花图像","f":"古风","c":["西陵高士，小隐段桥东。","十年酒圣，半世诗颠，千古文雄。","铜将军，麴道士，楮先生，者三君、踪迹时同。","屋如蜂。","屋头无数冷香，篱门都浸其中。","镇日和烟和雨，点点欹斜，片片朦胧。","杯在手，长侧帽，林间一笛风。"]},{"t":"四园竹 龚节孙卧疾东郊秋日过访用片玉词韵","f":"古风","c":["山光水态，浓淡上烟扉。","菊摇暗壁，蛩语坏廊，人卧萧帏。","停碧箫，歇翠斝，檀奴懒，况小窗、风月应知。","漫凄其。","床头尚有龙泉，从君且订交期。","戏作药名艳体，闲检方书，写上香辞。","临欲去，日影矬，茶烟飏渐稀。"]},{"t":"扑蝴蝶 咏蝶","f":"古风","c":["一生踪迹，总在花深处。","几番消受，小院红楼午。","黏来珠幌如痴，落上绣裙成雨。","有人记，曾暗结同心苣。","如今重到，依稀不认他门户。","满园野菜，领游蜂三五。","惹残流水难凭，舞遍微风莫主。","赚人一天花絮。"]},{"t":"侧犯 奚苏岭先生书来讯我近况词以奉柬","f":"古风","c":["罢官不乐，画帘暮卷空江雨。","无绪。","忆罨画溪头有人住。","阶前濯莽合，屋后虬梅古。","传语。","问彊饭、还能著书否。","使君足下，别后难行路。","嗟带甲满乾坤，只有儒生误。","昨已废书，行将学贾。","市上屠牛，山中射虎。"]},{"t":"侧犯 百花洲访南水上人","f":"古风","c":["闲寻茂苑，摘船碾遍琉璃滑。","明灭。","望半亩精庐隐林樾。","空香黏茗粥，野翠连巾拂。","幽绝。","想夜夜、经台浸秋月。","吴宫似梦，往事和谁说。","旧时节。","记盈盈、水面莲歌彻。","几阵西风，繁华吹歇。","满江红蓼，一园黄蝶。"]},{"t":"送入我门来 同龚仲震小饮高汝敬红梅花下 高系忠宪公孙所居即忠宪祠","f":"古风","c":["松漱微波，山铺暝翠，软风吹得帆斜。","柴门将掩，步屧诣君家。","灵均祠畔多香草，总变做孤山树树花。","小缕红糟鸡蹠，选花阴碧磴，弄酒拈茶。","况有良朋，凭醉作生涯。","明朝摇橹入城去，约仍过山窗听暮鸦。"]},{"t":"一丛花 咏白丁香同远公天石和原白韵","f":"古风","c":["一枝低亚晚妆台，吸露沁兰胎。","李花柳絮都难似，染梨云、一色新裁。","白粉墙边，水明楼上，动窃玉情怀。","累累银粟费安排，争趁月中开。","曾经打就心头结，相看处、脉脉疑猜。","记得重门，和他小摘，此事十年来。"]},{"t":"一丛花 杨梅","f":"古风","c":["江城初泊洞庭船，颗颗贩匀圆。","朱樱素柰都相逊，家乡在、消夏湾前。","两崦蒙茸，半湖幂䍥，笼重一帆偏。","买来恰趁晚凉天，冰井小亭轩。","妆馀浴罢春纤湿，粉裙上、几点红鲜。","莫是明朝，有人低问，羞晕转嫣然。"]},{"t":"一丛花 闰三月三日竹逸斋头看紫牡丹记前月修禊虞山故前半阕及之","f":"古风","c":["琴川前月记幽探，艇子漾柔蓝。","冶游恰值人修禊，风光在、碧嶂红潭。","街上饧箫，山边荠菜，春色上春衫。","今朝魏紫放晴檐，丽景十分添。","一年最好惟三月，谁频见、两度重三。","花好逢王，春浓遇闰，乐事艳江南。"]},{"t":"玉女度千秋 寿吴母任孺人","f":"古风","c":["八十称觞，齐仰裙笄尊宿。","如云子姓，捧钿车历碌。","春晖萦寸草，巨室森乔木。","思往事，青陵台上歌黄鹄。","歌罢灯寒，母绩还催儿读。","儿已成名，孙又饶兰玉。","真妃来洞府，天姥斟醽醁。","愿百岁，湔裙常趁晴波绿。"]},{"t":"过涧歇 暨阳秋城晚眺","f":"古风","c":["坏堞颓关暮烟积。","悄乎无人，祇闻江声千尺。","混茫极。","恍见水仙海妾，采月金鳌脊。","吾长啸泉底，恐惊织绡客。","春申遗垒在，古戍吹笳，乱洲伐荻。","碎把阑干拍。","沙草无情，不管兴亡，朝朝暮暮，西风只送巴船笛。"]},{"t":"过涧歇","f":"古风","c":["夹岸斜桥界山侧。","邪延陌阡，人家柴门俱仄。","翠螺织。","奇者狮蹲象跛，欲起还愁踣。","崖门破，总被老苔寿藤蚀。","居民燃楚竹，散诞陶渔，岩栖涧食。","带雨闲抟埴。","陶侃甓前，毕卓瓮头，窑烟四起，阵云一朵压城黑。"]},{"t":"侧犯 真娘墓和扶荔词韵","f":"古风","c":["碧阑干外，小坟一点衰桃黦。","凄咽。","剩綵袂、飞灰化蝴蝶。","灵旗飘复偃，社火明还灭。","芳骨约西子，吴天诉潭月。","三生事，五更风，阵阵饧箫歇。","耳边怯。","怕枝头、又到啼红鴂。","昨夜听歌，石场如雪。","夜台犹卸，玉簪偷节。"]},{"t":"红林檎近 人日雪中作","f":"古风","c":["千斛玉尘暗，万家冰馆开。","海素障窗槅，赩霜冻妆台。","扶将银人上胜，染取白燕摇钗。","献岁七日刚才，偏砌就瑶街。","阻绝挑菜侣，愁极踏青鞋。","何时出郭，春晴好散春怀。","待传柑过了，卖饧节近，湔裙准傍溪水涯。"]},{"t":"红林檎近 大鸿有西河之戚作此代唁 大鸿次子无逸没于岭南幕中","f":"古风","c":["黄蛤沈香浦，绿犀惶恐滩。","山郡荔枝叶，驿楼鹧鸪斑。","郁孤台高一去，琼岛水阔难还。","金齿细屐花间，茜雪洒红蛮。","黎女双袖泪，梅峤百重关。","槟榔椰子，枉劳赠自珠官。","怅花田草满，海天月出，小笼失却金尾鹇。"]},{"t":"小镇西 臬署夜坐，听前庭演剧，似是邯郸巡河一出。追忆东皋旧事，感赋此词","f":"古风","c":["小飏夜笛风，碎珠十斛。","歌丝袅、槛花轻簌。","此何曲。","翠阴阴、寻去如尘，想处疑烟，一庭幽瀑，满场哀玉。","逗纱曲。","渐循声细认，是邯郸曲。","年时景、暗中潜触。","瘦蛾蹙。","怅零箫剩管，耳边又续。","算来人世，偏有黄粱难熟。"]},{"t":"皂罗特髻 憩庆云庵方丈后小轩","f":"古风","c":["山风几斛，吹万笏晴螺，寺前堆积。","阴阴竹院，与尘寰都隔。","斜川外、几姓渔蛮，携绿箬、醉卧菱湖栅。","雨添湿翠，怕晚来偏剧。","小啜僧寮茗粥，助玉川茶癖。","禅榻后、三间茅阁，恰面对、九龙峰脊。","推窗惊叫，怪龙鳞都裂。"]},{"t":"有有令 咏画眉鸟","f":"古风","c":["风柔日媚。","一盏小金笼，绣帘深处坠。","红苣同心结，紧绾在、东风里。","最愁他、点径蜻蜓，衔泥燕子，往来容易。","娇影闲临渌水。","倩小玉、摘相思子。","好把猧儿打去，休搅春宵睡。","隔花悄唤名字。","远山卓氏，错认做、画眉郎至。"]},{"t":"最高楼 登原白斋中露台","f":"古风","c":["阑干外，淼淼暮云平，叠叠乱峰生。","六街灯火烟中没，万家帘幕雪中晴。","好楼居，吟不就，画难成。","弄一会、桓伊天际笛，蜡一会、嵇康林下屐，怜故国，笑浮名。","兴酣便拟骖鸾去，酒狂乍可御风行。","俯尘寰，青一点，月三更。"]},{"t":"蓦山溪 东溪雨中修禊","f":"古风","c":["蜗庐蚁国，不醉公何补。","脱帽放狂歌，自古说、英雄无主。","携朋命酒，船泊画溪东，挑荠菜，焙新茶，饱看浪花舞。","小村背郭，蘸绿杨千缕。","春事渐飘零，总付与、数声柔橹。","今朝天气，何必定鲜新，三月雨，一湖风，翻样兰亭谱。"]},{"t":"蓦山溪 惠山泉亭看月","f":"古风","c":["乱崖杏嶂，肯放篮舆倦。","呜咽夜泉吟，石栏边、冷云铺满。","携将一卷，陆羽斗茶经，煎雪乳，碾龙团，帻向松风岸。","碧天叫雁，街鼓三更断。","矫首盼冰轮，心已共、辘轳争转。","今宵桂影，休堕织绡宫，人更悄，夜无声，恐惹鱼龙怨。"]},{"t":"蓦山溪 禊日感旧 悼远公也","f":"古风","c":["去年上巳，正值春阴候。","千古艳兰亭，况岁是、重逢癸丑。","濛濛烟艇，小泊画溪东，林花溜，溪花皱，雨湿春衫袖。","今年上巳，满眼花如绣。","又到去年春，只少个、人儿携手。","虽然无雨，难道是晴天，淋漓久，非关酒，依旧春衫透。"]},{"t":"蓦山溪 虎邱送春夜同顾伊人天石留宿山中次伊人韵","f":"古风","c":["风涛掀舞，鞺鞳何曾住。","曛黑断人行，便箬帽、棕鞋难去。","堂堂春尽，含泪唱淋铃，莺花数，长亭路，注定今宵雨。","夜方踰午，投宿支公宇。","禅榻不成眠，听墙外、晓钟将度。","飘红坠粉，何限寺门情，挑灯句，凭阑语，各有关心处。"]},{"t":"蓦山溪 南涧山房作","f":"古风","c":["朱扉碧槛，垒石支墙罅。","曾记锁东风，谁轻到、小帘栊下。","如今世换，松鬣枉拿云，人去久，小楼空，园里梅俱嫁。","支颐太息，此意谁知者。","眼底足悲欢，休骋望、秦台汉瓦。","梅风醒梦，何必诉兴衰，闲酌酒，细捶琴，自把高怀写。"]},{"t":"新荷叶 本意","f":"古风","c":["绿缬成帷，江妃纤手初纫。","叠遍钱钱，较花饶有清芬。","莲舟出浦，水云宽、碧到无痕。","娇擎翠盖，彩鸳稳护腰身。","风起青蘋，才低旋举缤纷。","戏洒泉珠，侧盘泻玉倾银。","摘时须早，怕秋来、最不宜人。","后湖衰柳，同他一样消魂。"]},{"t":"新荷叶 新霁郊外纪游","f":"古风","c":["日丽风柔，水边天气鲜新。","闲坐斜桥，数完几折溪痕。","酒旗戏鼓，怯馀寒、未满前村。","小红乍乳，莺声一巷才匀。","节过收灯，风光尚未逾旬。","粉糁疏篱，谁家香玉粼粼。","雏晴嫩霁，似垂髫、好女盈盈。","江南烟景，殢人尤在初春。"]},{"t":"新荷叶 踰天长郭门里许，修堤被渚，高榆荫街，隔水一亭，曰放生池。芰荷沙鸟，颇极幽映，歇马徘徊，赋词寄兴","f":"古风","c":["席帽炎途，长征事与心违。","歇马溪桥，拍波水鸟斜飞。","林皋幽邈，凉如雨、乱点人衣。","曲潭脩坂，新荷短芰成围。","白板双扉，茶烟轻飏渔矶。","小店雏莺，江南景未全非。","被他重唤，扬州梦、往事依稀。","蜀冈凝黛，迢迢送我难归。"]},{"t":"柳腰轻 赠妓和柳屯田韵","f":"古风","c":["白家蛮柳丝丝软，织不尽，莺和燕。","酿雪轻阴，填词狎宴。","况遇曲中高选。","泥金襻、蘸雨逾鲜，墨花襦、无风犹颤。","谁耐钿筝衮遍，小立在、红桥窄板。","文鸯薄倖，青娥憔悴，鹊信沈吟都变。","偏今夜、不肯留侬，听门前、暮鸦啼断。"]},{"t":"千秋岁引 寿蘧庵先生七十","f":"古风","c":["松作龙形，枣如瓜大。","游戏神通复何碍。","当初摇鞭过韦杜，而今泛宅来吴会。","凤凰池，麒麟阁，抽身快。","且喜墨离山泼黛，且喜元宵灯尚赛。","万事难消风月债。","茶铛沸来同字煮，酒旗挑处和愁卖。","四时花，三弄笛，身长在。"]},{"t":"拂霓裳 冬夜观剧","f":"古风","c":["酿寒天，六街皓月荡成烟。","腰鼓闹，腾腾雨点打来圆。","银灯笼暮霭，铁拨迸秋泉。","映婵娟。","想后堂、笑语总群仙。","教坊绝艺，一队怀智龟年。","君不醉，风光孤负十分妍。","醉馀偏惹恨，归去不成眠。","忽凄然，怅桐花、一树翠帘前。"]},{"t":"爪茉莉 月夜渡扬子江","f":"古风","c":["淼淼江天，听中流笛响。","推篷看、一川凄爽。","六朝遗迹，问风景、几曾无恙。","只隔岸、建业城边，有商女，深夜唱。","一轮团月，与船头、正相向。","越显出、万层银浪。","十年作客，算将来、祇悲怆。","且渡江、溷迹骑奴厮养。","学贩畚，兼鬻酱。"]},{"t":"爪茉莉 茉莉","f":"古风","c":["暑院追凉，忆炎荒轶事。","蛮娘圃、琼天粉地。","任他开落，极望与、篱花相似。","更带暝、纫雪成团，沿坊叫，喧夜市。","赣州船下，到吴天、伴罗绮。","相宠爱、夜堂空翠。","而今离散，判分携、几千里。","料幽花、也怨月明如水。","海天冷，那易睡。"]},{"t":"满路花 荷珠","f":"古风","c":["红绡水面妆，碧玉波间柄。","低迷扶翠盖，西风劲。","玉人摇橹，隔浦莲歌竞。","花面交相映。","戏取春纤，掬他潭水芳冷。","洒来错落，尽向钱钱迸。","鲛珠圆又碎，难持赠。","低鬟凝想，总似檀郎性。","荡漾何时定。","惆怅回船，碧天早挂明镜。"]},{"t":"满路花 赠梵公 师住云门，工书画。时以选诗来荆溪","f":"古风","c":["荷钱贴野塘，竹粉黏晴砌。","师从何处到，云门寺。","零笺烂本，点笔聊轩轾。","试将小语戏。","高岑王孟，关卿定复何事。","平山堂下，鸿爪依稀记。","北邙王与宋，曾同醉。","重逢瓶拂，顿下山阳泪。","更欲游何地。","他时念我，巨然小幅须寄。"]},{"t":"满路花 咏禹门寺前一带颓崖峭石","f":"古风","c":["嵌空撑户牖，凿翠支堂奥。","淙淙岩溜响，喧银瀑。","硗确谽谺，铁色黏青峤。","石笋攒丹灶。","积雪层冰，玲珑原隰俱缟。","或为怪鹘，或作千年豹。","或似秋江岸，晴龟曝。","林青日黑，山畔归樵少。","野火连天烧。","虎腥如雨，瘦石此时更峭。"]},{"t":"洞仙歌 偶过岵云上人兰若见其庭下红梅盛开漫咏","f":"古风","c":["伤春病酒，日三竿贪睡。","睡起闲行巷南寺。","老僧烹活火，碾罢龙团，七椀后，门外烂柯谁记。","蓦看花朵上，頩脸微烘，似带三分午前醉。","索笑漫沈吟，莫是东邻，茜钗上、火珠初施。","只认做空门本无愁，又谁信枝枝，尽弹红泪。"]},{"t":"洞仙歌 善权洞","f":"古风","c":["天风忽下，劈破青红茧。","夸父愚公费裁剪。","看千螺倒矗，万笏斜垂，铺碧藓，一屋闲云自键。","玲珑光上下，一串银房，偏借虚空累层甗。","洞底洞还生，下有泉鸣，声声乱、云中鸡犬。","只石怕春寒悄无人，却走入墙阴，化成雷篆。"]},{"t":"洞仙歌 澹心园次梁汾问波灵本偶集寄畅园听小奚度曲坐有话水榭姬人近事者因并及","f":"古风","c":["嫩晴天气，坐水明楼畔。","三叠泉声诉幽怨。","霎然间、山半冷翠飞来，君莫去，且棹银船消遣。","玉鳞微动处，红绶双衔，隐隐歌丝逗帘幔。","半阕小秦王，入破方才，珠千颗、撒来成串。","又谁话当年杜秋娘，觉雁柱添愁，声声都换。"]},{"t":"洞仙歌 西瓜","f":"古风","c":["嫩瓤凉瓠，正红冰凝结。","绀唾霞膏斗芳洁。","傍银床、牵动百尺寒泉，缥色映，恍助玉壶寒彻。","夜深呼碧玉，同倚阑干，月色荷香两清绝。","笑问破瓜无，此夜琼浆，须怜取、寸心长热。","见手揽金刀细沈吟，悄不觉红潮，早堆肌雪。"]},{"t":"洞仙歌 从楞伽上方塔后觅径下坡过前村观剧","f":"古风","c":["晴峰乱矗，似丛丛春笋。","贴向吴天翠无尽。","映澄湖、几幅纯绿柔蓝，纷织处，烟际渔榔隐隐。","断崖横塔后，扪葛攀萝，私路萦纡细如蚓。","村鼓正喧阗，赛火成围，雏伶唱、消魂院本。","讶蓦地飘飘绿杨丝，乍小露墙头，一群红粉。"]},{"t":"洞仙歌 题采芝图为顾卓侯赋","f":"古风","c":["苍皮黛鬣，滴金膏丹溜。","下结千龄赤芝秀。","有先生、杖挂长柄葫芦，篮子内，百本木华红绣。","㗳然云水兴，瓢笠随身，炼术餐霞老岩窦。","戏斸茯苓归，封寄轩辕，雷文篆、形如鸟兽。","笑多事商颜四先生，同溺过儒冠，一般皓首。"]},{"t":"洞仙歌 途次曹县","f":"古风","c":["河流浩淼，去黏天无岸。","白草黄沙古曹县。","问居人、谁是僖负羁妻，谁惜我，十载蓬科未转。","一鞭官渡口，飒飒西风，落照昏鸦太零乱。","叹息旧繁华，往事还非，眢井畔、兔葵开遍。","访昔日东平故侯家，怅绣戟牙幢，一时都换。"]},{"t":"洞仙歌 上巳后五日游吴门观音山","f":"古风","c":["红船绿浪，雁翅排将遍。","早有香车俟春岸。","内家妆、谁要小凤帘垂，和弱柳，斗取腰身纤软。","麝裙飘碧磴，艳粉群群，尽倚晴峦谱幽怨。","脉脉祝空王，掷眼儿郎，愿岁岁、幡前长见。","又语悄风微怕莺知，早杏脸潮生，碎挼花瓣。"]},{"t":"洞仙歌 龙理侯纳姬秦淮词以赠之","f":"古风","c":["银床滑簟，碧阴阴秋水。","昨夜簪头喜蛛缒。","算青溪、红板艳粉浓蛾，娘尤小，第一南朝殊丽。","江潮轻打桨，船近枞阳，恰恰乔公旧乡里。","匿笑语檀奴，斗帐樱桃，祝蜥蜴、早添怀里。","也不枉人间唤乘龙，看紫贝霞绡，海天无二。"]},{"t":"洞仙歌 题乔石林舍人桃源图小照","f":"古风","c":["漫郎单舸，压半溪寒玉。","流向秦人洞边宿。","渐前村、竹外一两三枝，斜幂䍥，流水板桥茅屋。","忽然奇绝处，极望花枝，尽亚东风骋肌肉。","万树滴胭脂，下映平坡，都不许、蘼芜成绿。","也莫问花红种田人，只鸡犬桑麻，迥离尘俗。"]},{"t":"洞仙歌 證前生为阎牛叟赋 牛叟兑阁遗徽曰，予生于闽，故生平癖嗜，尤在枫亭荔枝。妻屡办装，助予入闽啖荔，以远道，逡巡未果也","f":"古风","c":["海山奇处，缀晶丸千颗。","老客炎乡尽还可。","恍瑶京、仙子绛縠中单，西风起，一笑回身欲堕。","前因图再访，为殢双栖，欲上烟樯未曾果。","弹指绣屏空，碧落离鸾，先已在、翠蓬山左。","拚不见今生荔枝香，怕见了添思，玉人梳裹。"]},{"t":"洞仙歌 催妆词为宋念功赋 念功彭氏婿","f":"古风","c":["中朝枢府，矗红墙翠瓦。","年少郎君况淹雅。","看今宵、井络不见天彭，刚一笑，已向人间下嫁。","铜舆声渐近，百盏晶笼，映得天街不曾夜。","尚有好心情，栏角沈吟，故意看、西山娇冶。","也不是萧疏爱看山，要选个遥峰，小眉边画。"]},{"t":"洞仙歌 夏夜憺园隔水闻笛","f":"古风","c":["灯青凤胫，正参差齐点。","屈戍玲珑带愁掩。","恰濛濛、天水浸赤阑桥，人不寐，梦到空园偏魇。","笛声何处响，乍有还无，似在荷深那边槛。","隔水倍清苍，竹脆弦轻，更潭子、鸭头新染。","才摹得风前不多声，又撺入伊州，小秦王犯。"]},{"t":"洞仙歌 戊申上元阴雨示桢百云臣青际","f":"古风","c":["春阴春雨，把碧天偷换。","赢得情思冻云懒。","料高楼、小市火树银花，都不见，有也无人寻玩。","狂朋应似我，手撚玉梅，低叹心头旧愁满。","早瞢腾孤睡，笑逐钿车，人影乱、拾得遗钗一半。","更灯灺鸡鸣梦回来，空斜压衾窝，孜孜细看。"]},{"t":"黄鹤引 咏半茧园双鹤","f":"古风","c":["榴红乍吐，下有胎仙暗来去。","翛然映水梳翎，琴心对舞。","珠衣雪举，凝想水天深处。","蓬山洞府，曾记得清凉无暑。","一自谪尘凡，几遍伤羁旅。","幸逢水冽泉香，此身有主。","莺啼燕乳，啄破绮窗花午。","人间愁苦，轻别了、吹笙俦侣。"]},{"t":"蕙兰芳引 咏兰","f":"古风","c":["溪店寺桥，映一带、铜峰蛾簇。","有黛叶离披，露萼烟条齐矗。","参差鹿柴，日给与、幽芬千斛。","似佳人绝代，零落今依草木。","数朵微含，一枝乍秀，淡淡如菊。","笑秾李夭桃，祇解寻常妆束。","无言一笑，嫣然空谷。","想采时、无数裙腰都绿。"]},{"t":"簇水 见古寺放生马而叹之","f":"古风","c":["回忆当年，霜蹄刷尽幽并夜。","草头一点，猛气削驽骀凡马。","羸病谁欤牧养，羁靮从宽假。","摩背痒、秋阴墙罅。","血泪洒。","叹日暮、群乌啄肉，伏栈枥、成悲咤。","西风夜响，重叙起沙场话。","俛首沈吟烙印，蓦听僧钟打。","馀生也、托象王台下。"]},{"t":"簇水 舟过梁溪不及泊舟遥望龙峰有作","f":"古风","c":["百幅晴漪，渔舟个个能轻妙。","几村红树，将郭外人家萦抱。","历历苇花明处，是水仙之庙。","正蘸上、一缕残照。","隔水峤。","喜几日、金风弄霁，做晚翠、十分峭。","蒲帆似鸟，翅竞向秋空矫。","姑待伍塘游倦，重与停吟棹。","茶铛沸、错认山园瀑。"]},{"t":"华胥引 咏走马灯","f":"古风","c":["烟中铠仗，影里弓刀，往来似织。","一片空明，夹纱水墨描蜹翼。","笑问何代兵争，更何朝方国。","滚遍街楼，有人喧笑帘隙。","些子光阴，恰一般、星驰飙激。","寸人豆马，依然幡幢戛击。","料想灰飞烛烬，战场方息。","顷刻收灯，红毬闷靠墙壁。"]},{"t":"促拍满路花 秋日同南耕衣白鲁望弟偶憩城南放生池","f":"古风","c":["峥泓寂历甚，杳霭有无间。","城南多古寺，得秋闲。","风廊石濑，竹筱更檀栾。","游鳞翻碧浪，雪鬣银鬐，此中大可投竿。","仗西风、寄语南山，窈窕好烟鬟。","如何偏不厌，老僧看。","南山覆我，君自喜尘寰。","倘肯经过密，秀黛三升，日应给与君餐。"]},{"t":"鹤冲天 题邹生巽含小像 像坐万山梅花中一童子煮茶于侧","f":"古风","c":["寒崖绿染，石窦低于甔。","极目总萧林，堆苍艳。","更梅花作海，绽香雪、飘千点。","幽人巾自垫。","趺坐苔阴，杳霭水明山店。","瑶翻碧滟，涧底泉澄湛。","童子泼茶光，连幽簟。","翠花瓷注茗，花沸乳、珠成绀。","风情何澹澹。","乍展吴绫，回味略如橄榄。"]},{"t":"鹤冲天 题钱葆馚莼䰻小像次原韵","f":"古风","c":["吾乡画渚，有个英雄处。","长想射蛟人，空吟句。","如君饶意气，偏不屑、尘埃住。","沿溪寻钓侣。","罾晒江村，一色压银欺苧。","君年未暮，讵逐鸱夷去。","宵半跃赪盘，沧波煮。","踞船头弄笛，快劈作、阑江雨。","凉飙添几许。","响入鲛宫，吹乱织绡机绪。"]},{"t":"八六子 枫隐寺感旧","f":"古风","c":["弄丝杨。","重过废馆，闲池顿起思量。","正髣髴纸鸢旧处，依稀竹马儿时，巡檐绕墙。","当年无限风光。","月照千山裙幄，莺啼一院糟床。","渐舞榭成坟，歌台作寺，松雏已老，梅妻都嫁，祇剩乱涧，闲腾鼯鼬，矮坡斜下牛羊。","太苍茫、疏林一抔夕阳。"]},{"t":"劝金船 茶花","f":"古风","c":["绿纱窗底幽姿喷，亸白花盈寸。","玉娥小剪明罗晕，递顾渚佳信。","檀心暗蹙，悄向胆瓶安顿。","最喜妆楼小撚，偏解春困。","茶娘家与春山近，雨过香成阵。","不知名处花尤俊，好傍人蝉鬓。","懊恼滇茶，长把红芳相混。","谁似伊行素雅，并没脂粉。"]},{"t":"惜红衣 苦热兼怀村居水木之胜","f":"古风","c":["闷欲凭虚，狂思拔宅，人间何窄。","朵朵奇云，殷红荡深黑。","溪西故隐，三万顷、湖天一色。","犹忆。","菱角莲须，满塘西舍北。","萧萧陂泽，旧日渔船，桥边甚人摘。","年来闹市，永隔水云国。","安得阳乌敛绛，早唤夜蟾堆碧。","更试攀华顶，剪取古尧时雪。"]},{"t":"石湖仙 题放庵上人红豆词卷","f":"古风","c":["春愁天样，将红豆词吟，愁归天上。","红板桥西帘飏，最关情处，绿窗有人争唱。","吟红叫紫，尽舞絮、沾泥无恙。","梅放。","把一樽、檐际相赏。","南朝许多烟景，被啼莺、梳乾柳浪。","千古兴亡，只抵斜阳片晌。","且趁疏狂，朝眠碧嶂，暮敲乌榜。","闲骋望，一生著屐几两。"]},{"t":"鱼游春水 万红友书来，云适金沙，周东会暨叙彝上人在舍，可过郭外，同看水色。余以他事未赴，作此柬之","f":"古风","c":["君家春矶嘴，一点炊烟芦荻里。","渚花飞处，绿到河边楼子。","细雨卖鱼声掠村，斜日焙茗人归市。","㗳尔捶琴，兀然隐几。","报道今朝闲未。","好向晴川弄芳芷。","况来高士羊裘，名僧麈尾。","那知有约长孤负，自分无缘供驱使。","茫茫此愁，略如溪水。"]},{"t":"鱼游春水 咏金鱼","f":"古风","c":["飞红盈盈起，跌下铜沟深半指。","一湖茜乳，染就鲤鱼猩尾。","浅贮空明翡翠瓶，小唼瀺灂桃花水。","蹙锦裁斑，将霞漾绮。","妆阁临流徙倚。","笑语纷纷垂杨涘。","来往破藻穿蘋，披兰拂芷。","似分醉靥素鳞上，误唾红绒银塘里。","微风差差，绿波瀰瀰。"]},{"t":"雪狮儿 新正五日雨窗柬云臣用程正伯韵","f":"古风","c":["兰啼未醒，梅妆易困，愁褰帘幕。","曾记年时，春向玉钗头落。","浅斟低谑，正斜凭、香肩瘦削。","红篝暖，任他小院，猧儿吠恶。","今岁雨梳风掠。","更寒胶钿盒，尘封筝索。","欲坏上元，胜里春人早觉。","脂慵粉弱。","此意倩、东皇怜著。","笺恳托。","须把层阴浣却。"]},{"t":"愁春未醒 春晓","f":"古风","c":["莺窥燕垒，蝶上犀钉。","绡帐萦香雪，夜珠和泪尚荧荧。","梳洗谁忺，懒扶残梦倚围屏。","依稀记得，宵来微雨，曾撼金铃。","绿水全昏，红闺半掩，春困难醒。","风弄处、釭花半朵，小似晨星。","理梦窗前，生憎鹦鹉隔帘听。","画楼深巷，卖花声到，才响还停。"]},{"t":"愁春未醒 元夕后三日饮曹荩臣宅适遇微雪","f":"古风","c":["落灯风定，舞絮天成。","听沙沙杂杂，檐声滴乱酒床声。","闻说南山，小队轻裘竞射生。","吾侪无事，且扶老懒，共博春酲。","起望尊前，林皋顿皓，轩槛将盈。","恰萧然、四垂阴重，六出花轻。","多少征人，琵琶风雪醉龙庭。","问他何似，疏狂老子，诗酒埋名。"]},{"t":"愁春未醒 竹逸招同云臣、南耕雨中看梅，余舟中既作离亭燕一词纪事，归见云臣、南耕、竹逸词，复次韵一首","f":"古风","c":["蝶魂欲栩，莺哢犹含。","尚是浅春候，未容红紫十分酣。","却喜君家，玉娥笑倚两三三。","判携侧帽，径乘短屐，来过街南。","满院横斜，一池清浅，正压雕檐。","尽消受、一生花癖，半世吟馋。","祇惜溪干，画桡斜阁面烟岚。","花知欲别，暗弹粉泪，故泥征衫。"]},{"t":"谢池春慢 乙卯三月三日作","f":"古风","c":["烘桃染杏，春到愁、思量处。","弱蕙试新荑，嫩蝶翻绵羽。","林际莺才满，梁畔燕将乳。","飏歌旗，喧戏鼓。","三三两两，挑荠谁家女。","鸭头搓足，匀遍了、城南浦。","半引前溪影，碧上垂杨缕。","半取烟汀色，绿蘸盈樽醑。","斟一斗，思千古。","兰亭洛水，淼淼波流去。"]},{"t":"鹊踏花翻 花朝行玉峰道中用蝶庵词韵","f":"古风","c":["柔浪如酥，遥峰欲笑，樯乌阵阵迎人话。","说道今日花朝，此去包山，歌台砌满苔钱罅。","玉箫金管劝东风，嫣红艳紫须迟卸。","频讶。","往事酒边灯下。","铜扉记隔秋千榭。","每到丁字帘前，群芳生日，昵语何曾罢。","如今好个奈何天，一船花月春江夜。"]},{"t":"鹊踏花翻 健儿吹笛","f":"古风","c":["十上燉煌，三过代郡，翩翩绣袷黄金勒。","曾在仆射营门，塞女如花，偷谱李谟银雁笛。","长城夜月一轮孤，沙场战马千群黑。","今日。","鬓点霜花谁识。","故国何年归始得。","几遍闲寻旧曲，才当入破，又犯龟兹急。","合阳城外遇乡人，一声红豆春衫湿。"]},{"t":"宣清 或以鹅炙啖我饱而填词","f":"古风","c":["亦食糠覈耳，只屠门大嚼，差强人意。","笑当年哇说于陵，问何人嗜同刘毅。","东郭长贫，左车渐脱，仰天直视。","秋社日，恰分将，红掌鹅群净美。","据案爬搔，临餐跳跃，餔歠真佳计。","似海客刳龙，壮夫斫彘，飘飘淩云之气。","放箸盘空，借君家、笼中闲戏。"]},{"t":"薄媚摘遍 偶感","f":"古风","c":["旧家门，闲院落，有个人儿在。","最伶俜，偏鬌，浓蛾秀鬋无赖。","轻红架底，青粉墙边，一树睡香开。","玉鸦叉，打来斜戴。","晚风大，低飏茜花裙带，小做恹恹态。","疑有恨，不胜娇，和烟早簇上眉黛。","一丸凉玉，挂向帘钩，逋发未全撩，记得濒行，送人栏外。"]},{"t":"凄凉犯 哭云间友人金蓬山和钱莼䰻韵","f":"古风","c":["秦淮水阁微茫景，回船使酒如昨。","笛床茗椀，烟帆雨幔，麝盟粉约。","江涛喷薄。","短咏长吟间作。","戏呼余、长鬣者，烛下恣嘲谑。","重过酒垆，纵歌谱犹存，翠凋珠铄。","玉京伴侣，似人间、也愁离索。","促返蓬山，果然去、骖鸾跨鹤。","砑香笺，漫写沈吟怎睡著。"]},{"t":"凄凉犯 寒柝","f":"古风","c":["一星星火红犹在，更阑空馆才觉。","甚地勾栏，那条京瓦，喑呜腷脯。","墙根市角。","风递到、一城郭索。","终不然、啼蛄吊月，或是夜丝络。","此际无衣子，冷巷闲坊，睡何曾著。","敲时和梦，似徐抛、零星珠雹。","陡触霜威，愁杀是、此身寒薄。","砉崩腾，柝声四起山月落。"]},{"t":"雪狮儿 本意","f":"古风","c":["雕霜捏粉，作西域、万里狻猊，攫拿爪踞。","侧脑平芜，猛气骁腾何怒。","奔犀骇虎。","更何论、田间狡兔。","似鲍老、装成假面，筵前决赌。","道上儿童戏汝。","算冰澌雪尽，愁伊无据。","恰遇狮王，微笑掷花而语。","明驼洛下，费几许、铜山才铸。","今何处。","一样荒烟细雨。"]},{"t":"雪狮儿","f":"古风","c":["大句胪唱，问几日、林邑船来，九宾列俎。","异兽来庭，不羡雕题碧砮。","轩然爪距。","色洒上铜盘仙露。","綵仗内、闹装蛮带，形模似否。","却笑偏陬蕞土。","记孙郎旧日，小名同汝。","蠢尔黄奴，讵识真龙有主。","铜绦难掣，轵道上、降王婴组。","尧阶舞。","赭幄曈昽日午。"]},{"t":"辘轳金井 咏闺人汲水浣花","f":"古风","c":["落灯风定，粉墙东、梅英一点红小。","景物融和，爱春光恁好。","鹦哥哢巧。","唤帘内、浣花须早。","况有阶前，东风露井，一泓清晓。","行来碎珠自舀。","倚银床百尺，轻漾素绠，却讶琅然，触铜瓶声悄。","多年玉导。","看依旧、凤蟠龙扰。","手抚遗钗，裙扶花影，归房微笑。"]},{"t":"塞翁吟 秋日过竹枝庵访灵机上人不遇与寒松上人茗谈","f":"古风","c":["出郭秋光好，黄叶飒沓霜空。","筱径织，石泉通。","漱碎玉淙淙。","三生堂后名僧至，乘兴杖笠过从。","拟问取，寺门松。","可仍旧如龙。","桥东。","谁延伫，虎溪三笑，逢相识、庐山远公。","说晓起、秋山有信，趣昨夜、出岫闲云，仍返山中。","姑留软语，饱看禅窗，瘦槲枯枫。"]},{"t":"东风齐著力 田家","f":"古风","c":["绿水湾头，青山叠处，有个人家。","藤梢橘刺，秃干矗槎枒。","烂熳田庄风味，篱穿笋、砌吐鲜花。","谁相饷，隔墙浊酒，过雨新茶。","溪口路三叉。","门半掩、小桥流水栖鸦。","芋区鸡栅，零乱向风斜。","处处村箫社鼓，丛祠畔、丝管咿哑。","君休去，鲚鱼大上，园韭才芽。"]},{"t":"满江红 题尤悔庵小影次韵二首 其一","f":"古风","c":["快马健儿，记当日、先生自许。","谁信道、骅骝一蹶，长鸣忆主。","凄切新词杨柳月，悲凉杂剧梧桐雨。","更北平、回首暮云低，呼鹰处。","朝共市，难容与。","山共水，聊延伫。","且岑牟单绞，搔头箕踞。","千石硬弓千日酒，三条桦烛三挝鼓。","正男儿、失路述生平，踦闾语。"]},{"t":"满江红 题尤悔庵小影次韵二首 其二","f":"古风","c":["天语琳琅，曾比汝、殿前之柳。","今老矣、漫云才子，居然聱叟。","三弄笛吹桓子野，双丸髻挽王昙首。","尽数来、作达昔人多，如君否。","脚有鬼，还叉手。","舌尚在，终开口。","肯车中闭置，学他新妇。","曲道士为盘内舞，铜将军侑花前酒。","对董龙、半醉语喃喃，何鸡狗。"]},{"t":"满江红 过邯郸道上吕仙祠示曼殊","f":"古风","c":["丝竹扬州，曾听汝、临川数种。","明月夜、黄粱一曲，绿醅千瓮。","枕里功名鸡鹿塞，刀头富贵麒麟冢。","只机房、唱罢酒都寒，梁尘动。","久已判，缘难共。","经几度，愁相送。","幸燕南赵北，金鞭双控。","万事关河人欲老，一生花月情偏重。","算两人、今日到邯郸，宁非梦。"]},{"t":"满江红 汴京怀古十首 其四","f":"古风","c":["太息韶华，想繁吹、凭空千尺。","其中贮、邯郸歌舞，燕齐技击。","宫女也行神峡雨，词人会赋名园雪。","羡天家、爱弟本轻华，通宾客。","梁狱具，宫车出。","汉诏下，高台坼。","叹山川依旧，绮罗非昔。","世事几番飞铁凤，人生转眼悲铜狄。","著轻衫、半醉落霜雕，弓弦砉。"]},{"t":"满江红 汴京怀古十首 其五","f":"古风","c":["野渡盘涡，中牟界、涛翻浪走。","勒马看、残山剩水，一番回首。","斜日乱碑森怪猬，危冈怒石蹲奇兽。","笑中原、从古战场多，阴风吼。","炎刘鼎，嗟沦覆。","袁曹辈，工争斗。","看金戈塞马，喧豗驰骤。","浪打前朝黄叶尽，霜封断壁青苔厚。","又几行、雁影落沙洲，多于豆。"]},{"t":"满江红 汴京怀古十首 其六","f":"古风","c":["宋室宣和，看艮岳、堆琼砌璐。","也费过、几番锤凿，两朝丹垩。","花石纲催朱太尉，宝津楼俯京东路。","晋铜驼、洛下笑人忙，曾回顾。","花千朵，雕阑护。","峰万状，长廊互。","使神搬鬼运，无朝无暮。","一自燕山亭去早，故宫有梦何由作。","叹此间、风物剧催人，成南渡。"]},{"t":"满江红 汴京怀古十首 其七","f":"古风","c":["曲水金塘，流不尽、汴京遗事。","记当日、昆明水战，都亭百戏。","相国寺前灯似昼，南薰门外天如水。","恰政和、天子赵官家，多才艺。","火仗转，星球坠。","水幄捲，云房蔽。","正扇分雉羽，桥排雁齿。","此夜只怜明月好，当时那晓金人至。","记居民、拂晓拨菰蒲，寻珠翠。"]},{"t":"满江红 汴京怀古十首 其八","f":"古风","c":["北宋樊楼，缥缈见、彤窗绣柱。","有多少、州桥夜市，汴河游女。","一统京华饶节物，两班文武排箫鼓。","又堕钗、斗起流花风，飘红雨。","西务里，猩唇煮。","南瓦内，鸾笙语。","数新妆炫服，师师举举。","风月不须愁变换，江山到处堪歌舞。","恰西湖、甲第又连天，申王府。"]},{"t":"满江红 汴京怀古十首 其九","f":"楚辞体","c":["古玉津园，斜阳照、满坡芦荻。","浑不见、铜街铁市，层楼列戟。","阴惨惨兮门自锁，冷清清地船谁摘。","缭垣边、觅个不愁人，如何得。","白玉沓，黄金槅。","园芳乐，楼青漆。","任凄风苦雨，笼窗动壁。","春去鸟啼樊重里，月明花落王根宅。","坏廊斜、石兽趁行人，行人嚇。"]},{"t":"满江红 汴京怀古十首 其十","f":"古风","c":["汴水分藩，忆帝子、金床玉册。","人都羡、宪王才调，孝王俦匹。","椒殿丁年喧鼓吹，桂宫甲帐翻图籍。","唱诚斋、乐府夜深时，筝琶急。","蔡河涨，兰桡织。","雁池汎，龙舟疾。","记牡丹时节，排当宿直。","一夜黄河瓠子决，满城红袖梨花湿。","痛波飘、菰米入宫墙，沈云黑。"]},{"t":"满江红 写近况酬寄曹顾庵学士即用学士来韵","f":"古风","c":["黄雀银鱼，羡秋后、拦街塞术。","属餍耳、神仙难学，底须炼术。","万事绊人园客茧，百年戏我狙公栗。","倚秋城、下瞰暮涛红，煎斜日。","风乍满，喧杉漆。","霜渐老，催机匹。","看雁排人字，玲珑几笔。","诗怕杀青刊复毁，鬓憎镊白芟逾密。","只酒悲、苦忆妇姑城，呼鹰出。"]},{"t":"满江红 其一","f":"古风","c":["酒尽天寒，弹短铗、半生无术。","拟还向、广陵卖药，荷苓挑术。","秋雨好携邛竹杖，荒原莫管周人栗。","束残书、准趁半江晴，期来日。","蝙蝠暗，空如漆。","络纬叫，难成匹。","正篱摇书带，庭欹木笔。","计画总嗟吾辈拙，安排尽让天公密。","笑青毡、一夜羽毛生，飞而出。"]},{"t":"满江红 其二","f":"古风","c":["盗语主人，骊驹唱、留行无术。","堪叹息、井丛熠耀，臼荒松术。","冥阸关高驴龁荐，王官谷险猿偷栗。","算一年、作客纵归来，无多日。","何不贩，山中漆。","何不织，机头匹。","只年年怀刺，几时投笔。","胠箧愁看君笥俭，缄縢喜逊邻家密。","请先生、晨起检空箱，如何出。"]},{"t":"满江红 赠史远公五十即用学士原韵","f":"古风","c":["画苑词场，数侪辈、君才横出。","论戈法、韭花虿尾，尽推遒密。","九殿争传鹦鹉赋，重瞳亲奖龙蛇笔。","更岐王、含笑看挥完，绫千匹。","熬不熟，仙家漆。","黏不住，天边日。","叹篱还采菊，里仍呼栗。","醉斫月中一片桂，闲收雨后三峰术。","尽清狂、舍此问成仙，无他术。"]},{"t":"满江红 贺曹掌公秋捷仍用前韵","f":"古风","c":["老尽诗人，吴与越、惟君杰出。","人都羡、家风华贵，文澜绮密。","三世金莲学士烛，一门银管湘东笔。","看来春、骏马蹴长楸，千千匹。","仆老矣，身空漆。","卿健者，怀吞日。","记酒行以往，玉温而栗。","学圃条丰君掇杏，砚田殖落余锄术。","拟蔗竿、变技学曹公，穿杨术。"]},{"t":"满江红 赠大西洋人鲁君仍用前韵","f":"古风","c":["怪怪奇奇，咄咄甚、嘻嘻出出。","经过处、暹罗瘴恶，荷兰烟密。","鹤语定知何代事，麟经不省何人笔。","驾崩涛、九万里而来，鼋鼍匹。","海外海，光如漆。","国外国，天无日。","话僬侥龙伯，魂摇股栗。","善弈惯藏仙叟橘，能医却笑神农术。","更诵完、一卷咒人经，惊奇术。"]},{"t":"满江红 赠吴白涵回用前韵","f":"古风","c":["轰隐家门，捉鼻免、问君何术。","适志耳、和烟种树，带云舂术。","杜老堂前邻扑枣，陶公酒后儿呼栗。","更风潭、夹宅月当门，消閒日。","诗酒外，谁胶漆。","猿鹤侣，吾俦匹。","任客誇裘马，人矜才笔。","书到成时松竟老，径当僻处萝偏密。","叩苔菲、半晌不逢人，琴声出。"]},{"t":"满江红 忆旧游寄金沙王弓铭张杜若徐岐雍史兼三诸子仍用学士来韵","f":"古风","c":["曾记中原，与数子、挥鞭竞出。","同凭吊、园空石尉，城荒李密。","夜卧戍楼风咽鼓，晨题败驿霜胶笔。","更月中、带雪上轘辕，奇无匹。","战场内，碑填漆。","丛祠外，灯摇日。","忆并鞍舞蔗，分筹赌栗。","往事铲来如削草，新愁制就同煎术。","算倩他、白日繫长绳，嗟无术。"]},{"t":"满江红 丹阳贺天山寄词二阕属和其韵 其一","f":"楚辞体","c":["枯树衰杨，三叹息，物犹如此。","白眼看、尘埃野马，子虚亡是。","四壁岂无穷可送，九天只有愁难寄。","放狂歌、金铁一时鸣，吾衰矣。","拜特进，官承旨。","僮列鼎，奴衣紫。","更屏间窈窕，阶前阿唯。","若有人兮宁足慕，彼何为者殊堪耻。","曾几回、策马乐游原，荒烟耳。"]},{"t":"满江红 丹阳贺天山寄词二阕属和其韵 其二","f":"古风","c":["速垒糟邱，卿莫惜、垆边酒价。","能几日、秦关月小，汉宫花谢。","万里秋从西极到，千年泪向南楼洒。","妇人装、胡粉且搔头，无人者。","风刮烛，窗多罅。","雨淋壁，帘须下。","溷南邻北户，诗场歌社。","白昼蘧蘧身化蝶，青天梦梦程生马。","约练湖、鸦舅十分红，余来也。"]},{"t":"满江红 舟次丹阳感怀二首仍用天山韵 其一","f":"古风","c":["水面弦生，郭索响、谁能遣此。","问白傅、浔阳江上，可曾如是。","天外雨随帆共落，洲边雁与船同寄。","人奴之、笞骂此生无，应足矣。","河蟹贱，肥而旨。","秋山暮，红兼紫。","但酒酣以后，呼牛亦唯。","铸铁竟成千古错，读书翻受群儿耻。","笑道旁、石马亦何为，风吹耳。"]},{"t":"满江红 舟次丹阳感怀二首仍用天山韵 其二","f":"古风","c":["且食蛤蜊，管婢价、何如奴价。","君不见、棠梨一树，昨开今谢。","形状何劳麟阁画，泪痕不上牛山洒。","愿他年、青史好为之，传来者。","月射隙，霜寻罅。","骑篷背，眠樯下。","笑长贫陈孺，肉难分社。","张祜宅荒碑窜鼠，吕蒙城阔帆如马。","问半生、何物误人欤，残编也。"]},{"t":"满江红 过京口复用前韵二首 其一","f":"古风","c":["剩垒残崖，有多少、英雄经此。","也则为、风吹浪打，趱成如是。","北顾髻鬟晴欲笑，南朝君相生同寄。","叹齐梁、一片好江山，都非矣。","茶沸乳，帘泉旨。","枫绣瘿，酡颜紫。","倘鹤猿招我，欣然曰唯。","夔纵怜蚿何所益，信偏伍哙徒增耻。","踞篷舱、吹火骋雄谈，臧三耳。"]},{"t":"满江红 过京口复用前韵二首 其二","f":"古风","c":["瓜步船来，亟为问、淮南米价。","念欲索、陶胡奴米，何如诣谢。","肝胆尽从邻媪露，毫毛拚向沙场洒。","叹臣精、今日已销亡，谁容者。","栗半熟，经霜罅。","豚对舞，浮波下。","听寺钟隐隐，隔江莲社。","快意且骑隋苑鹤，失时休使瞿塘马。","怪一军、银铠海门来，潮头也。"]},{"t":"满江红 渡江后车上作二首仍用前韵 其一","f":"古风","c":["磨镜来耶，怪范叔、一寒至此。","古所谓、吊丧借面，将毋同是。","十载江河淮泗客，一身南北东西寄。","问车中、闭置妇人乎，真穷矣。","村酿薄，寒加旨。","斜日淡，风添紫。","有舆驺拉饮，从而唯唯。","谒彼金张吾已过，厄于陈蔡谁之耻。","任儿童、拍手笑劳人，车生耳。"]},{"t":"满江红 渡江后车上作二首仍用前韵 其二","f":"古风","c":["亦复何伤，终不掩、文章光价。","曾抵突、不知屈宋，何论沈谢。","一曲楚声愁筑破，半生情泪如铅洒。","尽腹中、容得百千人，如卿者。","好觅个、西村罅。","竟须在、南山下。","结斩蛟射虎，疏狂之社。","梦里悲欢槐国蚁，世间得丧邻翁马。","语前驺、叱驭且从容，余归也。"]},{"t":"满江红 看牡丹感旧","f":"古风","c":["芍药啼烟，倚晴昼、枝枝欲颤。","恰又是、送春天气，夹衣庭院。","香径露浓围绣幄，软帘风细低歌扇。","将去年、情事倚阑干，思量遍。","花与月，曾留恋。","朝共夕，閒游衍。","在睢阳古郡，商邱旧县。","记得浓香笼两袖，醉馀马上携归便。","下小楼、红袖那人迎，人微倦。"]},{"t":"满江红 寿武林徐世臣贤配邵孺人六十","f":"古风","c":["曾在西泠，徐稚下、陈蕃之榻。","记当日、湖山浓淡，宾徒杂沓。","夜雨对眠灵隐寺，春帆竞掠雷峰塔。","几何时、云水竟飘然、携瓢衲。","室有妇，机声匝。","塾有子，书声答。","喜鸿妻操作，龙驹蹙踏。","设帨九天喧管籥，称觞七郡倾壶榼。","正中秋、月照浙江潮，银光合。"]},{"t":"满江红 余澹心、吴园次、周子俶、顾梁汾、秦对岩诸公共饮集生家，适余在山中，未与此雅游也。园次作词见示，余亦次韵","f":"古风","c":["醉帽欹斜，讶何处、玳筵留客。","却誇我、鲈鱼桑落，席门置食。","满眼红墙愁里过，千场锦瑟闲中忆。","只君家、数过酒杯宽，真难得。","也不羡，鹍弦擘。","又何用，鸾鎞摘。","但茶香双好，居然雅集。","笑我冻栖梅一树，输他醉把螯千只。","问酒谋之妇尚能乎。","期来夕。"]},{"t":"满江红 将发梁溪酒后与吴园次","f":"古风","c":["臣醒而狂，问何处、再寻荆聂。","但相见、金樽休放，玉箫须擪。","旧事漫誇冠盖里，新愁合付昆明劫。","幸名园、一月共联床，歌声接。","老凤叫，才何捷。","雏凤语，吟都惬。","奈匆匆欲唱，渭城三叠。","归去道场山下路，也应瘦了丹枫叶。","只邮亭、醉尉夜偏多，休轻猎。"]},{"t":"满江红 园次拿舟相访与予订布衣昆弟之欢而去赋此纪事","f":"古风","c":["雨覆云翻，论交道、令人冷齿。","告家庙、甲为乙友，从今日始。","官笑一麾君竟罢，病惊百日余刚起。","问乾坤、弟畜灌夫谁，惟卿耳。","嗟墨突，殊堪耻。","怜范釜，还私喜。","且樵苏不爨，清谈而已。","开口会能求相印，吾生讵向沟中死。","终不然、鬻畚华山阴，寻吾子。"]},{"t":"满江红 同云臣和天玉元夜泊舟溪口感旧之作","f":"古风","c":["峭冷尖寒，也算做、一番元夕。","还记忆、清歌妙舞，梅魂雪魄。","向日微闻年少事，狂夫曾到岐王宅。","把玉箫、吹起落梅风，成今昔。","水驿底，孤眠客。","月榭口，寒波积。","正沈吟何限，钗痕綦迹。","早信今宵鲛帕湿，悔教那夜屏风隔。","载一船、离恨压西溪，溪流碧。"]},{"t":"满江红 郝元公署中食饼忽有茂陵之忆赋词志感","f":"古风","c":["落拓无家，叹三匝、曾栖汝颍。","记那日、绿窗闲与，姬人说饼。","溲粉宛同春絮薄，映空绝似杭罗净。","笑鹦哥、偏爱啄香粳，吴儿性。","才半载，归乡井。","拚两地，悲萍梗。","算不因烽火，几成薄倖。","闻说衮师年尚幼，戛羹解向厨娘竞。","只今宵、入手恰输他，团圆影。"]},{"t":"满江红 秋日几士兄姬人生子词以志喜","f":"古风","c":["人种追来，喜阮曲、又生遥集。","是月里、风飘桂子，夜来亲拾。","旦日惊看佳气满，经年怪底吟声涩。","果息机、结得蚌胎成，珠光湿。","嫂已庆，螽斯缉。","孙渐解，胜衣揖。","笑阿兄此事，得毋非急。","小弟今冬方五十，飘零一线河之北。","待来春、挈取小狮儿，还乡邑。"]},{"t":"满江红 再叠前韵酬几士兄","f":"古风","c":["阿大中郎，论家世、人人有集。","吾老矣、沅湘香草，童蒙聊拾。","破屋霜红萝薜暗，空斋雨黑仓琅涩。","叹青衫、原不为琵琶，年年湿。","谁耐把，残编缉。","久懒向，侯门揖。","算曹刘沈谢，非今所急。","一片月悬关塞上，五更笛落阑干北。","正匣中、刀作老龙吟，声于邑。"]},{"t":"满江红 三用回韵与几士兄言怀并示珍百云臣竹逸诸同志","f":"古风","c":["蹶尽霜蹄，休再问、龙城马邑。","计决矣、我宁作我，北山之北。","焉用文之身既隐，未尝闻仕如斯急。","见长沮、桀溺耦而耕，趋而揖。","麻与苧，连宵缉。","松共桂，和云湿。","任园官荬苦，霜畦苋涩。","米号长腰舂碓煮，子名苍耳挥锄拾。","问挂来、牛角是何书，渊明集。"]},{"t":"满江红 四用回韵贺几士兄纳姬","f":"古风","c":["桃叶桃根，把双桨、亲迎邻邑。","记住在、香街直下，画桥斜北。","扶下铜舆雅鬓妥，贮来绡槛莺啼急。","晕桃痕、注靥道胜常，羞郎揖。","绣架亸，鸳针缉。","红浪皱，鸾衾湿。","学夫人举止，漫嫌生涩。","春懒一床和月捧，新娇半搦从天拾。","怪新词、艳粉恰盈箱，閒情集。"]},{"t":"满江红 怀龚仲震卧疾梁溪","f":"古风","c":["贳菊赊螯，记共醉、梁溪客夜。","风不定、软帘轻漾，一灯高下。","白发放颠长忍饿，朱门悭酒偏遭骂。","晓鸡号、犹欲挽银河，杯中泻。","书散诞，萧思话。","声嚄唶，甘兴霸。","每厕身铛杓，袒而行炙。","老兴郎当乌啄肉，秋怀浩荡鹰离架。","怪新来、痹疾偃霜檐，酸风射。"]},{"t":"满江红 余有怀仲震词，南耕昔在南昌，亦与仲震同作老客，遂次余韵，亦成一首，斐然见示。仍叠前韵，用柬南耕，并令仲震他日读之，一轩渠也","f":"古风","c":["五老匡庐，挂冷瀑、长晴不夜。","秋瑟瑟、两贤相见，琵琶亭下。","阅尽江山真欲舞，算来人物谁堪骂。","倚滕王、杰阁瞰章门，银涛泻。","羁旅恨，乡关话。","拉龚胜，呼曹霸。","尽雄心耗与，冷杯残炙。","一朵菊花人伏枕，半庭豆叶秋除架。","只几年、踪迹最难忘，同游射。"]},{"t":"满江红 拥炉","f":"古风","c":["炙尽乌金、销不了，鬓丝微雪。","依稀听、一城巷杵，半楼檐铁。","拨尽寒灰人语悄，跋完官烛鸡声咽。","笑西廊、鹦鹉也愁寒，频频说。","小窗底，屏风折。","微酣处，炉薰爇。","但得人围绕，心情顿别。","记得常年喧笑语，笛床茶臼参差列。","只侯门、兽炭枉堆盘，增寒冽。"]},{"t":"满江红 风雪行丹阳道中","f":"古风","c":["秃树僵杉，趁玉舞、离披作势。","经多少，断桥仄涧，破楼枯寺。","毡笠裹风嗟觱发，笋舆兀雪愁颠踬。","谢邮亭、汤社点红姜，招行骑。","凿不破，琉璃水。","冻不了，鱼龙市。","笑吴儿长鬣，有船难使。","冻雀迎人篱角噪，村翁傲我墙根睡。","撒晶盐、迷却吕蒙城，心如醉。"]},{"t":"满江红 玉峰沈天羽先生，词场耆宿也，选有草堂四集行世，不幸早逝乏嗣，岁月不居，距今已四十馀年矣。贤配钮夫人今年举七十觞，有从甥钮君南六，代为乞言，词以寄慨","f":"古风","c":["偶尔相关，小楼上、画阑凭遍。","记当日、东吴瘦沈，才名堪羡。","艳句和愁淋舞帕，香词蘸酒涂歌扇。","只金荃、身后竟无人，为收管。","绾不得，垂杨线。","禁不住，飞花片。","剩霜闺寡鹄，雨凄风怨。","转眼桑田朝市改，打头茅屋裙笄健。","绕雕梁、谁替话呢喃，邻巢燕。"]},{"t":"满江红 赠家小阮次山","f":"古风","c":["群从凋零，怅家世、空馀双戟。","算唯汝、过都历块，龙文虎脊。","我别西溪刚十载，数椽聊赁街东宅。","有压栏、先世一枝红，君堪摘。","林下酒，床头易。","吾与汝，交相惜。","笑我今衰矣，子应努力。","王谢门风终自在，纷纷程李钱宁直。","向渭阳、诗里说邹阳，悲畴昔。"]},{"t":"满江红","f":"古风","c":["易识君家，不须向、长街夹毂。","闲相过、主人不在，满园空绿。","蝴蝶轻狂金井畔，樱桃开落银屏曲。","陇山鹦、不省客来游，春眠熟。","沦落恨，飞红浴。","繁华梦，邮亭宿。","记筵开太守，一群香玉。","今日鍊师新入道，当时才子曾贻墨。","雨濛濛、燕子上空梁，将泥蹴。"]},{"t":"满江红 赠娄东周逸园兼怀毛亦史","f":"古风","c":["舞袖成围，正衮遍、筝琶阮笛。","有一客、众中索我，謼声甚急。","坐上两行红粉笑，亭边一夜青衫湿。","叹雄文、老将本幽燕，才相识。","风裂烛，喧豗黑。","星络角，晶荧白。","倘明朝分手，后期难的。","第令男儿存意气，休论世事多离别。","博徒中、归及见毛公，言相忆。"]},{"t":"满江红 春光甚冶健庵挈我鱼墩精舍小憩同潘次耕弟纬云赋","f":"古风","c":["半里春田，渐踏到、蘼芜丛里。","疏篱外、红桥画板，卧于烟水。","柳线飘时寒食近，梨云冻处东风起。","把满栏、紫艳嗅移时，忻然喜。","颖士仆，康成婢。","营小筑，饶名理。","有玉山彩翠，光浮髹几。","斗草心情忙似蝶，筑毬士女多于蚁。","算春来、何限断肠天，无踰此。"]},{"t":"满江红 赠溧阳王参戎","f":"古风","c":["小队城南，来踏遍、平陵春色。","迤逦望、秣陵钟阜，郁苍何极。","一片南朝箫鼓地，千年北府侯王宅。","到如今、草绿锦衣仓，成今昔。","帐下缚，黄皮褶。","座上拓，黄金戟。","论男儿须学，万人之敌。","家世故侯看射虎，江山儒将闻吹笛。","笑军中、缓带惯翻书，当阳癖。"]},{"t":"满江红 同恭士叔岱牧仲饮介子西湄草堂次公㦷壁间韵","f":"古风","c":["水榭清幽，宿雨罢、奔浑齐涨。","凭眺处、孤城剩垒，炮痕无恙。","波静细延帘阁底，草香乱扑纱窗上。","碧阴阴、一阵嫩凉来，沙禽饷。","篷六扇，烟中漾。","箫一缕，潭边唱。","况主人还有，吴羹法酿。","但醉且寻茶叟灶，欲归径借溪翁杖。","想此时、纤月挂西湄，难于状。"]},{"t":"满江红 秋日登单父城外春秋阁","f":"古风","c":["单父城东，堆遍了、万层秋色。","凭阑望、齐疆鲁甸，一泓晴碧。","此去渐通霄汉路，吾生只少翱翔翼。","缭櫩斜、百尺俯中原，空苍极。","铜鼓赛，松杉直。","阴雨吼，精灵急。","看藓衣泥马，晓行无迹。","日落漫添羁旅恨，时危专藉匡扶力。","读春秋、武帐烛花红，髯如戟。"]},{"t":"满江红","f":"古风","c":["江左周瑜，年少日、雄姿历落。","记十载、霜飞獬豸，风生台阁。","宦迹遽如春梦短，人情剧似秋云薄。","旧平泉、早付绿苔生，都非昨。","问鲍子，今难作。","怜弱女，凭谁托。","赖同官偏念，曩时花萼。","高谊漫言齐偶大，华堂定让韩居乐。","翟公门、一曲鼓求凰，惊罗雀。"]},{"t":"满江红 万脩承五十用吕居仁韵","f":"古风","c":["北郭先生，门恰对、峰回涧曲。","且小隐、渔庄蟹舍，长廊矮屋。","雨过拍茶香作雪，日高煨芋酥于玉。","向红尘、不到处逍遥，襟衫绿。","林滟滟，烘枫菊。","涛瑟瑟，锵梧竹。","问貂蝉蓑笠，谁荣谁辱。","豆架瓜棚三径在，黄鸡白酒千场足。","便水田、今岁不曾收，来年熟。"]},{"t":"满江红 秋杪同南耕鲁望弟过东郊外殿元叔祖废园感赋","f":"古风","c":["醉袖笼鞭，正杏苑、一枝新夺。","归卧处、溪山窈窕，亭台层叠。","松籁梧烟萦客梦，溪茶涧笋醒人渴。","羡升平、江左玉堂仙，风光别。","繁华事，行人说。","凄凉债，今生结。","又蜗黄藓绿，断碑残碣。","细雨零星渔榜火，乱鸦飒沓僧龛月。","记小楼、一片伎衣红，年时节。"]},{"t":"满江红 琴弈双清为阎牛叟赋","f":"古风","c":["绿齿摴蒱，憨狂煞、他家儿女。","笑此是、牧猪奴戏，何心共赌。","懒凭绣床抽蛱蝶，爱拈红子争龙虎。","恰偏逢、郎手劣于侬，降幡举。","奁乍敛，墙阴午。","香半灺，灯花吐。","逗琴心忽入，海天寒处。","时世几多筝笛耳，蛾眉也解英雄苦。","砉崩腾、只把汉宫秋，临风鼓。"]},{"t":"满江红 寿海宁家始升六十","f":"古风","c":["风景清佳，天气是、梅前菊后。","弧悬处、高轩列戟，软帘堆绣。","龙笛鹅笙喧午夜，衙香宫锦围晴昼。","笑吾宗、今日又重逢，图南叟。","摇铁凤，蟠金兽。","相府畔，沙堤右。","算家门华贵，于公何有。","坊曲漫劳誇韦杜，文章要使罗星宿。","看佳儿、新酝桂香浓，为春酎。"]},{"t":"满江红 送叶桐初还东阿即次其与曹雪樵倡和原韵","f":"古风","c":["若且歌乎，急配以、哀丝豪竹。","念来夜、故人一去，月明人独。","风吼军都山忽紫，雨收督亢天全绿。","笑好官、几个读书来，休耽读。","吟复写，螭蟠幅。","富与贵，蛇添足。","但逢花便插，有泉须掬。","建业云山通地肺，姑苏烟水连天目。","算谷城、虽好不如归，眠乡曲。"]},{"t":"满江红 送宝坻杜相国","f":"古风","c":["恒岳生申，恰黍谷、阳回时候。","沙堤上、弧悬相府，光腾宝甃。","万国河山平似掌，九天花鸟纷如绣。","正黄扉、暂阖衮衣闲，娱清昼。","房与杜，齐台斗。","李与杜，豪诗酒。","算文章勋业，公俱不朽。","八饼茶分龙凤碾，万钉带压蛟螭钮。","看无边、红烛下朝来，为公寿。"]},{"t":"满江红 闻往岁帝城烟火之盛，甲于天下，今年元夜，作客都门，适逢新禁，凄然独坐，词以遣怀","f":"古风","c":["夜火春宵，说此地、上元尤胜。","烟焰里、烘桃炙柳，飘梅灺杏。","绣羽花冠筒内放，缃苞翠蔓竿梢映。","紫葡萄、十丈满池莲，丝丝凝。","玛瑙寺，秋千竞。","琉璃厂，筝琶盛。","更钿车麝帕，嬉游不定。","今夜凤城偏寂寂，一灯微耿人初病。","只角残、吹到第三声，何心听。"]},{"t":"梅子黄时雨 本意","f":"古风","c":["天水空濛，只将暝织愁，催雨添恙。","乍过了东风，杨花一桁。","弹指还惊仲夏，萧萧檐瓦跳珠响。","葡萄涨。","鸠妇唤晴，凫母眠浪。","惆怅。","他乡谁傍。","算炉薰药裹，聊自屏当。","料故国楼头，茶烟新飏。","豆绿缸中梅水满，何时小啜龙团饷。","苔衣长。","赋得苧衫难爽。"]},{"t":"雪梅香 和竹逸再游石亭看落梅原韵同云臣赋","f":"古风","c":["梅将谢，临风招手唤重游。","恰瀰瀰照浪，愁情懒比眠鸥。","低扑村庄纨扇巧，乱飘溪阁粉茵稠。","糅绵弄雪送清芬，与梦俱幽。","再来增怅望，满径琼姿，零落谁收。","拾取残英，注来花乳磁瓯。","纵使暗香埋陇畔，胜于飞絮舞街头。","休回首，几枝含泪，正倚山楼。"]},{"t":"扫花游 早秋同云臣诣竹枝庵访寒松上人，时上人将往龙眠，用片玉词韵留赠，兼志别怀","f":"古风","c":["问秋何在，在郭外陂塘，涧边林楚。","野香几缕。","向衫痕暗扑，帽丝乱舞。","暑退凉生，一派嫩阴阁雨。","绕村去。","遥见支公，微笑迎处。","相别弹指许。","又竹翠沾厨，荷风凝路。","茗铛笋俎。","怅来朝愁听，江船捣素。","任是空王，也稔离情凄苦。","漫延伫。","怕催归、花宫浴鼓。"]},{"t":"红情 咏半吐红梅","f":"古风","c":["一丝凝晓。","似绛蕊浮釭，锦鳞拍沼。","搓透猩绒，卖弄憨嗔许谁拗。","莫是罗浮人困，珊枕上、小鬟新觉。","正睡晕初圆，偷倚绣奁照。","料峭。","年犹少。","更酒入潮生，春来靥笑。","娇香趁早。","休赚夭桃见时恼。","几颗朱樱绽口，甚日茜花压帽。","倩红泪、将绡裹，洒他开了。"]},{"t":"满庭芳 谈长益携具招游八公岩","f":"古风","c":["水寺拖烟，山楼嵌雨，日长经院无人。","茶香竹翠，也算是前因。","兽窟山前精舍，参差处、欲断还匀。","依稀似、凫雏雁子，零乱不成群。","逡巡。","思昔日，戴公故隐，往迹沉沦。","渐樱桃熟后，梅又生仁。","憔悴鬓丝禅榻，十年事、更与谁论。","空归去，数声暝磬，行过米颠坟。"]},{"t":"满庭芳 过辽后梳妆楼同洪昉思赋","f":"古风","c":["细马轻衫，西风南苑，偶然人过金沟。","道旁指点，辽后旧妆楼。","想像回心宫院，钿筝歇、含泪梳头。","青史上，武灵皇后，一样擅风流。","堪愁。","成往迹，缭垣败甃，满目残秋。","便脂田粉硙，零落谁收。","莫问完颜耶律，兴亡恨、总是荒邱。","红墙外，谁抛金弹，年小富平侯。"]},{"t":"满庭芳 题顾梁汾舍人扈驾诗后","f":"古风","c":["万乘旌旗，千官羽猎，翠华绝塞重经。","珠鞭玉靶，日黑虎风腥。","羡尔金闺年少，陪游幸、凤辇龙庭。","霜天晓，柘黄袍出，一骑按秋鹰。","至尊。","亲讲武，火城渐杳，交网犹扃。","更北平城外，岭断云横。","飞鞚传宣七校，黄羊酒、前队教停。","琵琶歇，碧天毡帐，一曲海东青。"]},{"t":"满庭芳 距汝州四十里，山有温泉，相传为唐武后幸洛时浴处","f":"古风","c":["武媚东巡，金轮春幸，洛川自古神州。","风光溢目，彩仗簇星球。","闻道香山山下，汤泉沸、玉滟琼流。","传驻跸，石榴裙湿，激水奉宸游。","六郎宣诏入，莲花一朵，相映娇柔。","趁晚凉閒话，水殿云帱。","千载朱颜难待，伤心似、太液池头。","凄凉也，骊山浴馆，一样野花稠。"]},{"t":"满庭芳 咏腊梅和京少韵","f":"古风","c":["仙泪流铜，蜂脾酿蜜，圣檀初傅新妆。","冰檐雪甃，带暝乱斜阳。","自是罗浮别种，依稀剩、金粟馀香。","王孙弹，枝头万颗，偏惹画帘长。","绕廊。","应错认，宛如梅子，熟后轻飏。","想宫人入道，絁帔都黄。","一段冷魂幽绪，扶疏态、谁与擎将。","春来也，红红白白，让尔冠群芳。"]},{"t":"满庭芳 玉簪花","f":"古风","c":["筑粉偏温，镂脂却暖，一枝颤影难休。","凉轩滑簟，常傍晚妆楼。","几度枕边轻坠，听不出、钗响悠悠。","寻觅取，依然未璺，重上玉人头。","开时刚浅夏，晓来笑折，人意先秋。","正睡馀梦远，翠幌空幽。","每被鬓丝笼住，香风动、蜂蝶先偷。","玲珑极，邻姬误认，卸取节秦讴。"]},{"t":"满庭芳 暮秋梁溪南郊看菊纪游","f":"古风","c":["雨坼池莲，霜彫岩桂，愁饯临去秋光。","城南漫兴，步屧趁林塘。","叹息人家兵后，莓苔遍、废井颓墙。","溪桥畔，柴门半掩，篱落未全荒。","烟庄。","经几处，娇红淡粉，压叠成行。","恨花繁境窄，姿态难详。","最后一园差胜，轩棂外、乱石疏廊。","西风劲、催将菊瘦，馀力袅衰杨。"]},{"t":"满庭芳 丁巳元夕后三日谒别驾林天友于长洲官署赋赠","f":"古风","c":["淼淼长洲，离离茂苑，无边草色连空。","两番借治，欢笑满吴宫。","一自暌离绛帐，相思切、早理烟篷。","平波远，谁吹五两，几阵落灯风。","忡忡。","怜别后，鸾飘凤泊，竹懒丝慵。","拟酒酣诉与，慷慨从公。","忆昨探梅摘蕙，铜官下、曾傍游筇。","经年矣，春来邓尉，香雪又濛濛。"]},{"t":"满庭芳 今春梅候，余适买棹吴门，乃因循羁绊，不及为邓尉之游，正深怅惋，及过里门，而枝头香雪已零落略尽矣，会放公以梅下见怀词并云臣和章相示，漫次原韵","f":"古风","c":["二月新晴，东风作阵，吴天梅讯频催。","伍塘飞棹，恰过浪花堆。","闻说疏香冷粉，铜坑畔、万树齐开。","真孤负、阖闾城下，容易放船回。","沿洄。","归罨画，閒赓绮韵，触绪增哀。","想一枝瘦玉，曾缀经台。","我是湖州杜牧，成阴候、侧帽才来。","明年事，相期花下，莫放浅深杯。"]},{"t":"满庭芳 咏西府海棠","f":"古风","c":["满院红绡，半楼绛雪，几丛艳冶成围。","倚栏无力，嫩柳斗腰肢。","粉壁银墙淡雅，明妆坐、人是琼枝。","东风动，花光映肉，桃晕入冰肌。","胭脂。","刚蘸雨，一番梳裹，别样芳菲。","似六宫昼暖，睡重杨妃。","赢得三郎一笑，花前闹、急管繁丝。","豪华甚，千堆蜀锦，那用杜陵诗。"]},{"t":"满庭芳 五日玉峰竞渡用梅村词韵","f":"古风","c":["菖歜芳筵，葵榴绮节，一雨凉透重湖。","绣旗画鼓，兰桨划菰蒲。","多少唐陵汉寝，千年恨、远近楸梧。","休凭吊，玉山将倒，翠袖可相扶。","狂夫。","狂更剧，花颠酒恼，脱帽喧呼。","唤湘累与汝，美酝同沽。","收拾金箫玉管，昆峰好、晚髻新梳。","家乡忆，层层水榭，红缕漾钗符。"]},{"t":"满庭芳 赠表兄万大士","f":"古风","c":["少日情亲，两家中表，羊车竞戏阶前。","雕虫薄技，里塾又随肩。","弹指渭阳凋谢，乌衣巷、蔓草平田。","谁能料，童时伴侣，相对两华颠。","中年。","抛艾绶，柴门罨画，三径萧然。","忆相州邺下，宦迹流传。","购得铜台绣瓦，归吟写、夜雨朝烟。","残生事，酒鎗棋局，此外总由天。"]},{"t":"满庭芳 咏宣德窑青花脂粉箱为莱阳姜学在赋","f":"古风","c":["龙德殿边，月华门内，万枝凤腊荧煌。","六宫半夜，齐起试新妆。","诏赐口脂面药，花枝袅、笑谢君王。","烧瓷翠，调铅贮粉，描画两鸳鸯。","当初温室树，宫中事秘，世上难详。","但铜沟涨腻，流出宫墙。","今日天家故物，门摊卖、冷市閒坊。","摩挲怯，内人红袖，恸哭话昭阳。"]},{"t":"满庭芳 吾邑茶具俱出蜀山，暮春泊舟山下，漫赋此词","f":"古风","c":["白甀生涯，红泥做活，乱烟细袅孤村。","春山脚下，流水浴柴门。","紫笋碧鲈时候，溪桥上、市贩争喧。","推篷望，高吟杜句，旭日散鸡豚。","田园。","淳朴处，牵车鬻畚，垒石支垣。","看鸱夷扑满，磊磊邱樊。","而我偏怜茗器，温而栗、湿翠难扪。","掀髯笑，盈崖绿雪，茶事正堪论。"]},{"t":"满庭芳 汴梁客舍同冯蓼庵夜坐，蓼庵出梁溪闺秀永愁人诗稿示余，凄然赋此","f":"古风","c":["冯衍长愁，陈思不乐，相逢同客东京。","乌啼落叶，惆怅可怜生。","无忌馆今何处，河声怒、搀著砧声。","秋宵永，几楞粉月，晒得绿窗晴。","莺莺。","闻尚在，诗人老去，一倍含情。","且开箱验取，锦字纵横。","料尔银钩未写，檀笺上、珠泪先盈。","休肠断，青衫红粉，一样是飘零。"]},{"t":"满庭芳 丙辰元夕","f":"古风","c":["战马千群，戍旗一片，江东月又刚圆。","凝妆艳粉，何异太平年。","楼上冰帘绛蜡，参差弄、凤管鹍弦。","楼儿下，金蛾玉茧，风景倍嫣然。","碧天。","何限事，一生能得，几度灯前。","况春城不禁，拾翠寻钿。","忍负衫红钗紫，生生博、园画淩烟。","归来晚，阑珊夜火，人立小门边。"]},{"t":"满庭芳 林天友别驾招饮同云臣赋赠","f":"古风","c":["荔浦楼台，榕城甲第，相门群羡贤甥。","诗篇宦迹，双斗早梅清。","几度桃花浪暖，贤劳最、转饷神京。","才归也，楚天在望，又听夜猿鸣。","三城。","父老说，孝侯一去，蛟虎纵横。","忆使君前事，千载齐名。","昨夜张筵召我，行春暇、绿酒红笙。","刚过雨，新莺语滑，唤起月盈盈。"]},{"t":"满庭芳 花朝后一日林天友邀同云臣为南岳之游词以纪事","f":"古风","c":["翠榜欹烟，红船委浪，水帘低捲晴晖。","晓山欲笑，迎我在春矶。","歇马谁家园子，游丝静、懒上人衣。","凭栏望，楼台易主，金粉未全非。","霏微。","小雨过，花笼寺阁，瀑溅僧扉。","正使君爱士，野客忘机。","斜日仍摇画艇，纱窗掩、玉椀频挥。","城头望，半溪灯火，争认醉翁归。"]},{"t":"满庭芳 清明前一日同云臣溪干观剧","f":"古风","c":["近水人家，弄晴天气，清明恰是来朝。","晓莺无赖，唤我驿边桥。","多少归宁溪女，花枝飐、香粉轻飘。","疏篱畔，兰芽杏蕊，开到十分娇。","垂髫。","刚十五，新声解唱，渌水红么。","忆少年同学，半插华貂。","我向江村潦倒，新年恨、比旧还饶。","秋千社，东风搅碎，戏鼓赛神箫。"]},{"t":"满庭芳","f":"古风","c":["宅列光延，门齐通德，君恩曾赐山庄。","胜衣膝下，粉署半含香。","白晰华貂插鬓，东头屋、绿野名堂。","依稀记，画檐鸱吻，烧作紫鸳鸯。","沧桑。","今已换，苇花枫叶，一片苍茫。","剩戟门未坼，酒旆新飏。","土锉谁人竞唱，边州调、白草黄獐。","缭垣外，西风吹到，憔悴旧家郎。"]},{"t":"满庭芳 寿王敬哉先生用棠村词韵","f":"古风","c":["菊尚拖黄，梅将凝粉，安排晴日开筵。","锦笙画鼓，谱出鹧鸪天。","两世尚书门第，朝回后、绣毂纷然。","华堂上，升平保傅，矍铄地行仙。","名园。","飞霰后，银灯火树，雪月光联。","要妆成瑶圃，映上红笺。","海畔群真介寿，骖鸾渡、弱水三千。","驼封赐，汪汪绿蚁，犹裛凤楼烟。"]},{"t":"满庭芳 寿大司农梁苍岩先生","f":"古风","c":["黄阁勋名，黑头卿相，瑶池第一神仙。","蕉林书屋，烟景胜平泉。","珠岛花洋万里，牙樯送、南海归船。","还朝后，锦袍茜袖，长侍紫宸前。","华筵。","群献斝，升平法曲，象管鹍弦。","有尚书红杏，丽句新填。","岁岁凤城今夜，阳回处、暖在春先。","缃梅绽，风光正好，次第到秋千。"]},{"t":"满庭芳 山阴沈躬范妇陈夫人，好读书，年二十三夭卒，卒之日，嘱以平日所诵书籍殉冢中。一时皆作诗以哀之，余亦为赋此阕","f":"古风","c":["人偶言愁，仆原多恨，说来也替神伤。","越溪有女，十五嫁王昌。","人在水晶帘底，簪花格、日仿千行。","才梳裹，湿蝉未敛，便自理铅黄。","梅妆。","容易谢，皇坟汲冢，雪魄同藏。","抱夜台吟诵，月冷枫香。","何必玉鱼金盌，遗编在、还累萧郎。","罗裙坏，草生书带，不化紫鸳鸯。"]},{"t":"满庭芳 送顾尼备南归为太夫人寿","f":"古风","c":["梅子生仁，柳绵著水，翠阴淰淰遮墙。","新裁綵袖，爱趁日初长。","立马都亭送客，鞭丝飐、帽影低飏。","凝情处，暮云堆碧，妒尔作轻装。","霞觞。","归捧候，黛添艾叶，红入榴房。","有江鲈篱笋，足膳高堂。","路次毗陵水驿，应相见、阳羡山光。","凭君说，倚阑游子，脉脉只思乡。"]},{"t":"满庭芳 吴门管烈妇夫亡殉节词以纪事","f":"古风","c":["镜掩离鸾，弦摧别鹤，千秋彤史留芬。","机中锦字，长恨与谁论。","一自磨笄人杳，成灰后、蝶化罗裙。","人间事，依然花月，空馆总无春。","夫君。","怜彩笔，土埋玉树，雨打黄昏。","痛梨花一树，同散朝云。","赢得巫箫社鼓，胥江畔、岁岁迎神。","凭谁画，啼斑满竹，别样管夫人。"]},{"t":"满庭芳 送吴初明南还秣陵","f":"古风","c":["飒沓寒鸦，聊萧冻叶，西风压雪将低。","芦沟南下，立马惜分携。","此去鸡笼山馆，江梅瘦、恰与檐齐。","都门事，墙头过酒，烂醉懒重提。","当时。","临发日，王郎作画，送别青溪。","看无多几笔，不数迂倪。","勿论风流二老，相关甚、正有邻奚。","长须到，欢迎隔浦，仍是杜家稽。"]},{"t":"满庭芳 中元节途次蒙阴追悼亡女","f":"古风","c":["庾氏苟娘，左家娇女，慰情谁道非男。","铭椒颂菊，略涉也粗谙。","每岁因爷作客，恒归伴、阿母香奁。","天涯信，灯花蟢子，频向紫姑占。","江淹。","何限恨，半生婚嫁，怨极愁添。","只今朝五岳，敢诩幽探。","惆怅中元令节，家山事、梵呗庄严。","蒙阴畔，两行红泪，寄不到江南。"]},{"t":"满庭芳 题徐武贻小像","f":"古风","c":["碧筱千竿，红兰一架，松涛韵杂笙竽。","科头箕踞，旁置小风炉。","回首文贞旧业，凄凉绝、绿野荒芜。","牢之好，家传宅相，名已动京都。","踌躇。","当日事，记曾抚掌，为我披图。","拟闲题数语，貌尔清癯。","讵料山邱华屋，重来处、此诺还逋。","徐君墓，未成挂剑，聊报秣陵书。"]},{"t":"徵招 送宋性存归吴门","f":"古风","c":["一灯分做还乡梦，君今果然归矣。","残月晓风天，暂挽君双袂。","柳条今剩几。","待折赠、沈吟无计。","君到江南，定逢梅放，也应相寄。","来夜白沟河，鸡声店、料尔早寒人起。","谁念凤城边，有倚阑心事。","暮云千万里。","留我作、天涯游子。","我亦有，茅屋三间，六朝斜照里。"]},{"t":"徵招 为王瑁湖编修悼亡","f":"古风","c":["柿叶翻时人病起，凄然悼亡新赋。","画箧尽伊搜，奈蕙丛先去。","元和才子恨，拚细砑、凤笺零谱。","不分西山，风前还斗，旧年眉妩。","故国水云多，曾侧帽、共听半船疏雨。","粉腕斫鲈香，更翠蒪凝箸。","如今秋夜笛，只递入、客窗偏苦。","缒蛛丝，丁字帘西，记有人行处。"]},{"t":"徵招 为尤悔庵悼亡","f":"古风","c":["蕙丛去后微之怨，当时韦娘年小。","别后镜鸾分，怅天涯人老。","小屏归路悄，怕重叠、吴山清晓。","此夜遥怜，水哉轩畔，月明多少。","侍史慢薰衣，金门启、愁听穿花漏早。","剔烛鼓冰弦，又犯些商调。","彩毫凭起草，错认画、远山眉稿。","不信是、白玉为堂，顿玉台人杳。"]},{"t":"水调歌头 宋荔裳曹顾庵王西樵招集刘峻度葭园即席限韵","f":"古风","c":["钿犊朱扉外，宝鸭画堂中。","重逢把酒飞盖，倍觉旅愁空。","人有庾徐潘陆，坐有楼台丝竹，那减晋人风。","慎莫赋怅怅，亟为拉红红。","吾醉矣，拓金戟，倚长弓。","不改狂奴故态，耳语有群公。","官是金闺贵客，身是画溪愁客，客自不相同。","起觅铁绰板，高唱大江东。"]},{"t":"水调歌头 送宋荔裳观察入都并寄蓼天司业同顾庵西樵赋","f":"古风","c":["酒冷天寒日，人去客愁中。","数行钿蝉柱雁，祖饯出城东。","衣上青天明月，马上黄河飞雪，雁背染霜红。","如此作装急，磊砢相桓公。","千斤椎，七宝辔，百石弓。","从奴宾客，所过栈马齧残通。","定过淮阴祠下，更到望诸墓上，怀古飒悲风。","若见苏司业，言我鬓成翁。"]},{"t":"水调歌头 留别阿云","f":"古风","c":["真作如此别，直是可怜虫。","鸳裯麝薰正暖，别思已匆匆。","昨夜金尊檀板，今夜晓风残月，踪迹太飘蓬。","莫以衫痕碧，偷揾脸波红。","分手处，秋雨底，雁声中。","回躯揽持，重抱宵箭怅将终。","安得当归药缺，更使大刀环折，萍梗共西东。","絮语未及已，帆势破晴空。"]},{"t":"水调歌头 舍南庭前牡丹将放词以催之","f":"古风","c":["峭冷侵金鸭，乍暖熨铜龙。","东皇好景何限，相别苦匆匆。","二十四番花信，一百五朝寒食，几阵酒旗风。","豆吐蚕婆绿，花绽鼠姑红。","画栏西，绮窗北，锦城中。","姚黄何事羞涩，媚脸未全融。","速办慈恩车骑，并倩华清钿笛，邀取谪仙翁。","早放木芍药，慢舞玉珑璁。"]},{"t":"水调歌头 夜饮季端木斋中归忽尔飞雪填词奉柬并怀尊甫孚公","f":"古风","c":["昨夜醉君酒，归路雪飞花。","淋衣那更裂烛，袖秃不禁遮。","妆遍琼楼万瓦，凝透绡宫千幕，冻杀冷虾蟆。","纸破苦拉杂，柱朽怕槎枒。","吾笑我，寒至此，独何耶。","愁时恨不倩汝，为我唤筝琶。","忽忆哦松尊甫，今夜断桥晴雪，吟兴定然佳。","客睡几曾著，城上咽悲笳。"]},{"t":"水调歌头 雪夜再赠季希韩叠前韵","f":"古风","c":["海上玉龙舞，糁作满空花。","城中十万朱户，琼粉乱周遮。","愁对一天飞雪，不见昨宵明月，桂影蚀金蟆。","短鬓飒秋叶，僵指矗枯枒。","当日事，须细忆，讵忘耶。","记筑球场，擪笛却手复为琶。","纵不神仙将相，但遇江山风月，流落亦为佳。","岂意有今日，侧帽数哀笳。"]},{"t":"水调歌头 立秋前一日述怀柬许岂凡","f":"古风","c":["将相宁有种，坚子半成名。","蚍蜉切莫撼树，听我短歌行。","薄俗人奴笞骂，末路妇人醇酒，一笑万缘轻。","夫子知我者，试与说生平。","斫豪猪，炙走兔，掣长鲸。","群儒龌龊可笑，我自习纵横。","明发西风削草，且约博徒会猎，小趁一秋晴。","须作猬毛磔，箭作饿鸱鸣。"]},{"t":"水调歌头 题友人词并示方邺大匡","f":"古风","c":["脱帽即擪笛，辍洗便弹筝。","千金教得乐部，坐此得狂名。","每叹英雄作事，万象雪中鸿爪，一过已忘情。","倏忽谢歌舞，寂寞掩柴荆。","新词句，真磊落，太纵横。","我作致师乐伯，摩垒更靡旌。","爽若并州快剪，又若短兵狭巷，杀贼不闻声。","举以示二子，大笑绝冠缨。"]},{"t":"水调歌头 赠西陵周勿庵","f":"古风","c":["拍手唱铜斗，蹋地舞回波。","世间穷达有命，扰扰若之何。","收罢百钱帘下，雨后一街人少，客有猎缨过。","仆病坐磨蝎，君丑类鸡窠。","如箕舌，皤其腹，口悬河。","眼中只爱绿帻，谁解爱青娥。","颇怪丈人痀偻，却恐舍人居謈，戏语莫相呵。","绝倒黄幡绰，抚掌敬新磨。"]},{"t":"水调歌头 题远公画洞山图送天石北上","f":"古风","c":["何以赠行卷，而作洞山图。","旁人拍手大笑，画者复谁欤。","此去燕姬马湩，况足金茎仙瀣，茗椀酷非须。","卿复携来否，长柄有葫芦。","掀髯语，画此者，定非迂。","败尽朱门酒肉，只此味清腴。","纵挟绫文三百，日给龙团凤饼，曾似故园无。","十丈红尘里，一幅冷秋菰。"]},{"t":"水调歌头 送原白北上","f":"古风","c":["莫作恋豆马，直学脱韝鹰。","送君秣魏刷赵，万里惬飞腾。","颇怪今人离别，出户定然复入，刺刺实堪憎。","似尔最飒爽，物态直凭陵。","公子去，臣宜从，病未能。","行也勉旃努力，勿复惮炎蒸。","为我慈仁阁下，寄讯支离老叟，短发定鬅鬙。","待我上元候，同看凤城灯。"]},{"t":"水调歌头 留别澹心即用来韵","f":"古风","c":["离别亦常事，惆怅慎毋然。","归舟一路弄笛，吹裂水中天。","犹记吴趋坊后，再到惠山松畔，两地酒如泉。","不久聚花下，小别向风前。","白翎雀，鸡叫子，想夫怜。","岐王空宅，旧日法曲散如烟。","君有龙文百轴，近作小词一卷，千载定流传。","早觅贺怀智，亟付李延年。"]},{"t":"水调歌头 橄榄","f":"古风","c":["造物有本性，此味最高严。","清芬却带酸涩，品格压黄柑。","多少橘官软美，无数荔奴甘滑，侧目看新参。","谏议尔之职，膻毳我何堪。","析烦热，开结轖，涤尘凡。","颇闻人语，输与崖蜜十分甜。","长揖水晶人退，不诣内黄侯谢，径自返漳南。","独醒颇相忆，摇落在江潭。"]},{"t":"水调歌头","f":"楚辞体","c":["东海黄门老，疾革话悲酸，呼儿吾骨累汝，霜剪一灯寒。","休返田横岛上，何用要离冢侧，莫恤道途艰。","忆奉重华命，遣往敬亭山。","三十载，怜弱水，几回乾。","铁衣生既未著，鬼亦戍其间。","此地层崖沓嶂，正接蒋陵钟阜，紫翠涌千盘。","若有人兮在，竦剑守重关。"]},{"t":"水调歌头 早秋托兴","f":"古风","c":["秋色一天雪，林壑映新旸。","皎如三尺新水，出匣漾干将。","亟敞杉窗竹院，要使金风玉露，洒濯我轩廊。","飒爽上眉宇，皎洁到衣裳。","小楼上，望极浦，太微茫。","估船夜笛江上，并作十分凉。","安得中原豁处，饱看出栊苍狗，大猎一千场。","淅罢刀头米，射杀鹿边獐。"]},{"t":"水调歌头 平远堂雨中即事。林天友使君席上同曹顾庵、丁药园、胡存人、吴园次、六益、余澹心、尤悔庵、宋既庭、钱宫声、顾云美、伊人、天石、赵旦兮、毛行九分赋，共用烟字","f":"古风","c":["千古莺花窟，四月雨晴天。","阑干一望平远，浓淡石湖烟。","催取茶鎗酒幔，唤得筝师篴伎，来做饯春筵。","且起舞回鹘，休去听啼鹃。","觞未半，风乍起，雨铿然。","嵯峨古塔将压，抉屋势斜穿。","万斛铃音铎语，四壁鲸呿鳌掷，劈裂几条弦。","脱帽叫奇绝，此景倩谁传。"]},{"t":"水调歌头 读董舜民苍梧词题后","f":"古风","c":["老屋数间耳，世事不关渠。","堆墙牛腰囷蠢，巨束笋般粗。","中有奇文兀奡，每夜必腾光怪，鳌掷与鲸呿。","力压古声叟，气慑万獠奴。","珠零乱，玉夭矫，翠模糊。","我行以手扪摸，作此定谁欤。","既似苔纹瓦篆，又似碑残鼓齾，字里吼于菟。","乃是兰陵董，词集曰苍梧。"]},{"t":"水调歌头 画楼诗为西陵吴子玙赋","f":"古风","c":["有客向余说，昨又到湖头。","湖中翠奁未敛，湖畔水明楼。","万本澄心堂纸，千页大观楼帖，百幅李营邱。","盘礴此楼上，缥缈紫绨裘。","风弄麝，波漾縠，浩悠悠。","涌金门外新月，听足采菱讴。","分付危栏飞槛，莫遣于祠岳墓，烟景触帘钩。","贮酒兼贮茗，不贮古今愁。"]},{"t":"水调歌头 渡长荡湖望三茅峰","f":"古风","c":["我住太湖口，四面匝烟鬟。","周回萦青缭黛，中托白银盘。","且纵龙宫一苇，耕破琼田万亩，笑傲水云宽。","篷背唱铜斗，沙尾辨金坛。","雪浪吼，大鱼出，矗如山。","茅家兄弟笑我，前路足风湍。","君自骖鸾翳鹤，我自骑鲸跨鲤，各自不相关。","挥手谢之去，吹笛弄潺湲。"]},{"t":"水调歌头 睢阳寓馆感旧题壁","f":"古风","c":["惆怅复惆怅，直视草茫茫。","风摇葵子藚叶，蝼蝈上空墙。","满目西州门内，转眼黄公垆畔，前事惹思量。","摇膝并负手，绕柱更循廊。","天欲黑，灯半绿，月微黄。","中年哀乐，何况人又在他乡。","飘去娇丝脆板，留下残香剩茗，狼藉小纱窗。","拨置不足道，念此断人肠。"]},{"t":"水调歌头 送侯叔岱之彭城","f":"古风","c":["酒罢忽不乐，结束挽强弓。","彭城此去苍莽，水蓼满陂红。","戏马台边骋望，下有河流似弩，混混尽鱼龙。","吾意欲起舞，屈指几英雄。","斜阳恨，关山影，一杯中。","袁曹刘项，付与烟草没孤鸿。","莫管千秋閒事，休误一生作达，笳吹竞西风。","盼盼去已久，明月小楼空。"]},{"t":"水调歌头 忆商邱宋介子西湄草堂","f":"古风","c":["雪苑女墙外，水色绿于苔。","郭南潭子尤胜，淼淼浸楼台。","长记升平旧事，弥望风亭雨榭，荡桨百壶来。","谁向乱前说，说罢使人哀。","西湄好，忆客夏，寄高斋。","南烹为余细糁，棐几净纤埃。","君笑热由卿至，仆笑羹应还我，戏语类优俳。","摇橹没烟去，背指野棠开。"]},{"t":"水调歌头 新秋寄骥沙徐仲宣","f":"古风","c":["秋色洁于雪，澄湛到帘钩。","凭轩忆尔更剧，君亦念余不。","记客泉亭草寺，闲弄吟篷钓笛，相与狎沙鸥。","一笑别君去，四节忽如流。","大江边、残照里，仲宣楼。","烟波虾菜，料尔生计尽优游。","此地孤城绝岛，长被蛟涎兔汁，鍊足一天秋。","横竹吹阿滥，叫醒千古愁。"]},{"t":"水调歌头 溪泛","f":"古风","c":["谁送半城绿，恰是两溪风。","茫茫银涛雪浪，天水有无中。","每到簟纹平处，不觉水香肥极，一色玉玲珑。","最恼闲鸥鹭，偏解占空濛。","驾一苇，淩万顷，浩无穷。","今宵圆月定好，寄语织绡宫。","脱帽五湖风景，捲幔半生心事，杳霭纵吟篷。","一笛中流发，乃是绿蓑翁。"]},{"t":"水调歌头 题毛会侯戴笠垂竿小像","f":"古风","c":["水色绿如鸭，又似乍磨铜。","靴纹细浪忽起，飒飒夹溪风。","数里江村茆屋，一带芦汀蟹舍，下遍钓鱼筒。","云作蔚蓝缬，衬以晚霞红。","燃楚竹，炊香糯，五湖东。","新来溪友堪讶，乃是大毛公。","赢得罛师拍手，汝有金貂玉佩，讵是绿蓑翁。","笑起唱铜斗，馀响落蛟宫。"]},{"t":"水调歌头 汾西侯仲辂示我九日纪梦词二阕依韵奉和 其一","f":"古风","c":["月落边墙黑，几扇雁门开。","苍然西极风雨，都向二陵来。","闻说胭脂小伎，能唱横汾旧曲，家傍古轮台。","我欲与之语，红粉最怜才。","饮醇酒，近妇女，莫疑猜。","世间馀子何限，两手底须推。","安得飞狐峪口，偕汝吹箫击筑，一日笑千回。","绿酒不晓事，有闷未能排。"]},{"t":"水调歌头 汾西侯仲辂示我九日纪梦词二阕依韵奉和 其二","f":"古风","c":["一笑老松下，握手亦前缘。","昨宵黄花节候，妒汝小游仙。","推道巫云入梦，谁料玳筵真个，事已遍流传。","我在银笙底，偷谱鹧鸪天。","追代马，挟赵瑟，是何年。","兵家女有殊色，可许阮公眠。","讵少朱门丝管，那抵青楼帘槛，如镜复如烟。","天上兔华满，只照别家圆。"]},{"t":"水调歌头 毛会侯席上限咏鹿脯诗，词以代之，同王惟夏、方雪眠、毛大可、允大诸君赋","f":"古风","c":["那晓鲁公帖，有手且飞觞。","觞行更催擘脯，此乐甚堂堂。","笑寄鹿皮翁语，乃有神仙上界，欲以汝为粮。","玉馔莫深恨，底事不潜藏。","呼毕卓，牵阮籍，态颓唐。","百年所得有限，不若醒而狂。","热洛河须痛饮，明日北风大作，结束上平冈。","箭作饿鸱叫，袒裼猎黄獐。"]},{"t":"水调歌头 初夏吴门舟次董樗亭钱葆馚留饮顾梁汾适至即席分韵","f":"古风","c":["往事细如雨，新水滑于罗。","十年才一会面，不饮欲如何。","雪抑松江银鲊，黄铸洞庭卢橘，酌以小红螺。","仆素不胜酒，醉态亦傀俄。","相乐也，复相泣，起婆娑。","眼中之人老矣，春后落花多。","休管谁家龙凤，不若狗儿吹笛，伴取胆娘歌。","小别数日耳，榴月复经过。"]},{"t":"水调歌头 酬别沈凤于即用来韵","f":"古风","c":["君住马溪上，我住滆湖中。","平生酒颠花恼，此事那输公。","自逐鹓班鹭队，回忆练裙檀板，甚日恰重逢。","也料秋江畔，开到粉芙蓉。","人世事，枝向背，絮西东。","青山见人分袂，替作别时容。","纵使锦袍入直，讵抵绿蓑听雨，钓艇漾晴空。","他日访君处，烟水定留侬。"]},{"t":"水调歌头 庚申五日","f":"古风","c":["又是女儿节，何处贳香醪。","艾装碧虎闪烁，与汝复相遭。","回忆家乡此际，不少痴儿騃女，綵鹢绣旗摇。","蹙起一川雪，崩落半空涛。","渚宫远，沣水阔，恐难招。","古来陈事何限，细数总今朝。","楚国湘累自苦，齐国薛君自乐，一笑等鸿毛。","我自饮我酒，卿自读卿骚。"]},{"t":"水调歌头 纪恨为魏里张太君赋","f":"古风","c":["越国燕莺地，春日绮罗年。","张星本连天上，朱户隐㛹娟。","谁料罗窗绣阁，吹到零风冷雾，飘散亦前缘。","旧日画眉事，追纪那能全。","织锦曲，缄情泪，寄谁边。","漳河独火小店，彻夜雨绵绵。","请看古来青史，何限伤心红粉，唱煞隔江船。","且尽一杯酒，莫拨四条弦。"]},{"t":"水调歌头 元夕前董樗亭至都下，樗亭昨岁射陂遇盗，身被重创，患不克来，今之来也，词以志喜，即用樗亭见赠原韵","f":"古风","c":["月黑淮南县，卸驮正关门。","门前声息汹汹，势若雨倾盆。","斫臂霜刀攒猬，燎瓦狐灯掣电，骇绝洞心魂。","讵复有活理，遑暇顾琴尊。","重握手，惊往事，剪灯论。","追思胥江酒伴，只我与君存。","三客弱来一个，公又几为异物，软语剪难分。","抹眵细相认，老眼日来昏。"]},{"t":"水调歌头 赵北口作","f":"古风","c":["忽复出门去，万事总由天。","难忘只有烟水，永不罢相怜。","此地燕南赵北，尽日黄尘白草，那抵旧溪山。","讵料故乡景，陡落笋舆前。","鄚州镇，大沽口，水云宽。","空明浩淼，碧筱红蓼满汀湾。","也有鱼羹莲米，安得笛床茶臼，水阁两三间。","卧听吴娘橹，带暝唱歌还。"]},{"t":"凤凰台上忆吹箫 广陵送孙介夫之石城","f":"古风","c":["红板桥头，方山栅口，中流冷拨吴装。","正萤飞冰簟，蝉咽银床。","经过郗僧施宅，青溪曲、曲似回肠。","云水外，千年陈迹，一片新凉。","堂堂。","过江人物，记畴昔狮儿，亦号孙郎。","奈残山剩垒，极浦斜阳。","持底寄愁天上，君须问、旧日平康。","还则怕，菖蒲花老，燕子楼荒。"]},{"t":"凤凰台上忆吹箫 汤阴城外十里，丝杨夹堤互引，额以柳廊名极竛隽，词以纪之","f":"古风","c":["淇水潺湲，爵台馺遝，中原泼火年光。","渐汤阴城下，陈迹荒凉。","一带丝杨蘸马，晴漪皱、宛转长廊。","萦人处，轻阴轻暝，窨就鹅黄。","思量。","添些蝉韵，便一襟秋思，那让吾乡。","记离离水驿，小小虫娘。","白苧新裁春雪，凭肩处、柳外贪凉。","中年也，情随飞絮，一样微茫。"]},{"t":"凤凰台上忆吹箫 本意","f":"古风","c":["贵主亭台，真妃环佩，月中凤吹悠悠。","占人间天上，两处风流。","一自彩鸾齐跨，双携手、玉宇琼楼。","咸阳树，宫娥怅望，仙驭难留。","回眸。","人民都换，望渭水秦川，顿惹閒愁。","叹重关百二，废苑成秋。","千载鲍鱼孙子，沙邱路、大药难求。","逌然啸，青天碧海，夜夜清讴。"]},{"t":"凤凰台上忆吹箫 题宋楚鸿倚楼词卷","f":"古风","c":["百万呼卢，十千买醉，世间何策驱愁。","惹铜仙多事，铅泪长流。","一片唐陵汉寝，遗基在、舞罢歌休。","何况是，败荷衰柳，总不宜秋。","凝眸。","金荃一卷，问宋玉家乡，陆瑁湖头。","怅频年踪迹，只客皇州。","欲觅燕昭旧事，高台畔、野水悠悠。","无聊甚，闲吟闲写，满幅银钩。"]},{"t":"梦扬州 蘧庵先生久客维扬词以寄怀","f":"古风","c":["蜀冈头。","记狂夫、旧日曾游。","薄倖樊川，赢得一梦青楼。","红桥上，藕丝菱蔓，当时费尽凝眸。","平陈业，烟花记，可怜逝水悠悠。","老矣先生何求。","也雨楫烟帆，北谒诸侯。","鹤发开元，老泪铜仙争流。","红衣落尽西风起，怕隋堤、最不宜秋。","隐隐见，一江灯火，人隔扬州。"]},{"t":"塞孤 早春寄周伯衡先生并讯倪子闇公","f":"古风","c":["问湘天，滴黛何时歇。","曾记周郎英发。","坐拥油幢临大别。","军笳奏，乡心截。","舳舻湓浦如麻，铠甲庾楼成雪。","严飙破碛，古树都裂。","孤蓬暂入吴，老鬓终怀阙。","第二泉声呜咽。","瀑走银虬三四叠。","冲动防身剑箧。","料此际、共儿宽，看水上、粉英结。","定吟残、乱山白月。"]},{"t":"塞孤 宣武城外书所见","f":"古风","c":["北风如箭吼，城门启。","不断香车流水。","侧卷绡帘拖燕尾。","巫鼓唱，蛮箫赛。","乌孙别、紫台人，黄鹄寡、青溪妹。","粉襟儿畔，多少红泪。","谁唱敕勒歌，诉尽消魂事。","绣镞残骸攒猬。","树腹崖根潜老魅。","招蜀魄，呼湘鬼。","鹃已叫、洛阳城，鹤未返、辽西市。","总春闺、梦中夫婿。"]},{"t":"八节长欢 元日后二日，积雨新晴，偕大鸿、云臣散步城南，望铜官一带翠色，眷恋久之，不克，游南岳而返","f":"古风","c":["竟欲成村。","似曾著雨，第五桥边。","盈盈临水寺，脉脉弄晴天。","溪痕入画年光惹，醉绕城、荻市茶船。","最好雏春乍霁，帽侧襟偏。","群峰一笑嫣然。","高低影，数行秀鬋堪怜。","所袂倚风前。","凝薄恚，迎人却又迁延。","恼何事，未斜阳，客子将还。","终有日、棕鞋笋屐，细续前缘。"]},{"t":"卓牌儿 夏日咏闺人斗叶子","f":"古风","c":["遥窥两重门，群掩映、凝烟碧幌。","卐字槅底，凭肩语笑，冰纹廊后，亸鬟沈想。","风流小南唐，金叶子、描鸾小样。","斑几滑笏玲珑，蜡笺纤脆轻盈，打来偏响。","七红四赏。","更花戳、京城新创。","兰闺似掌。","俨楚汉情状。","赢得帘西红鹦鹉，也隔屏山注望。","私讲。","笑粉装刘项。"]},{"t":"卓牌儿 联吟为阎牛叟赋","f":"古风","c":["谁填杏花天，却满幅、春愁无赖。","凤纸正叠，狸毫乍弄，笼鹦报道，娘来帘外。","新词讶轻狂，一半是、狂奴故态。","几遍绕柱循廊，一回暗想胡猜，蹙他蛾黛。","瓶容旋解。","毕竟是，清新堪爱。","乌丝小楷。","要麝墨新洒。","今日营斋营葬讫，石竹罗裙早坏。","裙带。","字斜行还在。"]},{"t":"天香 中元感旧","f":"古风","c":["夹路幡竿，盈城梵呗，分明元夜灯市。","露湿巫箫，秋生赛鼓，头上月轮初霁。","金波潋滟，还泻做、万家红泪。","天与玉容争淡，烟飘粉裙偏丽。","许多流莺声细。","似啼猿、楚峡嘹唳。","只有小坟新冢，谁修薄祭。","空伴唐陵汉寝，都一样、凄凉野田里。","黄土鸦鸣，白杨风起。"]},{"t":"天香 龙涎香","f":"古风","c":["万斛蛟漦，千堆蜃沫，沈沈碧海今夜。","湘蛾倚殿，贵主还宫，新捣都梁无价。","金盆煎处，趁月里、桂华初谢。","浓染鲛人茜泪，小衬冯夷冰帕。","天风彩鸾斜跨。","杜兰香、水边閒话。","几遍龙堂游戏，蓬莱乾也。","多少望陵愁梦，空剩得、分香雀台瓦。","散与人间，斗他檀麝。"]},{"t":"汉宫春 送郝元公先生之任宛陵","f":"古风","c":["秋色佳哉，剪绿帆半幅，与雁同飞。","船头新旸似雪，津树霏微。","后堂丝竹，记频年、屡解谈围。","真豪迈，传经刘向，肯言心事终违。","此去云山万叠，近天门牛渚，采石蟂矶。","今朝临风酾酒，往事都非。","江声千尺，推篷望，吟遍斜晖。","偏相羡，敬亭山色，朝朝得上君衣。"]},{"t":"汉宫春 送子万弟入都次梁棠村先生送舍弟南归原韵","f":"古风","c":["此际东吴，正黄菊离披，紫螯郭索。","作装底急，使我伤于哀乐。","西堂夜话，算曾经、几番晦朔。","又来朝，河桥判袂，匆匆弟酬兄酢。","昔日扬乌项橐。","须臾吾已老，凤飘鸾泊。","乌衣门巷，变做豆花篱落。","半生牧豕，问何年，离蔬释屩。","喜余季，来春花暖，休恨一官禄薄。"]},{"t":"汉宫春 赠梁苍岩先生次先生赠子万舍弟原韵","f":"古风","c":["缘鬓勋名，响上相靴刀，风生铃索。","筹边多暇，细马潜游平乐。","神仙富贵，总兼之、笑他饥朔。","擘词头，锦笺十样，朝朝翠酬红酢。","前岁粤装陆橐。","正花洋珠海，楼船停泊。","蛮天红豆，争向句中飞落。","独怜愁客，老泥涂、蹉跎芒屩。","幸当世，有公知我，莫管五陵轻薄。"]},{"t":"汉宫春 立春后一日雨雪从友人斋头醉归纪事","f":"古风","c":["婉娩熙春，有比邻药玉，计日安排。","昨朝新做綵胜，绿剪红裁。","几丝酥雨，酿浓阴、腻透铜街。","今朝又。","腾腾微雪，轻盈扑上人钗。","便拟放颠冲酒，要粉摇歌袖，玉溅吟䰄。","最喜银装世界，白佔楼台。","春泥没屐，怪枯筇、难稳芒鞋。","高楼上。","雏莺笑我，刘伶醉倒须埋。"]},{"t":"汉宫春 春夜听盲女弹琵琶词","f":"古风","c":["满院梅风，搅一钩纤月，糁上帘须。","檀槽有人慢撚，盘泻珍珠。","鼕鼕画鼓，似开元、妙手花奴。","奇哉技，飞扬感激，胜于读史迁书。","太息东篱实甫，有无穷块垒，墨染烟驱。","一声通仙铁笛，碧海云孤。","青衫湿透，问伊怜、旁有人无。","还相调，轻云蔽月，今宵渺渺愁余。"]},{"t":"雨中花慢 雨中过蘧庵先生宅看红梅","f":"古风","c":["白傅堂前，裴相庭中，一株浓艳垂垂。","恰拖将轻雨，亸尽腰肢。","绒索猩唇唾后，泪珠鹃舌凝时。","似恹恹宿酒，惯趁朝妆，来晕春肌。","嫣然一笑，悄无人处，倚栏心事谁知。","亟倩茜衫笼著，绛袖盛之。","带雪三分粉绽，秋阴一朵红欹。","还须嘱付，小楼钿笛，莫漫频吹。"]},{"t":"烛影摇红 丁未元夜","f":"古风","c":["第一良宵，雨丝搅得愁心碎。","六街铺遍是春阴，火树无人赛。","年少俊游不再。","剩恹恹、夜情私耐。","懒提箫局，慵整衾窝，有些寒在。","忆昔欢娱，堕钗小拾春城背。","自从圆月打头来，照见狂奴态。","直到收灯挑菜。","叹如今、事随年退。","藕花裙子，红漆车儿，抛人十载。"]},{"t":"烛影摇红 丁巳上元夜泊河桥","f":"古风","c":["露驿烟庄，一般箫鼓千门沸。","银毯綵幔四围红，漾遍斜桥里。","曼衍鱼龙百戏。","闹蛾儿、游童成队。","非无粉帕，亦有檀钗，暗中潜坠。","回首春城，上元风景依稀记。","今宵一棹缆烟汀，懒打看灯谜。","且引村醪自醉。","枕渔蓑、和愁早睡。","迢迢往绪，历历前情，付之流水。"]},{"t":"帝台春 五月南徐怀周翼微在都门即用其江上留别原韵","f":"古风","c":["红瘦成碧，鲥鱼堆网白。","怅杀年光，回首春前，旗亭饯客。","公路浦君为远别，吕蒙城、我无相识。","记曹家，园上看花，疏狂那夕。","高齿屐，黄金戟。","行不得，愁何益。","叹命不如人，雄姿俊侣，此日一齐抛掷。","试咏洛生谁解作，拟邀曲部何从索。","闷坐忆周郎，听江声千尺。"]},{"t":"暗香 柬竹逸讯荫绿轩前梅花消息","f":"古风","c":["晓寒正侧。","怅今春天气，连朝如墨。","郭外小桥，几树红香受寒勒。","况是风前水畔，有多少、明妆倾国。","也伴著、细雨轻烟，零乱翠帘隙。","悽寂。","正小极。","似十五玉娥，舞困无力。","僧楼伎席。","记得常年暗香积。","谁料误他花信，偏则惹、粉腮轻湿。","问甚日，含笑觑，素英狼籍。"]},{"t":"暗香 栀子花下有感","f":"古风","c":["夜窗全黑。","被一株栀子，凝来通白。","拂水著烟，轻袅风枝送香雪。","三十年前往事，曾记在、康崇坊宅。","见小玉、罗袂亭亭，含笑趁凉摘。","今夕。","重露滴。","总一任好花，满院狼籍。","暗巡花侧。","不见裙痕并鞋迹。","提起同心两字，人正隔、银墙千尺。","花在手，谁戴也，碎挼花掷。"]},{"t":"暗香 吴静安姑丈临风阁上赏梅","f":"古风","c":["玉堂人物。","况阶前琼树，一枝先发。","近手花欹，小倚晴楼汎香雪。","料理茶铛棋局，更乍破、蛟冰芳冽。","恰糁入、片片繁英，和取索郎啜。","幽绝。","恁时节。","又脆管娇丝，隔垣低揭。","红缄半拆。","脉脉相看倍亲切。","若待盈枝烂熳，怕误了、人生作达。","薄醉也，压帽是，一堆粉月。"]},{"t":"八声甘州 南耕斋中食鲥鱼作","f":"古风","c":["汝鱼乎、汝既弄潮来，何如趁潮归。","却波涛堆里，橙齑香处，自许轻肥。","千古断矶黄鹄，不了是和非。","贪听渔翁笛，误触危机。","谢汝崎岖万里，把浪花舞破，来慰晨饥。","问途经西塞，果否飐旌旗。","幸团圞、故园兄弟，况小窗、雨后漾晴晖。","浮生乐、无如斫鲙，安用呼豨。"]},{"t":"八声甘州 寄宛陵沈方邺兼怀梅耦长","f":"古风","c":["记西风、握手秣陵隈，苦语劝君归。","叹尉佗城下，小姑山口，风景全非。","何事年年作客，牢落寸心违。","且与王章妇，对泣牛衣。","谢尔吾言竟用，果幡然归葺，云壑烟扉。","更梅郎健在，酬和未应稀。","只伶仃、画溪野老，况今年。","烽火雁难飞。","关情甚、敬亭栗罅，石臼鱼肥。"]},{"t":"八声甘州 丙辰夏月，蘧先生游广陵，诸同人以先生昨岁七秩，补作诗画奉赠，初秋归里持以示余，遂于卷尾亦题一章","f":"古风","c":["恰秒江、袅袅碧于烟，先生峭帆归。","有锦贉麝㡠，芙蓉养纸，豆蒄缄题。","更爱写生妙手，烘染自蛾眉。","花月扬州路，犹未全非。","曾唱千秋岁引，向春灯挂处，满汎玻瓈。","羡铜仙鹤发，今古似公稀。","偶重经、玉人桥上，惹群真、争谱鹧鸪词。","閒披赏。","莼丝正熟，菰米刚肥。"]},{"t":"夏初临 杜鹃花同云臣赋","f":"古风","c":["昨夜枝头，问谁啼血，洒来并入花丛。","纵使春归，也须偷注殷红。","为伊细数行踪。","记乡关、栈阁千重。","曾随花蕊，葭萌驿前，一路飘蓬。","淡烟粉水，斜月绵州，华阳士女，蜀国丝桐。","便为花鸟，魂犹恋此安穷。","欲拜低头，最怜他、姓氏相同。","莫愁浓。","溪山此间，不异新丰。"]},{"t":"夏初临 雨泊洴练","f":"古风","c":["柳尽笼桥，罾多界浦，片帆闪碎波光。","鴳浪堆中，笛声散入微茫。","落花时候鸣榔。","笑洴来、雪练何长。","沙禽野鸭，啼晴唤阴，飞触船窗。","飒焉飓作，倏尔溪昏，盘涡瀄汨，紫凤腾骧。","涛奔万马，依稀屋瓦昆阳。","且泊轻航，贳香醪、暂浣愁肠。","渐昏黄。","烟潭水楼，尽点银釭。"]},{"t":"夏初临 立夏日雨中作","f":"古风","c":["乍过花时，才逢笋候，碧窗春去无踪。","似别情人，河桥愁盼征篷。","打梅摘豆俱慵。","正漫天、丝雨濛濛。","梦回酒醒，巡檐倚阑，离绪重重。","一场惆怅，半榻瞢腾，暂携溪老，閒讯渔翁。","落花天气，从君脱帽江东。","绿满长空。","笑几番、汉苑秦宫。","暗帘栊。","玫瑰成阴，渐逗薰风。"]},{"t":"梦芙蓉 寒月","f":"古风","c":["倍觉姮娥寡。","奈金波早冻，素光空泻。","此时帝里，六馆并三瓦。","拥炉围粉帕。","畴怜夜景如画。","让碧空中，只一丸独自，冷向凤楼挂。","除是贺兰山下。","老将营门，看得分明也。","清辉纵好，此外谁知者。","长宵更鼓打。","兔华莫也生怕。","且待新春，点红灯万盏，照著闹蛾耍。"]},{"t":"月边娇 己未长安元夕","f":"古风","c":["元夜年时，记水榭狂游，驿桥閒趁。","梅梢月上，楼檐灯挂，媚蝶闹蛾成阵。","春泥松软，镂十里、凤城鞋印。","小门残火，见多少、澹妆轻粉。","如今独客京华，料还怪我，归期难准。","金钱浪掷，紫姑羞卜，长自盼人书信。","晚寒偏嫩。","悄地向、冰蟾低问。","清辉何苦，照一宵潘鬓。"]},{"t":"醉蓬莱 积雪为桥和云臣作","f":"古风","c":["借连宵积雪，戏作银桥，横眠街路。","却也玲珑，现雕阑绣柱。","驾此何为，从来官道，有瞿塘滟滪。","笑倒春城，往来车马，纷纭士女。","追想当年，秦皇汉帝，鞭石为梁，霓旌西去。","万里鼋鼍，叹红颜难驻。","老子神通，偶然游戏，学填河鹊羽。","今夜桥成，看余矫首，共安期语。"]},{"t":"醉蓬莱 感遇二首 其一","f":"古风","c":["向斜阳红处，长歌斫地，忽然悲啸。","才烂樵柯，又尘生瑶岛。","一片江山，千村芦荻，剩几人屠钓。","拟抱冰弦，夜深弹向，黄陵古庙。","且约酒徒，閒过伎馆，掷帽狂呼，绕床大叫。","坐上何人，识袁家彦道。","历历神州，茫茫澥宇，问谁为刘表。","感慨登临，月明乌鹊，南枝绝少。"]},{"t":"醉蓬莱 感遇二首 其二","f":"古风","c":["把数行青史，读向床头，仰天孤啸。","可惜桃花，又落来琼岛。","谁是谁非，磻溪严濑，千古同垂钓。","准放狂颠，行歌乱冢，醉眠丛庙。","旷野苍茫，晓山重叠，红日将生，海天鸡叫。","残梦惊回，怅华胥古道。","一片旌旗，三更鼓角，怕吹来江表。","且向垆边，问他春瓮，酒存多少。"]},{"t":"醉蓬莱 碧山庄看杜鹃秦以新太翁留饮花下有怀对岩检讨","f":"古风","c":["折一枝笑问，也把鹃呼，尔何愁苦。","绿暗园林，点深红千树。","但到花间，休论身外，有酒何妨住。","况是今朝，弦管莺啼，池亭燕乳。","停杯忽忆，故人千里，鄂渚牙幢，武昌楼橹。","万一思乡，写断肠佳句。","那得凭阑，将花做鸟，向楚天低处。","黄鹤楼前，殷勤为我，叫他归去。"]},{"t":"醉蓬莱 虎邱月夜见有贵官呵止游人者戏填此词","f":"古风","c":["正歌场匝地，舞榭临风，碧天如昼。","官自何来，拖麟衫艾绶。","从事喧豗，郎君贵倨，禁游童趋走。","千载吴山，一场秋兴，月僝花僽。","黄鹤飞仙，玉清谪吏，偶趁风光，閒来林薮。","见此尘容，展轩渠笑口。","七贵貂蝉，五湖烟水，问谁堪长久。","且掣青萍，化为铁笛，作狂龙吼。"]},{"t":"醉蓬莱 戊午人日为曹曹溪广文寿","f":"古风","c":["喜新年七日，蕙雪微融，梅风才转。","百福钗幡，做蓬莱家宴。","碧柰花前，绛桃树底，簇舞衫歌扇。","节候黏鸡，门风绣虎，六街传遍。","回忆生平，当时讲舍，沪渎云遮，泖湖天远。","一笑抽簪，趁閒身犹健。","兰茁阶墀，鲤趋庭砌，纵封侯谁换。","胜里春人，玉缸遥指，向先生劝。"]},{"t":"玉簟凉 夏景","f":"古风","c":["杉驿烟乡。","正屏掩楚峰，簟滑吴江。","得风篁欲笑，就食鸟相忘。","鲈鱼美似北固，四十九、入手先香。","晚饭罢，觅閒僧话暑，老树赊凉。","吴装。","白莲著粉，红藕放花，野鸭暗触船窗。","风灯零乱极，渐暝色微茫。","波上已逗素月，问卖酒、甚处阳昌。","吾醉矣，拟夜游、琼岛云厢。"]},{"t":"玉簟凉 己未长安七夕","f":"古风","c":["太液荷香。","怅良夜今秋，仍卧他乡。","输他天上景，又填鹊成梁。","一从上苑入直，金鱼佩、谁放疏狂。","瓜果宴，奈庾楼高处，风露偏凉。","秋光。","旧家节物，往日心情，赢得无限思量。","一钩眉样月，记曾照幽窗。","粉云此夜千里，盼不到、小院疏廊。","银汉底，料有人、和泪凝妆。"]},{"t":"黄鹂绕碧树 冬夜观剧感旧","f":"古风","c":["燠馆风帘软，红槽榨酒，冬宵温煦。","筝琶狎宴，是延秋杂爨，华清全部。","一声入破，乍催醒、庭花无数。","蓦提起、年少疏狂踪迹，许多情绪。","记得江南燕乳。","杏花村、绿杨才絮。","恁时节、惯量珠买笑，醵锦酬舞。","落拓半生好梦。","风和雨、都吹去。","可怜白发重经，酒旗戏鼓。"]},{"t":"庆清朝慢 憺园即景","f":"古风","c":["正复淡沲，居然萧远，此中位置殊难。","主人略旋烟墨，已就林恋。","几尺红泥墙子，被风吹乱月同弯。","花深处，玲珑金粉，一半才乾。","碧一队，黄一队，皴染得亭榭，在水云间。","朱栏绿莎厅好，映带潺湲。","尽日唼波花鸭，参差睡破簟纹閒。","登楼望，斜阳士女，又满春山。"]},{"t":"西子妆慢 四月朔日同吴天篆过通真观王鍊师道院看牡丹即用天篆昨岁雨中看花韵","f":"古风","c":["紫府玲珑，丹房窈窕，长就枝头娇嫭。","看花人逐蝶蜂忙，隔花试寻游侣。","醮坛侧去。","露几朵、檀痕浅注。","羡盈盈、比人间金谷，更饶幽趣。","花如语。","低撼金铃，小向暮春诉。","红颜最怕落花风，乞鍊师、为花重铸。","师还念取。","刘郎鬓、已经如许。","待来春、元都观又成前度。"]},{"t":"长亭怨慢 春雨","f":"古风","c":["小楼外、丝丝缕缕。","也似楼头，个侬情绪。","搅幕萦帘，惹人愁恨甚时住。","夜香笼袖，妆才罢、天还暮。","拟细炙鹅笙，笙亦为春寒，凤嘴偏努。","小屏风几叠，瞥见重重南浦。","因思江上，算今夜、有人羁旅。","纵有日、赊到春晴，晴不得、腮边红雨。","怎能勾、梨花门掩，双双笑语。"]},{"t":"长亭怨慢 春晴和京少回用前韵","f":"古风","c":["正带梦、流莺碎语。","似诉帘间，已收宿雨。","此日墙头，花枝定是招行旅。","风光何处，总在斜桥极浦。","看才过收灯，却又是林边，春笋将努。","倚帘曾暗许，锦鳞来太迟暮。","连朝春困，浑欲倩、东风扶住。","便从此、炙杏烘桃，怕难熨、两眉愁绪。","凭阑久、斜阳红敛，渐沈霞缕。"]},{"t":"长亭怨慢 送曹二隐还郡","f":"古风","c":["记昨日、西风吹汝。","送到荆南，斜桥极浦。","船泊家门，水窗开在晚凉处。","与君兄弟，连夜作、销魂语。","语罢起而歌，一曲小秦王，为回鹘舞。","叹人生易散，记嘱分携休遽。","如何人说，竟私买、小舟归去。","吟不尽、故国秋光，听不得、天涯战鼓。","怕来夕、郡楼高望，閒愁无数。"]},{"t":"长亭怨慢 途次润州水涩舟胶柬何雍南","f":"古风","c":["自买得、霜篷风舸。","准办乘潮，秋衾梦妥。","讵信连朝，水窗还泊蒜山左。","愁多于水，水却似、真珠颗。","纵使似真珠，尽也有啼珠，添上些个。","故人江阁望，城外层层烟锁。","千帆载恨，谁料是、此间有我。","知甚日、丁卯桥西，随江鸟、片时飞过。","枉费尽、千挝柁鼓，一行樯火。"]},{"t":"瑶台第一层 秦园月夜听泉声用艺香词韵","f":"古风","c":["月影水痕都化碧，如游不夜城。","恰惊飞涧，陡然劈峡，溅沫难平。","阴森鳞鬣，还似玉龙，怒吼崚嶒。","真幽绝，添几声铁笛，一点茅亭。","凭陵。","狂歌一曲，夜深难得此空青。","嫦娥未睡，冯夷欲舞，宫殿俱晴。","乘风吾欲去，但神仙、何必东瀛。","洗银觥，笑醉看瀑布，认作霜藤。"]},{"t":"黄河清慢 清江浦渡黄河","f":"古风","c":["苍茫河声冲古驿，黄沙浊浪同色。","斜日谁来问渡，江南狂客。","醉倚柁楼吹笛，初入破、鱼龙悲咽。","古今多少英豪，最堪笑、南奔袁术。","几时瓠子功成，叹薪楗空劳，宣房难塞。","长啸忧时，自把宝刀閒拍。","且任短篷掀舞，不须怨、中原萧瑟。","城名下相，极望处、暮烟残荻。"]},{"t":"倦寻芳","f":"古风","c":["画堂左侧，绣槛东偏，朵朵轻俊。","欧碧姚黄，总是让他风韵。","紫府家乡原不远，红楼伴侣休相混。","记当时，恰一枝初颤，便曾厮认。","讵料是、六年一别，今日人归，倍添春晕。","满院浓香，砌就閒愁成阵。","雨后喜看娇态足，朝来怕见残妆褪。","这情怀，沈醉醒时，细将花问。"]},{"t":"月下笛 本意","f":"古风","c":["今夕何年，满天皓魄，一轮圆碧。","露桥水驿。","谁向风前喷笛。","趁关山、河汉夜凉，故将凤竹悽倦客。","正寒潭峭岸，离乡年少，凭江船侧。","当初曾记，趁寒食梨花，醉平阳宅。","念奴璚管，碎把画梁尘劈。","到如今、漂流路岐，西风落叶无相识。","月生烟，生怕铁龙，归海何处觅。"]},{"t":"孤鸾 赋得石亭梅花落如雪","f":"古风","c":["昨来时节。","记花倚晴阑，牵衣话别。","生怕重逢，未必有花堪折。","如今小楼仍上，果隔林、尽情飘瞥。","乱捲一天晴絮，映水半明灭。","正春阴暗把碧空黦。","似愁睹粉娥，临去凄咽。","谁唱阳关曲，仗数声啼鴂。","日斜游踪欲散，倩春衫、蘸些香雪。","图得盈盈归晚，有惜花人说。"]},{"t":"三部乐 题王瑁湖新诗卷首次田髴渊韵","f":"古风","c":["满幅清新，好谱上香弦，恨无纤手。","珊瑚七尺，石尉筵前尽有。","忆天上、几度花开，悔玉清轻别，凤侪鸾偶。","短拍长谣，迸碎鲛盘珠走。","御河连宵秋雨，换十亩残荷，一湾疏柳。","潜来擪笛宫墙，月明感旧。","墨迹离奇似斗。","半倒薤，半成急就。","馀兴淋漓，拚涴遍、舞巾歌袖。"]},{"t":"长亭怨 送徐郿伯还西泠倚玉田词韵同桐初京少蕺山次山赋","f":"古风","c":["有墙外、紫丁香树。","簸影钩帘，牵留数数。","可记年时，凤城灯市夜游否。","黄金台古，招手唤、燕昭共语。","霎地秋来，便去也、匆匆如许。","虽去。","暂盟鸥狎鹭，奈肝胆、酒边还露。","烹羔酌苦，归及见、江潮堆絮。","看万阵、犀弩张时，正百丈、银泷喧处。","意气尽昂藏，肯只鸣榔渔浦。"]},{"t":"应天长 红友约余辈重游石亭，以阴雨辞之，不允，复偕云臣、竹逸、放庵上人饮高士吴具茨墓下，落梅盈把，游情甚适，词以纪之","f":"古风","c":["寺桥阁雨，山馆弄阴，重游向时陂泽。","连袂行歌，依旧名僧与词客。","花妨帽，泥印屐。","便湿了、春衫奚惜。","疏圃外、映水一枝，旧曾相识。","对景且疏狂，莫负红瓶，潋滟倾春碧。","不见樽前，无数饥鸦作寒食。","庾家墓，王氏宅。","糁一片、落英堆积。","怕来岁，载酒城南，又是陈迹。"]},{"t":"真珠帘 咏雪珠","f":"古风","c":["瑶妃争取明珠拣。","误触金盘倾泻。","万颗玉匀圆，向小墀抛打。","淅淅泠泠敲不了，似阆苑、梨花都谢。","寒乍。","迸零钗碎佩，跳遍鸳瓦。","渐觉暗入琼肌，做红酥细粟，不禁春夜。","邻女惯娇憨，戏掬来盈把。","万斛鲛啼盛不定，只逗入、玉娥帘下。","轻洒。","怕一色难寻，粉裙绡衩。"]},{"t":"真珠帘 题宋牧仲枫香词次曹实庵韵","f":"古风","c":["当时红杏尚书句。","宋玉今朝风赋。","萤火柳绵词，斗阳阿激楚。","五色蛮笺螺子墨，渲染彀、微云疏雨。","凄苦。","满歌坊粉壁，舞巾纨素。","一曲减字偷声，听小屏风后，玉箫潜度。","低啭隔林莺，碎一庭花露。","鹍鸡又砉关山调，似万马、凭秋而怒。","相诉。","我中年以后，冰弦怕鼓。"]},{"t":"月华清 读芙蓉斋集有怀宗子梅岑并忆广陵旧游","f":"古风","c":["漠漠閒愁，濛濛往事，胜似柳丝盈把。","记解春衣，曾宿扬州城下。","粉墙畔、谢女红衫，菱塘上、萧郎白马。","月夜。","正游船争取，绿纱窗挂。","如今光景难寻，似晴丝偏脆，水烟终化。","碧浪朱栏，愁杀隔江如画。","将半帙、南国香词，做一夕、西窗閒话。","吟写。","被泪痕占满，银笺桃帕。"]},{"t":"月华清 十三夜舟泊望亭对月有作","f":"古风","c":["寂历烟汀，微茫水驿，尚隔吴山半舍。","懒慢长年，何不使船如马。","捣香齑、红糯微斟，靠锦树、绿帆初卸。","吟写。","听吴娘水调，旧愁重惹。","惆怅欢娱难借，似漂泊江天，客舟閒话。","冰彩无情，偏向愁边乱泻。","想连天、枫叶芦花，问何处、蝉钿罗帕。","今夜。","料王珣宅畔，风光如画。"]},{"t":"月华清 为蒋元肤催妆","f":"古风","c":["犀盒偷春，鹅笙沸夜，曲栏花睡初醒。","荀鸭微红，不许晚寒犹剩。","看门外、绛烛双笼，正楼上、麝巾低凭。","红定。","算全然不似，旧时三径。","寄语酒徒蒋济，总北酿清芬，休教酩酊。","渐觉帝城，玉漏隔花催暝。","怪何处、北阮疏狂，约来朝、西山寻胜。","谁应。","只推言且待，雪残冰净。"]},{"t":"月华清 病榻閒情为阎牛叟赋","f":"古风","c":["画尺吟瓢，笛床茗椀，屏当娟楚如昨。","记得前秋，满院西风斜削。","绽三朵、五朵疏花，映一层、两层帘阁。","墙角。","课獠奴棕帚，桐阴閒缚。","惯剪残灯读史，惹清狂夫婿，聊萧相谑。","今古干卿底事，祇须烧却。","便尘世、小住为佳，奈心情、年来偏恶。","黄鹤。","竟骑他奔入，月中偷药。"]},{"t":"玉蝴蝶 山游席上书所见","f":"古风","c":["十载鬓丝禅板，东风又起，吹到閒情。","谁遣枇杷花下，蓦遇卿卿。","绿水晓、满眶娇泻，垂杨软、一捻身轻。","斗倾城。","金九绿帻，分外盈盈。","回程。","兰舟同上，如规月白，似簟波平。","羞晕微红，半腮香玉脸潮生。","燕声松、解调闽语，莺喉脆、宛弄秦筝。","酒微酲。","小楼今夜，春梦难成。"]},{"t":"垂杨 上巳万柳堂雨中即事用竹山词韵","f":"古风","c":["花间微雨，响苏苏几点，乍听还小。","径冷泥香，凤城佳节游踪悄。","记曾骑马横门道。","有夹路、红深翠窈。","甚前番、社鼓饧箫，到今来偏少。","拚把春光湿了。","枉青粉墙西，酒旗斜袅。","扑蝶湔裙，梦华遗事何人晓。","落红旋被东风扫。","扫不去、閒愁缥缈。","纵然晴也，奈浓春渐老。"]},{"t":"无闷 益都冯相国夫人饮我以太和春赋此奉谢","f":"古风","c":["履道坊西，独乐园中，朝散沙堤似水。","拥绛帐生徒，青州从事。","唤取鸬鹚杓到，付侍立、清清小童洗。","咬春说饼，满船药玉，几瓯冰蚁。","风味。","倩谁拟。","似梅瘦春湖，茶香官焙。","尽濡甲郫筒，逊伊清绮。","曲部休嘲户小，也浮白、卷波如渴骥。","看泻向、粉盎霜瓷，一色白泱泱地。"]},{"t":"无闷 醉后排闷作","f":"古风","c":["长此安穷，定复不急，世事纷纷虎鼠。","笑狐尽带铃，荷偏成柱。","终日屋梁仰面，便著书、万卷谁怜汝。","休自喜，当日马中赤兔，人中吕布。","无补。","莫相疑，徒自苦。","今日一钱不值，李蔡下中，曾何足数。","且作槃中快舞。","更单绞、岑牟祢生鼓。","戏问君得哀梨，定当蒸食与否。"]},{"t":"燕山亭 和韵送魏禹平同京少蕺山次山赋","f":"古风","c":["为送人行，马上远山，也把晴蛾淡扫。","惜别情悰，中酒心期，自己殊难分晓。","一路相随，总输与、道旁春草。","来早。","怕梦里花多，意中人少。","计日迤逦吴关，和燕子杨花，一群齐到。","翠篷推处，白舫摇时，两岸露桃红小。","半幅蒲帆，浑疑是、掠波沙鸟。","尤好。","京口驿、鲚鱼上了。"]},{"t":"催雪 秋日过城南显亲寺","f":"古风","c":["潭北新秋，城南古寺，乱壑喧豗激濑。","爱虎落三间，渔蛮一带。","林际绀殿银墙，绣经幡、风定天花洒。","时来樵语，遥黏僧磬，暗添幽籁。","门外。","愁如海。","有野蔓荒榛，丛祠破冢。","闪石竹罗裙，多年色坏。","砌就苍凉景色，到路黑、灯青啼百怪。","只静侣、掩住禅关，日看国山螺黛。"]},{"t":"大有 春闺和片玉词","f":"古风","c":["亚字墙边，楝花风大，小楼中、帘捲人瘦。","满圆林、参差绿草谁斗。","屏山水鸟背人数，也何曾、爱单嫌偶。","恼恨柳色空濛，和烟锁画栏口。","灯前忏，花底咒。","小鸭恋红衾，清清坐守。","好梦瞢腾，愁到醒时依旧。","自谢了丁香后。","受无限、蜂僝蝶僽。","十年事、凝想如无，閒思恰有。"]},{"t":"新雁过妆楼 虎邱感旧","f":"古风","c":["绀殿雕轩，千人石、夜深曾记同游。","一天皓月，和烟罨住长洲。","谁奏定风波一曲，玉簪轻卸节秦讴。","蘸霜毫，题名偏向，青粉墙头。","重来莓苔蚀遍，更风吹雨打，往事都休。","回廊坼尽，数行难觅银钩。","池边重窥绝壑，只老树、斜眠压酒楼。","回船好，趁笛声未紧，归伴沙鸥。"]},{"t":"新雁过妆楼 再咏糊窗","f":"古风","c":["几扇疏棂，玲珑处、檀笺粉茧糊成。","夜来微雪，掩映更觉晶瑩。","做就贮愁函梦地，生疏踏月拗花情。","凭遮藏，偏被严飙，送到残更。","生平齑盐井臼，记欣然同听，败纸齐鸣。","今番燠馆，无奈一倍凄清。","无聊拈毫弄墨，倩小字、斜行春蚓萦。","閒题咏，把雪窗涴遍，何用通明。"]},{"t":"新雁过妆楼 围炉","f":"古风","c":["昨梦偷归，栏干外、雪花吹满帘衣。","门庭萧寂，绿窗景未全非。","榾柮乍红茶半熟，山妻绕膝小牢之。","剧喧阗，竞询狂客，江畔归期。","槛前小梅映水，被谁弹香粉，浅著横枝。","佛灯傩鼓，想应岁序旋移。","景阳钟声暗动，又官烛、更深欲灭时。","蘧然醒，笑红炉纵好，却不成围。"]},{"t":"丁香结 咏竹菇","f":"古风","c":["碎锦成斑，馀霞弄点，小圃胭脂隐隐。","正丛篁摇粉。","桃花靥、偷把烟梢扶衬。","竹郎门第好，姑年小、卯酒添晕。","潇湘二女去远，积下啼红盈寸。","淹润。","被雨后莺啼，唤出满林芳嫩。","樱笋年光，饧箫节候，做他轻俊。","小巷筠篮提入，带笑争相认。","似开元钱样，一缕娇痕巧印。"]},{"t":"琐窗寒 初春和云臣韵","f":"古风","c":["雪洒红窗，雨敲碧瓦，晓寒偏紧。","莺簧生涩，不似旧时淹润。","记前春、城南水边，内家车子绡成阵。","只新年节候，连阴做暝，误他花信。","点尽。","安仁鬓。","拚满幅春词，秦灰同烬。","纵然墨淡，还有啼红堪认。","况如今、苔花小笺，誓成乌鲗犹隐隐。","最难忘、梅月朦胧，不耐施脂粉。"]},{"t":"琐窗寒 乙卯元夕柬云臣竹逸竹虚","f":"古风","c":["今岁元宵，禁晴架雨，装阴做霭。","嫦娥何处，盼断一天冰彩。","遍春城、街泥未消，蕙花梅萼徒潇洒。","算六街寂静，火蛾罢闹，紫姑停赛。","窗外。","閒愁大。","笑冷淡光阴，岁华虚卖。","愔愔坊曲，残雪恹恹还在。","记当初、小市夜桥，月明笑语春如海。","叹如今、只有东风，乍小吹灯带。"]},{"t":"琐窗寒 本意闺情","f":"古风","c":["蛮字墙儿，冰纹槅子，谢娘三径。","乌龙怕睡，吠煞翠梧桐影。","蔚蓝天、一派雁程，年年耽误萧关信。","又栖鸦闹过，谁家玉笛，叫西楼暝。","愁听。","商飙劲。","便黑了一灯，唤人谁应。","银鸭娇憨，还泥薰笼偎并。","卸蜜簪、划月阑干，峭寒陡觉秋夜丙。","伴黄花、且熨红绵，冬釭应倍冷。"]},{"t":"琐窗寒 雪","f":"古风","c":["瑟瑟泠泠，漫天搅地，洒窗淋户。","旅情难妥，理煞也无头绪。","拚和他、琼瑶乱抛，风前都学梨花舞。","算侯门戚里，驼酥兽炭，几家笑语。","知否。","此间路。","是金粉关河，最消魂处。","几多旧事，总被六花飘去。","想外边、白遍长干，依然玉做南朝树。","惹江船、商妇琵琶，水上诉愁苦。"]},{"t":"金菊对芙蓉 禹州使院作","f":"古风","c":["雍氏亭空，大騩山老，一鞭袅尽斜晖。","正荒城苔绣，古驿花欹。","行人说是王孙第，怅金床、玉几都非。","巡檐背手，谁人怜我，情绪如丝。","此意枕簟应知。","共残釭青穗，伴我题诗。","叹星移物换，种种凄其。","不如且向东风外，好悲歌、聂政坟西。","明当竟去，频斟浊酒，细拂横碑。"]},{"t":"金菊对芙蓉 姜学在自宛陵扫墓归停舟过访即送其返吴门","f":"古风","c":["语响潭烟，橹鸣翠溪，他乡上冢人归。","恰停桡枉叩，竹下双扉。","相逢暗惹平生恨，西州路、事与心违。","羊昙已老，数行情泪，弹上君衣。","此去帆影霏霏。","正茂苑莲红，笠泽鱼肥。","叹吴中今岁，刈获全稀。","赁舂薄俗防人面，梁木萎、门户凋微。","怜君归去，乳鱼轩下，怅煞斜晖。"]},{"t":"金菊对芙蓉 送杨亭玉学博之任江浦和梁棠村先生","f":"古风","c":["棠邑名城，秣陵剧县，鳣堂坐对晴秋。","正人家夹岸，云物当楼。","扶风绛帐生徒盛，环讲舍、锦瑟红篝。","图书四部，才华六代，冠冕南州。","罨画暂尔淹留。","恰曲唱樽前，缆繫沙头。","盼离亭霜叶，黄重丹稠。","之官一水携家便，喜烟江、乍稳阳侯。","别来锦字，好寻双鲤，频溯中流。"]},{"t":"金菊对芙蓉 访单县琴台","f":"古风","c":["古树云平，荒台湍激，两贤留下祠堂。","见蛛丝网院，马苋围墙。","承尘画壁昏于梦，千年事、陈迹苍凉。","江南游子，无聊侧帽，有恨循廊。","迤逦渐下牛羊。","响落木西风，飒沓层冈。","怅琴声未杳，蘋藻谁将。","拟寻北地韩陵石，呼来语、相伴他乡。","那堪断碣，摩挲已遍，一笑斜阳。"]},{"t":"金菊对芙蓉 九日牧仲招同山蔚振衣楼登高填词惜别即次来韵奉酬","f":"古风","c":["梵客有言，悲哉气也，君家原不宜秋。","况帆停江上，人倚楼头。","菊英亦管人离别，赛柳绵、打块成毬。","那堪筵畔，轻敲檀板，缓节秦讴。","叹昔幕府风流。","羡落帽中原，戏马高邱。","更一时参佐，千载英游。","吾衰讵有风云想，算不如、岩岫清幽。","从兹归去，笔床茶灶，到处淹留。"]},{"t":"金菊对芙蓉 次前韵酬别山蔚","f":"古风","c":["郁郁中原，萧萧老鬓，不如归弄晴秋。","计数间茅屋，罨画东头。","每当月吐长溪口，水明夜、雪镜冰毬。","几村风叶，半湾烟渚，牧唱樵讴。","好趁淰淰寒流。","去窈窕崎岖，历壑经邱。","只离情还恋，梁苑朋游。","他乡老辈如君少，新诗句、兀奡空幽。","一樽尚暖，片帆聊卸，暂为君留。"]},{"t":"金菊对芙蓉 舟行遇大风仍用前韵","f":"古风","c":["雪浪鼍吟，布帆鸱叫，西风削碎晴秋。","看绿平楚尾，翠入吴头。","盘淌急洑孤光陷，铸一点、旸谷金毬。","柁楼长啸，汜人侑舞，海若供讴。","十载萍梗飘流。","只赁庑皋桥，卖饼安邱。","喜今朝尻马，仿佛天游。","水云混混黏无极，真欲犯、碧落空幽。","只怜今夜，琼宫高处，清冷难留。"]},{"t":"金菊对芙蓉 舟中有示仍用前韵","f":"古风","c":["泛泛清娱，迢迢樊素，相随单舸高秋。","学水云一色，浮渲梳头。","包山此去千峰橘，高低缀、耀日霜毬。","三更水面，吴娘橹响，一片清讴。","聊复映月乘流。","休袖倚沧江，回望商邱。","忍烟篷雨箬，故国清游。","簟纹双稳鵁鶄睡，君莫管、夜色幽幽。","祇愁商妇，隔船低唱，玉树鹂留。"]},{"t":"金菊对芙蓉 过侯敷文村居留赠仍用前韵","f":"古风","c":["紫艳牵裾，红香扑帽，手编花鸟阳秋。","有佳儿膝下，少妇楼头。","红栏粉壁吴船样，明棂外、蜂蝶成毬。","有时月上，前墟送到，牧笛樵讴。","一任金犊如流。","笑昔日金张，一半荒邱。","且芒鞋野服，散誔优游。","栽花晒药摊书外，无剥啄、人境双幽。","但逢酒熟，恰当花放，我到还留。"]},{"t":"金菊对芙蓉 舟次渐近江南仍用前韵","f":"古风","c":["或把琴书，或携粉镜，平分画舫清秋。","过女儿浦口，新妇矶头。","秋光澄湛明于雪，映水上、茜帐银毬。","敲针稚子，临风把钓，学唱吴讴。","依旧滚滚江流。","还半下吴门，半绕巴邱。","只江东麋鹿，几度来游。","迟归沙鸟应相笑，他乡景、有甚清幽。","黄花开过，紫螯卖过，谁把君留。"]},{"t":"金菊对芙蓉","f":"古风","c":["绣毂钿车，酒旗戏鼓，月明初浸延秋。","唤教坊全部，杂爨高头。","一声南内消魂曲，风乍定、灯袅红毬。","几层帘幕，一群莺燕，妙舞娇讴。","可惜四节如流。","背画槛低吟，华屋山邱。","怅朱门旧宅，红粉前游。","光阴负我堂堂去，空遗下、庭砌清幽。","阑干醉拍，鸿飞雪爪，往事难留。"]},{"t":"金菊对芙蓉 惠山夜饮坐有姬人同园次赋仍用前韵","f":"古风","c":["人比花娇，姓堪丝绣，问名云杜家秋。","且饼煎寒具，鲙切槎头。","相逢满酌梨花冻，欢场闹、打马抛毬。","忘忧馆后，水明楼上，妙啭轻讴。","酒罢暗诉飘流。","说家本严滩，门枕丹邱。","奈兵来雁荡，烽接龙游。","琵琶弹入思归调，助空山、落叶声幽。","江山如许，英雄难觅，旧日婆留。"]},{"t":"三姝媚 寄远用梅溪词韵","f":"古风","c":["柳线吹碧瓦。","记才倾别酒，泪同铅洒。","低拍萧娘，等吴枫红了，再来帘下。","讵料而今，折挫煞、游梁司马。","孤负伊家，蟢上琼簪，麝湮绡衩。","况是关河旅夜。","数长短更声，甚时方罢。","斜压红裯，曾化为蝴蝶，此欢无价。","恰又平明，好梦与、釭花都谢。","拟倩锦笺论恨，恹恹难写。"]},{"t":"三姝媚 纪半堂所见同纬云弟次山侄用湘瑟词韵","f":"古风","c":["重来偏寂寂。","算疏阑轻尘，粉纤曾拭。","两两雏鬟，记茜衫小露，水边门侧。","弄影凝妆，谁耐理、绣床刀尺。","閒盼山塘，细犊金舆，往来得得。","再向桥阴繫席。","只半艇烟昏，千檐雨滴。","此际兰闺，定双拥金凫，换吹钿笛。","眼底吴娃，枉自诩、娇红腻白。","其奈又经过处，断无消息。"]},{"t":"万年欢 赠宋子犹先生七十次朱致一原韵","f":"古风","c":["碧海青天，叹横江下濑，楼橹非昨。","贝阙龙堂，弹指绡宫乾却。","枪卧绿沈休拓。","任半世、凤飘鸾泊。","閒排纂、世史长编，朱黄细界疆索。","菰芦景略谁知，向窗前讽呗，肆上丸药。","老兴淋漓，一笑人间轻薄。","身亦北山猿鹤。","只一语、临风相托。","嘱渭水、好把纶竿，藏舟且付春壑。"]},{"t":"万年欢 寿毛卓人","f":"古风","c":["猿鹤相闻，说先生今岁，正满花甲。","又值秋晴，门外金风飒飒。","鹤背朝元薄醉，笑人世、沧桑一霎。","游仙倦、暂溷红尘，何妨佣保相杂。","当初竹林赠答。","记分携阮屐，争荷伶锸。","讵料栖乌，别后绕枝三匝。","谁识开元旧事，只除是、碧箫红蜡。","君须醉、莫负黄花，糟床琥珀新压。"]},{"t":"解语花 吴静安姑丈堂中闽兰盛开约同人过赏时有二校书在座","f":"古风","c":["玉堂窈窕，珍簟虚无，细压真珠榨。","萝阴石罅。","随风皱、一带回廊曲榭。","暗中香泻，列翠盎、轻扶红架。","羡高情、楚畹湘潭，助幽人消夏。","万朵珠承雪亚。","更花边浅立，人比姑射。","鬓蝉低卸。","微嗅处、不数海天冰麝。","裛来盈把。","总罨住、竹房茶舍。","倩繁弦、并鼓猗兰，将晚凉乱惹。"]},{"t":"解语花","f":"古风","c":["柳花似梦，莺语初圆，人遇章台下。","旧愁萦惹。","记曾与，宛转风轩水榭。","金丸抛洒。","佯不认、隔年司马。","恨无情、惆怅归来，拟碎揉花打。","因记杜陵元夜。","有春衣醉宿，肌沾冰麝。","重来繫马。","谁提起、昨夜月中私话。","扬州梦假。","烦寄语、嬉游小谢。","任盈盈、露井倡桃，向粉笺休写。"]},{"t":"渡江云 扬州感旧追悼西樵荔裳伯吁介夫诸先生并怀阮亭豹人穆倩定九舟次无言诸公","f":"古风","c":["扬州何限好，无情江水，送去渺天涯。","风流推宋玉，更有乌衣，门第旧琅琊。","珠帘璧月，宾徒盛、多少繁华。","记当年、水楼烟郭，满地采莲娃。","伤嗟。","一城画鼓，两岸红灯，共万家鸳瓦。","都付与、风彫菰米，浪打蘋花。","牧之已老青楼换，重经过、帽侧檐斜。","风定处，隔江隐隐琵琶。"]},{"t":"渡江云 送叶道子之任临清守府","f":"古风","c":["一鞭飞锦伞，凤城南去，红杏著花初。","建牙男子事，千骑东方，送尔上头居。","碧油幢捲，碾轻车、小猎平芜。","风流甚、茸茸绿草，浅映绣蝥弧。","愁余。","庾郎善赋，江令工文，任凭陵今古。","总输与、军中陶侃，江上周瑜。","何时玉靶元戎队，劈黄獐、烂醉驼酥。","毛锥子，问伊直一钱无。"]},{"t":"渡江云 送蒋京少下第游楚次储广期原韵","f":"古风","c":["向长安市上，仰天长啸，悔杀彩为毫。","月明无赖极，又照征南，万将赤霜袍。","掉头仍向，潇湘去、去采离骚。","算襄樊、几般往事，一半属孙曹。","舟摇。","天低滴竹，瘦黛凝斑，任崖倾峡倒。","恨茫茫、一军铁甲，九派银涛。","浔阳夜火黄州雪，应为我、徒倚无聊。","吾衰矣，漫劳送上云宵。"]},{"t":"渡江云 寒夜登城头吹笛有感作","f":"古风","c":["孤城横一片，千家楼阁，都在雁声中。","关河牢落甚，身世飘零，烟水太濛濛。","旧时赤壁，周郎少、正领艨艟。","有许多、银涛雪练，相映战旗红。","江东。","我携长笛，斜倚危栏，作霜林数弄。","总则把、平生遗恨，诉与长空。","一声才入梁州破，天风下、掣入蛟宫。","嗟横竹，慎毋灭没为龙。"]},{"t":"渡江云 欲雪","f":"古风","c":["碧翁将试手，趁春未到，要放一城花。","关河都冻紫，风惨云昏，冷色走龙沙。","笼窗拨火，料寒威、来早还加。","帘栊外、未曾飘瞥，吟兴已无涯。","山家。","当年此日，枯柳疏鸦，小柴门入画。","恰又是、梅边渡暝，雁低航斜。","玉尘休拟廉纤舞，念有人、新在京华。","凝盼处，预愁绿蚁难赊。"]},{"t":"念奴娇 龙眠公座上看诸客大合乐，记西酉中秋曾于合肥公青溪宅见此，今将十年矣。援笔填词呈龙眠公并示楼冈太史邵村侍御与三孝廉","f":"古风","c":["醉来阑入，正司空筵上，一群腰鼓。","老子婆娑床上坐，矍铄听歌似虎。","一片西风，千堆画烛，月好清辉苦。","回头往事，青溪旧梦重作。","谢公笑问儿郎，此閒何处，略记隋堤路。","老矣廉颇犹健饭，莫负红么翠羽。","人在当场，曲逢入破，白发休予侮。","新磨幡绰，世惟公等堪语。"]},{"t":"念奴娇 尤展成招饮草堂同丁飞涛彭云客宋既庭御之即席分赋同用飞涛韵","f":"古风","c":["别来何久，喜今朝坐上，五君二仲。","齐作镇西鸲鹆舞，舞罢持杯高讽。","蹴踏齐梁，凭陵晋魏，白眼看唐宋。","髀虽生肉，公然意气毫纵。","最是月落参横，主人留客，不放归鞭控。","能得几场花下醉，况是吴宫如梦。","锦瑟怜谁，青萍负我，快作临风弄。","唾壶阙尽，狂歌乱击春瓮。"]},{"t":"念奴娇 咏玫瑰花","f":"古风","c":["陡惊春去，算风光此际，又逢樱笋。","拂晓谢娘帘阁畔，忽逗卖花声韵。","篮底氤氲，担头狼籍，紫艳浓香喷。","佳人竞撚，看来和露尤俊。","最爱别样心情，天然梳掠，偏厌红英衬。","揉得花魂魂尽碎，另作一番安顿。","焙入衾窝，薰归裙缝，细细调红粉。","玉郎不觉，错疑戴向云鬓。"]},{"t":"念奴娇 八月初七夜对月呈李湘北太史","f":"古风","c":["帝城今夜，正万家齐看，一钩新月。","照过龙楼和凤苑，来照盈颠华发。","冷露初零，清辉未满，玉宇都清切。","六街香雾，也知丝管难歇。","最是太液词臣，金闺才子，对景偏轩豁。","退直玉鞭摇阙下，鸳瓦一时堆雪。","白可骑鲸，广能射虎，醉击珊瑚折。","料应相念，有人孤馆愁绝。"]},{"t":"念奴娇 初八夜对月饮纪伯紫处士寓仍用前韵","f":"古风","c":["挥杯一笑，恰举头又见，昨宵明月。","如此清光兼老伴，遗恨真无毫发。","莲子轻抛，蘋婆细劈，慢取橙齑切。","风前倚幌，满城晓角初歇。","可惜万事蹉跎，半生偪侧，难得胸怀豁。","谁把银河阶下泻，快作西山积雪。","感极关河，愁深砧杵，一寸心俱折。","为浑脱舞，乃公直是奇绝。"]},{"t":"念奴娇 初九夜对月饮吴默岩太史寓斋三叠前韵","f":"古风","c":["中宵狂叫，忆曹公有语，明明如月。","更记谪仙当日句，明镜三千白发。","入洛年非，游燕才尽，幸舍歌辛切。","空墙老骥，喷霜猛气难歇。","讵料宣武门前，长椿寺侧，竟见秋堂豁。","更借一尊桑落酒，光汎素瓷飘雪。","一片乡心，三更雁叫，拚把刀环折。","角鹰刷羽，脱韝固是横绝。"]},{"t":"念奴娇 初十夜对月同山右吴天章中州彭中郎吴门周子俶章素文饮汪钝庵户部寓庐四叠前韵","f":"古风","c":["虎邱石上，记曾经、看过几场秋月。","锦队花城浑不夜，一缕歌喉如发。","此际他乡，故人对酒，一倍关情切。","为欢休晚，中原军鼓初歇。","渐觉帝阙寒生，天街露悄，醉把双眸豁。","地界袁曹多战鬼，危语头须成雪。","萧瑟西风，凄凉北里，雁柱筝都折。","霜螯饱啖，不知前路愁绝。"]},{"t":"念奴娇 十一夜黑窑厂对月龚芝麓先生招陪诸公送董玉虬侍御之任秦中五叠前韵","f":"古风","c":["董公健者，到秦川、正看秦时明月。","立马灞陵桥上望，极目应添白发。","驰道云埋，重关日落，金铁争摩切。","慷慨怀古，西风飒飒难歇。","今夜客饯青门，马嘶珠络，好遣离愁豁。","高处凭阑飞火树，光映凤城如雪。","暂领河湟，旋朝京阙，丹槛看重折。","木皮岭上，燕书休使稀绝。"]},{"t":"念奴娇 十二夜对月戏柬刘公㦷吏部时吏部新纳姬六叠前韵","f":"古风","c":["今宵閒想，问谁家画阁，一双人月。","细把朝衫薰豆蔻，徐绾八盘元发。","人有琴心，家居颍尾，风调偏亲切。","红窗尔汝，夜阑一倍难歇。","为语十二楼中，金风初厉，莫任琼扉豁。","遥忆扫眉驱使处，茉莉万枝香雪。","天与貂蝉，地多金粉，笑拣名花折。","独怜银汉，有人捣药愁绝。"]},{"t":"念奴娇 十三夜大宗伯王敬哉先生招饮是夜无月七叠前韵","f":"古风","c":["先生语我，正一生消受，帝城烟月。","红烛短时横笛嗷，夜雨开元白发。","霜咽遗弓，风悽内苑，画角声酸切。","铜盘承露，泪如铅水不歇。","曾记樗杜笙箫，长杨刀箭，从猎霜林豁。","父子一时连上相，印纽银螭卧雪。","别墅初成，淮淝已捷，屐齿何曾折。","谈深酒冷，鼕鼕街鼓将绝。"]},{"t":"念奴娇 十四夜对月同王阮亭员外八叠前韵","f":"古风","c":["三更以后，碧天刚、碾上一轮圆月。","娇女故园应学母，宛转画眉梳发。","古巷蛩吟，小窗雁语，触景成悲切。","南飞乌鹊，绕枝何处栖歇。","我欲吹裂玉箫，拓残金戟，小把愁肠豁。","生不神仙兼将相，负此秋光堆雪。","灯下吴钩，腰间宝玦，拉杂都摧折。","明当竟去，终南闻道奇绝。"]},{"t":"念奴娇 十五夜宋蓼天太史招饮以雨不克赴少顷月出同纬云鲁望两弟暨曼殊小饮寺寓九叠前韵","f":"古风","c":["吾生万事，沈思遍、都似今宵之月。","只到圆时期便左，揉得愁成乱发。","此夜西园，故人东阁，迟我情偏切。","冲泥无计，车轮腹转难歇。","少顷皓魄东升，海天一碧，世界都轩豁。","燕市且须谋一醉，难得铜街泼雪。","丝竹颠狂，弟兄歌叱，碎拗金鞭折。","知他何处，笛声缕缕凄绝。"]},{"t":"念奴娇 十六夜对月呈孙北海先生十叠前韵","f":"古风","c":["浩歌被酒，喜举头仍见，昨宵圆月。","遥忆高斋歌猛虎，剑气绿人毛发。","老子龙头，细书虿尾，玉试昆吾切。","隗嚣旧物，土花千载难歇。","更有粉壁波涛，牙签蝌蚪，摊几供披豁。","吟健左车能决肉，日拓黄州快雪。","馀子纷纶，是翁矍铄，有角真堪折。","南楼高兴，依稀清啸将绝。"]},{"t":"念奴娇 看山如读画读画似看山为周栎园先生赋用曹顾庵韵二首 其一","f":"古风","c":["青天粉本，是五丁所凿，自然图画。","我识天公矜慎极，吮笔几曾轻下。","晴际添螺，昏时使墨，茜向朝霞借。","烟丝雨发，直教染岱烘华。","我欲地缩千山，袖携五岳，点缀閒亭榭。","一幅横披供眺望，便可于中耕稼。","非画非山，是看是读，饶舌都教罢。","一身冷翠，此间三伏无夏。"]},{"t":"念奴娇 看山如读画读画似看山为周栎园先生赋用曹顾庵韵二首 其二","f":"古风","c":["生平痴爱，是荆关老手，最纷披处。","狂叫墨花都发响，认作画师奇句。","比以汉书，挂来牛角，读入前村去。","千回不厌，直疑声振毫素。","回想老子篮舆，好天笋屐，曾到层山路。","今日明窗悬幅幅，一样晴鬟堪数。","峡角将崩，云根欲活，丘壑胸中具。","更怜著色，崖边碎点红树。"]},{"t":"念奴娇 邺中怀古","f":"古风","c":["滏阳南去，望邺城一带，逼人愁思。","记得群雄争割据，健者曹家吉利。","公子綵毫，佳人绣瓦，快意当如是。","漳河呜咽，至今犹染红泪。","犹忆秋夏读书，春冬射猎，泥水谯南地。","转眼寒烟萦战垒，耿耿还留霸气。","贺六浑来，韩擒虎去，苑树都如荠。","论人成败，世间何限馀子。"]},{"t":"念奴娇 题季端木小影","f":"古风","c":["丹青一幅，是西湖好手，戴苍之笔。","年少者谁真秀绝，不让王家摩诘。","绣虎清才，食牛奇气，刷羽霜空失。","科头箕踞，襟情一往萧瑟。","寄语莫赌罗囊，人身似尔，头地终须出。","安得画师乘快墨，并写骅骝十匹。","历块过都，莝燕秣越，此事为君必。","若翁大笑，看君长绕吟膝。"]},{"t":"念奴娇 红桥园亭宴集同限一屋韵","f":"古风","c":["霜红露白，借城南佳处，一餐秋菊。","更值群公连袂到，夹巷雕鞍绣轴。","一抹红霞，三分明月，此景扬州独。","挥杯自笑，吾生长是碌碌。","且喜绝代娥媌，元机娣姒，风致偏妍淑。","恼乱云鬟多刺史，何况閒愁似仆。","小逗琴心，轻翻帘额，一任颠毛秃。","倚阑吟眺，云鳞坟起如屋。"]},{"t":"念奴娇 读顾庵先生新词兼酬赠什即次原韵","f":"古风","c":["老颠欲裂，看盘空硬句，苍然十幅。","谁拍袁绉铁绰板，洗净琵琶场屋。","击物无声，杀人如草，笔扫㕙毫秃。","较量词品，稼轩白石山谷。","记得戏马长杨，割鲜下杜，天笑温堪掬。","玉靶角弓云外响，捎动离宫花木。","银海乌飞，铜池鲸舞，月照孤臣独。","江潭遗老，一声寒喷霜竹。"]},{"t":"念奴娇 送朱近修还海昌并怀丁飞涛之白下送既庭返吴门仍用顾庵韵","f":"古风","c":["住为佳耳，问先生何事，急装趋肃。","曾在竹西园子里，狼籍钗徵钏逐。","别酒红擎，离帆绿饱，人上兰舟宿。","君行烟际，吴山螺发新沐。","可惜世事匆匆，陡然方寸，起冈峦陵麓。","谁倩石尤吹鹢转，并转丁仪宋玉。","无数狂奴，一群荡子，屯守倡家屋。","此情莫遂，悄然熟视枫菊。"]},{"t":"念奴娇 被酒呈荔裳顾庵西樵三公并示豹人孝威梅岑舟次方邺希韩汝受散木诸子仍用原韵","f":"古风","c":["仆何为者，是东吴愁客，最能击筑。","记得阿奴年少日，曾直高人品目。","甚矣吾衰，时乎不再，二语那堪读。","朱门列戟，此中何限粱肉。","幸遇衮衮群公。","怜而召我，共看东篱菊。","我意亦思归去耳，聊葺溪干破屋。","行乞歌场，为佣屠肆，也觅三餐粥。","安能溪刻，矫廉长效孤竹。"]},{"t":"念奴娇 红桥倡和集成索李研斋序孙介夫记作词奉柬并呈冒巢民先生仍用顾庵韵","f":"古风","c":["夔门蜀栈，是史家粉本，先生所独。","更有孙樵雄且健，暗里汉书能覆。","二老纵横，两篇记序，并逐中原鹿。","古文奇字，他人恐不能读。","直可抵突曾王，激昂韩柳，揖欧阳永叔。","我与浯溪曾有约，采入文抄篇幅。","细写千行，高吟百遍，音响崩崖屋。","遇当佳处，浇之苦茗芳菊。"]},{"t":"念奴娇 赠阿秀并呈西樵","f":"古风","c":["晚风回处，忽帘开影露，鬓烟微绿。","蓦地见人犹掩敛，裙与阑干争曲。","萦损红巾，拨残锦瑟，顿惹愁千斛。","客来休入，请看门外金犊。","渐觉盏内鳞皴，篝边鸭瘦，觥事卿须录。","生世谐逢王吏部，绣佛还工惜玉。","爱尔娇憨，嗔人拘管，挼碎钗儿菊。","晚携素手，碧天雨过初沐。"]},{"t":"念奴娇 曹顾庵王西樵邓孝威沈方邺汪舟次季希韩李云田兄散木皆有送余归阳羡词作此留别","f":"古风","c":["此诸公者，乃狂歌未已，离歌又促。","仆本恨人臣已老，怕听将归丝竹。","捩柂秋空，发船月夜，浊浪堆银屋。","我行去作，荆南山下樵牧。","被酒膝席相呼，人生长聚，那得同麋鹿。","欢伯却输愁鬼厚，只是与人追逐。","天若有情，地如埋恨，此会何难续。","他时念我，杜陵男子萧育。"]},{"t":"念奴娇 送沈方邺还宣城兼怀唐耕坞施愚山梅子长同西樵用孝威韵","f":"楚辞体","c":["归兮何暮，叹风尘经岁，迷阳却曲。","忆我同君为狎宴，夜夜弹丝吹竹。","弟蓄余髯，人呼沈瘦，侧帽谈公谷。","人身似此，安能仰面看屋。","故里才子都官，舍人唐老，英妙兼耆宿。","更有肩吾能爱我，客舍绨袍情笃。","归见三君，雪深一尺，定理寻诗躅。","尺书好寄，江船不乏千斛。"]},{"t":"念奴娇 延令季苍苇席上送周子俶计偕京师","f":"古风","c":["长途迫岁，正黄河飞雪，马都没腹。","裤缚黄皮雄舞槊，那顾从奴猬缩。","斫彘屠门，射雕塞上，生啖黄獐肉。","看君意气，真成勇过贲育。","况是历落盘龙，风流公瑾，海内标名目。","此去长安声价重，定压庾徐潘陆。","愧我牢骚，借人杯炙，送汝登华轴。","慈恩题罢，归鞭春昼须速。"]},{"t":"念奴娇 广陵客夜却忆吴门同吴梅村先生暨叶讱庵盛珍示王维夏崔不雕李西渊范龙仙王升吉饮钱宫声宅时有新凰赖凰二校书在座","f":"楚辞体","c":["月之十八，记诸公共饮，钱郎书屋。","祭酒能为解散髻，下语千人都伏。","东观名卿，南朝才子，争举觞相属。","莫愁更鼓，任他烧短红烛。","何意尊合杯阑，一双么凤，齐注横波目。","假使客中皆此夜，讵羡八州之督。","上客如风，佳人似雨，薄命余同鞠。","鞠兮惜汝，一生长被人蹴。"]},{"t":"念奴娇 季沧苇宅夜看歌姬演剧即席成词并示张天任五丹九仪戴宏度季孚公希韩李三友朱石钟诸子","f":"古风","c":["吾生讵料，也曾经，亲听诸姨法曲。","非月非烟非雾雨，非肉非丝非竹。","不易描摹，最难忘记，耿耿萦心目。","依稀梁畔，暗尘飞堕千斛。","昨者我渡江来，正沙深月冷，浪花堆簇。","饥蜃馋蛟浑不怕，我有听歌奇福。","拍到残时，人将散处，乐往伤幽独。","重逢难必，岸巾且吸船玉。"]},{"t":"念奴娇 重过广陵同王西樵孙介夫夜话即宿西樵寓中","f":"古风","c":["登车一叹，叹羊裘已破，朔风如镞。","枉道那辞三百里，为与琅琊情熟。","却遇兴公，铿然屐响，也过东头屋。","三人相对，寒灯淡晕生绿。","少顷客去余留，王公呼我，大被从君宿。","睡说三冬歧路事，起坐何烦频蹴。","绵定奇温，居殊不易，握粟凭谁卜。","车中霜满，夜寒私语童仆。"]}]};